INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('SudoMaker/rEFui/refui', 'community', 'SudoMaker', 'rEFui', 'SudoMaker/rEFui', 'refui', 0, 0, 36, '2026-03-08T01:57:15.277Z', '2026-03-08T02:00:43.593Z', '82cd8194aa22335e8918571d0ce03ff2f0614eaa901a783a6cc09c3be82640eb', '{"id":"SudoMaker/rEFui/refui","name":"refui","description":{"en":"refui is a JavaScript framework for UI projects across web, native, and embedded platforms, utilizing a retained-mode and signals model for efficient updates. It benefits developers seeking to optimize UI development.","zh":"refui是一种JavaScript框架，用于优化UI项目，支持Web、Native和Embedded开发。它采用保留模式和信号模型，确保高效的UI更新","ja":"refuiは、Web、ネイティブ、エンベデッドUIの開発をサポートするJavaScriptフレームワークです。保留モードとシグナルモデルを採用し、効率的なUI更新を実現します","ko":"refui는 웹, 네이티브, 임베디드 UI 개발을 지원하는 JavaScript 프레임워크입니다. 보존 모드와 신호 모델을 사용하여 효율적인 UI 업데이트를 제공합니다","es":"refui es un framework JavaScript que utiliza un modelo de retención y señales para actualizar la UI de forma incremental, ideal para proyectos en web, nativo y embebido.","fr":"refui est un framework JavaScript qui utilise un modèle de rétention et de signaux pour mettre à jour l''UI de manière incrémentale, idéal pour les projets sur le web, natif et intégré.","de":"refui ist ein JavaScript-Framework, das ein Retention- und Signalmodell verwendet, um die Benutzeroberfläche inkrementell zu aktualisieren, ideal für Projekte im Web, Native und Embedded.","pt":"rEFui é um framework JavaScript que refaz sua UI em web, nativo e incorporado. Aprenda a aplicar o modelo de modo retido e sinais corretamente","ru":"rEFui - это фреймворк JavaScript, который обновляет ваш UI в вебе, нативной и встроенной среде. Узнайте, как правильно применять модель режима удержания и сигналов","ar":"rEFui هو إطار عمل جافاسكريبت يعيد بناء واجهة المستخدم الخاصة بك في الويب والأصلية والمضمنة. تعلم كيفية تطبيق نموذج الوضع المحفوظ والإشارات بشكل صحيح"},"seo":{"title":{"en":"refui: Retained-Mode UI Setup Guide | AI Agent Skill","zh":"refui Setup Guide: 优化UI项目的JavaScript框架","ja":"refuiのセットアップガイド: Web、ネイティブ、エンベデッドUIのためのJavaScriptフレームワーク","ko":"refui 설정 가이드: 웹, 네이티브, 임베디드 UI를 위한 JavaScript 프레임워크","es":"Guía de configuración de refui: framework JavaScript para UI","fr":"Guide de configuration de refui: framework JavaScript pou...","de":"Einrichtungsleitfaden für refui: JavaScript-Framework für...","pt":"Guia de Configuração rEFui: Melhores Práticas para UI","ru":"Настройка rEFui: Руководство по лучшим практикам для ИИ А...","ar":"دليل إعداد rEFui: أفضل الممارسات لتحسين واجهة المستخدم"},"description":{"en":"Unlock efficient UI development with refui''s signals model and JSX renderer. Learn how to apply retained-mode correctly and fix reactivity issues today!","zh":"了解refui的保留模式和信号模型，选择合适的JSX模式和渲染器，解决反应性和生命周期问题","ja":"refuiの保留モードとシグナルモデルを理解し、適切なJSXモードとレンダラーを選択し、リアクティブ性とライフサイクルの問題を解決する","ko":"refui의 보존 모드와 신호 모델을 이해하고, 적절한 JSX 모드와 렌더러를 선택하여 반응성과 生命周期 문제를 해결합니다","es":"Aprende a utilizar refui, un framework JavaScript para proyectos de UI en web, nativo y embebido, con su modelo de retención y señales","fr":"Découvrez refui, un framework JavaScript pour les projets d''UI sur le web, natif et intégré, avec son modèle de rétention et de signaux","de":"Erfahren Sie, wie Sie refui verwenden, ein JavaScript-Framework für UI-Projekte im Web, Native und Embedded, mit seinem Retention- und Signalmodell","pt":"Aprenda a configurar o rEFui corretamente e resolva problemas de reatividade e ciclo de vida sem importar padrões de outros frameworks de UI","ru":"Узнайте, как правильно настроить rEFui и решить проблемы реактивности и жизненного цикла без импорта шаблонов из других фреймворков ИИ Агентов","ar":"تعرف على كيفية إعداد rEFui بشكل صحيح وحل مشاكل التفاعل وحياة الدورة دون استيراد أنماط من إطار عمل واجهة المستخدم الأخرى"},"definition":{"en":"refui is a JavaScript framework that applies a retained-mode and signals model to UI development, enabling incremental updates and efficient rendering.","zh":"refui是一种用于优化UI项目的JavaScript框架，采用保留模式和信号模型","ja":"refuiは、保留モードとシグナルモデルを採用したUIプロジェクトのためのJavaScriptフレームワークです","ko":"refui는 보존 모드와 신호 모델을 사용하는 UI 프로젝트를 위한 JavaScript 프레임워크입니다","es":"refui es un framework JavaScript para proyectos de UI que utiliza un modelo de retención y señales para actualizar la interfaz de usuario","fr":"refui est un framework JavaScript pour les projets d''UI qui utilise un modèle de rétention et de signaux pour mettre à jour l''interface utilisateur","de":"refui ist ein JavaScript-Framework für UI-Projekte, das ein Retention- und Signalmodell verwendet, um die Benutzeroberfläche zu aktualisieren","pt":"rEFui é um framework JavaScript que utiliza o modelo de modo retido e sinais para atualizar a UI","ru":"rEFui - это фреймворк JavaScript, который использует модель режима удержания и сигналов для обновления ИИ Агентов","ar":"rEFui هو إطار عمل جافاسكريبت يستخدم نموذج الوضع المحفوظ والإشارات لتحديث واجهة المستخدم"},"features":{"en":["Utilizes retained-mode for efficient UI updates","Employs signals for incremental UI updates","Supports JSX mode/renderer for flexible rendering","Enables fixing reactivity and lifecycle issues without importing patterns","Allows for setup of component bodies that run once and do not re-render","Evaluates JSX once and updates the already-built UI incrementally"],"zh":["保留模式（Retained Mode）","信号模型（Signals Model）","JSX模式和渲染器选择","反应性和生命周期问题解决","支持Web、Native和Embedded开发"],"ja":["保留モード（Retained Mode）","シグナルモデル（Signals Model）","JSXモードとレンダラーの選択","リアクティブ性とライフサイクルの問題解決","Web、ネイティブ、エンベデッド開発のサポート"],"ko":["보존 모드（Retained Mode）","신호 모델（Signals Model）","JSX 모드와 렌더러 선택","반응성과 生命周期 문제 해결","웹, 네이티브, 임베디드 개발 지원"],"es":["Modelo de retención para componentes","Señales para actualizar la UI de forma incremental","Compatibilidad con JSX para la creación de interfaces de usuario","Soporte para proyectos en web, nativo y embebido","Actualizaciones reactivas sin necesidad de patrones de otros frameworks"],"fr":["Modèle de rétention pour les composants","Signaux pour mettre à jour l''UI de manière incrémentale","Compatibilité avec JSX pour la création d''interfaces utilisateur","Prise en charge de projets sur le web, natif et intégré","Mises à jour réactives sans nécessité de modèles d''autres frameworks"],"de":["Retention-Modell für Komponenten","Signale für die inkrementelle Aktualisierung der Benutzeroberfläche","Kompatibilität mit JSX für die Erstellung von Benutzeroberflächen","Unterstützung für Projekte im Web, Native und Embedded","Reaktive Aktualisierungen ohne Notwendigkeit von Mustern anderer Frameworks"],"pt":["Modo retido para componentes","Sinais para atualizar a UI incrementalmente","JSX avaliado uma vez para construir a UI","Resolução de problemas de reatividade e ciclo de vida","Compatibilidade com web, nativo e incorporado"],"ru":["Режим удержания для компонентов","Сигналы для инкрементального обновления ИИ Агентов","JSX оценивается один раз для построения ИИ Агентов","Решение проблем реактивности и жизненного цикла","Совместимость с вебом, нативной и встроенной средой"],"ar":["الوضع المحفوظ للمكونات","الإشارات لتحديث واجهة المستخدم بشكل متزايد","JSX تقييم مرة واحدة لبناء واجهة المستخدم","حل مشاكل التفاعل وحياة الدورة","التوافق مع الويب والأصلية والمضمنة"]},"keywords":{"en":["how to use refui","what is refui","refui alternative","refui vs react","refui install","refui setup guide","refui retained mode","refui signals model","refui JSX renderer"],"zh":["refui","JavaScript框架","UI优化","保留模式","信号模型","JSX模式","反应性","生命周期","Web开发","Native开发","Embedded开发"],"ja":["refui","JavaScriptフレームワーク","UI最適化","保留モード","シグナルモデル","JSXモード","リアクティブ性","ライフサイクル","Web開発","ネイティブ開発","エンベデッド開発"],"ko":["refui","JavaScript 프레임워크","UI 최적화","보존 모드","신호 모델","JSX 모드","반응성","생명주기","웹 개발","네이티브 개발","임베디드 개발"],"es":["refui","framework JavaScript","UI","retención","señales","JSX","proyectos web","proyectos nativos","proyectos embebidos","desarrollo de interfaces de usuario"],"fr":["refui","framework JavaScript","UI","rétention","signaux","JSX","projets web","projets natifs","projets intégrés","développement d''interfaces utilisateur"],"de":["refui","JavaScript-Framework","UI","Retention","Signale","JSX","Web-Projekte","Native-Projekte","Embedded-Projekte","Entwicklung von Benutzeroberflächen"],"pt":["rEFui","framework JavaScript","modo retido","sinais","JSX","reactividade","ciclo de vida","UI","web","nativo","incorporado"],"ru":["rEFui","фреймворк JavaScript","режим удержания","сигналы","JSX","реактивность","жизненный цикл","ИИ Агенты","веб","нативная","встроенная"],"ar":["rEFui","إطار عمل جافاسكريبت","الوضع المحفوظ","الإشارات","JSX","التفاعل","حياة الدورة","واجهة المستخدم","الويب","الأصلية","المضمنة"]}},"owner":"SudoMaker","repo":"rEFui","repoPath":"SudoMaker/rEFui","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.277Z","topics":[],"category":"community","skillMd":{"name":"refui","description":"Use when working with rEFui (refui) applications where you cannot rely on reading the library source. Covers the retained-mode + signals mental model, DOM/HTML/Reflow renderers, JSX setup (classic pragma vs automatic runtime), directives (on:/class:/style:/attr:/prop:/m: macros), HMR via refurbish/refui/hmr, debugging “UI not updating” issues, and migrating React/Vue/Solid/Svelte patterns to rEFui.","bodyPreview":"# rEFui\n\n## Overview\n\nApply rEFui’s retained-mode + signals model correctly, choose the right JSX mode/renderer, and fix reactivity/lifecycle issues without importing patterns from other UI frameworks.\n\n## General guide\n\n### Mental model (retained mode)\n\n- Component bodies are **setup**: they run once; they do not “re-render”.\n- JSX is evaluated once; **signals** update the already-built UI incrementally.\n- If something “doesn’t update”, you almost always read `.value` too early (non-reactively)","body":"# rEFui\n\n## Overview\n\nApply rEFui’s retained-mode + signals model correctly, choose the right JSX mode/renderer, and fix reactivity/lifecycle issues without importing patterns from other UI frameworks.\n\n## General guide\n\n### Mental model (retained mode)\n\n- Component bodies are **setup**: they run once; they do not “re-render”.\n- JSX is evaluated once; **signals** update the already-built UI incrementally.\n- If something “doesn’t update”, you almost always read `.value` too early (non-reactively) or mutated in place without `trigger()`.\n\n### Signals & reactivity\n\n- State: `const count = signal(0)`\n- Reactive JSX: `{count}` (not `{count.value}`)\n- Derived: `const label = $(() => `Count: ${count.value}`)` and then `{label}`\n- In-place mutation: call `sig.trigger()` after mutating arrays/objects.\n\n```jsx\nimport { signal, $ } from ''refui''\n\nconst Counter = () => {\n\tconst count = signal(0)\n\treturn (\n\t\t<button on:click={() => count.set(count.value + 1)}>\n\t\t\t{$(() => `Count: ${count.value}`)}\n\t\t</button>\n\t)\n}\n```\n\n### Effects & cleanup\n\n- Reactive effect: `watch(() => { ...reads signals... })`\n- Setup/cleanup: `useEffect(() => { ...; return () => cleanup })`\n- Teardown-only: `onDispose(() => cleanup)`\n- Scheduling: if you need “after updates applied”, `await nextTick()`.\n\n### Control flow components\n\n- Conditional UI: `<If condition={cond}>{() => <Then />}{() => <Else />}</If>`\n- Lists: `<For entries={items} track=\"id\">{({ item, index }) => ...}</For>`\n- Inline dynamic subtree with lifecycle: `<Fn ctx={something}>{(ctx) => ...}</Fn>`\n- `For` has **no** `fallback`; for empty states, wrap with `<If>`.\n\n```jsx\nimport { signal, $, If, For } from ''refui''\n\nconst App = () => {\n\tconst items = signal([{ id: 1, name: ''A'' }])\n\treturn (\n\t\t<If condition={$(() => items.value.length)}>\n\t\t\t{() => <For entries={items} track=\"id\">{({ item }) => <div>{item.name}</div>}</For>}\n\t\t\t{() => <div>Empty</div>}\n\t\t</If>\n\t)\n}\n```\n\n### Async UI\n\n- `<Async>` for a single promise boundary.\n- `<Suspense>` to group multiple async subtrees under one fallback.\n- `lazy(() => import(...))` for code-splitting; pair with fallback boundaries.\nSee `references/async-suspense-transition.md` for the “rules of engagement”.\n\n### Context\n\nUse context for shared subtree values. If consumers must react to changes, provide a signal as the context value.\n\n```jsx\nimport { signal, $, createContext, useContext } from ''refui''\n\nconst Theme = createContext(signal(''light''), ''Theme'')\n\nconst Button = () => {\n\tconst theme = useContext(Theme)\n\treturn <button class:dark={$(() => theme.value === ''dark'')}>OK</button>\n}\n```\n\nNon-Reflow/custom renderer: wrap Provider children in a function so they inherit context: `<Theme value={x}>{() => <Button />}</Theme>`.\n\n### Mounting (DOM / HTML)\n\n- DOM renderer (browser): `createDOMRenderer(defaults).render(target, App)`\n- HTML renderer (SSR/SSG): `createHTMLRenderer().serialize(createElement(App, props))`\n- JSX + renderer selection: see `references/jsx-and-renderers.md` (automatic vs classic transform).\n\n```jsx\nimport { createDOMRenderer } from ''refui/dom''\nimport { defaults } from ''refui/browser''\n\ncreateDOMRenderer(defaults).render(document.getElementById(''app''), App)\n```\n\n### DOM directives (browser preset)\n\n- Events: `on:click={fn}` (+ `on-once:*`, `on-passive:*`, `on-capture:*`)\n- Classes/styles: `class:active={boolOrSignal}`, `style:color={valueOrSignal}`\n- Attributes vs props: `attr:*` (SVG/read-only), `prop:*` (force property write)\n- Macros: `m:*` for reusable DOM behaviors (renderer-registered handlers)\n\n## Default Policy: Use rEFui Built-ins First\n\nWhen implementing a requirement, prefer rEFui’s built-in primitives (signals/components/extras/renderers) over custom plumbing. Only fall back to a custom implementation when:\n- rEFui has no built-in primitive that matches the requirement, and\n- the project’s rEFui version lacks an equivalent helper, and\n- you can’t express it cleanly as a DOM macro (`m:*`) or small reusable component.\n\nBefore writing code, consult `references/dos-and-donts.md` to avoid React-style mistakes.\n\n## Quick Triage (do this first)\n\n1. Identify **JSX mode** in the target repo:\n\t - **Automatic runtime**: look for `jsx: ''automatic''` + `jsxImportSource: ''refui''` (Vite/esbuild) or `jsxImportSource: \"refui\"` (tsconfig/Bun).\n\t - **Classic transform**: look for `jsxFactory: ''R.c''` + `jsxFragment: ''R.f''` (Vite/esbuild) or `/** @jsx R.c */` file pragmas.\n2. Identify the **host renderer**:\n\t - Browser apps: `createDOMRenderer(defaults)` from `refui/dom` + `refui/browser` (or `refui/presets/browser` in older repos).\n\t - SSR/SSG: `createHTMLRenderer()` from `refui/html`, then `serialize()`.\n\t - Reflow logic-only modules: `refui/reflow` (often injected via `jsxInject: import { R } from ''refui/reflow''` in classic mode).\n3. Confirm **rEFui version** (it changes API details across repos). Prefer the repo’s local docs or installed `refui` exports.\n\nIf you want an automated scan for JSX mode + common pitfalls, run `node scripts/refui-audit.mjs <path>` from inside this skill folder.\n\n## When Usage Is Unclear (consult MCP docs)\n\nIf you are unsure about a rEFui API, behavior, or best practice and cannot inspect the library source:\n\n- Use **Context7 MCP** to pull authoritative, up-to-date library docs/snippets:\n\t- First resolve the library: `mcp__context7__resolve-library-id` with `libraryName: \"refui\"`.\n\t- Then query: `mcp__context7__query-docs` for the specific API/task (e.g. “`For` track vs indexed”, “`createDOMRenderer` macros”, “`nextTick` vs `tick` semantics”, “classic vs automatic JSX setup”).\n- Use **DeepWiki MCP** for repository-level questions (when the upstream repo is available):\n\t- `mcp__deepwiki__read_wiki_structure` then `mcp__deepwiki__ask_question` on `SudoMaker/rEFui` for conceptual/system questions or “where is X documented?”.\n\nIf MCP docs still leave ambiguity, ask the user for: the `refui` version, their bundler config (Vite/esbuild/Bun/TS/Babel), and a minimal repro snippet.\n\n## “Which rEFui feature should I use?” (fast mapping)\n\nUse these references when choosing a built-in solution:\n- Idiot-proof do/don’t checklist: `references/dos-and-donts.md`\n- Async UI: `references/async-suspense-transition.md`\n- Overlays/teleports/rich HTML/custom elements: `references/portals-parse-custom-elements.md`\n- Lists/identity/caching/perf: `references/lists-cache-memo.md`\n- Project setup: `references/project-setup.md`\n\n## Non-Negotiables (retained mode)\n\n- Do not write React/Vue/Solid/Svelte primitives (`useState`, hooks, VDOM assumptions, `$:` blocks, etc.). Map them to rEFui signals/effects.\n- Treat component bodies as **setup** (constructor-ish). JSX is evaluated once; signals drive incremental updates afterward.\n- Keep reactive reads reactive:\n\t- ✅ Use a signal directly: `<div>{count}</div>`\n\t- ✅ Wrap derived expressions: `<div>{$(() => `Count: ${count.value}`)}</div>` or `<div>{computed(() => ...)}</div>`\n\t- ❌ Avoid inline `.value` in JSX: `<div>{count.value}</div>` (evaluates once, won’t update)\n- Remember scheduling: signal effects/computed flush at the end of the tick; use `await nextTick()` when you must observe derived updates.\n\n## Hard Rules (idiot-proof guardrails)\n\n- This is **not React**. Component bodies run once; JSX does not re-run. Do not expect re-renders.\n- Do not invent props. If the API is unclear, open the .d.ts or use MCP. Example: `For` has **no** `fallback` prop.\n- `If` / `For` / templates accept a **single** renderable. If you need multiple nodes, wrap them in a container or fragment.\n- `For` empty state: wrap it in `If` and provide a false branch. Example:\n\t- `<If condition={$(() => items.value.length)}><For entries={items} track=\"id\">{({ item }) => <Row item={item} />}</For><Empty /></If>`\n- Use `.value` inside `computed` / `$(() => ...)` / `watch` / event handlers, not directly in JSX text/attrs.\n\n## Default Patterns (copy these mentally)\n\n- State: `const x = signal(initial)`\n- Derived: `const y = $(() => /* uses x.value */)` (or `computed(() => ...)`)\n- Effects: `watch(fn)` for reactive computations; `useEffect(setup)` for setup+cleanup; `onDispose(cleanup)` for teardown.\n- Lists:\n\t- Keyed: `<For entries={items} track=\"id\">{({ item }) => ...}</For>`\n\t- Unkeyed (perf experiments / reorder heavy): `UnKeyed` from `refui/extras/unkeyed.js`\n\t- If mutating arrays/objects in place: call `sig.trigger()` after mutation.\n- Async:\n\t- `<Async future={promise} fallback={...} catch={...}>{({ result }) => ...}</Async>`\n\t- `<Suspense>` for grouping async subtrees\n\t- `async` components are supported; pair with fallbacks when needed.\n- DOM directives/events (DOM renderer):\n\t- Events: `on:click={...}`, plus options `on-once:*`, `on-passive:*`, `on-capture:*`\n\t- Attributes vs props: prefer `attr:` for SVG or when a DOM prop is read-only; use `prop:` to force a property set.\n\t- Preset directives (browser preset): `class:x={boolSignal}`, `style:color={valueOrSignal}`\n\t- Macros: `m:name={value}` where `name` is registered on the renderer.\n- Refs/handles:\n\t- `$ref={sig}` to receive a node/instance in `sig.value`\n\t- `$ref={(node) => ...}` callback form\n\t- Prefer `expose` prop for imperative child handles (v0.8.0+).\n\n## Workflows\n\n### Fix “UI not updating”\n\n1. Search for JSX `{something.value}` and decide if it must be reactive:\n\t - Replace with `{something}` when `something` is already a signal.\n\t - Wrap derived text/attrs with `$(() => ...)` / `computed(() => ...)` / `t\\`...\\``.\n2. If you mutated an object/array held by a signal in-place, add `sig.trigger()` (or replace with a new object/array).\n3. If you read derived values immediately after writes, insert `await nextTick()` before reading computed/DOM-dependent values.\n4. If an effect runs “forever”, ensure it’s created inside a component scope and cleaned up via `useEffect`/`onDispose`.\n\n### Add a feature safely\n\n1. Keep renderer creation at the entry point; do not create renderers inside components.\n2. Localize state: prefer per-component signals over global blobs; use `extract`/`derivedExtract` to reduce fan-out.\n3. For repeated DOM behaviors, register a macro and use it via `m:*` rather than duplicating manual DOM code.\n4. For lists, choose keyed `<For>` unless you have a measured reason to use unkeyed.\n\n### Set up a new project (when asked)\n\n1. Ask only: preferred package manager (`npm`/`pnpm`/`yarn`/`bun`) and language (JS/TS). Do not ask runtime.\n2. Default to JSX automatic runtime + JavaScript + `refui` latest from npm unless the user specifies otherwise.\n3. Follow `references/project-setup.md`.\n\n## Repo Navigation (load only if needed)\n\nRead these files when you need deeper details:\n\n- `references/project-triage.md` for determining JSX mode/renderer/version from a project that uses rEFui as a dependency.\n- `references/project-setup.md` for scaffolding a new project (default: JSX automatic runtime + pure JS).\n- `references/jsx-and-renderers.md` for choosing classic vs automatic and DOM/HTML/Reflow specifics.\n- `references/reactivity-pitfalls.md` for high-signal debugging checklists and anti-patterns.\n- `references/dos-and-donts.md` for per-API/component do’s and don’ts that prevent React-mindset mistakes.\n- `references/async-suspense-transition.md` for `<Async>`, `<Suspense>`, `lazy`, and `Transition`.\n- `references/portals-parse-custom-elements.md` for portals/teleports, HTML parsing, and custom elements.\n- `references/lists-cache-memo.md` for `<For>`, identity, `UnKeyed`, caching, and memoization.\n\n## Resources\n\n### `scripts/`\n- `scripts/refui-audit.mjs`: quick scan for JSX mode + common `.value`-in-JSX pitfalls.\n\n### `references/`\n- `references/project-triage.md`\n- `references/jsx-and-renderers.md`\n- `references/reactivity-pitfalls.md`\n- `references/dos-and-donts.md`\n- `references/async-suspense-transition.md`\n- `references/portals-parse-custom-elements.md`\n- `references/lists-cache-memo.md`\n- `references/project-setup.md`\n"},"lastSynced":"2026-03-08T02:00:43.593Z","agentAnalysis":{"suitability":{"en":"Ideal for Frontend Agents requiring efficient UI development with retained-mode and signals model.","zh":"适用于需要高效UI开发的前端代理，保留模式和信号模型。","ja":"効率的なUI開発と保持モードおよびシグナルモデルを必要とするフロントエンドエージェントに最適です。","ko":"효율적인 UI 개발과 유지 모드 및 신호 모델이 필요한 프론트엔드 에이전트에 적합합니다.","es":"Ideal para agentes Frontend que requieren un desarrollo de UI eficiente con modo retenido y modelo de señales","fr":"Idéal pour les agents Frontend nécessitant un développement d''UI efficace avec mode retenu et modèle de signaux","de":"Ideal für Frontend-Agents, die eine effiziente UI-Entwicklung mit Beibehaltungsmodus und Signalmodell erfordern","pt":"Ideal para Agentes Frontend que exigem desenvolvimento de UI eficiente com modo retido e modelo de sinais.","ru":"Идеально для агентов Frontend, требующих эффективного разработки UI с режимом удержания и сигнальной моделью.","ar":"مثالي لعميل واجهة المستخدم الأمامية الذي يتطلب تنمية واجهة المستخدم有效ة مع وضع الحفظ ونموذج الإشارات."},"recommendation":{"en":"Empowers agents to build optimized UI projects across web, native, and embedded platforms using refui''s retained-mode + signals model, and efficiently update UI components with JSX and signals, while avoiding reactivity and lifecycle issues.","zh":"赋予代理构建跨web、原生和嵌入式平台的优化UI项目的能力，使用refui的保持模式+信号模型，并使用JSX和信号高效更新UI组件，同时避免反应性和生命周期问题。","ja":"エージェントが、refuiの保持モード+シグナルモデルを使用して、Web、ネイティブ、エンベデッドプラットフォームを横断する最適化されたUIプロジェクトを構築し、JSXとシグナルを使用してUIコンポーネントを効率的に更新し、リアクティブ性とライフサイクルの問題を回避する能力を付与します。","ko":"에이전트가 refui의 유지 모드 + 신호 모델을 사용하여 웹, 네이티브, 임베디드 플랫폼을 아우르는 최적화된 UI 프로젝트를 구축하고, JSX와 신호를 사용하여 UI 컴포넌트를 효율적으로 업데이트하며, 반응성과 라이프 사이클 문제를 피할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a crear proyectos de UI optimizados en plataformas web, nativas y embebidas utilizando el modelo de modo retenido + señales de refui, y a actualizar eficientemente los componentes de UI con JSX y señales, evitando problemas de reactividad y ciclo de vida","fr":"Permet aux agents de créer des projets d''UI optimisés sur des plates-formes web, natives et intégrées en utilisant le modèle de mode retenu + signaux de refui, et de mettre à jour efficacement les composants d''UI avec JSX et signaux, tout en évitant les problèmes de réactivité et de cycle de vie","de":"Ermöglicht es Agents, optimierte UI-Projekte über Web-, Native- und Embedded-Plattformen mit refuis Beibehaltungsmodus + Signalmodell zu erstellen und UI-Komponenten mit JSX und Signalen effizient zu aktualisieren, während Probleme mit Reaktivität und Lebenszyklus vermieden werden","pt":"Habilita os agentes a construir projetos de UI otimizados em plataformas web, nativas e incorporadas usando o modelo de modo retido + sinais do refui, e atualizar componentes de UI de forma eficiente com JSX e sinais, evitando problemas de reatividade e ciclo de vida.","ru":"Наделяет агентов возможностью создавать оптимизированные проекты UI на веб-, родных и встроенных платформах, используя модель удержания + сигналы refui, и эффективно обновлять компоненты UI с помощью JSX и сигналов, избегая проблем реактивности и жизненного цикла.","ar":"يمنح العميل القدرة على بناء مشاريع واجهة المستخدم المُحسّنة عبر منصات الويب والأصلية والمتأصلة باستخدام نموذج الحفظ + الإشارات من refui، وتحديث مكونات واجهة المستخدم بفعالية باستخدام JSX والإشارات، وتجنب مشاكل التفاعل والدورة الحياتية."},"useCases":{"en":["Building cross-platform UI applications with retained-mode","Optimizing UI updates using signals and JSX","Debugging reactivity and lifecycle issues in refui projects"],"zh":["使用保持模式构建跨平台UI应用程序","使用信号和JSX优化UI更新","调试refui项目中的反应性和生命周期问题"],"ja":["保持モードを使用したクロスプラットフォームUIアプリケーションの構築","シグナルとJSXを使用したUI更新の最適化","refuiプロジェクトのリアクティブ性とライフサイクルの問題のデバッグ"],"ko":["유지 모드를 사용한 크로스 플랫폼 UI 애플리케이션 구축","신호와 JSX를 사용한 UI 업데이트 최적화","refui 프로젝트의 반응성과 라이프 사이클 문제 디버깅"],"es":["Crear aplicaciones de UI multiplataforma con 