INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('SudoMaker/rEFui/refui', 'refui', 'SudoMaker', 'rEFui', 'community', 'refui SudoMaker rEFui community refui is a JavaScript framework for UI projects across web, native, and embedded platforms, utilizing a retained-mode and signals model for efficient updates. It benefits developers seeking to optimize UI development. refui是一种JavaScript框架，用于优化UI项目，支持Web、Native和Embedded开发。它采用保留模式和信号模型，确保高效的UI更新 refuiは、Web、ネイティブ、エンベデッドUIの開発をサポートするJavaScriptフレームワークです。保留モードとシグナルモデルを採用し、効率的なUI更新を実現します refui는 웹, 네이티브, 임베디드 UI 개발을 지원하는 JavaScript 프레임워크입니다. 보존 모드와 신호 모델을 사용하여 효율적인 UI 업데이트를 제공합니다 refui es un framework JavaScript que utiliza un modelo de retención y señales para actualizar la UI de forma incremental, ideal para proyectos en web, nativo y embebido. refui est un framework JavaScript qui utilise un modèle de rétention et de signaux pour mettre à jour l''UI de manière incrémentale, idéal pour les projets sur le web, natif et intégré. refui ist ein JavaScript-Framework, das ein Retention- und Signalmodell verwendet, um die Benutzeroberfläche inkrementell zu aktualisieren, ideal für Projekte im Web, Native und Embedded. rEFui é um framework JavaScript que refaz sua UI em web, nativo e incorporado. Aprenda a aplicar o modelo de modo retido e sinais corretamente rEFui - это фреймворк JavaScript, который обновляет ваш UI в вебе, нативной и встроенной среде. Узнайте, как правильно применять модель режима удержания и сигналов rEFui هو إطار عمل جافاسكريبت يعيد بناء واجهة المستخدم الخاصة بك في الويب والأصلية والمضمنة. تعلم كيفية تطبيق نموذج الوضع المحفوظ والإشارات بشكل صحيح how to use refui what is refui refui alternative refui vs react refui install refui setup guide refui retained mode refui signals model refui JSX renderer refui JavaScript框架 UI优化 保留模式 信号模型 JSX模式 反应性 生命周期 Web开发 Native开发 Embedded开发 Utilizes retained-mode for efficient UI updates Employs signals for incremental UI updates Supports JSX mode/renderer for flexible rendering Enables fixing reactivity and lifecycle issues without importing patterns Allows for setup of component bodies that run once and do not re-render Evaluates JSX once and updates the already-built UI incrementally refui is a JavaScript framework that applies a retained-mode and signals model to UI development, enabling incremental updates and efficient rendering.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('BlockRunAI/ClawRouter/clawrouter', 'community', 'BlockRunAI', 'ClawRouter', 'BlockRunAI/ClawRouter', 'clawrouter', 0, 0, 36, '2026-03-08T01:57:15.282Z', '2026-03-08T02:00:52.982Z', 'ac56e6c5625f557bdd0026928414a05da981708b1827343f15142e3db241a2a5', '{"id":"BlockRunAI/ClawRouter/clawrouter","name":"clawrouter","description":{"en":"clawrouter is a smart LLM router that saves 67% on inference costs by routing requests to the cheapest model. It supports 41 models across 5 providers through one wallet.","zh":"ClawRouter是一种智能LLM路由器，通过路由每个请求到最便宜的模型来节省推理成本。支持41个模型，5个提供商，仅需一个钱包","ja":"ClawRouterは、各リクエストを最も安いモデルにルーティングすることで推論コストを節約するスマートLLMルーターです。41のモデル、5つのプロバイダー、1つのウォレットのみで利用可能","ko":"ClawRouter는 각 요청을 가장 저렴한 모델로 라우팅하여 추론 비용을 절감하는智能 LLM 라우터입니다. 41개 모델, 5개 공급자, 1개의 지갑만으로 사용할 수 있습니다","es":"ClawRouter es un enrutador de LLM inteligente que ahorra un 67% en costos de inferencia. Soporta 41 modelos a través de 5 proveedores.","fr":"ClawRouter est un routeur LLM intelligent qui économise 67% sur les coûts d''inférence. Il prend en charge 41 modèles à travers 5 fournisseurs.","de":"ClawRouter ist ein intelligenter LLM-Router, der 67% der Inferenzkosten spart. Er unterstützt 41 Modelle über 5 Anbieter.","pt":"O ClawRouter é um roteador de LLM inteligente que economiza 67% nos custos de inferência. Ele suporta 41 modelos em 5 provedores com uma carteira única.","ru":"ClawRouter - умный маршрутизатор LLM, который экономит 67% на затратах на вывод. Он поддерживает 41 модель в 5 провайдерах с единственным кошельком.","ar":"ClawRouter هو روتر LLM ذكي يوفر 67% من التكاليف الاستدلالية. يدعم 41 نموذجًا في 5 مزودين بحساب واحد"},"seo":{"title":{"en":"clawrouter: Smart LLM Router Setup Guide | AI Agent Skill","zh":"ClawRouter 智能路由器设置指南 - 优化LLM推理成本","ja":"ClawRouter のスマートルーティング設定方法 - LLM 推論コストを削減","ko":"ClawRouter智能 라우터 설정 가이드 - LLM 추론 비용 최적화","es":"Guía de configuración de ClawRouter: Ahorra en costos de ...","fr":"ClawRouter Setup Guide: Réduisez les coûts d''inférence de...","de":"ClawRouter-Konfigurationsleitfaden: Sparen Sie 78% bei In...","pt":"Guia de Configuração do ClawRouter - Roteador de LLM Inte...","ru":"Настройка ClawRouter - Умный маршрутизатор LLM","ar":"دليل إعداد ClawRouter - روتر LLM ذكي"},"description":{"en":"Discover how to save 78% on inference costs with clawrouter. Learn to install and setup this smart LLM router for optimal performance. Get started now!","zh":"使用ClawRouter智能路由器，通过自动选择最便宜的LLM模型来节省67%的推理成本","ja":"ClawRouterスマートルーティングを使用して、最も安いLLMモデルを自動的に選択し、67%の推論コストを削減します","ko":"ClawRouter智能 라우터를 사용하여 자동으로 가장 저렴한 LLM 모델을 선택하여 67%의 추론 비용을 절감합니다","es":"Descubre cómo configurar ClawRouter para reducir costos de inferencia en un 78%. Conoce sus características y beneficios.","fr":"Découvrez comment configurer ClawRouter pour réduire les coûts d''inférence de 78%. Explorez ses fonctionnalités et avantages.","de":"Erfahren Sie, wie Sie ClawRouter konfigurieren, um Inferenzkosten um 78% zu reduzieren. Erforschen Sie seine Funktionen und Vorteile.","pt":"Aprenda a configurar o ClawRouter e economize 78% nos custos de inferência com 30+ modelos e micropagamentos","ru":"Узнайте, как настроить ClawRouter и сэкономьте 78% на затратах на вывод с 30+ моделями и микроплатежами","ar":"تعرف على كيفية إعداد ClawRouter وتوفير 78% من التكاليف الاستدلالية مع 30+ نموذجًا ودفع الميكرو"},"definition":{"en":"clawrouter is a smart LLM router that optimizes inference costs by dynamically routing requests to the most cost-effective model.","zh":"ClawRouter是一种智能LLM路由器，用于优化LLM推理成本","ja":"ClawRouterは、LLM推論コストを最適化するためのスマートLLMルーターです","ko":"ClawRouter는 LLM 추론 비용을 최적화하는智能 LLM 라우터입니다","es":"ClawRouter es un agente de IA que enruta solicitudes a los modelos más baratos que pueden manejarlas.","fr":"ClawRouter est un agent IA qui achemine les requêtes vers les modèles les moins chers qui peuvent les gérer.","de":"ClawRouter ist ein IA-Agent, der Anfragen an die günstigsten Modelle weiterleitet, die sie verarbeiten können.","pt":"O que é ClawRouter? É um roteador de LLM inteligente que roteia cada solicitação para o modelo mais barato que possa lidar com ela.","ru":"Что такое ClawRouter? Это умный маршрутизатор LLM, который маршрутизирует каждый запрос к самому дешевому модели, который может его обработать.","ar":"ما هو ClawRouter؟ هو روتر LLM ذكي يوجه كل طلب إلى النموذج الأقل تكلفة الذي يمكنه التعامل معه"},"features":{"en":["Supports 41 models across 5 providers through one wallet","Enables smart routing with auto-picks cheapest model per request using openclaw models set blockrun/auto","Allows pinning a specific model using openclaw models set openai/gpt-4o","Installs via openclaw plugins install @blockrun/clawrouter","Handles x402 micropayments for flexible billing","Classifies each request into optimal model handling"],"zh":["支持41个LLM模型","5个提供商的模型可用","仅需一个钱包即可管理所有模型","自动选择最便宜的模型进行推理","通过路由每个请求到最便宜的模型来节省推理成本"],"ja":["41のLLMモデルをサポート","5つのプロバイダーのモデルが利用可能","1つのウォレットのみですべてのモデルを管理","最も安いモデルを自動的に選択して推論","各リクエストを最も安いモデルにルーティングして推論コストを節約"],"ko":["41개 LLM 모델 지원","5개 공급자의 모델 사용 가능","1개의 지갑만으로 모든 모델 관리","가장 저렴한 모델 자동 선택하여 추론","각 요청을 가장 저렴한 모델로 라우팅하여 추론 비용 절감"],"es":["Soporte para 41 modelos a través de 5 proveedores","Enrutamiento inteligente para reducir costos de inferencia","Compatibilidad con micropagos x402","Instalación sencilla con openclaw plugins","Configuración flexible con openclaw models"],"fr":["Prise en charge de 41 modèles à travers 5 fournisseurs","Acheminement intelligent pour réduire les coûts d''inférence","Compatibilité avec les micropaiements x402","Installation facile avec openclaw plugins","Configuration flexible avec openclaw models"],"de":["Unterstützung für 41 Modelle über 5 Anbieter","Intelligente Weiterleitung für reduzierte Inferenzkosten","Kompatibilität mit Mikrozahlungen x402","Einfache Installation mit openclaw plugins","Flexible Konfiguration mit openclaw models"],"pt":["Suporte a 41 modelos em 5 provedores","Carteira única para todos os modelos","Roteamento inteligente para o modelo mais barato","Micropagamentos para economia de custos","Instalação simples via CLI","Configuração fácil com comandos openclaw"],"ru":["Поддержка 41 модели в 5 провайдерах","Единый кошелек для всех моделей","Умный маршрутизатор для самого дешевого модели","Микроплатежи для экономии затрат","Простая установка через CLI","Легкая настройка с помощью команд openclaw"],"ar":["دعم 41 نموذجًا في 5 مزودين","حساب واحد لجميع النماذج","توجيه ذكي إلى النموذج الأقل تكلفة","دفع الميكرو لتوفير التكاليف","تثبيت بسيط عبر CLI","إعداد سهل باستخدام أوامر openclaw"]},"keywords":{"en":["how to use clawrouter","clawrouter setup guide","clawrouter alternative","clawrouter vs openai","clawrouter install","what is clawrouter","clawrouter smart routing","clawrouter inference costs","clawrouter wallet management"],"zh":["ClawRouter","LLM路由器","智能路由器","LLM推理成本优化","自动选择最便宜的模型","路由每个请求到最便宜的模型","AIエージェント","AI工具"],"ja":["ClawRouter","LLMルーター","スマートルーティング","LLM推論コスト最適化","最も安いモデルを自動的に選択","各リクエストを最も安いモデルにルーティング","AIエージェント","AIツール"],"ko":["ClawRouter","LLM 라우터","智能 라우터","LLM 추론 비용 최적화","가장 저렴한 모델 자동 선택","각 요청을 가장 저렴한 모델로 라우팅","AI 에이전트","AI 도구"],"es":["ClawRouter","enrutador de LLM","ahorro de costos de inferencia","agentes de IA","herramientas de IA","openclaw plugins","micropagos x402","configuración de modelos"],"fr":["ClawRouter","routeur LLM","économie de coûts d''inférence","agents IA","outils IA","openclaw plugins","micropaiements x402","configuration de modèles"],"de":["ClawRouter","LLM-Router","Inferenzkosten sparen","IA-Agenten","IA-Tools","openclaw plugins","Mikrozahlungen x402","Modellkonfiguration"],"pt":["ClawRouter","roteador de LLM","economia de custos","micropagamentos","CLI","openclaw","roteamento inteligente","modelo de LLM","provedores de LLM"],"ru":["ClawRouter","маршрутизатор LLM","экономия затрат","микроплатежи","CLI","openclaw","умный маршрутизатор","модель LLM","провайдеры LLM","ИИ Агенты"],"ar":["ClawRouter","روتر LLM","توفير التكاليف","دفع الميكرو","CLI","openclaw","توجيه ذكي","نموذج LLM","مزودي LLM","أدوات الذكاء الاصطناعي"]}},"owner":"BlockRunAI","repo":"ClawRouter","repoPath":"BlockRunAI/ClawRouter","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.282Z","topics":[],"category":"community","skillMd":{"name":"clawrouter","description":"Smart LLM router — save 67% on inference costs. Routes every request to the cheapest capable model across 41 models from OpenAI, Anthropic, Google, DeepSeek, and xAI.","bodyPreview":"# ClawRouter\n\nSmart LLM router that saves 67% on inference costs by routing each request to the cheapest model that can handle it. 41 models across 5 providers, all through one wallet.\n\n## Install\n\n```bash\nopenclaw plugins install @blockrun/clawrouter\n```\n\n## Setup\n\n```bash\n# Enable smart routing (auto-picks cheapest model per request)\nopenclaw models set blockrun/auto\n\n# Or pin a specific model\nopenclaw models set openai/gpt-4o\n```\n\n## How Routing Works\n\nClawRouter classifies each request into","body":"# ClawRouter\n\nSmart LLM router that saves 67% on inference costs by routing each request to the cheapest model that can handle it. 41 models across 5 providers, all through one wallet.\n\n## Install\n\n```bash\nopenclaw plugins install @blockrun/clawrouter\n```\n\n## Setup\n\n```bash\n# Enable smart routing (auto-picks cheapest model per request)\nopenclaw models set blockrun/auto\n\n# Or pin a specific model\nopenclaw models set openai/gpt-4o\n```\n\n## How Routing Works\n\nClawRouter classifies each request into one of four tiers:\n\n- **SIMPLE** (40% of traffic) — factual lookups, greetings, translations → Gemini Flash ($0.60/M, 99% savings)\n- **MEDIUM** (30%) — summaries, explanations, data extraction → DeepSeek Chat ($0.42/M, 99% savings)\n- **COMPLEX** (20%) — code generation, multi-step analysis → Claude Opus ($75/M, best quality)\n- **REASONING** (10%) — proofs, formal logic, multi-step math → o3 ($8/M, 89% savings)\n\nRules handle ~80% of requests in <1ms. Only ambiguous queries hit the LLM classifier (~$0.00003 per classification).\n\n## Available Models\n\n41 models including: gpt-5.2, gpt-4o, gpt-4o-mini, o3, o1, claude-opus-4.6, claude-sonnet-4.6, claude-haiku-4.5, gemini-3.1-pro, gemini-2.5-pro, gemini-2.5-flash, gemini-2.5-flash-lite, deepseek-chat, deepseek-reasoner, grok-3, grok-3-mini.\n\n## Example Output\n\n```\n[ClawRouter] google/gemini-2.5-flash (SIMPLE, rules, confidence=0.92)\n             Cost: $0.0025 | Baseline: $0.308 | Saved: 99.2%\n```\n"},"lastSynced":"2026-03-08T02:00:52.982Z","agentAnalysis":{"suitability":{"en":"Perfect for Cost-Optimization Agents needing smart LLM routing capabilities to reduce inference costs.","zh":"非常适合需要智能LLM路由功能来降低推理成本的成本优化代理。","ja":"コスト最適化エージェントがスマートなLLMルーティング機能を必要とする場合に最適です。","ko":"スマート한 LLM 라우팅 기능을 통해 추론 비용을 줄이는 비용 최적화 에이전트에 적합합니다.","es":"Perfecto para agentes de optimización de costos que necesitan capacidades de enrutamiento de LLM inteligentes para reducir los costos de inferencia.","fr":"Parfait pour les agents d''optimisation de coûts ayant besoin de capacités de routage de LLM intelligentes pour réduire les coûts d''inférence.","de":"Perfekt für Cost-Optimization-Agents, die intelligente LLM-Routing-Funktionen benötigen, um Inferenzkosten zu reduzieren.","pt":"Perfeito para Agentes de Otimização de Custo que precisam de capacidades de roteamento LLM inteligentes para reduzir os custos de inferência.","ru":"Идеально подходит для агентов оптимизации стоимости, которым необходимы функции интеллектуального маршрутизации LLM для снижения стоимости вывода.","ar":"مثالي لعميل تحسين التكلفة الذي يحتاج إلى قدرات التوجيه الذكية LLM لتقليل تكاليف الاستدلال."},"recommendation":{"en":"Empowers agents to route requests to the cheapest model across 41 models and 5 providers through one wallet, utilizing smart routing to save 67% on inference costs with libraries like openclaw.","zh":"使代理能够通过一个钱包跨41个模型和5个提供商路由请求到最便宜的模型，利用智能路由通过类似openclaw的库节省67%的推理成本。","ja":"エージェントが1つのウォレットを通じて41個のモデルと5つのプロバイダーにわたって最も安いモデルにリクエストをルーティングできるようにし、openclawのようなライブラリを使用してスマートルーティングで67%の推理コストを節約します。","ko":"에이전트가 하나의 지갑을 통해 41개의 모델과 5개의 공급자에 걸쳐 가장 저렴한 모델로 요청을 라우팅 할 수 있도록 하여 openclaw와 같은 라이브러리를 사용하여 스마트 라우팅으로 67%의 추론 비용을 절약합니다.","es":"Habilita a los agentes a enrutar solicitudes al modelo más barato entre 41 modelos y 5 proveedores a través de una sola billetera, utilizando el enrutamiento inteligente para ahorrar el 67% de los costos de inferencia con bibliotecas como openclaw.","fr":"Permet aux agents de router les requêtes vers le modèle le moins cher parmi 41 modèles et 5 fournisseurs via une seule bourse, en utilisant le routage intelligent pour économiser 67% sur les coûts d''inférence avec des bibliothèques comme openclaw.","de":"Ermächtigt Agents, Anfragen an das günstigste Modell unter 41 Modellen und 5 Anbietern über eine einzige Brieftasche zu routen, indem sie intelligente Routen nutzen, um 67% der Inferenzkosten mit Bibliotheken wie openclaw zu sparen.","pt":"Permite que os agentes encaminhem solicitações para o modelo mais barato entre 41 modelos e 5 provedores por meio de uma carteira, utilizando roteamento inteligente para economizar 67% nos custos de inferência com bibliotecas como openclaw.","ru":"Позволяет агентам направлять запросы к самому дешевому модели из 41 модели и 5 поставщиков через один кошелек, используя умное маршрутизация для экономии 67% на стоимости вывода с помощью библиотек, таких как openclaw.","ar":"يتمكن العملاء من توجيه الطلبات إلى أقل модель تكلفة عبر 41 نموذج و 5 مزودين من خلال محفظة واحدة، باستخدام التوجيه الذكي لتوفير 67٪ من تكاليف الاستدلال باستخدام مكتبات مثل openclaw."},"useCases":{"en":["Routing requests to the cheapest LLM model","Automating model selection for cost optimization","Integrating with multiple LLM providers through one wallet"],"zh":["将请求路由到最便宜的LLM模型","自动为成本优化选择模型","通过一个钱包与多个LLM提供商集成"],"ja":["最も安いLLMモデルへのリクエストのルーティング","コスト最適化のためのモデル選択の自動化","1つのウォレットを通じて複数のLLMプロバイダーとの統合"],"ko":["요청을 가장 저렴한 LLM 모델로 라우팅","비용 최적화를 위한 모델 선택 자동화","하나의 지갑을 통해 여러 LLM 공급자와 통합"],"es":["Enrutar solicitudes al modelo LLM más barato","Automatizar la selección de modelos para la optimización de costos","Integrar con varios proveedores de LLM a través de una sola billetera"],"fr":["Router les requêtes vers le modèle LLM le moins cher","Automatiser la sélection de modèles pour l''optimisation des coûts","Intégrer avec plusieurs fournisseurs de LLM via une seule bourse"],"de":["Anfragen an das günstigste LLM-Modell routen","Modellauswahl für die Kostenoptimierung automatisieren","Integration mit mehreren LLM-Anbietern über eine einzige Brieftasche"],"pt":["Encaminhar solicitações para o modelo LLM mais barato","Automatizar a seleção de modelo para otimização de custo","Integrar com vários provedores LLM por meio de uma carteira"],"ru":["Направление запросов к самому дешевому модели LLM","Автоматизация выбора модели для оптимизации стоимости","Интеграция с несколькими поставщиками LLM через один кошелек"],"ar":["توجيه الطلبات إلى أقل نموذج LLM تكلفة","تأتمة اختيار النموذج لتحسين التكلفة","التكامل مع عدة مزودين LLM من خلال محفظة واحدة"]},"limitations":{"en":["Requires openclaw plugins installation","Limited to 41 supported models across 5 providers"],"zh":["需要安装openclaw插件","仅支持5个提供商的41个模型"],"ja":["openclawプラグインのインストールが必要","5つのプロバイダーの41個のモデルのみをサポート"],"ko":["openclaw 플러그인 설치가 필요","5개의 공급자의 41개의 모델만 지원"],"es":["Requiere la instalación de plugins de openclaw","Limitado a 41 modelos compatibles entre 5 proveedores"],"fr":["Nécessite l''installation de plugins openclaw","Limité à 41 modèles pris en charge parmi 5 fournisseurs"],"de":["Benötigt die Installation von openclaw-Plugins","Begrenzt auf 41 unterstützte Modelle unter 5 Anbietern"],"pt":["Requer instalação de plugins openclaw","Limitado a 41 modelos suportados entre 5 provedores"],"ru":["Требуется установка плагинов openclaw","Ограничен до 41 поддерживаемой модели из 5 поставщиков"],"ar":["يتطلب تثبيت إضافات openclaw","محدود بـ 41 نموذجًا مدعومًا عبر 5 مزودين"]},"version":4},"contentHash":"ac56e6c5625f557bdd0026928414a05da981708b1827343f15142e3db241a2a5","qualityScore":36}');
