INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('timescale/pg-aiguide/migrate-postgres-tables-to-hypertables', 'community', 'timescale', 'pg-aiguide', 'timescale/pg-aiguide', 'migrate-postgres-tables-to-hypertables', 0, 0, 36, '2026-03-08T01:57:15.283Z', '2026-03-08T02:00:54.613Z', 'f434ca9db64b6e638f90a1bbc43dddfb181dfe5cfc806bcfccd5adf825ededb3', '{"id":"timescale/pg-aiguide/migrate-postgres-tables-to-hypertables","name":"migrate-postgres-tables-to-hypertables","description":{"en":"The migrate-postgres-tables-to-hypertables skill helps AI coding tools generate better PostgreSQL code by migrating identified tables to TimescaleDB hypertables. It benefits developers working with PostgreSQL and TimescaleDB.","zh":"本技能帮助开发者将 Postgres 表迁移至 TimescaleDB Hypertable，提供优化配置和迁移规划","ja":"Postgres から TimescaleDB Hypertable への移行を支援する AI エージェント スキル。最適な設定と移行計画を提供","ko":"Postgres 테이블을 TimescaleDB Hypertable로 마이그레이션하는 것을 지원하는 AI 에이전트 스킬. 최적의 구성 및 마이그레이션 계획을 제공","es":"Migra tablas de Postgres a Hypertables con la ayuda de AI Agent y mejora tus habilidades en PostgreSQL. Esta guía te muestra cómo configurar y migrar tablas de manera óptima.","fr":"Migrez vos tables Postgres vers Hypertables avec l''aide de l''outil AI et améliorez vos compétences en PostgreSQL. Ce guide vous montre comment configurer et migrer des tables de manière optimale.","de":"Migrieren Sie Tabellen von Postgres zu Hypertables mit Hilfe von KI-Tools und verbessern Sie Ihre Fähigkeiten in PostgreSQL. Dieser Leitfaden zeigt Ihnen, wie Sie Tabellen optimal konfigurieren und migrieren können.","pt":"Migre tabelas Postgres para TimescaleDB Hypertables com configuração ótima e planejamento de migração","ru":"Мигрируйте таблицы Postgres в TimescaleDB Hypertables с помощью ИИ Агентов и оптимальной конфигурации","ar":"هجّر جداول PostgreSQL إلى Hypertables باستخدام أدوات AI وخطط هجرة مثالية"},"seo":{"title":{"en":"migrate-postgres-tables-to-hypertables: Hypertable Migrat...","zh":"Postgres 表迁移至 TimescaleDB Hypertable 指南","ja":"Postgres から TimescaleDB Hypertable への移行ベストプラクティス - AIエージェント","ko":"Postgres 테이블을 TimescaleDB Hypertable로 마이그레이션하는 방법","es":"Guía de configuración para migrar tablas de Postgres a Hy...","fr":"Migration de tables Postgres vers Hypertables avec l''outi...","de":"Leitfaden für die Migration von Postgres-Tabellen zu Hype...","pt":"Guia de Migração de Tabelas Postgres para Hypertables","ru":"ИИ Агенты: Руководство по миграции таблиц Postgres в Time...","ar":"دليل هجرة جداول PostgreSQL إلى Hypertables باستخدام أدوات AI"},"description":{"en":"Discover how to migrate PostgreSQL tables to TimescaleDB hypertables with optimal configuration and validation. Get started with our AI agent skill today!","zh":"使用 AI 工具将 Postgres 表迁移至 TimescaleDB Hypertable，优化配置和迁移规划","ja":"AIエージェントを使用して Postgres から TimescaleDB Hypertable への移行を実施。最適な設定と移行計画を実現","ko":"AI 도구를 사용하여 Postgres 테이블을 TimescaleDB Hypertable로 마이그레이션하고 최적의 구성 및 마이그레이션 계획을 수립","es":"Aprende a migrar tablas de Postgres a Hypertables con nuestra guía paso a paso y mejora tus habilidades en PostgreSQL con AI Agent","fr":"Découvrez comment migrer vos tables Postgres vers Hypertables avec notre guide étape par étape et améliorez vos compétences en PostgreSQL avec les outils AI","de":"Erfahren Sie, wie Sie Tabellen von Postgres zu Hypertables migrieren können, mit unserem Schritt-für-Schritt-Leitfaden und verbessern Sie Ihre Fähigkeiten in...","pt":"Aprenda a migrar tabelas Postgres para TimescaleDB Hypertables com configuração ótima e planejamento de migração","ru":"Откройте для себя, как мигрировать таблицы Postgres в TimescaleDB Hypertables с помощью ИИ Агентов и оптимальной конфигурации","ar":"اكتشف كيفية هجرة جداول PostgreSQL إلى Hypertables باستخدام أدوات AI وخطط هجرة مثالية"},"definition":{"en":"migrate-postgres-tables-to-hypertables is a skill that migrates PostgreSQL tables to TimescaleDB hypertables with optimal configuration, migration planning, and validation.","zh":"Postgres 表迁移至 TimescaleDB Hypertable 是一种将 Postgres 表转换为 TimescaleDB Hypertable 的过程","ja":"Postgres から TimescaleDB Hypertable への移行とは、Postgres のテーブルを TimescaleDB の Hypertable に変換するプロセス","ko":"Postgres 테이블을 TimescaleDB Hypertable로 마이그레이션하는 것은 Postgres 테이블을 TimescaleDB Hypertable로 변환하는 과정","es":"La migración de tablas de Postgres a Hypertables es el proceso de transferir datos de una tabla de Postgres a una Hypertable de TimescaleDB para mejorar el rendimiento y la escalabilidad","fr":"La migration de tables Postgres vers Hypertables est le processus de transfert de données d''une table Postgres à une Hypertable de TimescaleDB pour améliorer les performances et la scalabilité","de":"Die Migration von Tabellen von Postgres zu Hypertables ist der Prozess des Transfers von Daten aus einer Postgres-Tabelle in eine Hypertable von TimescaleDB, um die Leistung und Skalierbarkeit zu verbessern","pt":"Migração de tabelas Postgres para TimescaleDB Hypertables é um processo de transferência de dados","ru":"Миграция таблиц Postgres в TimescaleDB Hypertables - это процесс передачи данных","ar":"هجرة جداول PostgreSQL إلى Hypertables هي عملية نقل البيانات"},"features":{"en":["Migrates identified PostgreSQL tables to TimescaleDB hypertables","Optimizes configuration for hypertable migration","Plans and validates migration for optimal results","Selects optimal partition columns using SQL queries","Works with companion skill ''find-hypertable-candidates'' for table identification"],"zh":["优化配置","迁移规划","验证","Partition 列选择","支持 Postgres 到 TimescaleDB 的迁移"],"ja":["最適な設定","移行計画","検証","Partition 列の選択","Postgres から TimescaleDB への移行をサポート"],"ko":["최적의 구성","마이그레이션 계획","검증","Partition 열 선택","Postgres에서 TimescaleDB로의 마이그레이션 지원"],"es":["Selección de columnas de partición para una configuración óptima","Planificación de migración y validación para garantizar la integridad de los datos","Migración de tablas de Postgres a Hypertables de Ti