INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('timescale/pg-aiguide/migrate-postgres-tables-to-hypertables', 'migrate-postgres-tables-to-hypertables', 'timescale', 'pg-aiguide', 'community', 'migrate-postgres-tables-to-hypertables timescale pg-aiguide community The migrate-postgres-tables-to-hypertables skill helps AI coding tools generate better PostgreSQL code by migrating identified tables to TimescaleDB hypertables. It benefits developers working with PostgreSQL and TimescaleDB. 本技能帮助开发者将 Postgres 表迁移至 TimescaleDB Hypertable，提供优化配置和迁移规划 Postgres から TimescaleDB Hypertable への移行を支援する AI エージェント スキル。最適な設定と移行計画を提供 Postgres 테이블을 TimescaleDB Hypertable로 마이그레이션하는 것을 지원하는 AI 에이전트 스킬. 최적의 구성 및 마이그레이션 계획을 제공 Migra tablas de Postgres a Hypertables con la ayuda de AI Agent y mejora tus habilidades en PostgreSQL. Esta guía te muestra cómo configurar y migrar tablas de manera óptima. Migrez vos tables Postgres vers Hypertables avec l''aide de l''outil AI et améliorez vos compétences en PostgreSQL. Ce guide vous montre comment configurer et migrer des tables de manière optimale. Migrieren Sie Tabellen von Postgres zu Hypertables mit Hilfe von KI-Tools und verbessern Sie Ihre Fähigkeiten in PostgreSQL. Dieser Leitfaden zeigt Ihnen, wie Sie Tabellen optimal konfigurieren und migrieren können. Migre tabelas Postgres para TimescaleDB Hypertables com configuração ótima e planejamento de migração Мигрируйте таблицы Postgres в TimescaleDB Hypertables с помощью ИИ Агентов и оптимальной конфигурации هجّر جداول PostgreSQL إلى Hypertables باستخدام أدوات AI وخطط هجرة مثالية how to use migrate-postgres-tables-to-hypertables migrate-postgres-tables-to-hypertables setup guide migrate-postgres-tables-to-hypertables alternative migrate-postgres-tables-to-hypertables vs TimescaleDB PostgreSQL to TimescaleDB hypertable migration migrate-postgres-tables-to-hypertables install what is migrate-postgres-tables-to-hypertables Postgres 表迁移 TimescaleDB Hypertable AI 工具 迁移规划 优化配置 Partition 列选择 Migrates identified PostgreSQL tables to TimescaleDB hypertables Optimizes configuration for hypertable migration Plans and validates migration for optimal results Selects optimal partition columns using SQL queries Works with companion skill ''find-hypertable-candidates'' for table identification migrate-postgres-tables-to-hypertables is a skill that migrates PostgreSQL tables to TimescaleDB hypertables with optimal configuration, migration planning, and validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rohitg00/awesome-claude-code-toolkit/git-advanced', 'community', 'rohitg00', 'awesome-claude-code-toolkit', 'rohitg00/awesome-claude-code-toolkit', 'git-advanced', 0, 0, 36, '2026-03-08T01:57:15.285Z', '2026-03-08T02:00:56.553Z', 'c73729b00678af678a364bd72b30661f292ba609f6167154e5f78a26c6e7c489', '{"id":"rohitg00/awesome-claude-code-toolkit/git-advanced","name":"git-advanced","description":{"en":"git-advanced is a comprehensive toolkit for managing Git repositories, enabling developers to work on multiple branches simultaneously. It benefits AI agent developers by simplifying branch management.","zh":"Git高级工具提供工作树和分支管理功能，帮助开发者高效管理代码","ja":"Git Advancedはワークツリーとブランチ管理機能を提供し、開発者の生産性を向上させます","ko":"Git 고급 도구는 작업 트리와 분기 관리 기능을 제공하여 개발자의 생산성을 높입니다","es":"El kit de herramientas más completo para Claude Code, que incluye 135 agentes y 35 habilidades curadas, con funcionalidades avanzadas de Git como worktrees","fr":"Le kit d''outils le plus complet pour Claude Code, qui comprend 135 agents et 35 compétences curator, avec des fonctionnalités avancées de Git telles que les worktrees","de":"Das umfassendste Toolkit für Claude Code, das 135 Agenten und 35 kuratierte Fähigkeiten enthält, mit erweiterten Git-Funktionen wie Worktrees","pt":"O Git Avançado é uma ferramenta poderosa para desenvolvedores, permitindo trabalhar com múltiplas branches simultaneamente","ru":"Расширенный Git - это мощный инструмент для разработчиков, позволяющий работать с несколькими ветками одновременно - ИИ Агенты","ar":"جيت المتقدم هو أداة قوية للمطورين، مما يسمح بالعمل مع عدة فروع في نفس الوقت - أدوات ذكاء اصطناعي"},"seo":{"title":{"en":"git-advanced: Mastering Git Worktrees for AI Agents | AI ...","zh":"Git 高级工具：工作树和分支管理Setup Guide","ja":"Git Advanced: ワークツリーとブランチ管理のベストプラクティス","ko":"Git 고급 도구: 작업 트리와 분기 관리를 위한 완벽한 가이드","es":"Guía de Configuración de Git Avanzado para Desarrolladores","fr":"Guide de Configuration de Git Avancé pour Développeurs","de":"Erweitertes Git-Setup für Entwickler","pt":"Guia de Configuração do Git Avançado","ru":"Руководство по настройке расширенного Git - ИИ Агенты","ar":"دليل إعداد جيت المتقدم - أدوات ذكاء اصطناعي"},"description":{"en":"Unlock efficient branch management with git-advanced. Learn how to create and manage worktrees, and streamline your development workflow. Get started now!","zh":"了解Git高级工具的强大功能，包括工作树和分支管理，提高开发效率","ja":"Git Advancedの強力な機能、ワークツリーとブランチ管理を紹介します","ko":"Git 고급 도구의 강력한 기능을 살펴보세요. 작업 트리와 분기 관리로 개발 효율성을 높이세요","es":"Aprende a utilizar Git de manera avanzada con worktrees y comandos personalizados para mejorar tu flujo de trabajo","fr":"Découvrez comment utiliser Git de manière avancée avec des worktrees et des commandes personnalisées pour améliorer votre workflow","de":"Erfahren Sie, wie Sie Git erweitert mit Worktrees und benutzerdefinierten Befehlen verwenden, um Ihren Arbeitsablauf zu verbessern","pt":"Aprenda a usar o Git Avançado com worktrees, branches e comandos para melhorar a produtividade do seu desenvolvimento","ru":"Узнайте, как использовать расширенный Git с worktrees, branches и командами для повышения производительности разработки - ИИ Агенты","ar":"تعلم كيفية استخدام جيت المتقدم مع worktrees و branches وأوامر لتحسين إنتاجية التطوير - أدوات ذكاء اصطناعي"},"definition":{"en":"git-advanced is a set of Git tools that includes worktrees, allowing developers to work on multiple branches without stashing or committing work-in-progress.","zh":"Git高级工具是一种强大的代码管理工具，提供工作树和分支管理功能","ja":"Git Advancedは強力なコード管理ツールで、ワークツリーとブランチ管理機能を提供します","ko":"Git 고급 도구는 강력한 코드 관리 도구로 작업 트리와 분기 관리 기능을 제공합니다","es":"Git Avanzado es una herramienta que permite a los desarrolladores trabajar en múltiples ramas simultáneamente con worktrees","fr":"Git Avancé est un outil qui permet aux développeurs de travailler sur plusieurs branches simultanément avec des worktrees","de":"Erweitertes Git ist ein Tool, das es Entwicklern ermöglicht, an mehreren Zweigen gleichzeitig mit Worktrees zu arbeiten","pt":"O que é Git Avançado? É uma ferramenta de desenvolvimento que permite trabalhar com worktrees e branches","ru":"Что такое расширенный Git? Это инструмент разработки, который позволяет работать с worktrees и ветками - ИИ Агенты","ar":"ما هو جيت المتقدم؟ إنه أداة تطوير تتيح العمل مع worktrees و branches"},"features":{"en":["Creates worktrees for feature branches using `git worktree add` command","Supports creating worktrees with new branches using `-b` option","Lists all worktrees using `git worktree list` command","Removes worktrees after merging using `git worktree remove` command","Enables simultaneous work on multiple branches without stashing or committing","Uses Git commands for efficient branch management"],"zh":["工作树管理","分支管理","多分支同时开发","无需暂存和提交","工作树列表和删除","支持多种分支操作"],"ja":["ワークツリー管理","ブランチ管理","複数ブランチ同時開発","一時保存とコミット不要","ワークツリー一覧と削除","複数のブランチ操作をサポート"],"ko":["작업 트리 관리","분기 관리","다중 분기同時 개발","임시 저장과 커밋 불필요","작업 트리 목록과 삭제","다중 분기操作 지원"],"es":["Worktrees para trabajar en múltiples ramas simultáneamente","Comandos personalizados para mejorar el flujo de trabajo","Soporte para 135 agentes y 35 habilidades curadas","Integración con Claude Code para una experiencia de desarrollo más completa","Capacidad para crear y gestionar worktrees de manera eficiente","Compatibilidad con Git para una integración perfecta"],"fr":["Worktrees pour travailler sur plusieurs branches simultanément","Commandes personnalisées pour améliorer le flux de travail","Prise en charge de 135 agents et 35 compétences curator","Intégration avec Claude Code pour une expérience de développement plus complète","Capacité à créer et gérer des worktrees de manière efficace","Compatibilité avec Git pour une intégration parfaite"],"de":["Worktrees zum Arbeiten an mehreren Zweigen gleichzeitig","Benutzerdefinierte Befehle zur Verbesserung des Arbeitsablaufs","Unterstützung für 135 Agenten und 35 kuratierte Fähigkeiten","Integration mit Claude Code für eine umfassendere Entwicklungserfahrung","Fähigkeit, Worktrees effizient zu erstellen und zu verwalten","Kompatibilität mit Git für eine perfekte Integration"],"pt":["Crie worktrees para branches de recursos","Trabalhe com múltiplas branches simultaneamente","Use comandos como git worktree add e git worktree list","Remova worktrees após mesclar","Trabalhe com branches de hotfix","Use o Git Avançado com o CLI"],"ru":["Создайте worktrees для веток функций","Работайте с несколькими ветками одновременно","Используйте команды như git worktree add и git worktree list","Удалите worktrees после слияния","Работайте с ветками hotfix","Используйте расширенный Git с CLI - ИИ Агенты"],"ar":["أنشئ worktrees لفرع الميزات","اعمل مع عدة فروع في نفس الوقت","استخدم أوامر مثل git worktree add و git worktree list","أزل worktrees بعد الدمج","اعمل مع فروع الإصلاح السريع","استخدم جيت المتقدم مع CLI"]},"keywords":{"en":["how to use git-advanced","git-advanced worktree tutorial","git-advanced vs git basics","git-advanced install guide","what is git-advanced","git-advanced alternative tools","git-advanced setup for AI agents","git worktree management","git-advanced best practices"],"zh":["Git高级工具","工作树管理","分支管理","代码管理","开发效率","Git工作树","Git分支","AIエージェント工具"],"ja":["Git Advanced","ワークツリー管理","ブランチ管理","コード管理","開発効率","Gitワークツリー","Gitブランチ","AIエージェントツール"],"ko":["Git 고급 도구","작업 트리 관리","분기 관리","코드 관리","개발 효율","Git 작업 트리","Git 분기","AI에이전트 도구"],"es":["git avanzado","worktrees","comandos personalizados","claude code","desarrollo de software","herramientas de desarrollo","git para desarrolladores","mejora del flujo de trabajo","integración con git"],"fr":["git avancé","worktrees","commandes personnalisées","claude code","développement de logiciels","outils de développement","git pour développeurs","amélioration du flux de travail","intégration avec git"],"de":["erweitertes git","worktrees","benutzerdefinierte befehle","claude code","software-entwicklung","entwicklungstools","git für entwickler","verbesserung des arbeitsablaufs","integration mit git"],"pt":["git avançado","worktrees","branches","comandos git","desenvolvimento de software","ferramentas de desenvolvimento","CLI","git worktree add","git worktree list"],"ru":["расширенный git","worktrees","ветки","команды git","разработка программного обеспечения","инструменты разработки","CLI","git worktree add","git worktree list","ИИ Агенты"],"ar":["جيت متقدم","worktrees","فروع","أوامر جيت","تطوير البرمجيات","أدوات التطوير","CLI","git worktree add","git worktree list","أدوات ذكاء اصطناعي"]}},"owner":"rohitg00","repo":"awesome-claude-code-toolkit","repoPath":"rohitg00/awesome-claude-code-toolkit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.285Z","topics":[],"category":"community","skillMd":{"name":"git-advanced","description":"Advanced git workflows including worktrees, bisect, interactive rebase, hooks, and recovery techniques","bodyPreview":"# Git Advanced\n\n## Worktrees\n\n```bash\n# Create a worktree for a feature branch (avoids stashing)\ngit worktree add ../feature-auth feature/auth\n\n# Create a worktree with a new branch\ngit worktree add ../hotfix-123 -b hotfix/123 origin/main\n\n# List all worktrees\ngit worktree list\n\n# Remove a worktree after merging\ngit worktree remove ../feature-auth\n```\n\nWorktrees let you work on multiple branches simultaneously without stashing or committing WIP. Each worktree has its own working directory but sh","body":"# Git Advanced\n\n## Worktrees\n\n```bash\n# Create a worktree for a feature branch (avoids stashing)\ngit worktree add ../feature-auth feature/auth\n\n# Create a worktree with a new branch\ngit worktree add ../hotfix-123 -b hotfix/123 origin/main\n\n# List all worktrees\ngit worktree list\n\n# Remove a worktree after merging\ngit worktree remove ../feature-auth\n```\n\nWorktrees let you work on multiple branches simultaneously without stashing or committing WIP. Each worktree has its own working directory but shares the same `.git` repository.\n\n## Bisect\n\n```bash\n# Start bisect, mark current as bad and known good commit\ngit bisect start\ngit bisect bad HEAD\ngit bisect good v1.5.0\n\n# Git checks out a midpoint commit. Test it, then mark:\ngit bisect good   # if this commit works\ngit bisect bad    # if this commit is broken\n\n# Automate with a test script\ngit bisect start HEAD v1.5.0\ngit bisect run npm test\n\n# When done, reset\ngit bisect reset\n```\n\nBisect performs binary search across commits to find which commit introduced a bug. Automated bisect with `run` is the fastest approach.\n\n## Interactive Rebase\n\n```bash\n# Rebase last 5 commits interactively\ngit rebase -i HEAD~5\n\n# Common operations in the editor:\n# pick   - keep commit as-is\n# reword - change commit message\n# edit   - stop to amend the commit\n# squash - merge into previous commit, keep both messages\n# fixup  - merge into previous commit, discard this message\n# drop   - remove the commit entirely\n\n# Rebase feature branch onto latest main\ngit fetch origin\ngit rebase origin/main\n\n# Continue after resolving conflicts\ngit rebase --continue\n\n# Abort if things go wrong\ngit rebase --abort\n```\n\n## Git Hooks\n\n```bash\n#!/bin/sh\n# .git/hooks/pre-commit\n\n# Run linter on staged files only\nSTAGED_FILES=$(git diff --cached --name-only --diff-filter=d | grep -E ''\\.(ts|tsx|js|jsx)$'')\nif [ -n \"$STAGED_FILES\" ]; then\n  npx eslint $STAGED_FILES --fix\n  git add $STAGED_FILES\nfi\n```\n\n```bash\n#!/bin/sh\n# .git/hooks/commit-msg\n\n# Enforce conventional commit format\nCOMMIT_MSG=$(cat \"$1\")\nPATTERN=\"^(feat|fix|docs|style|refactor|test|chore)(\\(.+\\))?: .{1,72}$\"\n\nif ! echo \"$COMMIT_MSG\" | head -1 | grep -qE \"$PATTERN\"; then\n  echo \"Error: Commit message must follow Conventional Commits format\"\n  echo \"Example: feat(auth): add OAuth2 login flow\"\n  exit 1\nfi\n```\n\n```bash\n#!/bin/sh\n# .git/hooks/pre-push\n\n# Run tests before pushing\nnpm test\nif [ $? -ne 0 ]; then\n  echo \"Tests failed. Push aborted.\"\n  exit 1\nfi\n```\n\n## Recovery Techniques\n\n```bash\n# Undo last commit but keep changes staged\ngit reset --soft HEAD~1\n\n# Recover a deleted branch using reflog\ngit reflog\ngit checkout -b recovered-branch HEAD@{3}\n\n# Recover a file from a specific commit\ngit checkout abc1234 -- path/to/file.ts\n\n# Find lost commits (dangling after reset or rebase)\ngit fsck --lost-found\ngit show <dangling-commit-sha>\n\n# Undo a rebase\ngit reflog\ngit reset --hard HEAD@{5}  # point before rebase started\n```\n\n## Useful Aliases\n\n```bash\n# ~/.gitconfig\n[alias]\n  lg = log --graph --oneline --decorate --all\n  st = status -sb\n  co = checkout\n  unstage = reset HEAD --\n  last = log -1 HEAD --stat\n  branches = branch -a --sort=-committerdate\n  stash-all = stash push --include-untracked\n  conflicts = diff --name-only --diff-filter=U\n```\n\n## Anti-Patterns\n\n- Force-pushing to shared branches without `--force-with-lease`\n- Rebasing commits that have already been pushed and shared\n- Committing large binary files without Git LFS\n- Using `git add .` without reviewing `git diff --staged`\n- Not using `.gitignore` for build artifacts, dependencies, and secrets\n- Keeping long-lived feature branches instead of merging frequently\n\n## Checklist\n\n- [ ] Worktrees used for parallel branch work instead of stashing\n- [ ] `git bisect run` automates bug-finding with a test command\n- [ ] Interactive rebase cleans up commits before merging to main\n- [ ] Pre-commit hooks run linting on staged files\n- [ ] Commit message format enforced via commit-msg hook\n- [ ] `--force-with-lease` used instead of `--force` when force-pushing\n- [ ] Reflog consulted before any destructive operation\n- [ ] `.gitignore` covers build outputs, dependencies, and environment files\n"},"lastSynced":"2026-03-08T02:00:56.553Z","agentAnalysis":{"suitability":{"en":"Ideal for Version Control Agents needing simultaneous branch management capabilities with Git worktrees.","zh":"适用于需要使用Git worktrees进行同时分支管理的版本控制代理的理想选择。","ja":"Gitのworktreesを使用した同時ブランチ管理機能を必要とするバージョン管理エージェントに最適です。","ko":"Git worktrees를 사용하여 동시 분기 관리 기능이 필요한 버전 관리 에이전트에게 적합합니다.","es":"Ideal para agentes de control de versiones que necesitan capacidades de gestión de ramas simultáneas con Git worktrees.","fr":"Idéal pour les agents de contrôle de version nécessitant des capacités de gestion de branches simultanées avec Git worktrees.","de":"Ideal für Version Control Agents, die simultane Branch-Management-Funktionen mit Git worktrees benötigen.","pt":"Ideal para Agentes de Controle de Versão que precisam de capacidades de gerenciamento de branch simultâneo com Git worktrees.","ru":"Идеально для агентов контроля версий, требующих возможностей одновременного управления ветками с Git worktrees.","ar":"مثالي لعميليات التحكم في الإصدار التي تحتاج إلى إمكانيات إدارة الفرع المتزامن مع Git worktrees."},"recommendation":{"en":"Empowers agents to manage multiple Git branches simultaneously using worktrees, avoiding stashing or committing work-in-progress, and supports creating new branches with git worktree add, listing all worktrees with git worktree list, and removing worktrees after merging with git worktree remove.","zh":"赋予代理同时管理多个Git分支的能力，使用worktrees，避免暂存或提交工作进度，并支持使用git worktree add创建新分支，使用git worktree list列出所有worktrees，使用git worktree remove在合并后删除worktrees。","ja":"エージェントがworktreesを使用して複数のGitブランチを同時に管理できるようにし、作業中の変更を一時保存したりコミットしたりすることを避け、git worktree addで新しいブランチを作成し、git worktree listですべてのworktreesをリストし、git worktree removeでマージ後にworktreesを削除することをサポートします。","ko":"에이전트가 worktrees를 사용하여 여러 개의 Git 브랜치를 동시에 관리할 수 있도록 해주고, 작업 중인 파일을 임시 저장하거나 커밋하는 것을 피하며, git worktree add로 새로운 브랜치를 생성하고, git worktree list로 모든 worktrees를 나열하며, git worktree remove로 병합 후 worktrees를 삭제하는 것을 지원합니다.","es":"Habilita a los agentes a gestionar múltiples ramas de Git simultáneamente utilizando worktrees, evitando el almacenamiento temporal o el compromiso de trabajos en curso, y admite la creación de nuevas ramas con git worktree add, la lista de todos los worktrees con git worktree list y la eliminación de worktrees después de la fusión con git worktree remove.","fr":"Permet aux agents de gérer plusieurs branches Git simultanément à l''aide de worktrees, évitant ainsi le stockage temporaire ou l''engagement de travaux en cours, et prend en charge la création de nouvelles branches avec git worktree add, la liste de tous les worktrees avec git worktree list et la suppression des worktrees après fusion avec git worktree remove.","de":"Ermächtigt Agenten, mehrere Git-Branches simultan mit Worktrees zu verwalten, wodurch das Zwischenspeichern oder Committen von Arbeit in Bearbeitung vermieden wird, und unterstützt die Erstellung neuer Branches mit git worktree add, die Auflistung aller Worktrees mit git worktree list und die Entfernung von Worktrees nach der Zusammenführung mit git worktree remove.","pt":"Habilita os agentes a gerenciar várias branches do Git simultaneamente usando worktrees, evitando armazenar ou confirmar trabalho em andamento, e suporta a criação de novas branches com git worktree add, listando todos os worktrees com git worktree list e removendo worktrees após mesclagem com git worktree remove.","ru":"Наделяет агентов возможностью управлять несколькими ветками Git одновременно с помощью worktrees, избегая сохранения или фиксации работы в процессе, и поддерживает создание новых веток с git worktree add, перечисление всех worktrees с git worktree list и удаление worktrees после слияния с git worktree remove.","ar":"يمنح الوكلاء إمكانية إدارة عدة فروع Git في نفس الوقت باستخدام worktrees، وتجنب حفظ أو إرسال العمل قيد التنفيذ، ودعم إنشاء فروع جديدة مع git worktree add، وlisting جميع worktrees مع git worktree list، وإزالة worktrees بعد الدمج مع git worktree remove."},"useCases":{"en":["Creating separate worktrees for feature branches","Managing hotfix branches with isolated working directories","Listing and removing worktrees after merging or completion"],"zh":["为功能分支创建单独的worktrees","使用隔离的工作目录管理hotfix分支","在合并或完成后列出并删除worktrees"],"ja":["機能ブランチ用の個別のworktreesを作成する","隔離された作業ディレクトリを使用してホットフィックスブランチを管理する","マージまたは完了後にworktreesを列挙して削除する"],"ko":["기능 브랜치용 별도의 worktrees 생성","분리된 작업 디렉토리를 사용한 핫픽스 브랜치 관리","병합 또는 완료 후 worktrees 나열 및 삭제"],"es":["Crear worktrees separados para ramas de características","Gestionar ramas de correcciones con directorios de trabajo aislados","Listar y eliminar worktrees después de la fusión o finalización"],"fr":["Créer des worktrees séparés pour les branches de fonctionnalités","Gérer les branches de correction avec des répertoires de travail isolés","Lister et supprimer les worktrees après fusion ou achèvement"],"de":["Erstellen von separaten Worktrees für Funktionsbranchen","Verwalten von Hotfix-Branchen mit isolierten Arbeitsverzeichnissen","Auflisten und Entfernen von Worktrees nach Zusammenführung oder Abschluss"],"pt":["Criando worktrees separados para branches de recursos","Gerenciando branches de hotfix com diretórios de trabalho isolados","Listando e removendo worktrees após mesclagem ou conclusão"],"ru":["Создание отдельных worktrees для веток функций","Управление ветками hotfix с изолированными рабочими каталогами","Перечисление и удаление worktrees после слияния или завершения"],"ar":["إنشاء worktrees منفصلة لفروع الميزات","إدارة فروع الإصلاح السريع مع مديرلات العمل المعزولة","قائمة وازالة worktrees بعد الدمج أو الانتهاء"]},"limitations":{"en":["Requires Git version supporting worktrees","Limited to local repository management"],"zh":["需要支持worktrees的Git版本","仅限本地仓库管理"],"ja":["worktreesをサポートするGitバージョンが必要","ローカルリポジトリ管理のみ"],"ko":["worktrees를 지원하는 Git 버전 필요","로컬 저장소 관리만 지원"],"es":["Requiere una versión de Git que admita worktrees","Limitado a la gestión de repositorios locales"],"fr":["Nécessite une version de Git prenant en charge les worktrees","Limité à la gestion de référentiels locaux"],"de":["Benötigt eine Git-Version, die Worktrees unterstützt","Begrenzt auf die Verwaltung lokaler Repositorys"],"pt":["Requer Git na versão que suporta worktrees","Limitado ao gerenciamento de repositório local"],"ru":["Требует Git версии, поддерживающей worktrees","Ограничен управлением локальным репозиторием"],"ar":["يتطلب Git إصدار يدعم worktrees","محدود بالإدارة المحلية للمستودع"]},"version":4},"contentHash":"c73729b00678af678a364bd72b30661f292ba609f6167154e5f78a26c6e7c489","qualityScore":36}');
