INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('rohitg00/awesome-claude-code-toolkit/git-advanced', 'git-advanced', 'rohitg00', 'awesome-claude-code-toolkit', 'community', 'git-advanced rohitg00 awesome-claude-code-toolkit community git-advanced is a comprehensive toolkit for managing Git repositories, enabling developers to work on multiple branches simultaneously. It benefits AI agent developers by simplifying branch management. Git高级工具提供工作树和分支管理功能，帮助开发者高效管理代码 Git Advancedはワークツリーとブランチ管理機能を提供し、開発者の生産性を向上させます Git 고급 도구는 작업 트리와 분기 관리 기능을 제공하여 개발자의 생산성을 높입니다 El kit de herramientas más completo para Claude Code, que incluye 135 agentes y 35 habilidades curadas, con funcionalidades avanzadas de Git como worktrees Le kit d''outils le plus complet pour Claude Code, qui comprend 135 agents et 35 compétences curator, avec des fonctionnalités avancées de Git telles que les worktrees Das umfassendste Toolkit für Claude Code, das 135 Agenten und 35 kuratierte Fähigkeiten enthält, mit erweiterten Git-Funktionen wie Worktrees O Git Avançado é uma ferramenta poderosa para desenvolvedores, permitindo trabalhar com múltiplas branches simultaneamente Расширенный Git - это мощный инструмент для разработчиков, позволяющий работать с несколькими ветками одновременно - ИИ Агенты جيت المتقدم هو أداة قوية للمطورين، مما يسمح بالعمل مع عدة فروع في نفس الوقت - أدوات ذكاء اصطناعي how to use git-advanced git-advanced worktree tutorial git-advanced vs git basics git-advanced install guide what is git-advanced git-advanced alternative tools git-advanced setup for AI agents git worktree management git-advanced best practices Git高级工具 工作树管理 分支管理 代码管理 开发效率 Git工作树 Git分支 AIエージェント工具 Creates worktrees for feature branches using `git worktree add` command Supports creating worktrees with new branches using `-b` option Lists all worktrees using `git worktree list` command Removes worktrees after merging using `git worktree remove` command Enables simultaneous work on multiple branches without stashing or committing Uses Git commands for efficient branch management git-advanced is a set of Git tools that includes worktrees, allowing developers to work on multiple branches without stashing or committing work-in-progress.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('anam-org/metaxy/sybil', 'community', 'anam-org', 'metaxy', 'anam-org/metaxy', 'sybil', 0, 0, 36, '2026-03-08T01:57:15.293Z', '2026-03-08T02:01:06.411Z', 'bc0d0c5591e50dd9eacc9eefb6485210391b31709fc60637d41074bec302fa6b', '{"id":"anam-org/metaxy/sybil","name":"sybil","description":{"en":"Sybil provides pluggable sample-level metadata versioning for incremental multimodal pipelines, benefiting developers working with complex data pipelines. It validates code examples embedded in documentation and docstrings.","zh":"Sybil提供可插拔样本级元数据版本控制，用于增量多模态管道，支持pytest集成和文档测试","ja":"Sybilは、増分マルチモーダルパイプライン用のプラグ可能なサンプルレベルメタデータバージョニングを提供し、pytest統合とドキュメントテストをサポートします","ko":"Sybil은 증분 멀티모달 파이프라인을 위한 플러그 가능한 샘플 레벨 메타데이터 버저닝을 제공하며, pytest 통합과 문서 테스트를 지원합니다","es":"Sybil es una herramienta para la validación de metadatos de nivel de muestra en pipelines multimodales. Se integra con Pytest para validar código en documentación","fr":"Sybil est un outil pour la validation des métadonnées au niveau de l''échantillon dans les pipelines multimodaux. Il s''intègre avec Pytest pour valider le code dans la documentation","de":"Sybil ist ein Tool für die Validierung von Metadaten auf Sample-Ebene in inkrementalen Multimodal-Pipelines. Es integriert sich mit Pytest, um Code in Dokumentationen zu validieren","pt":"Sybil é uma ferramenta para gerenciar metadados de nível de amostra em pipelines multimodais incrementais. Ele valida código em documentação e docstrings.","ru":"Sybil — это инструмент для управления метаданными на уровне образцов в инкрементальных мультимодальных конвейерах. Он проверяет код в документации и docstrings для ИИ Агентов.","ar":"Sybil هو أداة لإدارة بيانات وصفية لمستويات العينة في خطوط أنابيب متعددة الحسائل المتزايدة. 그는 يتحقق من الكود في الوثائق و docstrings للأدوات الذكية."},"seo":{"title":{"en":"Sybil: Pluggable Metadata Versioning for AI Agents | Setu...","zh":"Sybil.setup指南：增量多模态管道的可插拔样本级元数据版本控制","ja":"Sybil設定ガイド：増分マルチモーダルパイプラインのプラグ可能なサンプルレベルメタデータバージョニング","ko":"Sybil 설정 가이드: 증분 멀티모달 파이프라인을 위한 플러그 가능한 샘플 레벨 메타데이터 버저닝","es":"Guía de configuración de Sybil para pipelines multimodales","fr":"Guide d''intégration de Sybil pour les pipelines multimodaux","de":"Sybil-Setup-Leitfaden für inkrementale Multimodal-Pipelines","pt":"Sybil: Guia de Configuração para Metadados de Nível de Am...","ru":"Sybil: Руководство по настройке метаданных на уровне обра...","ar":"Sybil: دليل إعداد بيانات وصفية لمستويات العينة للأدوات ال..."},"description":{"en":"Discover how to integrate Sybil for incremental multimodal pipelines. Learn to validate code examples and execute them with Pytest. Get started now!","zh":"了解Sybil的功能和特点，包括可插拔样本级元数据版本控制、pytest集成和文档测试，快速提升开发效率","ja":"Sybilの機能と特徴を紹介します。プラグ可能なサンプルレベルメタデータバージョニング、pytest統合、ドキュメントテストなどを使用して開発効率を向上させる","ko":"Sybil의 기능과 특징을 소개합니다. 플러그 가능한 샘플 레벨 메타데이터 버저닝, pytest 통합, 문서 테스트 등을 사용하여 개발 효율을 높이세요","es":"Descubre cómo Sybil valida metadatos de nivel de muestra para pipelines multimodales con Pytest y Python","fr":"Découvrez comment Sybil valide les métadonnées au niveau de l''échantillon pour les pipelines multimodaux avec Pytest et Python","de":"Erfahren Sie, wie Sybil Metadaten auf Sample-Ebene für inkrementale Multimodal-Pipelines mit Pytest und Python validiert","pt":"Aprenda a configurar o Sybil para gerenciar metadados de nível de amostra em pipelines multimodais incrementais","ru":"Узнайте, как настроить Sybil для управления метаданными на уровне образцов в инкрементальных мультимодальных конвейерах для ИИ Агентов","ar":"تعرف على كيفية ضبط Sybil لإدارة بيانات وصفية لمستويات العينة في خطوط أنابيب متعددة الحسائل المتزايدة للأدوات الذكية"},"definition":{"en":"Sybil is a pluggable sample-level metadata versioning system for incremental multimodal pipelines, enabling efficient validation and execution of code examples.","zh":"Sybil是一种AI工具，提供可插拔样本级元数据版本控制，用于增量多模态管道","ja":"Sybilは、AIエージェントの一種で、増分マルチモーダルパイプライン用のプラグ可能なサンプルレベルメタデータバージョニングを提供します","ko":"Sybil은 AI 에이전트의 일종으로, 증분 멀티모달 파이프라인을 위한 플러그 가능한 샘플 레벨 메타데이터 버저닝을 제공합니다","es":"Sybil es una herramienta de validación de metadatos para pipelines multimodales","fr":"Sybil est un outil de validation de métadonnées pour les pipelines multimodaux","de":"Sybil ist ein Tool zur Validierung von Metadaten für inkrementale Multimodal-Pipelines","pt":"Sybil é uma ferramenta de gerenciamento de metadados de nível de amostra para pipelines multimodais","ru":"Sybil — это инструмент управления метаданными на уровне образцов для мультимодальных конвейеров ИИ Агентов","ar":"Sybil هو أداة لإدارة بيانات وصفية لمستويات العينة في خطوط أنابيب متعددة الحسائل للأدوات الذكية"},"features":{"en":["Validates code examples embedded in documentation and docstrings","Supports Pytest integration for automated testing","Installs via pip with ''pip install sybil[pytest]'' command","Configures in conftest.py for seamless integration","Executes code examples as part of normal test runs","Provides official documentation at https://sybil.readthedocs.io/en/latest/"],"zh":["可插拔样本级元数据版本控制","pytest集成","文档测试","增量多模态管道支持","Python集成","CLI支持"],"ja":["プラグ可能なサンプルレベルメタデータバージョニング","pytest統合","ドキュメントテスト","増分マルチモーダルパイプラインサポート","Python統合","CLIサポート"],"ko":["플러그 가능한 샘플 레벨 메타데이터 버저닝","pytest 통합","문서 테스트","증분 멀티모달 파이프라인 지원","Python 통합","CLI 지원"],"es":["Validación de metadatos de nivel de muestra","Integración con Pytest para pruebas automatizadas","Compatibilidad con Python","Documentación y ejemplos de código","Instalación sencilla con pip","Configuración flexible en conftest.py"],"fr":["Validation des métadonnées au niveau de l''échantillon","Intégration avec Pytest pour les tests automatisés","Compatibilité avec Python","Documentation et exemples de code","Installation facile avec pip","Configuration flexible dans conftest.py"],"de":["Validierung von Metadaten auf Sample-Ebene","Integration mit Pytest für automatisierte Tests","Kompatibilität mit Python","Dokumentation und Code-Beispiele","Einfache Installation mit pip","Flexible Konfiguration in conftest.py"],"pt":["Validação de código em documentação e docstrings","Integração com Pytest","Suporte a metadados de nível de amostra em pipelines multimodais","Instalação via pip","Configuração em conftest.py"],"ru":["Проверка кода в документации и docstrings","Интеграция с Pytest","Поддержка метаданных на уровне образцов в мультимодальных конвейерах для ИИ Агентов","Установка через pip","Настройка в conftest.py"],"ar":["التحقق من الكود في الوثائق و docstrings","التكامل مع Pytest","دعم بيانات وصفية لمستويات العينة في خطوط أنابيب متعددة الحسائل للأدوات الذكية","التثبيت عبر pip","التكوين في conftest.py"]},"keywords":{"en":["how to use sybil","sybil documentation","sybil vs pytest","sybil install guide","what is sybil","sybil alternative","sybil setup tutorial","sybil and multimodal pipelines","sybil for AI agents","sybil pytest integration"],"zh":["Sybil","AI工具","可插拔样本级元数据版本控制","增量多模态管道","pytest集成","文档测试","Python开发","CLI支持"],"ja":["Sybil","AIエージェント","プラグ可能なサンプルレベルメタデータバージョニング","増分マルチモーダルパイプライン","pytest統合","ドキュメントテスト","Python開発","CLIサポート"],"ko":["Sybil","AI 에이전트","플러그 가능한 샘플 레벨 메타데이터 버저닝","증분 멀티모달 파이프라인","pytest 통합","문서 테스트","Python 개발","CLI 지원"],"es":["Sybil","pip install sybil","pytest integration","validación de metadatos","pipelines multimodales","documentación de Sybil","Sybil para desarrolladores","herramientas de AI para desarrolladores","Agentes de IA para pipelines"],"fr":["Sybil","pip install sybil","intégration pytest","validation de métadonnées","pipelines multimodaux","documentation de Sybil","Sybil pour les développeurs","outils d''IA pour les développeurs","Agents d''IA pour les pipelines"],"de":["Sybil","pip install sybil","Pytest-Integration","Validierung von Metadaten","inkrementale Multimodal-Pipelines","Sybil-Dokumentation","Sybil für Entwickler","AI-Tools für Entwickler","KI-Agents für Pipelines"],"pt":["Sybil","metadados de nível de amostra","pipelines multimodais","Pytest","documentação","docstrings","gerenciamento de metadados","ferramentas de desenvolvimento"],"ru":["Sybil","метаданные на уровне образцов","мультимодальные конвейеры","Pytest","документация","docstrings","управление метаданными","инструменты для разработки ИИ Агентов"],"ar":["Sybil","بيانات وصفية لمستويات العينة","خطوط أنابيب متعددة الحسائل","Pytest","الوثائق","docstrings","إدارة بيانات وصفية","أدوات تطوير الأدوات الذكية"]}},"owner":"anam-org","repo":"metaxy","repoPath":"anam-org/metaxy","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.293Z","topics":[],"category":"community","skillMd":{"name":"sybil","description":"Use Sybil for testing code examples in documentation and docstrings. Covers pytest integration, parsers, skip directives, and namespace management.","bodyPreview":"# Sybil Documentation Testing\n\nSybil validates code examples embedded in documentation and docstrings by parsing and executing them as part of normal test runs.\n\n**Official Documentation**: https://sybil.readthedocs.io/en/latest/\n\n## Installation\n\n```bash\npip install sybil[pytest]\n```\n\n## Pytest Integration\n\nConfigure in `conftest.py`. See [pytest integration docs](https://sybil.readthedocs.io/en/latest/integration.html#pytest-integration).\n\n```python\nfrom sybil import Sybil\nfrom sybil.parsers.m","body":"# Sybil Documentation Testing\n\nSybil validates code examples embedded in documentation and docstrings by parsing and executing them as part of normal test runs.\n\n**Official Documentation**: https://sybil.readthedocs.io/en/latest/\n\n## Installation\n\n```bash\npip install sybil[pytest]\n```\n\n## Pytest Integration\n\nConfigure in `conftest.py`. See [pytest integration docs](https://sybil.readthedocs.io/en/latest/integration.html#pytest-integration).\n\n```python\nfrom sybil import Sybil\nfrom sybil.parsers.markdown.codeblock import PythonCodeBlockParser\nfrom sybil.parsers.markdown.skip import SkipParser\n\npytest_collect_file = Sybil(\n    parsers=[\n        SkipParser(),\n        PythonCodeBlockParser(),\n    ],\n    patterns=[\"*.md\", \"**/*.py\"],\n).pytest()\n```\n\n### Sybil Parameters\n\nSee [API reference](https://sybil.readthedocs.io/en/latest/api.html#sybil.Sybil).\n\n| Parameter        | Description                                                     |\n| ---------------- | --------------------------------------------------------------- |\n| `parsers`        | Sequence of parser callables                                    |\n| `patterns`       | File glob patterns to include (e.g., `[\"*.md\", \"src/**/*.py\"]`) |\n| `excludes`       | File glob patterns to exclude                                   |\n| `setup`          | Callable receiving namespace dict, called before each document  |\n| `teardown`       | Callable receiving namespace dict, called after each document   |\n| `fixtures`       | List of pytest fixture names to inject into namespace           |\n| `document_types` | Map file extensions to Document classes                         |\n\n### Document Types\n\nSee [API reference](https://sybil.readthedocs.io/en/latest/api.html#documents).\n\n- **Default**: Parse entire file\n- `PythonDocument`: Import `.py` file as module, names available in namespace\n- `PythonDocStringDocument`: Parse only docstrings from `.py` files\n\n```python\nfrom sybil.document import PythonDocStringDocument\n\npytest_collect_file = Sybil(\n    parsers=[...],\n    patterns=[\"src/**/*.py\"],\n    document_types={\".py\": PythonDocStringDocument},\n).pytest()\n```\n\n### Fixtures\n\n```python\nimport pytest\nfrom sybil import Sybil\n\n\n@pytest.fixture\ndef my_fixture():\n    return {\"key\": \"value\"}\n\n\npytest_collect_file = Sybil(\n    parsers=[...],\n    patterns=[\"*.md\"],\n    fixtures=[\"my_fixture\"],  # Available in document namespace\n).pytest()\n```\n\n### Setup/Teardown\n\n```python\ndef sybil_setup(namespace):\n    namespace[\"helper\"] = lambda x: x * 2\n\n\ndef sybil_teardown(namespace):\n    pass  # Cleanup if needed\n\n\npytest_collect_file = Sybil(\n    parsers=[...],\n    setup=sybil_setup,\n    teardown=sybil_teardown,\n).pytest()\n```\n\n## Disable pytest''s Built-in Doctest\n\nAdd to `pyproject.toml` to prevent conflicts:\n\n```toml\n[tool.pytest.ini_options]\naddopts = \"-p no:doctest\"\n```\n\n## Markdown Parsers\n\nSee [Markdown parsers docs](https://sybil.readthedocs.io/en/latest/markdown.html).\n\n```python\nfrom sybil.parsers.markdown.codeblock import PythonCodeBlockParser, CodeBlockParser\nfrom sybil.parsers.markdown.skip import SkipParser\nfrom sybil.parsers.markdown.clear import ClearNamespaceParser\n```\n\n## Skip Directives\n\nSee [skip directive docs](https://sybil.readthedocs.io/en/latest/markdown.html#skipping-examples).\n\n**SkipParser must come before other parsers** to handle skip directives.\n\n````markdown\n<!-- skip: next -->\n\n```python\n# This example is skipped\n```\n````\n\n<!-- skip: next \"reason for skipping\" -->\n\n```python\n# Skipped and reported as skipped test with reason\n```\n\n<!-- skip: start -->\n\n```python\n# Multiple examples\n```\n\n```python\n# All skipped\n```\n\n<!-- skip: end -->\n\n<!-- skip: next if(condition_var) -->\n\n```python\n# Conditionally skipped based on namespace variable\n```\n\n````\n## Invisible Code Blocks\n\nSetup code that doesn''t render in documentation. See [invisible code blocks docs](https://sybil.readthedocs.io/en/latest/markdown.html#invisible-code-blocks).\n\n```markdown\n<!-- invisible-code-block: python\nsetup_var = \"hidden setup\"\n-->\n````\n\n## Clear Namespace\n\nReset the document namespace for isolation. See [clear namespace docs](https://sybil.readthedocs.io/en/latest/markdown.html#clearing-the-namespace).\n\n```markdown\n<!-- clear-namespace -->\n```\n\n## Custom Evaluators\n\nSee [evaluators API](https://sybil.readthedocs.io/en/latest/api.html#evaluators).\n\n```python\nfrom sybil.parsers.markdown.codeblock import CodeBlockParser\nfrom sybil.evaluators.python import PythonEvaluator\n\n# Custom evaluator with future imports\nevaluator = PythonEvaluator(future_imports=[\"annotations\"])\n\nparser = CodeBlockParser(language=\"python\", evaluator=evaluator)\n```\n\n## Running Sybil Tests\n\nSybil tests are collected like regular pytest tests. To run only Sybil tests:\n\n```bash\n# Run tests from specific directory containing documented code\npytest src/mypackage/ -v\n\n# Exclude regular tests, only run documentation examples\npytest docs/ -v\n```\n\nTo exclude Sybil tests from regular test runs, use pytest''s `--ignore` flag or configure `addopts` in `pyproject.toml`.\n\n## Example: Complete conftest.py\n\n```python\n\"\"\"Sybil configuration for docstring testing.\"\"\"\n\nfrom sybil import Sybil\nfrom sybil.document import PythonDocStringDocument\nfrom sybil.evaluators.python import PythonEvaluator\nfrom sybil.parsers.markdown.codeblock import CodeBlockParser\nfrom sybil.parsers.markdown.skip import SkipParser\n\nimport mypackage\n\n\ndef sybil_setup(namespace):\n    \"\"\"Pre-populate namespace for all examples.\"\"\"\n    namespace[\"pkg\"] = mypackage\n\n\ndef sybil_teardown(namespace):\n    \"\"\"Cleanup after document.\"\"\"\n    pass\n\n\npytest_collect_file = Sybil(\n    parsers=[\n        SkipParser(),\n        CodeBlockParser(language=\"python\", evaluator=PythonEvaluator()),\n        CodeBlockParser(language=\"py\", evaluator=PythonEvaluator()),\n    ],\n    patterns=[\"src/mypackage/**/*.py\"],\n    document_types={\".py\": PythonDocStringDocument},\n    setup=sybil_setup,\n    teardown=sybil_teardown,\n    excludes=[\n        \"**/tests/**\",\n        \"**/_internal/**\",\n    ],\n).pytest()\n```\n"},"lastSynced":"2026-03-08T02:01:06.411Z","agentAnalysis":{"suitability":{"en":"Perfect for Python Development Agents needing advanced code validation and metadata versioning for incremental multimodal pipelines.","zh":"非常适合需要高级代码验证和元数据版本控制的用于增量多模式管道的Python开发代理。","ja":"Python開発エージェントが高度なコード検証とメタデータのバージョニングを必要とする場合に最適です。증分的多モーダルパイプライン。","ko":"고급 코드 유효성 검사 및 메타데이터 버전 관리가 필요한 파이썬 개발 에이전트에 적합합니다. 증분 멀티모달 파이프라인","es":"Perfecto para agentes de desarrollo de Python que necesitan una validación de código avanzada y una versión de metadatos para pipelines multimodales incrementales.","fr":"Parfait pour les agents de développement Python nécessitant une validation de code avancée et une version de métadonnées pour les pipelines multimodaux incrémentiels.","de":"Perfekt für Python-Entwicklungsagenten, die eine erweiterte Code-Validierung und eine Metadaten-Versionierung für inkrementelle multimodale Pipelines benötigen.","pt":"Perfeito para Agentes de Desenvolvimento Python que necessitam de validação de código avançada e versionamento de metadados para pipelines multimodais incrementais.","ru":"Идеально подходит для агентов разработки Python, которым требуются продвинутая проверка кода и версионирование метаданных для инкрементальных мульти-модальных конвейеров.","ar":"مثالي للعميلاء التطويرية بايثون التي تحتاج إلى التحقق من صحة الكود المتقدم وإصدار البيانات الوصفية للخطوط الأنابيب متعددة التحكم المتزايدة."},"recommendation":{"en":"Empowers agents to validate code examples embedded in documentation and docstrings using pytest integration, providing pluggable sample-level metadata versioning for complex data pipelines with libraries like Sybil and protocols such as incremental multimodal pipelines.","zh":"赋予代理验证文档和文档字符串中嵌入的代码示例的能力，使用pytest集成，并为复杂的数据管道提供可插拔的样本级元数据版本控制，例如使用Sybil和增量多模式管道等协议。","ja":"エージェントに、ドキュメントとドキュメント文字列に埋め込まれたコード例を検証する機能を提供します。Pytest統合を使用し、Sybilやインクリメンタルマルチモーダルパイプラインなどのプロトコルを使用する複雑なデータパイプラインに、プログラム可能なサンプルレベルのメタデータバージョニングを提供します。","ko":"에이전트가 문서 및 문서 문자열에 포함 된 코드 예를 검증 할 수 있는 기능을 제공합니다. pytest 통합을 사용하여 Sybil 및 증분 멀티 모드 파이프 라인과 같은 프로토콜을 사용하는 복잡한 데이터 파이프 라인에 대한 プログラム 가능한 샘플 수준의 메타 데이터 버전 관리를 제공합니다.","es":"Habilita a los agentes a validar ejemplos de código incrustados en la documentación y cadenas de documentación utilizando la integración de pytest, proporcionando una versión de metadatos a nivel de muestra configurable para pipelines de datos complejos con bibliotecas como Sybil y protocolos como pipelines multimodales incrementales.","fr":"Permet aux agents de valider les exemples de code intégrés dans la documentation et les docstrings en utilisant l''intégration de pytest, fournissant une version de métadonnées au niveau de l''échantillon configurable pour les pipelines de données complexes avec des bibliothèques comme Sybil et des protocoles tels que les pipelines multimodaux incrémentiels.","de":"Ermächtigt Agenten, Code-Beispiele in der Dokumentation und Docstrings mithilfe der pytest-Integration zu validieren und bietet eine konfigurierbare Metadaten-Version auf Sample-Ebene für komplexe Daten-Pipelines mit Bibliotheken wie Sybil und Protokollen wie inkrementelle multimodale Pipelines.","pt":"Habilita os agentes a validar exemplos de código incorporados na documentação e docstrings usando a integração pytest, fornecendo versionamento de metadados de nível de amostra para pipelines de dados complexos com bibliotecas como Sybil e protocolos como pipelines multimodais incrementais.","ru":"Наделяет агентов возможностью проверять примеры кода, встроенные в документацию и docstrings, используя интеграцию pytest, обеспечивая версионирование метаданных на уровне выборки для сложных конвейеров данных с библиотеками, такими как Sybil, и протоколами, такими как инкрементальные мульти-модальные конвейеры.","ar":"يمنح الوكيل القدرة على التحقق من صحة أمثلة الكود المضمنة في الوثائق وdocstrings باستخدام دمج pytest، وتوفير إصدار البيانات الوصفية على مستوى العينة للخطوط الأنابيب المعقدة للبيانات مع المكتبات مثل Sybil والبروتوكولات مثل خطوط الأنابيب متعددة التحكم المتزايدة."},"useCases":{"en":["Validating code examples in documentation","Executing embedded code as part of test runs","Parsing and testing docstrings for accuracy"],"zh":["验证文档中的代码示例","作为测试运行的一部分执行嵌入代码","解析和测试文档字符串以确保准确性"],"ja":["ドキュメント内のコード例の検証","テスト実行の一部として埋め込まれたコードの実行","ドキュメント文字列の解析と精度のテスト"],"ko":["문서의 코드 예제의 유효성 검사","테스트 실행의 일부로 포함 된 코드의 실행","문서 문자열의 구문 분석 및 정확도 테스트"],"es":["Validar ejemplos de código en la documentación","Ejecutar código incrustado como parte de las ejecuciones de pruebas","Analizar y probar cadenas de documentación para precisión"],"fr":["Valider les exemples de code dans la documentation","Exécuter le code intégré dans le cadre des exécutions de test","Analyser et tester les docstrings pour l''exactitude"],"de":["Code-Beispiele in der Dokumentation validieren","Incorporierten Code als Teil von Testläufen ausführen","Docstrings analysieren und auf Genauigkeit testen"],"pt":["Validar exemplos de código na documentação","Executar código incorporado como parte das execuções de teste","Analizar e testar docstrings para precisão"],"ru":["Проверка примеров кода в документации","Выполнение встроенного кода в качестве части запусков тестов","Парсинг и тестирование docstrings на точность"],"ar":["التحقق من صحة أمثلة الكود في الوثائق","تشغيل الكود المضمن كجزء من تشغيل الاختبارات","تحليل واختبار docstrings على الدقة"]},"limitations":{"en":["Requires pytest installation","Python environment needed","Limited to Python-based projects"],"zh":["需要pytest安装","需要Python环境","仅限Python基于项目"],"ja":["Pytestのインストールが必要","Python環境が必要","Pythonベースのプロジェクトのみ"],"ko":["pytest 설치가 필요합니다","파이썬 환경이 필요합니다","파이썬 기반 프로젝트에만 제한"],"es":["Requiere la instalación de pytest","Se necesita un entorno de Python","Limitado a proyectos basados en Python"],"fr":["Nécessite l''installation de pytest","Un environnement Python est nécessaire","Limité aux projets basés sur Python"],"de":["Benötigt die Installation von pytest","Ein Python-Umgebung ist erforderlich","Begrenzt auf Python-basierte Projekte"],"pt":["Requer instalação do pytest","Ambiente Python necessário","Limitado a projetos baseados em Python"],"ru":["Требуется установка pytest","Необходимо окружение Python","Ограничен проектами на основе Python"],"ar":["يتطلب تثبيت pytest","بيئة بايثو