INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('anam-org/metaxy/sybil', 'sybil', 'anam-org', 'metaxy', 'community', 'sybil anam-org metaxy community Sybil provides pluggable sample-level metadata versioning for incremental multimodal pipelines, benefiting developers working with complex data pipelines. It validates code examples embedded in documentation and docstrings. Sybil提供可插拔样本级元数据版本控制，用于增量多模态管道，支持pytest集成和文档测试 Sybilは、増分マルチモーダルパイプライン用のプラグ可能なサンプルレベルメタデータバージョニングを提供し、pytest統合とドキュメントテストをサポートします Sybil은 증분 멀티모달 파이프라인을 위한 플러그 가능한 샘플 레벨 메타데이터 버저닝을 제공하며, pytest 통합과 문서 테스트를 지원합니다 Sybil es una herramienta para la validación de metadatos de nivel de muestra en pipelines multimodales. Se integra con Pytest para validar código en documentación Sybil est un outil pour la validation des métadonnées au niveau de l''échantillon dans les pipelines multimodaux. Il s''intègre avec Pytest pour valider le code dans la documentation Sybil ist ein Tool für die Validierung von Metadaten auf Sample-Ebene in inkrementalen Multimodal-Pipelines. Es integriert sich mit Pytest, um Code in Dokumentationen zu validieren Sybil é uma ferramenta para gerenciar metadados de nível de amostra em pipelines multimodais incrementais. Ele valida código em documentação e docstrings. Sybil — это инструмент для управления метаданными на уровне образцов в инкрементальных мультимодальных конвейерах. Он проверяет код в документации и docstrings для ИИ Агентов. Sybil هو أداة لإدارة بيانات وصفية لمستويات العينة في خطوط أنابيب متعددة الحسائل المتزايدة. 그는 يتحقق من الكود في الوثائق و docstrings للأدوات الذكية. how to use sybil sybil documentation sybil vs pytest sybil install guide what is sybil sybil alternative sybil setup tutorial sybil and multimodal pipelines sybil for AI agents sybil pytest integration Sybil AI工具 可插拔样本级元数据版本控制 增量多模态管道 pytest集成 文档测试 Python开发 CLI支持 Validates code examples embedded in documentation and docstrings Supports Pytest integration for automated testing Installs via pip with ''pip install sybil[pytest]'' command Configures in conftest.py for seamless integration Executes code examples as part of normal test runs Provides official documentation at https://sybil.readthedocs.io/en/latest/ Sybil is a pluggable sample-level metadata versioning system for incremental multimodal pipelines, enabling efficient validation and execution of code examples.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Screenly/Playground/create-an-edge-app', 'community', 'Screenly', 'Playground', 'Screenly/Playground', 'create-an-edge-app', 0, 0, 36, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:12.439Z', '1cefe8a16e7489b368893c63be6be98e7eb8d2dea595ee6ae193c68ad4d045cd', '{"id":"Screenly/Playground/create-an-edge-app","name":"create-an-edge-app","description":{"en":"The create-an-edge-app skill provides developers with examples and guidance on using Screenly and its API to create Edge Apps. It benefits developers looking to build custom Edge Apps","zh":"使用Screenly和API创建Edge应用，包括使用bun create模板和Figma设计","ja":"ScreenlyとAPIエージェントを使用してEdgeアプリケーションを作成します","ko":"Screenly와 API를 사용하여 Edge 애플리케이션을 생성합니다 - bun create 템플릿 및 Figma 디자인 사용","es":"Crear aplicaciones Edge con Screenly y su API es fácil. Sigue nuestros ejemplos y mejores prácticas para empezar","fr":"Créer des applications Edge avec Screenly et son API est simple. Suivez nos exemples et meilleures pratiques pour commencer","de":"Das Erstellen von Edge-Anwendungen mit Screenly und seiner API ist einfach. Folgen Sie unseren Beispielen und Best Practices, um loszulegen","pt":"Criar um aplicativo de borda com Screenly envolve scaffold com `bun create` e configuração de `screenly.yml`","ru":"Создание приложения Edge с Screenly включает в себя создание каркаса с помощью `bun create` и настройку `screenly.yml`","ar":"إنشاء تطبيق حافي مع Screenly يتضمن إنشاء هيكل باستخدام `bun create` وتكوين `screenly.yml`"},"seo":{"title":{"en":"create-an-edge-app: Edge App Setup Guide | AI Agent Skill","zh":"创建Edge应用 Setup Guide - 使用Screenly和API","ja":"Edgeアプリケーションを作成するためのBest Practices - ScreenlyとAPIエージェント","ko":"Edge 애플리케이션 생성 가이드 - Screenly와 API를 사용하여","es":"Guía de configuración de create-an-edge-app con Screenly","fr":"Guide de mise en place de create-an-edge-app avec Screenly","de":"Ein