INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Screenly/Playground/create-an-edge-app', 'create-an-edge-app', 'Screenly', 'Playground', 'community', 'create-an-edge-app Screenly Playground community The create-an-edge-app skill provides developers with examples and guidance on using Screenly and its API to create Edge Apps. It benefits developers looking to build custom Edge Apps 使用Screenly和API创建Edge应用，包括使用bun create模板和Figma设计 ScreenlyとAPIエージェントを使用してEdgeアプリケーションを作成します Screenly와 API를 사용하여 Edge 애플리케이션을 생성합니다 - bun create 템플릿 및 Figma 디자인 사용 Crear aplicaciones Edge con Screenly y su API es fácil. Sigue nuestros ejemplos y mejores prácticas para empezar Créer des applications Edge avec Screenly et son API est simple. Suivez nos exemples et meilleures pratiques pour commencer Das Erstellen von Edge-Anwendungen mit Screenly und seiner API ist einfach. Folgen Sie unseren Beispielen und Best Practices, um loszulegen Criar um aplicativo de borda com Screenly envolve scaffold com `bun create` e configuração de `screenly.yml` Создание приложения Edge с Screenly включает в себя создание каркаса с помощью `bun create` и настройку `screenly.yml` إنشاء تطبيق حافي مع Screenly يتضمن إنشاء هيكل باستخدام `bun create` وتكوين `screenly.yml` how to create an edge app create-an-edge-app setup guide create-an-edge-app alternative create-an-edge-app vs screenly create-an-edge-app install what is create-an-edge-app create-an-edge-app tutorial create-an-edge-app api documentation create-an-edge-app examples Edge应用创建 Screenly API bun create模板 Figma设计 kebab-case命名约定 Edge应用开发 AIエージェント Edge应用Setup Guide Scaffolds new Edge Apps using the bun create template Supports kebab-case naming convention for app names Requires adding an id field to screenly.yml and screenly_qc.yml Integrates with Figma designs for implementation guidance Utilizes the bun run dev command for development create-an-edge-app is a skill that enables developers to create Edge Apps using Screenly''s API and the bun create template');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('johnlindquist/script-kit-next/script-kit-logging', 'community', 'johnlindquist', 'script-kit-next', 'johnlindquist/script-kit-next', 'script-kit-logging', 0, 0, 36, '2026-03-08T01:57:15.296Z', '2026-03-08T02:01:14.488Z', 'f555a4ec8b9f968edefbc45d247f1e7bd9b7509aa36e2e637a0d305bd4a36fea', '{"id":"johnlindquist/script-kit-next/script-kit-logging","name":"script-kit-logging","description":{"en":"script-kit-logging provides structured logging patterns for debugging and observability, benefiting developers working with Rust and GPUI. It offers a compact stderr format for efficient log analysis.","zh":"脚本工具包日志记录提供结构化日志模式，用于调试和可观察性，支持Compact stderr格式和多种日志类别","ja":"Script Kit Loggingは構造化ログパターンを提供し、デバッグと観察性を高め、Compact stderr形式と多種多様なログカテゴリをサポート","ko":"스크립트 키트 로깅은 구조화된 로그 패턴을 제공하여 디버깅과 관찰성을 높이고 Compact stderr 형식 및 다양한 로그 카테고리를 지원","es":"Script Kit Logging es un patrón de registro estructurado para la depuración y observabilidad en proyectos de IA, implementado con Rust y GPUI","fr":"Script Kit Logging est un modèle de journalisation structuré pour le débogage et l''observabilité dans les projets d''IA, mis en œuvre avec Rust et GPUI","de":"Script Kit Logging ist ein strukturiertes Protokollmuster für die Fehlersuche und Überwachung in KI-Projekten, implementiert mit Rust und GPUI","pt":"O Script Kit Logging é uma ferramenta de registro estruturado para depuração e observabilidade, escrita em Rust e utilizando o framework GPUI","ru":"Script Kit Logging - это инструмент структурированного логирования для отладки и наблюдаемости, написанный на Rust и использующий фреймворк GPUI для ИИ Агентов","ar":"Script Kit Logging هو أداة تسجيل متوافرة لعمليات التصحيح والإشراف، مكتوبة بلغة Rust و تستخدم إطار GPUI لعمليات الإعداد الآلية"},"seo":{"title":{"en":"script-kit-logging: Structured Logging Setup Guide | AI A...","zh":"脚本工具包日志记录最佳实践 - AI工具","ja":"Script Kit Loggingセットアップガイド - AIエージェント","ko":"스크립트 키트 로깅 설정 가이드 - AI 에이전트","es":"Guía de configuración de script-kit-logging para agentes ...","fr":"Guide de mise en œuvre de script-kit-logging pour les out...","de":"Einrichtungsleitfaden für script-kit-logging in KI-Agenten","pt":"Guia de Configuração do Script Kit Logging com Rust e GPUI","ru":"Настройка Script Kit Logging с Rust и GPUI: ИИ Агенты","ar":"دليل إعداد Script Kit Logging مع Rust و GPUI لعمليات الإع..."},"description":{"en":"Unlock efficient debugging with script-kit-logging. Discover how to set up compact log modes and utilize categories like position, app, and UI for enhanced o...","zh":"了解脚本工具包日志记录的技术细节，实现结构化日志模式，提高调试和可观察性","ja":"Script Kit Loggingの技術的な詳細を学び、構造化ログパターンを実現し、デバッグと観察性を高める","ko":"스크립트 키트 로깅의 기술적인 세부사항을 익히고 구조화된 로그 패턴을 구현하여 디버깅과 관찰성을 높여라","es":"Aprende a configurar script-kit-logging para mejorar la depuración y la observabilidad en tus proyectos de IA con patrones de registro estructurados","fr":"Découvrez comment configurer script-kit-logging pour améliorer le débogage et l''observabilité dans vos projets d''IA avec des modèles de journalisation struct...","de":"Erfahren Sie, wie Sie script-kit-logging einrichten, um die Fehlersuche und Überwachung in Ihren KI-Projekten mit strukturierten Protokollmustern zu verbessern","pt":"Aprenda a configurar o Script Kit Logging com Rust e GPUI para melhorar a depuração e observabilidade em suas aplicações","ru":"Узнайте, как настроить Script Kit Logging с Rust и GPUI для улучшения отладки и наблюдаемости в ваших приложениях с помощью ИИ Агентов","ar":"تعرف على كيفية إعداد Script Kit Logging مع Rust و GPUI لتحسين عمليات التصحيح والإشراف في تطبيقاتك باستخدام أدوات الإعداد الآلي"},"definition":{"en":"script-kit-logging is a Rust-based logging framework using GPUI, offering structured logging patterns for improved debugging and observability","zh":"脚本工具包日志记录是一种结构化日志模式，用于调试和可观察性","ja":"Script Kit Loggingはデバッグと観察性のための構造化ログパターン","ko":"스크립트 키트 로깅은 디버깅과 관찰성을 위한 구조화된 로그 패턴","es":"Script Kit Logging es un patrón de registro que proporciona una forma estructurada de registrar eventos en proyectos de IA","fr":"Script Kit Logging est un modèle de journalisation qui fournit une façon structurée d''enregistrer des événements dans les projets d''IA","de":"Script Kit Logging ist ein Protokollmuster, das eine strukturierte Methode zur Aufzeichnung von Ereignissen in KI-Projekten bietet","pt":"O que é Script Kit Logging? É uma ferramenta de registro estruturado para depuração e observabilidade","ru":"Что такое Script Kit Logging? Это инструмент структурированного логирования для отладки и наблюдаемости","ar":"ما هو Script Kit Logging؟ هو أداة تسجيل متوافرة لعمليات التصحيح والإشراف"},"features":{"en":["Compact stderr format: `SS.mmm|L|C|message` for efficient log analysis","Supports AI Compact Log Mode (SCRIPT_KIT_AI_LOG=1) for reduced log verbosity","Utilizes categories like position (P), app (A), UI (U), and stdin (S) for log organization","Includes log levels: INFO (i), WARN (w), ERROR (e), DEBUG (d), and TRACE (t) for flexible logging","Offers visibility into execution (E), key (K), focus (F), and theme (T) for enhanced debugging"],"zh":["支持Compact stderr格式","多种日志类别，包括位置、应用、UI、stdin、热键等","结构化日志模式，用于调试和可观察性","使用Rust和GPUI（Zed的UI框架）重写","支持AI Compact Log Mode（SCRIPT_KIT_AI_LOG=1）"],"ja":["Compact stderr形式のサポート","多種多様なログカテゴリ，位置、应用、UI、stdin、ホットキー等","構造化ログパターン，デバッグと観察性のため","RustとGPUI（ZedのUIフレームワーク）で書き直し","AI Compact Log Mode（SCRIPT_KIT_AI_LOG=1）のサポート"],"ko":["Compact stderr 형식 지원","다양한 로그 카테고리, 위치, 애플리케이션, UI, stdin, 핫키 등","구조화된 로그 패턴, 디버깅과 관찰성을 위한","Rust와 GPUI（Zed의 UI 프레임워크）로 다시 작성","AI Compact Log Mode（SCRIPT_KIT_AI_LOG=1） 지원"],"es":["Registro compacto en stderr con formato personalizable","Soporte para categorías de registro como posición, aplicación y UI","Niveles de registro ajustables, incluyendo INFO, WARN, ERROR, DEBUG y TRACE","Compatibilidad con Rust y GPUI para una implementación eficiente","Modo de registro compacto para AI con la variable de entorno SCRIPT_KIT_AI_LOG","Registro de eventos con categorías como visibilidad, ejecución y enfoque"],"fr":["Journalisation compacte en stderr avec format personnalisable","Prise en charge de catégories de journalisation telles que position, application et UI","Niveaux de journalisation ajustables, incluant INFO, WARN, ERROR, DEBUG et TRACE","Compatibilité avec Rust et GPUI pour une mise en œuvre efficace","Mode de journalisation compact pour l''IA avec la variable d''environnement SCRIPT_KIT_AI_LOG","Journalisation d''événements avec des catégories telles que visibilité, exécution et focus"],"de":["Kompaktes Protokollieren in stderr mit anpassbarem Format","Unterstützung für Protokollkategorien wie Position, Anwendung und Benutzeroberfläche","Einstellbare Protokollniveaus, einschließlich INFO, WARN, ERROR, DEBUG und TRACE","Kompatibilität mit Rust und GPUI für eine effiziente Implementierung","Kompaktes Protokollmodus für KI mit der Umgebungsvariable SCRIPT_KIT_AI_LOG","Protokollieren von Ereignissen mit Kategorien wie Sichtbarkeit, Ausführung und Fokus"],"pt":["Registro estruturado com formato compacto de stderr","Categorias de registro personalizáveis, como posição, app e UI","Níveis de log personalizáveis, como INFO, WARN, ERROR e DEBUG","Suporte ao modo de log compacto do AI","Integração com o framework GPUI para interface de usuário"],"ru":["Структурированное логирование с компактным форматом stderr","Настраиваемые категории логирования, такие как позиция, приложение и UI","Настраиваемые уровни логирования, такие как INFO, WARN, ERROR и DEBUG","Поддержка компактного режима логирования ИИ","Интеграция с фреймворком GPUI для интерфейса пользователя"],"ar":["تسجيل متوافق مع تنسيق stderr المضغوط","فئات تسجيل قابلة للتعديل، مثل الموقع والتطبيق وواجهة المستخدم","مستويات تسجيل قابلة للتعديل، مثل INFO و WARN و ERROR و DEBUG","دعم وضع تسجيل مضغوط للعمليات الآلية","التكامل مع إطار GPUI لواجهة المستخدم"]},"keywords":{"en":["how to use script-kit-logging","script-kit-logging setup guide","what is script-kit-logging","script-kit-logging alternative","script-kit-logging vs log4j","script-kit-logging install","rust logging frameworks","GPUI logging tools","structured logging patterns"],"zh":["脚本工具包日志记录","AI工具","结构化日志模式","调试","可观察性","Rust","GPUI","Zed的UI框架"],"ja":["Script Kit Logging","AIエージェント","構造化ログパターン","デバッグ","観察性","Rust","GPUI","ZedのUIフレームワーク"],"ko":["스크립트 키트 로깅","AI 에이전트","구조화된 로그 패턴","디버깅","관찰성","Rust","GPUI","Zed의 UI 프레임워크"],"es":["script-kit-logging","agentes de IA","registro estructurado","depuración","observabilidad","Rust","GPUI","registro compacto","categorías de registro","niveles de registro"],"fr":["script-kit-logging","outils d''IA","journalisation structurée","débogage","observabilité","Rust","GPUI","journalisation compacte","catégories de journalisation","niveaux de journalisation"],"de":["script-kit-logging","KI-Agenten","strukturierte Protokolle","Fehlersuche","Überwachung","Rust","GPUI","kompaktes Protokollieren","Protokollkategorien","Protokollniveaus"],"pt":["Script Kit Logging","Rust","GPUI","registro estruturado","depuração","observabilidade","log compacto","modo de log do AI"],"ru":["Script Kit Logging","Rust","GPUI","структурированное логирование","отладка","наблюдаемость","компактный лог","режим логирования ИИ","ИИ Агенты"],"ar":["Script Kit Logging","Rust","GPUI","تسجيل متوافق","عمليات التصحيح","الإشراف","سجل مضغوط","وضع تسجيل العمليات الآلية","أدوات الإعداد الآلي"]}},"owner":"johnlindquist","repo":"script-kit-next","repoPath":"johnlindquist/script-kit-next","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.296Z","topics":[],"category":"community","skillMd":{"name":"script-kit-logging","description":"Logging and observability patterns for Script Kit GPUI. Use when adding logs, debugging, or understanding the logging system. Covers JSONL format, compact AI log mode, correlation IDs, and error handling.","bodyPreview":"# Script Kit Logging\n\nStructured logging patterns for debugging and observability.\n\n## AI Compact Log Mode (SCRIPT_KIT_AI_LOG=1)\n\nCompact stderr format: `SS.mmm|L|C|message`\n\n- `L`: `i` INFO, `w` WARN, `e` ERROR, `d` DEBUG, `t` TRACE\n- `C` categories:\n  - `P` position, `A` app, `U` UI, `S` stdin, `H` hotkey\n  - `V` visibility, `E` exec, `K` key, `F` focus, `T` theme\n  - `C` cache, `R` perf, `W` window_mgr, `X` error\n  - `M` mouse_hover, `L` scroll_state, `Q` scroll_perf\n  - `D` design, `B` scrip","body":"# Script Kit Logging\n\nStructured logging patterns for debugging and observability.\n\n## AI Compact Log Mode (SCRIPT_KIT_AI_LOG=1)\n\nCompact stderr format: `SS.mmm|L|C|message`\n\n- `L`: `i` INFO, `w` WARN, `e` ERROR, `d` DEBUG, `t` TRACE\n- `C` categories:\n  - `P` position, `A` app, `U` UI, `S` stdin, `H` hotkey\n  - `V` visibility, `E` exec, `K` key, `F` focus, `T` theme\n  - `C` cache, `R` perf, `W` window_mgr, `X` error\n  - `M` mouse_hover, `L` scroll_state, `Q` scroll_perf\n  - `D` design, `B` script, `N` config, `Z` resize\n\nExample:\n- Standard: `... INFO ... Selected display origin=(0,0)`\n- Compact: `13.150|i|P|Selected display origin=(0,0)`\n\nEnable:\n```bash\nSCRIPT_KIT_AI_LOG=1 ./target/debug/script-kit-gpui 2>&1\n```\n\n## Log Modes\n\n| Mode | Command | Use Case |\n|------|---------|----------|\n| Compact AI logs | `SCRIPT_KIT_AI_LOG=1` | Default for AI agents (saves ~70% tokens) |\n| Full debug logs | `RUST_LOG=debug` | Deep debugging |\n| Specific module | `RUST_LOG=script_kit::theme=debug` | Target one module |\n\n## JSONL Logging\n\nLogs to: `~/.scriptkit/logs/script-kit-gpui.jsonl`\n\nLine example:\n```json\n{\"timestamp\":\"...\",\"level\":\"INFO\",\"target\":\"script_kit::executor\",\"message\":\"Script executed\",\"fields\":{\"script_name\":\"hello.ts\",\"duration_ms\":142,\"exit_code\":0}}\n```\n\n## Tracing Patterns\n\nUse `tracing` + `tracing-subscriber`:\n- `#[instrument]` for spans\n- Record `duration_ms`; warn if slow (e.g. >100ms)\n\nCorrelation IDs:\n- Generate UUID per user action/run\n- Attach to spans so nested logs inherit it\n\nRequired fields when relevant: `correlation_id`, `duration_ms`, `bead_id`, `agent_name`, `files_touched`\n\n## Log Level Guide\n\n- `error`: failure\n- `warn`: unexpected but handled\n- `info`: key events\n- `debug`: development\n- `trace`: very verbose\n\nFilter by targets (module paths): `script_kit::ui`, `script_kit::executor`, `script_kit::theme`\n\n## Error Handling\n\n- Application errors: `anyhow::Result`; add `.context()` at boundaries\n- Domain/library errors: `thiserror` when callers match variants\n- User-facing errors: `NotifyResultExt` → log first (`tracing::error!`) then toast\n\nBest practices:\n- Don''t `unwrap()`/`expect()`\n- Add context at each level (\"which file?\", \"what operation?\")\n- Use typed fields in logs (avoid interpolated strings)\n\n## Log Queries\n\n```bash\ngrep ''\"correlation_id\":\"abc-123\"'' ~/.scriptkit/logs/script-kit-gpui.jsonl\ngrep ''\"duration_ms\":'' ~/.scriptkit/logs/script-kit-gpui.jsonl | jq ''select(.fields.duration_ms > 100)''\ngrep ''\"level\":\"ERROR\"'' ~/.scriptkit/logs/script-kit-gpui.jsonl | tail -50\n```\n"},"lastSynced":"2026-03-08T02:01:14.488Z","agentAnalysis":{"suitability":{"en":"Perfect for Debugging Agents requiring structured logging patterns for efficient log analysis in Rust and GPU environments.","zh":"非常适合需要结构化日志模式以实现高效日志分析的 Rust 和 GPU 环境下的调试代理。","ja":"Rust と GPU 環境での効率的なログ分析のための構造化されたログパターンを必要とするデバッグエージェントに最適です。","ko":"구조화된 로깅 패턴이 필요한 Rust 및 GPU 환경에서 효율적인 로그 분석을 위한 디버깅 에이전트에 적합합니다.","es":"Perfecto para agentes de depuración que requieren patrones de registro estructurados para un análisis de registro eficiente en Rust y entornos de GPU.","fr":"Parfait pour les agents de débogage nécessitant des modèles de journalisation structurés pour une analyse de journal efficace dans Rust et les environnements de GPU.","de":"Perfekt für Debugging-Agents, die strukturierte Protokollmuster für eine effiziente Protokollanalyse in Rust- und GPU-Umgebungen erfordern.","pt":"Perfeito para agentes de depuração que exigem padrões de registro estruturados para análise de log eficiente em Rust e ambientes de GPU.","ru":"Идеально подходит для агентов отладки, требующих структурированных шаблонов журналирования для эффективного анализа журналов в средах Rust и GPU.","ar":"مثالي لعمليات تصحيح الأعطال التي تتطلب أنماط تسجيل متسلسلة للتحليل الفعال للسجلات في بيئات Rust و GPU."},"recommendation":{"en":"Empowers agents to utilize compact stderr formats, such as `SS.mmm|L|C|message`, for streamlined log processing, incorporating categories like position, app, and UI, and log levels including INFO, WARN, ERROR, DEBUG, and TRACE.","zh":"赋予代理使用紧凑的 stderr 格式（如 `SS.mmm|L|C|message`），用于简化的日志处理，融合类别如位置、应用和 UI，以及包括 INFO、WARN、ERROR、DEBUG 和 TRACE 在内的日志级别。","ja":"エージェントに `SS.mmm|L|C|message` のようなコンパクトな stderr フォーマットを使用することを可能にし、位置、アプリ、UI などのカテゴリや INFO、WARN、ERROR、DEBUG、TRACE などのログレベルを含むストリームライン化されたログ処理を実現します。","ko":"에이전트가 `SS.mmm|L|C|message`와 같은 컴팩트한 stderr 형식을 사용할 수 있게 하여, 위치, 앱, UI와 같은 카테고리 및 INFO, WARN, ERROR, DEBUG, TRACE와 같은 로그 레벨을 포함한 로그 처리를 간소화합니다.","es":"Habilita a los agentes a utilizar formatos de stderr compactos, como `SS.mmm|L|C|mensaje`, para un procesamiento de registros optimizado, incorporando categorías como posición, aplicación y UI, y niveles de registro que incluyen INFO, WARN, ERROR, DEBUG y TRACE.","fr":"Permet aux agents d''utiliser des formats de stderr compacts, tels que `SS.mmm|L|C|message`, pour un traitement de journal optimisé, incorporant des catégories comme position, application et UI, et des niveaux de journalisation incluant INFO, WARN, ERROR, DEBUG et TRACE.","de":"Ermächtigt Agenten, kompakten stderr-Formate wie `SS.mmm|L|C|message` zu verwenden, für ein optimiertes Protokollverarbeitung, das Kategorien wie Position, App und UI umfasst, und Protokollstufen einschließlich INFO, WARN, ERROR, DEBUG und TRACE.","pt":"Habilita os agentes a utilizarem formatos de stderr compactos, como `SS.mmm|L|C|message`, para processamento de log em fluxo, incorporando categorias como posição, aplicativo e UI, e níveis de log incluindo INFO, WARN, ERROR, DEBUG e TRACE.","ru":"Позволяет агентам использовать компактные форматы stderr, такие как `SS.mmm|L|C|message`, для оптимизированной обработки журналов, включающей категории, такие как позиция, приложение и UI, и уровни журналирования, включая INFO, WARN, ERROR, DEBUG и TRACE.","ar":"يمكن للوكلاء استخدام تنسيقات stderr المضغوطة، مثل `SS.mmm|L|C|message`، لمعالجة السجلات المُتدفقة، ودمج الفئات مثل الموضع والتطبيق وواجهة المستخدم، ومستويات السجلات بما في ذلك INFO و WARN و ERROR و DEBUG و TRACE."},"useCases":{"en":["Debugging complex GPU-accelerated applications with structured logging","Analyzing stderr logs for performance optimization in Rust-based systems","Implementing compact log formats for enhanced observability in AI-driven projects"],"zh":["使用结构化日志调试复杂的 GPU 加速应用","分析 stderr 日志以优化 Rust 基础系统的性能","在 AI 驱动的项目中实现紧凑的日志格式以增强可观察性"],"ja":["構造化されたログを使用して複雑な GPU アクセラレーションアプリケーションをデバッグする","Rust ベースのシステムのパフォーマンス最適化のための stderr ログを分析する","AI ドライブンのプロジェクトでコンパクトなログ形式を実装して可観測性を高める"],"ko":["구조화된 로깅을 사용하여 복잡한 GPU 가속 응용 프로그램을 디버깅하는 것","Rust 기반 시스템의 성능 최적화를 위한 stderr 로그 분석","AI 주도 프로젝트에서 컴팩트한 로그 형식을 구현하여 관찰 가능성을 향상시키는 것"],"es":["Depuración de aplicaciones complejas aceleradas por GPU con registro estructurado","Análisis de registros de stderr para la optimización del rendimiento en sistemas basados en Rust","Implementación de formatos de registro compactos para una mejor observabilidad en proyectos impulsados por IA"],"fr":["Débogage d''applications complexes accélérées par GPU avec journalisation structurée","Analyse des journaux de stderr pour l''optimisation des performances dans les systèmes basés sur Rust","Mise en œuvre de formats de journal compact pour une meilleure observabilité dans les projets pilotés par l''IA"],"de":["Fehlerbehebung komplexer GPU-beschleunigter Anwendungen mit strukturiertem Protokoll","Analyse von stderr-Protokollen für die Leistungsoptimierung in Rust-basierten Systemen","Implementierung kompakten Protokollformate für eine verbesserte Beobachtbarkeit in künstlicher Intelligenz-getriebenen Projekten"],"pt":["Depuração de aplicações complexas com aceleração por GPU com registro estruturado","Análise de logs de stderr para otimização de desempenho em sistemas baseados em Rust","Implementação de formatos de log compactos para observabilidade aprimorada em projetos impulsionados por IA"],"ru":["Отладка сложных приложений с ускорением на GPU с структурированным журналированием","Анализ журналов stderr для оптимизации производительности в системах на основе Rust","Реализация компактных форматов журналов для улучшенной наблюдаемости в проектах, управляемых ИИ"],"ar":["تصحيح الأعطال للتطبيقات المعقدة التي تعمل بالتسريع عن طريق GPU مع سجلات متسلسلة","تحليل سجلات stderr لتحسين الأداء في الأنظمة المستندة إلى Rust","تنفيذ تنسيقات سجلات مضغوطة لتحسين الرصد في مشاريع مدفوعة بالذكاء الاصطناعي"]},"limitations":{"en":["Requires SCRIPT_KIT_AI_LOG environment variable to be set","Primarily designed for Rust and GPU environments, may require adaptation for other ecosystems"],"zh":["需要设置 SCRIPT_KIT_AI_LOG 环境变量","主要设计用于 Rust 和 GPU 环境，可能需要适应其他生态系统"],"ja":["SCRIPT_KIT_AI_LOG 環境変数を設定する必要がある","主に Rust と GPU 環境のために設計されており、他のエコシステムでは適応が必要となる可能性がある"],"ko":["SCRIPT_KIT_AI_LOG 환경 변수를 설정해야 함","주로 Rust 및 GPU 환경을 위해 설계되었으며, 다른 생태계에서는 적응이 필요할 수 있음"],"es":["Requiere que la variable de entorno SCRIPT_KIT_AI_LOG esté establecida","Diseñado principalmente para entornos de Rust y GPU, puede requerir adaptación para otros ecosistemas"],"fr":["Requiert que la variable d''environnement SCRIPT_KIT_AI_LOG soit définie","Conçu principalement pour les environnements Rust et GPU, peut nécessiter une adaptation pour d''autres écosystèmes"],"de":["Erfordert, dass die Umgebungsvariable SCRIPT_KIT_AI_LOG festgelegt ist","In erster Linie für Rust- und GPU-Umgebungen konzipiert, kann eine Anpassung für andere Ökosysteme erforderlich sein"],"pt":["Exige que a variável de ambiente SCRIPT_KIT_AI_LOG seja definida","Projetado principalmente para ambientes Rust e GPU, pode exigir adaptação para outros ecossistemas"],"ru":["Требует, чтобы переменная среды SCRIPT_KIT_AI_LOG была установлена","В основном предназначен для сред Rust и GPU, может потребовать адаптации для других экосистем"],"ar":["يتطلب تعريف متغير البيئة SCRIPT_KIT_AI_LOG","تم تصميمه في المقام الأول للبيئات Rust و GPU، ويمكن أن يتطلب التكيف مع بيئات أخرى"]},"version":4},"contentHash":"f555a4ec8b9f968edefbc45d247f1e7bd9b7509aa36e2e637a0d305bd4a36fea","qualityScore":36}');
DELETE FROM skills_fts WHERE id = 'johnlindquist/script-kit-next/script-kit-logging';
INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('johnlindquist/script-kit-next/script-kit-logging', 'script-kit-logging', 'johnlindquist', 'script-kit-next', 'community', 'script-kit-logging johnlindquist script-kit-next community script-kit-logging provides structured logging patterns for debugging and observability, benefiting developers working with Rust and GPUI. It offers a compact stderr format for efficient log analysis. 脚本工具包日志记录提供结构化日志模式，用于调试和可观察性，支持Compact stderr格式和多种日志类别 Script Kit Loggingは構造化ログパターンを提供し、デバッグと観察性を高め、Compact stderr形式と多種多様なログカテゴリをサポート 스크립트 키트 로깅은 구조화된 로그 패턴을 제공하여 디버깅과 관찰성을 높이고 Compact stderr 형식 및 다양한 로그 카테고리를 지원 Script Kit Logging es un patrón de registro estructurado para la depuración y observabilidad en proyectos de IA, implementado con Rust y GPUI Script Kit Logging est un modèle de journalisation structuré pour le débogage et l''observabilité dans les projets d''IA, mis en œuvre avec Rust et GPUI Script Kit Logging ist ein strukturiertes Protokollmuster für die Fehlersuche und Überwachung in KI-Projekten, implementiert mit Rust und GPUI O Script Kit Logging é uma ferramenta de registro estruturado para depuração e observabilidade, escrita em Rust e utilizando o framework GPUI Script Kit Logging - это инструмент структурированного логирования для отладки и наблюдаемости, написанный на Rust и использующий фреймворк GPUI для ИИ Агентов Script Kit Logging هو أداة تسجيل متوافرة لعمليات التصحيح والإشراف، مكتوبة بلغة Rust و تستخدم إطار GPUI لعمليات الإعداد الآلية how to use script-kit-logging script-kit-logging setup guide what is script-kit-logging script-kit-logging alternative script-kit-logging vs log4j script-kit-logging install rust logging frameworks GPUI logging tools structured logging patterns 脚本工具包日志记录 AI工具 结构化日志模式 调试 可观察性 Rust GPUI Zed的UI框架 Compact stderr format: `SS.mmm|L|C|message` for efficient log analysis Supports AI Compact Log Mode (SCRIPT_KIT_AI_LOG=1) for reduced log verbosity Utilizes categories like position (P), app (A), UI (U), and stdin (S) for log organization Includes log levels: INFO (i), WARN (w), ERROR (e), DEBUG (d), and TRACE (t) for flexible logging Offers visibility into execution (E), key (K), focus (F), and theme (T) for enhanced debugging script-kit-logging is a Rust-based logging framework using GPUI, offering structured logging patterns for improved debugging and observability');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('PackmindHub/coding-agents-matrix/add-agent-property', 'community', 'PackmindHub', 'coding-agents-matrix', 'PackmindHub/coding-agents-matrix', 'add-agent-property', 0, 0, 36, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:17.292Z', 'b171e1ed50c61dc1d99688e641ac098e4e8cdff5fab210d57b14204c541506b9', '{"id":"PackmindHub/coding-agents-matrix/add-agent-property","name":"add-agent-property","description":{"en":"The add-agent-property skill allows developers to add new properties to AI agents by modifying four files in sequence. This skill benefits developers working with AI coding agents.","zh":"添加代理属性到AI工具，需要修改四个文件，包括设置属性键、显示标签、tooltip描述和单元格类型等","ja":"AIエージェントにプロパティを追加するには、四つのファイルを修正する必要があります。プロパティキー、表示ラベル、ツールチップの説明、セルのタイプなど","ko":"AI 에이전트에 속성을 추가하려면 네 개의 파일을 수정해야 합니다. 속성 키, 표시 레이블, 툴팁 설명, 셀 유형 등","es":"La habilidad ''add-agent-property'' permite agregar nuevas propiedades a la tabla de agentes de código AI, mejorando la personalización y el control","fr":"La compétence ''add-agent-property'' permet d''ajouter de nouvelles propriétés au tableau d''agents de codage AI, améliorant la personnalisation et le contrôle","de":"Die Fähigkeit ''add-agent-property'' ermöglicht das Hinzufügen neuer Eigenschaften zur Tabelle von AI-Coding-Agents, was die Anpassung und Kontrolle verbessert","pt":"O Add Agent Property é uma funcionalidade que permite adicionar novas propriedades aos agentes de codificação de IA, modificando quatro arquivos em sequência","ru":"Add Agent Property - это функция, позволяющая добавлять новые свойства агентам кодирования ИИ, изменяя четыре файла в последовательности","ar":"الإضافة خاصية الوكيل هي ميزة تسمح بإضافة خصائص جديدة إلى وكلاء البرمجة الذكية، من خلال تعديل أربعة ملفات بالتسلسل"},"seo":{"title":{"en":"add-agent-property: Setup Guide for AI Agents","zh":"AI工具添加代理属性设置指南","ja":"AIエージェントのプロパティ追加セットアップガイド","ko":"AI 에이전트 속성 추가 설정 가이드","es":"Configuración de Agente de Código AI: Guía de Instalación...","fr":"Guide d''Installation des Propriétés d''Agent de Codage AI","de":"AI-Coding-Agent-Eigenschaften: Einrichtungsanleitung","pt":"Guia de Configuração do Add Agent Property para Ferrament...","ru":"Настройка свойства агента ИИ: пошаговое руководство","ar":"دليل إعداد خاصية الإضافة للوكلاء الذكية"},"description":{"en":"Discover how to add new properties to AI agents with our step-by-step guide. Learn to modify files in sequence and optimize your workflow today!","zh":"了解如何添加代理属性到AI工具，包括设置属性键、显示标签、tooltip描述等","ja":"AIエージェントにプロパティを追加する方法を学びます。プロパティキー、表示ラベル、ツールチップの説明など","ko":"AI 에이전트에 속성을 추가하는 방법을 알아보세요. 속성 키, 표시 레이블, 툴팁 설명 등","es":"Aprende a agregar propiedades a la tabla de agentes de código AI con nuestra guía paso a paso para desarrolladores","fr":"Découvrez comment ajouter des propriétés au tableau d''agents de codage AI avec notre guide étape par étape pour les développeurs","de":"Erfahren Sie, wie Sie Eigenschaften zur Tabelle von AI-Coding-Agents hinzufügen, mit unserer Schritt-für-Schritt-Anleitung für Entwickler","pt":"Aprenda a adicionar propriedades aos agentes de codificação de IA com este guia passo a passo, incluindo detalhes de schema e fluxo de trabalho","ru":"Узнайте, как добавить свойства агентам кодирования ИИ с помощью этого пошагового руководства, включая detalles схемы и рабочего процесса","ar":"تعلم كيفية إضافة خصائص إلى وكلاء البرمجة الذكية باستخدام هذا الدليل المتسلسل، بما في ذلك تفاصيل Schema وflux de travail"},"definition":{"en":"add-agent-property is a curated comparison matrix of AI coding agents that enables developers to add new properties to the agents board","zh":"添加代理属性是指向AI工具添加新的属性，以扩展其功能","ja":"プロパティの追加は、AIエージェントに新しいプロパティを追加して機能を拡張すること","ko":"속성 추가는 AI 에이전트에 새로운 속성을 추가하여 기능을 확장하는 것","es":"Un agente de código AI es una herramienta que ayuda a los desarrolladores a escribir código de manera más eficiente","fr":"Un agent de codage AI est un outil qui aide les développeurs à écrire du code de manière plus efficace","de":"Ein AI-Coding-Agent ist ein Werkzeug, das Entwicklern hilft, Code effizienter zu schreiben","pt":"O que é Add Agent Property? É uma funcionalidade de codificação de IA que adiciona propriedades aos agentes","ru":"Что такое Add Agent Property? Это функция кодирования ИИ, добавляющая свойства агентам","ar":"ما هي إضافة خاصية الوكيل؟ هي ميزة برمجة ذكية تضيف خصائص إلى الوكلاء"},"features":{"en":["Modifies four files in sequence to add new properties","Asks users for property key, display label, tooltip description, and cell type","Supports badge and text cell types for property display","References schema.md for data structures","Enables grouping of properties for organized display"],"zh":["支持camelCase属性键","自定义显示标签和tooltip描述","支持badge和text单元格类型","属性分组功能"],"ja":["camelCaseプロパティキーをサポート","表示ラベルとツールチップの説明をカスタマイズ","badgeとtextセルのタイプをサポート","プロパティのグループ化機能"],"ko":["camelCase 속성 키 지원","표시 레이블과 툴팁 설명을 사용자 정의","badge와 text 셀 유형 지원","속성 그룹화 기능"],"es":["Modificación de cuatro archivos en secuencia para agregar propiedades","Soporte para tipos de celda ''badge'' y ''text''","Posibilidad de agregar una etiqueta de visualización y una descripción de tooltip","Compatibilidad con la referencia de esquema en references/schema.md"],"fr":["Modification de quatre fichiers en séquence pour ajouter des propriétés","Prise en charge des types de cellule ''badge'' et ''text''","Possibilité d''ajouter une étiquette d''affichage et une description de tooltip","Compatibilité avec la référence de schéma dans references/schema.md"],"de":["Modifizierung von vier Dateien in Folge, um Eigenschaften hinzuzufügen","Unterstützung für Zelltypen ''badge'' und ''text''","Möglichkeit, eine Anzeigelabel und eine Tooltip-Beschreibung hinzuzufügen","Kompatibilität mit der Schemareferenz in references/schema.md"],"pt":["Modificação de quatro arquivos em sequência","Adição de propriedades aos agentes de codificação de IA","Utilização de schema de referência para estruturas de dados","Suporte a tipos de células como badge e texto"],"ru":["Изменение четырех файлов в последовательности","Добавление свойств агентам кодирования ИИ","Использование схемы ссылки для структур данных","Поддержка типов ячеек, таких как badge и текст"],"ar":["تعديل أربعة ملفات بالتسلسل","إضافة خصائص إلى وكلاء البرمجة الذكية","استخدام schema مرجعية لSTRUCTURES البيانات","دعم أنواع الخلايا مثل badge وtext"]},"keywords":{"en":["how to use add-agent-property","add-agent-property setup guide","add-agent-property vs AI coding agents","what is add-agent-property","add-agent-property install","add-agent-property alternative","AI agent property management","curated comparison matrix","AI coding agent workflow optimization"],"zh":["AI工具","添加代理属性","属性键","显示标签","tooltip描述","单元格类型","属性分组"],"ja":["AIエージェント","プロパティの追加","プロパティキー","表示ラベル","ツールチップの説明","セルのタイプ","プロパティのグループ化"],"ko":["AI 에이전트","속성 추가","속성 키","표시 레이블","툴팁 설명","셀 유형","속성 그룹화"],"es":["agente de código AI","herramientas de codificación AI","agregar propiedades a agentes de código","personalización de agentes de código","control de agentes de código","desarrollo de software con AI","integración de AI en el desarrollo de software"],"fr":["agent de codage AI","outils de codage AI","ajouter des propriétés aux agents de codage","personnalisation des agents de codage","contrôle des agents de codage","développement de logiciels avec l''IA","intégration de l''IA dans le développement de logiciels"],"de":["AI-Coding-Agent","AI-Coding-Tools","Eigenschaften zu AI-Coding-Agents hinzufügen","Anpassung von AI-Coding-Agents","Kontrolle von AI-Coding-Agents","Softwareentwicklung mit KI","Integration von KI in die Softwareentwicklung"],"pt":["add agent property","ferramentas de ia","codificação de ia","adicionar propriedades","schema de referência","tipos de células","badge","texto"],"ru":["add agent property","ии агенты","кодирование ии","добавление свойств","схема ссылки","типы ячеек","badge","текст"],"ar":["إضافة خاصية الوكيل","أدوات ذكية","برمجة ذكية","إضافة خصائص","schema مرجعية","أنواع الخلايا","badge","نص"]}},"owner":"PackmindHub","repo":"coding-agents-matrix","repoPath":"PackmindHub/coding-agents-matrix","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"add-agent-property","description":"Add a new property to the AI agents database. Use when the user wants to add, create, or introduce a new column, property, field, or feature to track across all agents in the comparison matrix. Handles all four required steps - database updates, groups.json, table display, and GitHub issue templates.","bodyPreview":"# Add Agent Property\n\nAdd a new property to the agents board by modifying four files in sequence.\n\n**Schema reference:** See [references/schema.md](references/schema.md) for data structures.\n\n## Workflow\n\n### 1. Gather Property Details\n\nAsk the user for:\n- **Property key** (camelCase, e.g., `contextWindow`)\n- **Display label** (short, e.g., \"Context Window\")\n- **Tooltip description** (1 sentence explaining the property)\n- **Cell type**: `badge` (yes/no/partial) or `text` (free-form)\n- **Group**:","body":"# Add Agent Property\n\nAdd a new property to the agents board by modifying four files in sequence.\n\n**Schema reference:** See [references/schema.md](references/schema.md) for data structures.\n\n## Workflow\n\n### 1. Gather Property Details\n\nAsk the user for:\n- **Property key** (camelCase, e.g., `contextWindow`)\n- **Display label** (short, e.g., \"Context Window\")\n- **Tooltip description** (1 sentence explaining the property)\n- **Cell type**: `badge` (yes/no/partial) or `text` (free-form)\n- **Group**: `identity`, `packaging`, or `features`\n\n### 2. Update agents-detailed.json\n\nAdd the property to **every agent** in `src/data/agents-detailed.json`:\n\n```json\n\"propertyKey\": {\n  \"value\": null,\n  \"detail\": null\n}\n```\n\nInsert after the last feature property, before `additionalInfo`.\n\n### 3. Update groups.json\n\nAdd the property key to the appropriate group''s `columns` array in `src/data/groups.json`:\n\n```json\n{\n  \"id\": \"features\",\n  \"label\": \"Features\",\n  \"columns\": [\"existingProp\", \"propertyKey\"]\n}\n```\n\n### 4. Update AgentTable.jsx\n\nAdd column definition to the `columns` array in `src/components/AgentTable.jsx`:\n\n```javascript\n{ key: ''propertyKey'', label: ''Label'', sortable: true, cellType: ''badge'', tooltip: ''Description'' }\n```\n\nInsert at the position matching its group order.\n\n### 5. Update useAgentsData.js\n\nAdd transformation in `src/hooks/useAgentsData.js`:\n\n```javascript\npropertyKey: agent.propertyKey.value,\npropertyKeyDetail: agent.propertyKey.detail,\n```\n\n### 6. Update FilterBar.jsx (for filterable properties)\n\nIf the property is in `packaging` or `features` group **and** has `cellType: ''badge''`, add it to the `featureOptions` array in `src/components/FilterBar.jsx`:\n\n```javascript\n{ key: ''propertyKey'', label: ''Label'' }\n```\n\nInsert in the appropriate section (Packaging or Features) following the existing order.\n\n### 7. Update GitHub Issue Templates\n\n**01-update-agent.md** - Add under Features section:\n\n```markdown\n- [ ] **Property Label** (`propertyKey`)\n  - New value: <!-- yes/no/partial/null -->\n  - Detail:\n```\n\n**02-add-new-agent.md** - Add new section with property definition, value format, and examples.\n\n## Checklist\n\n- [ ] Property added to all agents in agents-detailed.json\n- [ ] Property key added to correct group in groups.json\n- [ ] Column definition added to AgentTable.jsx\n- [ ] Transformation added to useAgentsData.js\n- [ ] Filter option added to FilterBar.jsx (if badge in packaging/features)\n- [ ] Update template modified in .github/ISSUE_TEMPLATE/01-update-agent.md\n- [ ] New agent template modified in .github/ISSUE_TEMPLATE/02-add-new-agent.md\n"},"lastSynced":"2026-03-08T02:01:17.292Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Coding Agents needing customized property management and enhanced data visualization capabilities.","zh":"非常适合需要自定义属性管理和增强数据可视化能力的AI编码代理。","ja":"カスタマイズされたプロパティ管理と強化されたデータ視覚化機能を必要とするAIコーディングエージェントに最適です。","ko":"사용자 지정 속성 관리와 강화된 데이터 시각화 기능이 필요한 AI 코딩 에이전트에 적합합니다.","es":"Perfecto para agentes de codificación de IA que necesitan una gestión de propiedades personalizada y capacidades de visualización de datos mejoradas.","fr":"Parfait pour les agents de codage de l''IA nécessitant une gestion de propriétés personnalisée et des capacités de visualisation de données améliorées.","de":"Perfekt für AI-Coding-Agents, die eine benutzerdefinierte Eigenschaftsverwaltung und erweiterte Datenvisualisierungsfunktionen benötigen.","pt":"Perfeito para Agentes de Codificação de IA que necessitam de gerenciamento de propriedades personalizadas e capacidades de visualização de dados aprimoradas.","ru":"Идеально для агентов кодирования ИИ, которым необходимы настраиваемое управление свойствами и улучшенные возможности визуализации данных.","ar":"مثالي للوكلاء البرمجيين بالذكاء الاصطناعي الذين يحتاجون إلى إدارة خصائص مخصصة وقدرات تمثيل بيانات محسنة."},"recommendation":{"en":"Empowers agents to modify and extend their capabilities by adding new properties through sequential file modifications, utilizing schema references and supporting cell types like badges and text.","zh":"赋予代理修改和扩展其功能的能力，通过顺序文件修改添加新属性，利用架构引用并支持类似徽章和文本的单元格类型。","ja":"シーケンシャルファイルの変更を通じて新しいプロパティを追加し、スキーマ参照を利用し、バッジやテキストなどのセルタイプをサポートすることで、エージェントが機能を変更および拡張できるようにします。","ko":"순차적인 파일 수정을 통해 새로운 속성을 추가하고, 스키마 참조를 활용하며, 배지 또는 텍스트와 같은 셀 유형을 지원함으로써 에이전트가 기능을 수정하고 확장할 수 있도록 합니다.","es":"Habilita a los agentes a modificar y ampliar sus capacidades agregando nuevas propiedades a través de modificaciones de archivos secuenciales, utilizando referencias de esquema y admitiendo tipos de celdas como insignias y texto.","fr":"Permet aux agents de modifier et d''étendre leurs capacités en ajoutant de nouvelles propriétés via des mises à jour de fichiers séquentielles, en utilisant des références de schéma et en prenant en charge des types de cellules tels que les badges et le texte.","de":"Ermöglich es den Agenten, ihre Fähigkeiten zu modifizieren und zu erweitern, indem sie neue Eigenschaften durch sequenzielle Dateimodifikationen hinzufügen, Schema-Referenzen verwenden und Zellentypen wie Abzeichen und Text unterstützen.","pt":"Habilita os agentes a modificar e estender suas capacidades adicionando novas propriedades por meio de modificações de arquivos sequenciais, utilizando referências de esquema e suportando tipos de células como emblemas e texto.","ru":"Позволяет агентам изменять и расширять свои возможности, добавляя новые свойства путем последовательных изменений файлов, используя ссылки на схему и поддерживая типы ячеек, такие как значки и текст.","ar":"تمكّن الوكلاء من تعديل وتوسيع قدراتهم بإضافة خصائص جديدة من خلال تحديثات الملفات المتتالية، واستخدام المراجع الموجودة في المخطط ودعم أنواع الخلايا مثل الشعارات والنص."},"useCases":{"en":["Modifying agent boards with custom properties","Extending agent functionality through sequential file updates","Enhancing data visualization with new property types"],"zh":["使用自定义属性修改代理面板","通过顺序文件更新扩展代理功能","使用新属性类型增强数据可视化"],"ja":["カスタムプロパティを使用してエージェントパネルを変更する","シーケンシャルファイルの更新を通じてエージェントの機能を拡張する","新しいプロパティタイプを使用してデータ視覚化を強化する"],"ko":["사용자 지정 속성을 사용하여 에이전트 패널을 수정하는 것","순차적인 파일 업데이트를 통해 에이전트 기능을 확장하는 것","새로운 속성 유형을 사용하여 데이터 시각화를 강화하는 것"],"es":["Modificar tableros de agentes con propiedades personalizadas","Ampliar la funcionalidad del agente mediante actualizaciones de archivos secuenciales","Mejorar la visualización de datos con nuevos tipos de propiedades"],"fr":["Modifier les tableaux d''agents avec des propriétés personnalisées","Étendre la fonctionnalité de l''agent via des mises à jour de fichiers séquentielles","Améliorer la visualisation de données avec de nouveaux types de propriétés"],"de":["Modifizieren von Agenten-Boards mit benutzerdefinierten Eigenschaften","Erweitern der Agentenfunktionalität durch sequenzielle Datei-Aktualisierungen","Verbessern der Datenvisualisierung mit neuen Eigenschaftstypen"],"pt":["Modificar quadros de agentes com propriedades personalizadas","Estender a funcionalidade do agente por meio de atualizações de arquivos sequenciais","Aprimorar a visualização de dados com novos tipos de propriedades"],"ru":["Модифицировать доски агентов с настраиваемыми свойствами","Расширять функциональность агента за счет последовательных обновлений файлов","Улучшать визуализацию данных с новыми типами свойств"],"ar":["تعديل لوحات الوكلاء بخصائص مخصصة","توسيع وظيفة الوكيل من خلال تحديثات الملفات المتتالية","تحسين تمثيل البيانات بأنواع خصائص جديدة"]},"limitations":{"en":["Requires modification of four specific files","Limited to adding properties with predefined cell types (badge or text)"],"zh":["需要修改四个特定的文件","仅限添加具有预定义单元格类型（徽章或文本）的属性"],"ja":["4つの特定のファイルを変更する必要がある","事前に定義されたセルタイプ（バッジまたはテキスト）を持つ属性のみを追加できる"],"ko":["네 개의 특정 파일을 수정해야 함","미리 정의된 셀 유형(배지 또는 텍스트)을 갖는 속성만 추가할 수 있음"],"es":["Requiere la modificación de cuatro archivos específicos","Limitado a agregar propiedades con tipos de celdas predefinidos (insignia o texto)"],"fr":["Nécessite la modification de quatre fichiers spécifiques","Limité à l''ajout de propriétés avec des types de cellules prédéfinis (badge ou texte)"],"de":["Erfordert die Modifikation von vier bestimmten Dateien","Begrenzt auf das Hinzufügen von Eigenschaften mit vordefinierten Zellentypen (Abzeichen oder Text)"],"pt":["Exige a modificação de quatro arquivos específicos","Limitado à adição de propriedades com tipos de células predefinidos (emblema ou texto)"],"ru":["Требует изменения четырёх конкретных файлов","Ограничен добавлением свойств с предопределенными типами ячеек (значок или текст)"],"ar":["يتطلب تعديل أربعة ملفات محددة","محدود بإضافة خصائص بأشكال خلايا محددة مسبقًا (شعار أو نص)"]},"version":4},"contentHash":"b171e1ed50c61dc1d99688e641ac098e4e8cdff5fab210d57b14204c541506b9","qualityScore":36}');
