INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('PackmindHub/coding-agents-matrix/add-agent-property', 'add-agent-property', 'PackmindHub', 'coding-agents-matrix', 'community', 'add-agent-property PackmindHub coding-agents-matrix community The add-agent-property skill allows developers to add new properties to AI agents by modifying four files in sequence. This skill benefits developers working with AI coding agents. 添加代理属性到AI工具，需要修改四个文件，包括设置属性键、显示标签、tooltip描述和单元格类型等 AIエージェントにプロパティを追加するには、四つのファイルを修正する必要があります。プロパティキー、表示ラベル、ツールチップの説明、セルのタイプなど AI 에이전트에 속성을 추가하려면 네 개의 파일을 수정해야 합니다. 속성 키, 표시 레이블, 툴팁 설명, 셀 유형 등 La habilidad ''add-agent-property'' permite agregar nuevas propiedades a la tabla de agentes de código AI, mejorando la personalización y el control La compétence ''add-agent-property'' permet d''ajouter de nouvelles propriétés au tableau d''agents de codage AI, améliorant la personnalisation et le contrôle Die Fähigkeit ''add-agent-property'' ermöglicht das Hinzufügen neuer Eigenschaften zur Tabelle von AI-Coding-Agents, was die Anpassung und Kontrolle verbessert O Add Agent Property é uma funcionalidade que permite adicionar novas propriedades aos agentes de codificação de IA, modificando quatro arquivos em sequência Add Agent Property - это функция, позволяющая добавлять новые свойства агентам кодирования ИИ, изменяя четыре файла в последовательности الإضافة خاصية الوكيل هي ميزة تسمح بإضافة خصائص جديدة إلى وكلاء البرمجة الذكية، من خلال تعديل أربعة ملفات بالتسلسل how to use add-agent-property add-agent-property setup guide add-agent-property vs AI coding agents what is add-agent-property add-agent-property install add-agent-property alternative AI agent property management curated comparison matrix AI coding agent workflow optimization AI工具 添加代理属性 属性键 显示标签 tooltip描述 单元格类型 属性分组 Modifies four files in sequence to add new properties Asks users for property key, display label, tooltip description, and cell type Supports badge and text cell types for property display References schema.md for data structures Enables grouping of properties for organized display add-agent-property is a curated comparison matrix of AI coding agents that enables developers to add new properties to the agents board');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('sylin-org/koan-framework/koan-performance', 'community', 'sylin-org', 'koan-framework', 'sylin-org/koan-framework', 'koan-performance', 0, 0, 36, '2026-03-08T01:57:15.297Z', '2026-03-08T02:01:18.852Z', '4f904346ca269ab84a6a922593399a46e39a565dcce9f83a23475e84fc1bbd89', '{"id":"sylin-org/koan-framework/koan-performance","name":"koan-performance","description":{"en":"koan-performance is a modern .NET 10 framework that enables small teams to build sophisticated applications with simple patterns, optimizing for scale from day one. It benefits developers seeking efficient entity-first persistence and event-driven architecture.","zh":"Koan 性能优化是一种现代的、模块化的 .NET 10 框架，旨在帮助小团队构建大规模应用。它提供了实体优先的持久性、多提供者透明度、AI 集成和事件驱动的架构","ja":"Koan パフォーマンス最適化は、モダンでモジュラー化された .NET 10 フレームワークであり、小規模チームが大規模アプリケーションを構築することを可能にします。エンティティ優先の永続性、多プロバイダー透明性、AI 統合、イベント駆動アーキテクチャを提供します","ko":"Koan 성능 최적화는 현대적인 모듈화된 .NET 10 프레임워크로, 소규모 팀이 대규모 애플리케이션을 구축할 수 있도록 설계되었습니다. 엔티티 우선의 지속성, 다중 공급자 투명성, AI 통합 및 이벤트 주도 아키텍처를 제공합니다","es":"koan-performance es un marco de trabajo .NET 10 modular que permite a los equipos pequeños construir aplicaciones sofisticadas con patrones simples, incluyendo persistencia de entidad, transparencia de proveedores múltiples y arquitectura orientada a eventos","fr":"koan-performance est un cadre de travail .NET 10 modulaire qui permet aux petites équipes de construire des applications sophistiquées avec des modèles simples, notamment la persistance d''entité, la transparence de plusieurs fournisseurs et l''architecture orientée vers les événements","de":"koan-performance ist ein modulares .NET 10-Framework, das es kleinen Teams ermöglicht, komplexe Anwendungen mit einfachen Mustern zu erstellen, einschließlich Entitätspersistenz, Transparenz mehrerer Anbieter und ereignisorientierter Architektur","pt":"O Koan é um framework .NET 10 modular que permite que equipes pequenas construam aplicações sofisticadas com padrões simples. Otimização de escala desde o início com streaming, operações em lote e contagens rápidas.","ru":"Koan - это модульный фреймворк .NET 10, который позволяет небольшим командам создавать сложные приложения с простыми шаблонами. Оптимизация масштабируемости с самого начала с помощью потоковой передачи, пакетных операций и быстрого подсчета.","ar":"Koan هو إطار عمل .NET 10 قائم على الوحدات يسمح للفرق الصغيرة ببناء تطبيقات معقدة باستخدام أنماط بسيطة. تحسين القابلية للتحجيم منذ البداية مع البث، عمليات الدفع والعد السريع"},"seo":{"title":{"en":"koan-performance: Scalable .NET Framework Setup Guide | A...","zh":"Koan 性能优化指南 - 实现大规模应用的最佳实践","ja":"Koan パフォーマンス最適化セットアップガイド - 大規模アプリケーションのためのベストプラクティス","ko":"Koan 성능 최적화 설정 가이드 - 대규모 애플리케이션을 위한 최적의 사례","es":"Guía de configuración de koan-performance para escalabilidad","fr":"Configurer koan-performance pour des applications à grand...","de":"Leitfaden für die Einrichtung von koan-performance für Sk...","pt":"Guia de Desempenho do Koan: Otimização de Escala","ru":"Руководство по производительности Koan: оптимизация масшт...","ar":"دليل أداء Koan: تحسين القابلية للتحجيم"},"description":{"en":"Unlock efficient application development with koan-performance. Learn how to optimize for scale and streamline your workflow with our expert guide.","zh":"了解 Koan 性能优化的核心原则和模式，包括流处理、批处理、快速计数和分页，实现大规模应用的高效性能","ja":"Koan パフォーマンス最適化のコア原則とパターンを学び、ストリーミング、バッチ処理、高速カウント、ページネーションを使用して大規模アプリケーションのパフォーマンスを向上させます","ko":"Koan 성능 최적화의 핵심 원칙과 패턴을 학습하고 스트리밍, 배치 처리, 빠른 카운트 및 페이징을 사용하여 대규모 애플리케이션의 성능을 향상시키는 방법을 알아보세요","es":"Aprende a optimizar tu aplicación .NET 10 con koan-performance, incluyendo transmisión en streaming y operaciones por lotes para mejorar el rendimiento","fr":"Découvrez comment optimiser vos applications .NET 10 avec koan-performance, y compris la transmission en continu et les opérations par lot pour améliorer les...","de":"Erfahren Sie, wie Sie Ihre .NET 10-Anwendung mit koan-performance optimieren, einschließlich Streaming-Übertragung und Batch-Operationen für bessere Leistung","pt":"Aprenda a otimizar o desempenho do Koan com padrões de streaming, operações em lote e contagens rápidas para UI","ru":"Узнайте, как оптимизировать производительность Koan с помощью шаблонов потоковой передачи, пакетных операций и быстрого подсчета для UI","ar":"تعرف على كيفية تحسين أداء Koan باستخدام أنماط البث، عمليات الدفع والعد السريع للواجهة"},"definition":{"en":"koan-performance is a modular .NET framework designed for scalable application development with features like entity-first persistence, multi-provider transparency, and AI integration.","zh":"Koan 性能优化是一种 .NET 10 框架，旨在优化大规模应用的性能","ja":"Koan パフォーマンス最適化は、.NET 10 フレームワークであり、大規模アプリケーションのパフォーマンスを最適化することを目的としています","ko":"Koan 성능 최적화는 .NET 10 프레임워크로, 대규모 애플리케이션의 성능을 최적화하는 것을 목표로 합니다","es":"koan-performance es un marco de trabajo de escalabilidad para aplicaciones .NET 10 que optimiza el rendimiento con transmisión en streaming y operaciones por lotes","fr":"koan-performance est un cadre de travail d''évolutivité pour les applications .NET 10 qui optimise les performances avec la transmission en continu et les opérations par lot","de":"koan-performance ist ein Skalierungsframework für .NET 10-Anwendungen, das die Leistung mit Streaming-Übertragung und Batch-Operationen optimiert","pt":"O que é Koan Performance? É um framework .NET 10 que otimiza o desempenho com padrões de streaming e operações em lote","ru":"Что такое производительность Koan? Это фреймворк .NET 10, который оптимизирует производительность с помощью шаблонов потоковой передачи и пакетных операций","ar":"ما هو أداء Koan؟ إنه إطار عمل .NET 10 يتحسن الأداء باستخدام أنماط البث وعمليات الدفع"},"features":{"en":["Entity-first persistence for efficient data management","Multi-provider transparency for flexible architecture","AI integration for enhanced application capabilities","Event-driven architecture with zero configuration ceremony","Streaming for large datasets to optimize performance","Batch operations for bulk changes to improve efficiency"],"zh":["实体优先的持久性","多提供者透明度","AI 集成","事件驱动的架构","流处理","批处理"],"ja":["エンティティ優先の永続性","多プロバイダー透明性","AI 統合","イベント駆動アーキテクチャ","ストリーミング","バッチ処理"],"ko":["엔티티 우선의 지속성","다중 공급자 투명성","AI 통합","이벤트 주도 아키텍처","스트리밍","배치 처리"],"es":["Transmisión en streaming para grandes conjuntos de datos","Operaciones por lotes para cambios masivos","Recuentos rápidos para interfaces de usuario","Paginación para APIs web","Persistencia de entidad","Transparencia de proveedores múltiples"],"fr":["Transmission en continu pour les grands ensembles de données","Opérations par lot pour les modifications massives","Comptages rapides pour les interfaces utilisateur","Pagination pour les API web","Persistance d''entité","Transparence de plusieurs fournisseurs"],"de":["Streaming-Übertragung für große Datensätze","Batch-Operationen für umfangreiche Änderungen","Schnelle Zählungen für Benutzeroberflächen","Paginierung für Web-APIs","Entitätspersistenz","Transparenz mehrerer Anbieter"],"pt":["Padrões de streaming para grandes conjuntos de dados","Operações em lote para alterações em massa","Contagens rápidas para UI","Paginação para APIs da web"],"ru":["Шаблоны потоковой передачи для больших наборов данных","Пакетные операции для массовых изменений","Быстрый подсчет для UI","Пагинация для веб-API"],"ar":["أنماط البث للcollections البيانات الكبيرة","عمليات الدفع لتغييرات الكتلة","العد السريع للواجهة","تنقيل للواجهات البرمجية للويب"]},"keywords":{"en":["how to use koan-performance","koan-performance vs entity framework","koan-performance setup guide","what is koan-performance","koan-performance alternative to asp.net","koan-performance install for .net 10","koan-performance best practices for scalable applications","koan-performance and ai integration","koan-performance for event-driven architecture"],"zh":["Koan 性能优化",".NET 10 框架","大规模应用性能优化","AIエージェント","实体优先的持久性","多提供者透明度","事件驱动的架构"],"ja":["Koan パフォーマンス最適化",".NET 10 フレームワーク","大規模アプリケーションパフォーマンス最適化","AIエージェント","エンティティ優先の永続性","多プロバイダー透明性","イベント駆動アーキテクチャ"],"ko":["Koan 성능 최적화",".NET 10 프레임워크","대규모 애플리케이션 성능 최적화","AI 에이전트","엔티티 우선의 지속성","다중 공급자 투명성","이벤트 주도 아키텍처"],"es":["koan-performance","escalabilidad .NET 10","transmisión en streaming","operaciones por lotes","persistencia de entidad","arquitectura orientada a eventos","herramientas de desarrollo de aplicaciones","agentes de inteligencia artificial"],"fr":["koan-performance","évolutivité .NET 10","transmission en continu","opérations par lot","persistance d''entité","architecture orientée vers les événements","outils de développement d''applications","agents d''intelligence artificielle"],"de":["koan-performance","Skalierbarkeit .NET 10","Streaming-Übertragung","Batch-Operationen","Entitätspersistenz","ereignisorientierte Architektur","Entwicklungstools für Anwendungen","Künstliche Intelligenz Agenten"],"pt":["Koan performance","otimização de desempenho","padrões de streaming","operações em lote","contagens rápidas","paginação para APIs","desenvolvimento de aplicações .NET","ferramentas de desenvolvimento de software"],"ru":["Производительность Koan","оптимизация производительности","шаблоны потоковой передачи","пакетные операции","быстрый подсчет","пагинация для веб-API","разработка приложений .NET","инструменты разработки программного обеспечения"],"ar":["أداء Koan","تحسين الأداء","أنماط البث","عمليات الدفع","العد السريع","تنقيل للواجهات البرمجية للويب","تطوير التطبيقات .NET","أدوات تطوير البرمجيات","ИИ Агенты","AI Tools"]}},"owner":"sylin-org","repo":"koan-framework","repoPath":"sylin-org/koan-framework","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.297Z","topics":[],"category":"community","skillMd":{"name":"koan-performance","description":"Streaming, pagination, count strategies, bulk operations","bodyPreview":"# Koan Performance\n\n## Core Principle\n\n**Optimize for scale from day one.** Use streaming for large datasets, batch operations for bulk changes, fast counts for UI, and pagination for web APIs.\n\n## Performance Patterns\n\n### Streaming (Large Datasets)\n\n```csharp\n// ❌ WRONG: Load everything into memory\nvar allTodos = await Todo.All(); // 1 million records!\n\n// ✅ CORRECT: Stream in batches\nawait foreach (var todo in Todo.AllStream(batchSize: 1000))\n{\n    await ProcessTodo(todo);\n}\n```\n\n### Count St","body":"# Koan Performance\n\n## Core Principle\n\n**Optimize for scale from day one.** Use streaming for large datasets, batch operations for bulk changes, fast counts for UI, and pagination for web APIs.\n\n## Performance Patterns\n\n### Streaming (Large Datasets)\n\n```csharp\n// ❌ WRONG: Load everything into memory\nvar allTodos = await Todo.All(); // 1 million records!\n\n// ✅ CORRECT: Stream in batches\nawait foreach (var todo in Todo.AllStream(batchSize: 1000))\n{\n    await ProcessTodo(todo);\n}\n```\n\n### Count Strategies\n\n```csharp\n// Fast count (metadata estimate - 1000x+ faster)\nvar fast = await Todo.Count.Fast(ct); // ~5ms for 10M rows\n\n// Exact count (guaranteed accuracy)\nvar exact = await Todo.Count.Exact(ct); // ~25s for 10M rows\n\n// Optimized (framework chooses)\nvar optimized = await Todo.Count; // Uses Fast if available\n```\n\n**Use Fast for:** Pagination UI, dashboards, estimates\n**Use Exact for:** Critical business logic, reports, inventory\n\n### Bulk Operations\n\n```csharp\n// Bulk create\nvar todos = Enumerable.Range(1, 1000)\n    .Select(i => new Todo { Title = $\"Task {i}\" })\n    .ToList();\nawait todos.Save(); // Single operation\n\n// Bulk removal\nawait Todo.RemoveAll(RemoveStrategy.Fast); // TRUNCATE/DROP (225x faster)\n```\n\n### Batch Retrieval\n\n```csharp\n// ❌ WRONG: N queries\nforeach (var id in ids)\n{\n    var todo = await Todo.Get(id);\n}\n\n// ✅ CORRECT: 1 query\nvar todos = await Todo.Get(ids);\n```\n\n### Pagination\n\n```csharp\npublic async Task<IActionResult> GetTodos(\n    int page = 1,\n    int pageSize = 20,\n    CancellationToken ct = default)\n{\n    var result = await Todo.QueryWithCount(\n        t => !t.Completed,\n        new DataQueryOptions { OrderBy = nameof(Todo.Created), Descending = true },\n        ct);\n\n    Response.Headers[\"X-Total-Count\"] = result.TotalCount.ToString();\n    return Ok(result.Items);\n}\n```\n\n## Performance Benchmarks\n\n| Operation | Inefficient | Efficient | Speedup |\n|-----------|-------------|-----------|---------|\n| **Bulk Remove (1M)** | DELETE loop ~45s | TRUNCATE ~200ms | 225x |\n| **Count (10M)** | Full scan ~25s | Metadata ~5ms | 5000x |\n| **Batch Get (100)** | 100 queries | 1 query | 100x |\n| **Stream (1M)** | Load all (OOM) | Stream batches | Memory safe |\n\n## When This Skill Applies\n\n- ✅ Performance tuning\n- ✅ Large datasets\n- ✅ Optimization\n- ✅ Production readiness\n- ✅ Memory issues\n- ✅ Query optimization\n\n## Reference Documentation\n\n- **Example Code:** `.claude/skills/entity-first/examples/batch-operations.cs`\n- **Guide:** `docs/guides/performance.md`\n- **Sample:** `samples/S14.AdapterBench/` (Performance benchmarks)\n"},"lastSynced":"2026-03-08T02:01:18.852Z","agentAnalysis":{"suitability":{"en":"Perfect for .NET Agents needing efficient entity-first persistence and event-driven architecture for scalable applications.","zh":"非常适合需要高效实体优先持久性和事件驱动架构的可扩展应用的 .NET Agents。","ja":".NET Agents にとって、効率的なエンティティファースト永続化とイベントドリブンアーキテクチャが必要なスケーラブルなアプリケーションに最適です。","ko":".NET 에이전트가 효율적인 엔티티 우선 지속성 및 이벤트 주도 아키텍처를 사용하는 확장 가능한 애플리케이션에 적합합니다.","es":"Perfecto para agentes .NET que necesitan una persistencia de entidad-primera eficiente y una arquitectura de eventos para aplicaciones escalables.","fr":"Parfait pour les agents .NET qui ont besoin d''une persistance d''entité-première efficace et d''une architecture de type événementielle pour des applications scalables.","de":"Perfekt für .NET-Agents, die eine effiziente Entity-First-Persistenz und eine ereignisgesteuerte Architektur für skalierbare Anwendungen benötigen.","pt":"Perfeito para agentes .NET que necessitam de persistência eficiente de entidade-primeira e arquitetura orientada a eventos para aplicações escaláveis.","ru":"Идеально подходит для агентов .NET, требующих эффективной первой сущности-пersistência и событийно-ориентированной архитектуры для масштабируемых приложений.","ar":"مثالي لعميل .NET الذي يحتاج إلى استمرارية كفءة للكيان الأول وتقنية الحدث الموجهة للتطبيقات القابلة للتحجيم."},"recommendation":{"en":"Empowers agents to optimize for scale from day one using streaming for large datasets, batch operations for bulk changes, fast counts for UI, and pagination for web APIs, all within the .NET 10 framework.","zh":"使得代理能够从第一天开始优化扩展，使用流媒体处理大型数据集、批处理操作进行批量更改、快速计数用于 UI，以及用于 Web API 的分页，所有这些都在 .NET 10 框架内。","ja":"エージェントが最初からスケールに最適化できるようにすることで、大規模なデータセットのストリーミング、バルク変更のバッチ操作、UI 用の高速カウント、Web API 用のページネーションなど、すべて .NET 10 フレームワーク内で実行できます。","ko":"에이전트가 처음부터 확장에 최적화할 수 있도록 해줌으로써, 대규모 데이터셋에 대한 스트리밍, 대량 변경에 대한 배치 작업, UI용 빠른 카운트, 웹 API용 페이징 등을 모두 .NET 10 프레임워크 내에서 수행할 수 있습니다.","es":"Permite a los agentes optimizar para escala desde el primer día utilizando streaming para grandes conjuntos de datos, operaciones por lotes para cambios masivos, recuentos rápidos para la interfaz de usuario y paginación para APIs web, todo dentro del marco .NET 10.","fr":"Permet aux agents d''optimiser pour l''échelle dès le premier jour en utilisant le streaming pour les grands ensembles de données, les opérations par lots pour les modifications en masse, les décomptes rapides pour l''interface utilisateur et la pagination pour les API Web, le tout dans le cadre du framework .NET 10.","de":"Ermöglicht es Agenten, von Tag eins an für Skalierbarkeit zu optimieren, indem sie Streaming für große Datensätze, Batch-Operationen für Massenänderungen, schnelle Zählungen für die Benutzeroberfläche und Paginierung für Web-APIs verwenden, alles innerhalb des .NET 10-Frameworks.","pt":"Habilita os agentes a otimizar para escala desde o primeiro dia usando transmissão para grandes conjuntos de dados, operações em lote para alterações em massa, contagens rápidas para interface do usuário e paginação para APIs da web, tudo dentro do framework .NET 10.","ru":"Позволяет агентам оптимизировать масштабируемость с первого дня, используя потоковую передачу для больших наборов данных, пакетные операции для массовых изменений, быстрые подсчеты для интерфейса пользователя и постраничную навигацию для веб-API, все в рамках фреймворка .NET 10.","ar":"تمكّن الوكيل من تحسين القدرة على التوسع منذ اليوم الأول باستخدام البث للkoli كبير من البيانات، والعمليات المجمعة للتغييرات الكبيرة،และการ تعداد سريع لواجهة المستخدم، وتجزئة الصفحات لويب API، كل ذلك داخل إطار .NET 10."},"useCases":{"en":["Streaming large datasets in batches for efficient processing","Implementing event-driven architecture for scalable applications","Optimizing database queries with fast counts and pagination for web APIs"],"zh":["流媒体处理大型数据集以实现高效处理","实现事件驱动架构以实现可扩展应用","使用快速计数和分页优化数据库查询以用于 Web API"],"ja":["効率的な処理のために大規模なデータセットをストリーミングする","スケーラブルなアプリケーションのためにイベントドリブンアーキテクチャを実装する","Web API 用の高速カウントとページネーションを使用してデータベース クエリを最適化する"],"ko":["효율적인 처리를 위해 대규모 데이터셋을 스트리밍함","확장 가능한 애플리케이션을 위해 이벤트 주도 아키텍처를 구현함","웹 API용 빠른 카운트 및 페이징을 사용하여 데이터베이스 쿼리를 최적화함"],"es":["Transmisión de grandes conjuntos de datos en lotes para un procesamiento eficiente","Implementación de una arquitectura de eventos para aplicaciones escalables","Optimización de consultas de base de datos con recuentos rápidos y paginación para APIs web"],"fr":["Diffusion de grands ensembles de données par lots pour un traitement efficace","Mise en œuvre d''une architecture de type événementielle pour des applications scalables","Optimisation des requêtes de base de données avec des décomptes rapides et une pagination pour les API Web"],"de":["Streaming großer Datensätze in Batches für effizientes Verarbeiten","Implementierung einer ereignisgesteuerten Architektur für skalierbare Anwendungen","Optimierung von Datenbankabfragen mit schnellen Zählungen und Paginierung für Web-APIs"],"pt":["Transmissão de grandes conjuntos de dados em lote para processamento eficiente","Implementação de arquitetura orientada a eventos para aplicações escaláveis","Otimização de consultas de banco de dados com contagens rápidas e paginação para APIs da web"],"ru":["Потоковая передача больших наборов данных пакетами для эффективной обработки","Реализация событийно-ориентированной архитектуры для масштабируемых приложений","Оптимизация запросов к базе данных с помощью быстрых подсчетов и постраничной навигации для веб-API"],"ar":["بث كولي كبير من البيانات في شكل دفعات لمعالجة فعالة","تنفيذ هيكل موجه بالحدث للتطبيقات القابلة للتحجيم","تحسين استفسارات قاعدة البيانات باستخدام تعداد سريع وتجزئة الصفحات لويب API"]},"limitations":{"en":[".NET 10 framework required","Limited to entity-first persistence and event-driven architecture patterns"],"zh":[".NET 10 框架必需","仅限于实体优先持久性和事件驱动架构模式"],"ja":[".NET 10 フレームワークが必要","エンティティファースト永続化とイベントドリブンアーキテクチャのパターンに限定される"],"ko":[".NET 10 프레임워크가 필요함","엔티티 우선 지속성 및 이벤트 주도 아키텍처 패턴으로 제한됨"],"es":[".NET 10 framework requerido","Limitado a patrones de persistencia de entidad-primera y arquitectura de eventos"],"fr":["Framework .NET 10 requis","Limité aux modèles de persistance d''entité-première et d''architecture de type événementielle"],"de":[".NET 10-Framework erforderlich","Begrenzt auf Muster für Entity-First-Persistenz und ereignisgesteuerte Architektur"],"pt":[".NET 10 framework necessário","Limitado a padrões de persistência de entidade-primeira e arquitetura orientada a eventos"],"ru":["Требуется фреймворк .NET 10","Ограничен шаблонами первой сущности-пersistência и событийно-ориентированной архитектуры"],"ar":["إطار .NET 10 مطلوب","محدود بنمط استمرارية الكيان الأول وهندسة الحدث الموجهة"]},"version":4},"contentHash":"4f904346ca269ab84a6a922593399a46e39a565dcce9f83a23475e84fc1bbd89","qualityScore":36}');
