INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('sylin-org/koan-framework/koan-performance', 'koan-performance', 'sylin-org', 'koan-framework', 'community', 'koan-performance sylin-org koan-framework community koan-performance is a modern .NET 10 framework that enables small teams to build sophisticated applications with simple patterns, optimizing for scale from day one. It benefits developers seeking efficient entity-first persistence and event-driven architecture. Koan 性能优化是一种现代的、模块化的 .NET 10 框架，旨在帮助小团队构建大规模应用。它提供了实体优先的持久性、多提供者透明度、AI 集成和事件驱动的架构 Koan パフォーマンス最適化は、モダンでモジュラー化された .NET 10 フレームワークであり、小規模チームが大規模アプリケーションを構築することを可能にします。エンティティ優先の永続性、多プロバイダー透明性、AI 統合、イベント駆動アーキテクチャを提供します Koan 성능 최적화는 현대적인 모듈화된 .NET 10 프레임워크로, 소규모 팀이 대규모 애플리케이션을 구축할 수 있도록 설계되었습니다. 엔티티 우선의 지속성, 다중 공급자 투명성, AI 통합 및 이벤트 주도 아키텍처를 제공합니다 koan-performance es un marco de trabajo .NET 10 modular que permite a los equipos pequeños construir aplicaciones sofisticadas con patrones simples, incluyendo persistencia de entidad, transparencia de proveedores múltiples y arquitectura orientada a eventos koan-performance est un cadre de travail .NET 10 modulaire qui permet aux petites équipes de construire des applications sophistiquées avec des modèles simples, notamment la persistance d''entité, la transparence de plusieurs fournisseurs et l''architecture orientée vers les événements koan-performance ist ein modulares .NET 10-Framework, das es kleinen Teams ermöglicht, komplexe Anwendungen mit einfachen Mustern zu erstellen, einschließlich Entitätspersistenz, Transparenz mehrerer Anbieter und ereignisorientierter Architektur O Koan é um framework .NET 10 modular que permite que equipes pequenas construam aplicações sofisticadas com padrões simples. Otimização de escala desde o início com streaming, operações em lote e contagens rápidas. Koan - это модульный фреймворк .NET 10, который позволяет небольшим командам создавать сложные приложения с простыми шаблонами. Оптимизация масштабируемости с самого начала с помощью потоковой передачи, пакетных операций и быстрого подсчета. Koan هو إطار عمل .NET 10 قائم على الوحدات يسمح للفرق الصغيرة ببناء تطبيقات معقدة باستخدام أنماط بسيطة. تحسين القابلية للتحجيم منذ البداية مع البث، عمليات الدفع والعد السريع how to use koan-performance koan-performance vs entity framework koan-performance setup guide what is koan-performance koan-performance alternative to asp.net koan-performance install for .net 10 koan-performance best practices for scalable applications koan-performance and ai integration koan-performance for event-driven architecture Koan 性能优化 .NET 10 框架 大规模应用性能优化 AIエージェント 实体优先的持久性 多提供者透明度 事件驱动的架构 Entity-first persistence for efficient data management Multi-provider transparency for flexible architecture AI integration for enhanced application capabilities Event-driven architecture with zero configuration ceremony Streaming for large datasets to optimize performance Batch operations for bulk changes to improve efficiency koan-performance is a modular .NET framework designed for scalable application development with features like entity-first persistence, multi-provider transparency, and AI integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('cskwork/llm-review/multi-ai', 'community', 'cskwork', 'llm-review', 'cskwork/llm-review', 'multi-ai', 0, 0, 36, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:21.525Z', '212df65b929d06756e31a5f1d498c78ed51291f0bc5e3a0c70562d8d5bd3ed92', '{"id":"cskwork/llm-review/multi-ai","name":"multi-ai","description":{"en":"The multi-ai skill enables developers to manage AI pipelines efficiently by automating tasks such as cleaning up previous tasks and capturing user requests. It benefits AI developers and engineers working with complex pipelines.","zh":"Multi-AI Pipeline Orchestrator 是一个集成 Claude 和 Codex 的 AI 工具，用于优化代码审查和生成","ja":"Multi-AI パイプライン オーケストレーターは、Claude と Codex を統合した AI ツールで、コードのレビューと生成を最適化","ko":"멀티 AI 파이프라인 오케스트레이터는 Claude와 Codex를 통합한 AI 도구로 코드 리뷰와 생성을 최적화","es":"Multi-ai es un pipeline de inteligencia artificial que combina Claude y Codex para planificar y codificar proyectos de desarrollo","fr":"Multi-ai est un pipeline d''intelligence artificielle qui combine Claude et Codex pour planifier et coder des projets de développement","de":"Multi-ai ist eine KI-Pipeline, die Claude und Codex kombiniert, um Entwicklungsprojekte zu planen und zu codieren","pt":"O Multi-AI é um pipeline de orquestração que combina Claude e Codex para automatizar tarefas. Aprenda a configurá-lo aqui","ru":"Мульти-АИ - это пайплайн оркестрации, который объединяет Claude и Codex для автоматизации задач. Узнайте, как его настроить","ar":"الفني المتعدد للذكاء الاصطناعي هو مسار تآزر يجمع بين كلود وكودكس لتحسين المهام. تعلم كيفية إعدادها هنا"},"seo":{"title":{"en":"multi-ai: Pipeline Orchestrator Setup Guide | AI Agent Skill","zh":"Multi-AI Pipeline Orchestrator Setup Guide","ja":"Multi-AI パイプライン オーケストレーター設定ガイド","ko":"멀티 AI 파이프라인 오케스트레이터 설정 가이드","es":"Guía de configuración de multi-ai: Agentes de inteligenci...","fr":"Guide de configuration de multi-ai: Outils d''intelligence...","de":"Einrichtungsleitfaden für multi-ai: KI-Tools und -Agenten","pt":"Guia de Configuração do Multi-AI: Pipeline de Orquestração","ru":"Настройка Мульти-АИ: Руководство по Созданию Пайплайна","ar":"دليل إعداد الفني المتعدد للذكاء الاصطناعي: مسار التآزر"},"description":{"en":"Unlock the full potential of multi-ai by following our expert guide. Learn how to set up and utilize the multi-ai pipeline orchestrator for optimized AI work...","zh":"了解 Multi-AI 的技术细节和设置流程，实现 AI Agents 的高效协作","ja":"Multi-AI の技術的詳細と設定プロセスを学び、AI エージェントの効率的なコラボレーションを実現","ko":"멀티 AI의 기술적 세부 사항과 설정 과정을 학습하여 AI 에이전트의 효율적인 협력을 실현","es":"Aprende a configurar y utilizar multi-ai, un pipeline de inteligencia artificial para desarrolladores, con Claude y Codex","fr":"Découvrez comment configurer et utiliser multi-ai, un pipeline d''intelligence artificielle pour les développeurs, avec Claude et Codex","de":"Erfahren Sie, wie Sie multi-ai konfigurieren und verwenden, eine KI-Pipeline für Entwickler, mit Claude und Codex","pt":"Aprenda a configurar o pipeline de orquestração do Multi-AI com Claude e Codex, incluindo limpeza de tarefas e captura de solicitações de usuário","ru":"Узнайте, как настроить пайплайн Мульти-АИ с Claude и Codex, включая очистку задач и захват запросов пользователей","ar":"تعلم كيفية إعداد مسار التآزر للفني المتعدد للذكاء الاصطناعي مع كلود وكودكس، بما في ذلك تنظيف المهام واستقبال طلبات المستخدم"},"definition":{"en":"multi-ai is a pipeline orchestrator that automates tasks such as cleaning up previous tasks, capturing user requests, and creating initial plans for AI workflows","zh":"Multi-AI 是一种 AI 工具，通过集成多个 AI 模型来优化代码审查和生成","ja":"Multi-AI は、複数の AI モデルを統合してコードのレビューと生成を最適化する AI ツール","ko":"멀티 AI는 여러 개의 AI 모델을 통합하여 코드 리뷰와 생성을 최적화하는 AI 도구","es":"Multi-ai es un pipeline de inteligencia artificial que automatiza tareas de planificación y codificación","fr":"Multi-ai est un pipeline d''intelligence artificielle qui automatise les tâches de planification et de codage","de":"Multi-ai ist eine KI-Pipeline, die Planungs- und Codierungsaufgaben automatisiert","pt":"O Multi-AI é um pipeline de orquestração que combina planejamento e codificação para automatizar tarefas","ru":"Мульти-АИ - это пайплайн оркестрации, который объединяет планирование и кодирование для автоматизации задач","ar":"الفني المتعدد للذكاء الاصطناعي هو مسار تآزر يجمع بين التخطيط والبرمجة لتحسين المهام"},"features":{"en":["Removes old .task/ directory using rm -rf command","Creates a new .task/ directory using mkdir -p command","Writes user requests to .task/user-request.txt file","Follows standards outlined in skill/multi-ai/reference/standards.md","Executes step-by-step pipeline process for AI workflow management"],"zh":["支持 Claude 和 Codex 的集成","提供代码审查和生成的优化","实现 AI Agents 的高效协作","支持命令行界面（CLI）操作","提供代码标准和审查标准文档"],"ja":["Claude と Codex の統合をサポート","コードのレビューと生成の最適化を提供","AI エージェントの効率的なコラボレーションを実現","コマンドラインインターフェース（CLI）操作をサポート","コード標準とレビュー基準文書を提供"],"ko":["Claude와 Codex의 통합을 지원","코드 리뷰와 생성의 최적화를 제공","AI 에이전트의 효율적인 협력을 실현","명령줄 인터페이스（CLI）操作을 지원","코드 표준과 리뷰 표준 문서를 제공"],"es":["Integración de Claude y Codex para planificar y codificar proyectos","Limpieza de directorios y creación de nuevos directorios de tarea","Captura de solicitudes de usuario y creación de planes iniciales","Uso de estándares de codificación y criterios de revisión","Compatibilidad con tecnologías de línea de comandos como Bash"],"fr":["Intégration de Claude et Codex pour planifier et coder des projets","Nettoyage de répertoires et création de nouveaux répertoires de tâche","Capture de demandes d''utilisateur et création de plans initiaux","Utilisation de normes de codage et de critères de révision","Compatibilité avec des technologies de ligne de commande comme Bash"],"de":["Integration von Claude und Codex zur Planung und Codierung von Projekten","Bereinigung von Verzeichnissen und Erstellung neuer Aufgabenverzeichnisse","Erfassung von Benutzeranfragen und Erstellung von Initialplänen","Verwendung von Codierungsstandards und Überprüfungskriterien","Kompatibilität mit Kommandozeilentecnologien wie Bash"],"pt":["Limpeza de tarefas anteriores","Captura de solicitações de usuário","Criação de plano inicial","Integração com Claude e Codex","Automatização de tarefas","Otimização de processos"],"ru":["Очистка предыдущих задач","Захват запросов пользователей","Создание начального плана","Интеграция с Claude и Codex","Автоматизация задач","Оптимизация процессов"],"ar":["تنظيف المهام السابقة","استقبال طلبات المستخدم","إنشاء خطة أولية","التكامل مع كلود وكودكس","تحسين المهام","تحسين العمليات"]},"keywords":{"en":["how to use multi-ai","multi-ai pipeline orchestrator","multi-ai vs codex","multi-ai setup guide","what is multi-ai","multi-ai install","multi-ai alternative","multi-ai pipeline management","multi-ai for AI developers","multi-ai workflow automation"],"zh":["Multi-AI","AI Agents","代码审查","代码生成","Claude","Codex","命令行界面","AI 工具"],"ja":["Multi-AI","AI エージェント","コードレビュー","コード生成","Claude","Codex","コマンドラインインターフェース","AI ツール"],"ko":["멀티 AI","AI 에이전트","코드 리뷰","코드 생성","Claude","Codex","명령줄 인터페이스","AI 도구"],"es":["multi-ai","agentes de inteligencia artificial","pipeline de inteligencia artificial","desarrollo de software","automatización de tareas","Claude y Codex","estándares de codificación","criterios de revisión","tecnologías de línea de comandos"],"fr":["multi-ai","outils d''intelligence artificielle","pipeline d''intelligence artificielle","développement de logiciels","automatisation de tâches","Claude et Codex","normes de codage","critères de révision","technologies de ligne de commande"],"de":["multi-ai","KI-Tools und -Agenten","KI-Pipeline","Softwareentwicklung","Automatisierung von Aufgaben","Claude und Codex","Codierungsstandards","Überprüfungskriterien","Kommandozeilentecnologien"],"pt":["Multi-AI","pipeline de orquestração","automatização de tarefas","Claude","Codex","limpeza de tarefas","captura de solicitações de usuário","criação de plano inicial","integração com AI"],"ru":["Мульти-АИ","пайплайн оркестрации","автоматизация задач","Claude","Codex","очистка задач","захват запросов пользователей","создание начального плана","интеграция с ИИ"],"ar":["الفني المتعدد للذكاء الاصطناعي","مسار التآزر","تحسين المهام","كلود","كودكس","تنظيف المهام","استقبال طلبات المستخدم","إنشاء خطة أولية","التكامل مع الذكاء الاصطناعي"]}},"owner":"cskwork","repo":"llm-review","repoPath":"cskwork/llm-review","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"multi-ai","description":"Start the multi-AI pipeline with a given request. Guides through plan -> review -> implement -> review workflow.","bodyPreview":"# Multi-AI Pipeline Orchestrator\n\nYou are starting the multi-AI pipeline. Follow this process exactly.\n\n## Reference Documents\n\nFirst, read the standards that guide all reviews:\n- `skill/multi-ai/reference/standards.md` - Coding standards and review criteria\n\n## Step 1: Clean Up Previous Task\n\nRemove old `.task/` directory if it exists:\n\n```bash\nrm -rf .task\nmkdir -p .task\n```\n\n## Step 2: Capture User Request\n\nWrite the user''s request to `.task/user-request.txt`.\n\n## Step 3: Create Initial Plan","body":"# Multi-AI Pipeline Orchestrator\n\nYou are starting the multi-AI pipeline. Follow this process exactly.\n\n## Reference Documents\n\nFirst, read the standards that guide all reviews:\n- `skill/multi-ai/reference/standards.md` - Coding standards and review criteria\n\n## Step 1: Clean Up Previous Task\n\nRemove old `.task/` directory if it exists:\n\n```bash\nrm -rf .task\nmkdir -p .task\n```\n\n## Step 2: Capture User Request\n\nWrite the user''s request to `.task/user-request.txt`.\n\n## Step 3: Create Initial Plan\n\nWrite `.task/plan.json`:\n\n```json\n{\n  \"id\": \"plan-YYYYMMDD-HHMMSS\",\n  \"title\": \"Short descriptive title\",\n  \"description\": \"What the user wants to achieve\",\n  \"requirements\": [\"req1\", \"req2\"],\n  \"created_at\": \"ISO8601\",\n  \"created_by\": \"claude\"\n}\n```\n\n## Step 4: Refine Plan\n\nResearch the codebase and create `.task/plan-refined.json`:\n\n```json\n{\n  \"id\": \"plan-001\",\n  \"title\": \"Feature title\",\n  \"description\": \"What the user wants\",\n  \"requirements\": [\"req1\", \"req2\"],\n  \"technical_approach\": \"Detailed how-to\",\n  \"files_to_modify\": [\"path/to/file.ts\"],\n  \"files_to_create\": [\"path/to/new.ts\"],\n  \"dependencies\": [],\n  \"estimated_complexity\": \"low|medium|high\",\n  \"potential_challenges\": [\"Challenge and mitigation\"],\n  \"refined_by\": \"claude\",\n  \"refined_at\": \"ISO8601\"\n}\n```\n\n## Step 5: Sequential Plan Reviews\n\nRun reviews in sequence. Fix issues after each before continuing:\n\n1. **Invoke /review-sonnet**\n   - Read `.task/review-sonnet.json` result\n   - If `needs_changes`: fix issues in plan, update `.task/plan-refined.json`\n\n2. **Invoke /review-codex**\n   - Read `.task/review-codex.json` result\n   - If `needs_changes`: fix issues and **restart from step 5.1**\n   - If `approved`: continue to implementation\n\n## Step 6: Implement\n\n**Invoke /implement-sonnet**\n\nThis skill will:\n- Read the approved plan from `.task/plan-refined.json`\n- Implement the code\n- Add tests\n- Output to `.task/impl-result.json`\n\n## Step 7: Sequential Code Reviews\n\nRun reviews in sequence. Fix issues after each before continuing:\n\n1. **Invoke /review-sonnet**\n   - Read `.task/review-sonnet.json` result\n   - If `needs_changes`: fix code issues\n\n2. **Invoke /review-codex**\n   - Read `.task/review-codex.json` result\n   - If `needs_changes`: fix issues and **restart from step 7.1**\n   - If `approved`: continue to completion\n\n## Step 8: Complete\n\nWrite `.task/state.json`:\n\n```json\n{\n  \"state\": \"complete\",\n  \"plan_id\": \"plan-001\",\n  \"completed_at\": \"ISO8601\"\n}\n```\n\nReport success to the user with:\n- Summary of what was implemented\n- Files changed\n- Tests added\n\n---\n\n## Important Rules\n\n- Follow this process exactly - no shortcuts\n- Fix ALL issues raised by reviewers before continuing\n- If codex rejects, restart the review cycle from sonnet\n- Keep the user informed of progress at each major step\n\n## State Files Reference\n\n| File | Purpose |\n|------|---------|\n| `.task/user-request.txt` | Original user request |\n| `.task/plan.json` | Initial plan |\n| `.task/plan-refined.json` | Refined plan with technical details |\n| `.task/impl-result.json` | Implementation result |\n| `.task/review-sonnet.json` | Sonnet review output |\n| `.task/review-codex.json` | Codex review output |\n| `.task/state.json` | Pipeline state |\n\n## Reference Directory\n\n| Path | Purpose |\n|------|---------|\n| `skill/multi-ai/reference/standards.md` | Review criteria and coding standards |\n| `skill/multi-ai/reference/schemas/` | JSON schemas for structured output |\n"},"lastSynced":"2026-03-08T02:01:21.525Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Pipeline Agents needing efficient task management and automation capabilities.","zh":"适合需要高效任务管理和自动化能力的AI Pipeline Agents。","ja":"タスク管理と自動化能力が必要なAI Pipeline Agentsに最適です。","ko":"효율적인 작업 관리 및 자동화 기능이 필요한 AI Pipeline 에이전트에 적합합니다.","es":"Ideal para Agentes de Pipeline de IA que necesitan una gestión de tareas eficiente y capacidades de automatización.","fr":"Idéal pour les agents de pipeline d''IA nécessitant une gestion de tâches efficace et des capacités d''automatisation.","de":"Ideal für AI-Pipeline-Agents, die eine effiziente Aufgabenverwaltung und Automatisierungsfähigkeiten benötigen.","pt":"Ideal para Agentes de Pipeline de IA que necessitam de gerenciamento de tarefas eficiente e capacidades de automação.","ru":"Идеально для агентов конвейера ИИ, требующих эффективного управления задачами и возможностей автоматизации.","ar":"مثالية للوكلاء أنابيب الذكاء الاصطناعي الذين يحتاجون إلى إدارة مهمة فعالة وقدرات الأتمتة."},"recommendation":{"en":"Empowers agents to automate tasks such as cleaning up previous tasks and capturing user requests, streamlining AI pipeline development with standardized coding practices and review criteria, utilizing files like `.task/user-request.txt` and protocols like bash scripting.","zh":"赋予代理自动执行清理前置任务和捕获用户请求等任务的能力，通过标准化编码实践和审查标准来简化AI Pipeline开发，利用诸如`.task/user-request.txt`的文件和bash脚本等协议。","ja":"エージェントにタスクのクリーンアップやユーザー要求のキャプチャなどのタスクを自動化する能力を付与し、標準化されたコード実践とレビュークリテリアを使用してAIパイプライン開発を簡素化し、`.task/user-request.txt`などのファイルやbashスクリプトなどのプロトコルを利用する。","ko":"에이전트가 이전 작업을 정리하고 사용자 요청을 캡처하는 등의 작업을 자동화할 수 있는 능력을 부여하여 표준화된 코딩 관행 및 검토 기준을 사용하여 AI 파이프라인 개발을 간소화하며 `.task/user-request.txt`와 같은 파일 및 bash 스크립트와 같은 프로토콜을 활용합니다.","es":"Permite a los agentes automatizar tareas como la limpieza de tareas anteriores y la captura de solicitudes de usuarios, simplificando el desarrollo de la canalización de IA con prácticas de codificación estandarizadas y criterios de revisión, utilizando archivos como `.task/user-request.txt` y protocolos como bash scripting.","fr":"Permet aux agents d''automatiser des tâches telles que le nettoyage des tâches précédentes et la capture des demandes des utilisateurs, simplifiant le développement du pipeline d''IA avec des pratiques de codage standardisées et des critères d''examen, en utilisant des fichiers tels que `.task/user-request.txt` et des protocoles tels que bash scripting.","de":"Ermächtigt Agents, Aufgaben wie die Bereinigung vorheriger Aufgaben und die Erfassung von Benutzeranfragen zu automatisieren, vereinfacht die Entwicklung der AI-Pipeline mit standardisierten Codierpraktiken und Überprüfungskriterien, unter Verwendung von Dateien wie `.task/user-request.txt` und Protokollen wie bash scripting.","pt":"Habilita os agentes a automatizar tarefas, como limpar tarefas anteriores e capturar solicitações de usuário, racionalizando o desenvolvimento de pipeline de IA com práticas de codificação padronizadas e critérios de revisão, utilizando arquivos como `.task/user-request.txt` e protocolos como script de bash.","ru":"Наделяет агентов возможностью автоматизировать задачи, такие как очистка предыдущих задач и захват запросов пользователей, оптимизируя разработку конвейера ИИ с помощью стандартизированных практик кодирования и критериев рассмотрения, используя файлы типа `.task/user-request.txt` и протоколы типа скриптов bash.","ar":"تمكين الوكلاء من أتمتة المهام مثل تنظيف المهام السابقة و захоп الطلبات من المستخدم ، و تسريع تطوير أنابيب الذكاء الاصطناعي باستخدام ممارسات الترميز الموحدة ومعايير المراجعة ، باستخدام الملفات مثل `.task/user-request.txt` و البروتوكولات مثل البرمجة النصية bash."},"useCases":{"en":["Automating pipeline cleanup","Capturing and processing user requests","Orchestrating multi-AI pipeline workflows"],"zh":["自动化管道清理","捕获和处理用户请求","编排多AI管道工作流"],"ja":["パイプラインのクリーンアップを自動化する","ユーザー要求をキャプチャして処理する","マルチAIパイプラインワークフローをオーケストレートする"],"ko":["파이프라인 정리를 자동화하는 것","사용자 요청을 캡처하고 처리하는 것","다중 AI 파이프라인 워크플로우를 오케스트레이션하는 것"],"es":["Automatización de la limpieza de la canalización","Captura y procesamiento de solicitudes de usuarios","Orquestación de flujos de trabajo de canalización de IA múltiple"],"fr":["Automatisation du nettoyage de la canalisation","Capture et traitement des demandes des utilisateurs","Orchestration de flux de travail de canalisation d''IA multiple"],"de":["Automatisierung der Pipeline-Bereinigung","Erfassung und Verarbeitung von Benutzeranfragen","Orchestrierung von Multi-IA-Pipeline-Arbeitsflüssen"],"pt":["Automatizar limpeza de pipeline","Capturar e processar solicitações de usuário","Orquestrar fluxos de trabalho de pipeline de IA múltiplos"],"ru":["Автоматизировать очистку конвейера","Захват и обработка запросов пользователей","Оркестрировать рабочие процессы конвейера ИИ"],"ar":["أتمتة تنظيف أنابيب","أستقبال ومعالجة الطلبات من المستخدم","إشراف على سير عمل أنابيب الذكاء الاصطناعي المتعددة"]},"limitations":{"en":["Requires filesystem access for task directory management","Dependent on specific directory structure like `.task/`","Limited to bash-compatible environments"],"zh":["需要文件系统访问以管理任务目录","依赖于特定的目录结构如`.task/`","仅限bash兼容环境"],"ja":["タスクディレクトリの管理のためにファイルシステムへのアクセスが必要","`.task/`などの特定のディレクトリ構造に依存している","bash互換環境に限定される"],"ko":["작업 디렉토리 관리를 위해 파일 시스템에 액세스해야 함","`.task/`와 같은 특정 디렉토리 구조에 의존","bash와 호환되는 환경으로 제한됨"],"es":["Requiere acceso al sistema de archivos para la gestión del directorio de tareas","Dependiente de una estructura de directorio específica como `.task/`","Limitado a entornos compatibles con bash"],"fr":["Nécessite un accès au système de fichiers pour la gestion du répertoire de tâches","Dépend d''une structure de répertoire spécifique comme `.task/`","Limité aux environnements compatibles bash"],"de":["Benötigt Dateisystemzugriff für die Verwaltung des Aufgabenverzeichnisses","Abhängig von einer bestimmten Verzeichnisstruktur wie `.task/`","Begrenzt auf bash-kompatible Umgebungen"],"pt":["Requer acesso ao sistema de arquivos para gerenciamento de diretório de tarefas","Dependente de estrutura de diretório específica como `.task/`","Limitado a ambientes compatíveis com bash"],"ru":["Требует доступа к файловой системе для управления каталогом задач","Зависит от конкретной структуры каталога, такой как `.task/`","Ограничен средами, совместимыми с bash"],"ar":["يتطلب الوصول إلى نظام الملفات لإدارة دليل المهام","يعتمد على هيكل دليل محدد مثل `.task/`","محدود بالبيئات المتوافقة مع bash"]},"version":4},"contentHash":"212df65b929d06756e31a5f1d498c78ed51291f0bc5e3a0c70562d8d5bd3ed92","qualityScore":36}');
