INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('cskwork/llm-review/multi-ai', 'multi-ai', 'cskwork', 'llm-review', 'community', 'multi-ai cskwork llm-review community The multi-ai skill enables developers to manage AI pipelines efficiently by automating tasks such as cleaning up previous tasks and capturing user requests. It benefits AI developers and engineers working with complex pipelines. Multi-AI Pipeline Orchestrator 是一个集成 Claude 和 Codex 的 AI 工具，用于优化代码审查和生成 Multi-AI パイプライン オーケストレーターは、Claude と Codex を統合した AI ツールで、コードのレビューと生成を最適化 멀티 AI 파이프라인 오케스트레이터는 Claude와 Codex를 통합한 AI 도구로 코드 리뷰와 생성을 최적화 Multi-ai es un pipeline de inteligencia artificial que combina Claude y Codex para planificar y codificar proyectos de desarrollo Multi-ai est un pipeline d''intelligence artificielle qui combine Claude et Codex pour planifier et coder des projets de développement Multi-ai ist eine KI-Pipeline, die Claude und Codex kombiniert, um Entwicklungsprojekte zu planen und zu codieren O Multi-AI é um pipeline de orquestração que combina Claude e Codex para automatizar tarefas. Aprenda a configurá-lo aqui Мульти-АИ - это пайплайн оркестрации, который объединяет Claude и Codex для автоматизации задач. Узнайте, как его настроить الفني المتعدد للذكاء الاصطناعي هو مسار تآزر يجمع بين كلود وكودكس لتحسين المهام. تعلم كيفية إعدادها هنا how to use multi-ai multi-ai pipeline orchestrator multi-ai vs codex multi-ai setup guide what is multi-ai multi-ai install multi-ai alternative multi-ai pipeline management multi-ai for AI developers multi-ai workflow automation Multi-AI AI Agents 代码审查 代码生成 Claude Codex 命令行界面 AI 工具 Removes old .task/ directory using rm -rf command Creates a new .task/ directory using mkdir -p command Writes user requests to .task/user-request.txt file Follows standards outlined in skill/multi-ai/reference/standards.md Executes step-by-step pipeline process for AI workflow management multi-ai is a pipeline orchestrator that automates tasks such as cleaning up previous tasks, capturing user requests, and creating initial plans for AI workflows');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('darthlinuxer/Agentic-Skills/game-design', 'community', 'darthlinuxer', 'Agentic-Skills', 'darthlinuxer/Agentic-Skills', 'game-design', 0, 0, 36, '2026-03-08T01:57:15.298Z', '2026-03-08T02:01:23.575Z', 'c8795c5a13b2e91a803d787c59f6bcb7c726c95094d0db54fb69ccc3f71bdc3b', '{"id":"darthlinuxer/Agentic-Skills/game-design","name":"game-design","description":{"en":"The game-design skill enables developers to create engaging games using core loop design principles. It benefits game developers and designers by providing a structured approach to game development.","zh":"游戏设计涉及创建吸引人的核心循环，包括30秒测试和设计思维","ja":"ゲームデザインでは、30秒ループテストとデザイン思考を使用してエンゲージメントの高いゲームを作成する","ko":"게임 디자인은 사용자 참여를 유도하는 핵심 루프 생성을 포함하며, 30초 테스트와 디자인 사고를 활용","es":"Diseño de juegos con agentes de IA para crear experiencias de juego atractivas y divertidas","fr":"Concevoir des jeux avec des outils d''IA pour offrir des expériences de jeu engageantes et amusantes","de":"Game-Design mit KI-Agenten für unterhaltsame und ansprechende Spielerlebnisse","pt":"O design de jogo envolve a criação de um loop de jogo atraente, com ação, feedback e recompensa. Aprenda a aplicar o pensamento sequencial para resolver problemas complexos.","ru":"Дизайн игр включает в себя создание увлекательного основного цикла, состоящего из действия, обратной связи и награды. Изучите, как применять последовательное мышление для решения сложных проблем.","ar":"تصميم الألعاب يتضمن إنشاء حلقة لعبة جذابة، مع عمل، ملاحظات و مكافأة. تعلم كيفية تطبيق التفكير التسلسلي لحل المشكلات المعقدة."},"seo":{"title":{"en":"Game-Design: Core Loop Optimization for AI Agents | AI Ag...","zh":"游戏设计最佳实践：30秒循环测试指南","ja":"ゲームデザインのためのAIエージェント：30秒ループテストの設定","ko":"게임 디자인 설정 가이드: 30초 루프 테스트 및 시퀀셜 싱킹","es":"Guía de Diseño de Juegos con Agentes de IA","fr":"Concevoir des Jeux avec des Outils d''IA - Guide de Démarrage","de":"Game-Design-Setup mit KI-Agenten - Beste Praktiken","pt":"Desenvolvimento de Jogos: Guia de Design de Loop de Jogo","ru":"ИИ Агенты для Дизайна Игр: Настройка Основного Цикла","ar":"تصميم الألعاب: دليل إنشاء حلقة اللعبة"},"description":{"en":"Unlock engaging game design with our AI Agent Skill. Learn how to create addictive core loops and improve player experience. Get started now!","zh":"了解游戏设计的核心循环设计和30秒测试，打造更吸引人的游戏体验","ja":"ゲームデザインの基本である30秒ループテストとシーケンシャル思考を学び、エンゲージメントの高いゲームを作成する","ko":"게임 디자인을 위한 30초 루프 테스트와 시퀀셜 싱킹을 통해 사용자 참여度를 높이는 방법","es":"Aprende a diseñar juegos con un ciclo de juego divertido y atractivo utilizando agentes de IA y técnicas de pensamiento secuencial","fr":"Découvrez comment concevoir des jeux engageants avec des outils d''IA et des principes de design de jeu pour une expérience utilisateur optimale","de":"Entdecken Sie, wie Sie Spiele mit einem unterhaltsamen Spielzyklus und KI-Agenten entwickeln können, um komplexe Probleme zu lösen","pt":"Aprenda a criar jogos engajadores com o design de loop de jogo certinho. Descubra como aplicar o pensamento sequencial para resolver problemas complexos.","ru":"Изучите основы дизайна игр с помощью ИИ Агентов. Создайте увлекательные игры с помощью правильно спроектированного основного цикла.","ar":"تعلم كيفية تصميم ألعاب ممتعة مع تصميم حلقة اللعبة الصحيح. اكتشف كيفية تطبيق التفكير التسلسلي لحل المشكلات المعقدة."},"definition":{"en":"Game-design is a set of principles and practices used to create engaging and interactive games, focusing on core loop design and player experience.","zh":"游戏设计是指创建引人入胜的游戏体验的过程，涉及核心循环设计和用户反馈","ja":"ゲームデザインとは、エンゲージメントの高いゲーム体験を作成するためのプロセスであり、コアループ設計とユーザーフィードバックが含まれる","ko":"게임 디자인은 사용자의 참여를 유도하는 게임 경험을 생성하는 과정으로, 핵심 루프 설계 및 사용자 피드백이 포함","es":"Diseño de juegos es el proceso de crear experiencias de juego interactivas y atractivas utilizando técnicas de diseño y agentes de IA","fr":"La conception de jeux est le processus de création d''expériences de jeu interactives et engageantes en utilisant des techniques de design et des outils d''IA","de":"Game-Design ist der Prozess der Erstellung interaktiver und unterhaltsamer Spielerlebnisse mithilfe von Design-Techniken und KI-Agenten","pt":"O design de jogo é o processo de criar experiências de jogo interativas e envolventes, com foco no loop de jogo e na resolução de problemas complexos.","ru":"Дизайн игр - это процесс создания интерактивных и увлекательных игровых опытов, с фокусом на основном цикле и решении сложных проблем.","ar":"تصميم الألعاب هو عملية إنشاء تجارب ألعاب تفاعلية وملفتة، مع التركيز على حلقة اللعبة وحل المشكلات المعقدة."},"features":{"en":["Applies Sequential Thinking for complex problem-solving in game design","Utilizes the 30-Second Test for evaluating core loop effectiveness","Supports design thinking for creating engaging games","Breaks down decisions and design processes into structured reasoning steps","Enables creation of fun and rewarding core loops using ACTION, FEEDBACK, and REWARD sequences"],"zh":["核心循环设计","30秒测试","设计思维","序列思考","用户反馈机制","奖励系统设计"],"ja":["コアループ設計","30秒ループテスト","デザイン思考","シーケンシャル思考","ユーザーフィードバック機構","報酬システム設計"],"ko":["핵심 루프 설계","30초 루프 테스트","디자인 사고","시퀀셜 싱킹","사용자 피드백 메커니즘","보상 시스템 설계"],"es":["Ciclo de juego de 30 segundos para experiencias de juego divertidas","Técnicas de pensamiento secuencial para resolver problemas complejos","Diseño de bucles de juego para experiencias de juego engaging","Uso de agentes de IA para mejorar la experiencia del jugador","Principios de diseño de juego para crear experiencias de juego atractivas"],"fr":["Cycle de jeu de 30 secondes pour des expériences de jeu amusantes","Téchniques de pensée séquentielle pour résoudre des problèmes complexes","Conception de boucles de jeu pour des expériences de jeu engageantes","Utilisation d''outils d''IA pour améliorer l''expérience du joueur","Principes de conception de jeu pour créer des expériences de jeu attractives"],"de":["Spielzyklus von 30 Sekunden für unterhaltsame Spielerlebnisse","Techniken des sequenziellen Denkens für die Lösung komplexer Probleme","Entwurf von Spielzyklen für ansprechende Spielerlebnisse","Verwendung von KI-Agenten zur Verbesserung der Spielerfahrung","Prinzipien des Game-Designs für die Erstellung unterhaltsamer Spielerlebnisse"],"pt":["Design de loop de jogo com ação, feedback e recompensa","Pensamento sequencial para resolver problemas complexos","Criação de experiências de jogo interativas e envolventes","Análise de jogos por gênero e tipo de loop de jogo","Aplicação de princípios de design de jogo para resolver problemas","Uso de ferramentas de design de jogo para criar jogos personalizados"],"ru":["Дизайн основного цикла с действием, обратной связью и наградой","Последовательное мышление для решения сложных проблем","Создание интерактивных и увлекательных игровых опытов","Анализ игр по жанру и типу основного цикла","Применение принципов дизайна игр для решения проблем","Использование инструментов дизайна игр для создания индивидуальных игр"],"ar":["تصميم حلقة اللعبة مع عمل، ملاحظات و مكافأة","التفكير التسلسلي لحل المشكلات المعقدة","إنشاء تجارب ألعاب تفاعلية وملفتة","تحليل الألعاب حسب النوع و نوع حلقة اللعبة","تطبيق مبادئ تصميم الألعاب لحل المشكلات","استخدام أدوات تصميم الألعاب لإنشاء ألعاب مخصصة"]},"keywords":{"en":["how to use game-design","game-design principles","core loop design examples","game-design vs level design","game-design setup guide","what is game-design","game-design install for AI Agents","game-design alternative for developers"],"zh":["游戏设计","核心循环设计","30秒测试","设计思维","序列思考","游戏开发","AI游戏设计","游戏设计工具","游戏设计软件"],"ja":["ゲームデザイン","コアループ設計","30秒ループテスト","デザイン思考","シーケンシャル思考","ゲーム開発","AIゲームデザイン","ゲームデザインツール","ゲームデザインソフトウェア"],"ko":["게임 디자인","핵심 루프 설계","30초 루프 테스트","디자인 사고","시퀀셜 싱킹","게임 개발","AI 게임 디자인","게임 디자인 툴","게임 디자인 소프트웨어"],"es":["diseño de juegos","agentes de IA","ciclo de juego","pensamiento secuencial","experiencias de juego","juegos interactivos","desarrollo de juegos","herramientas de IA para juegos","principios de diseño de juego"],"fr":["conception de jeux","outils d''IA","cycle de jeu","pensée séquentielle","expériences de jeu","jeux interactifs","développement de jeux","outils d''IA pour les jeux","principes de conception de jeu"],"de":["Game-Design","KI-Agenten","Spielzyklus","sequenzielles Denken","Spielerlebnisse","interaktive Spiele","Spieleentwicklung","KI-Tools für Spiele","Prinzipien des Game-Designs"],"pt":["desenvolvimento de jogos","design de loop de jogo","pensamento sequencial","criação de jogos","análise de jogos","ferramentas de design de jogo","princípios de design de jogo","jogos interativos","experiências de jogo","resolução de problemas complexos"],"ru":["разработка игр","дизайн основного цикла","последовательное мышление","создание игр","анализ игр","инструменты дизайна игр","принципы дизайна игр","интерактивные игры","игровые опыты","решение сложных проблем"],"ar":["تصميم الألعاب","تصميم حلقة اللعبة","التفكير التسلسلي","إنشاء ألعاب","تحليل الألعاب","أدوات تصميم الألعاب","مبادئ تصميم الألعاب","ألعاب تفاعلية","تجارب ألعاب","حل المشكلات المعقدة"]}},"owner":"darthlinuxer","repo":"Agentic-Skills","repoPath":"darthlinuxer/Agentic-Skills","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.298Z","topics":[],"category":"community","skillMd":{"name":"game-design","description":"Game design principles. GDD structure, balancing, player psychology,","bodyPreview":"# Game Design Principles\n\n> **🧠 MCP Tool Available**: Use **Sequential Thinking** for complex problem-solving in this domain. Break down decisions, debug chains, or design processes into structured reasoning steps.\n\n> Design thinking for engaging games.\n\n---\n\n## 1. Core Loop Design\n\n### The 30-Second Test\n\n```\nEvery game needs a fun 30-second loop:\n1. ACTION → Player does something\n2. FEEDBACK → Game responds\n3. REWARD → Player feels good\n4. REPEAT\n```\n\n### Loop Examples\n\n| Genre | Core Loop |","body":"# Game Design Principles\n\n> **🧠 MCP Tool Available**: Use **Sequential Thinking** for complex problem-solving in this domain. Break down decisions, debug chains, or design processes into structured reasoning steps.\n\n> Design thinking for engaging games.\n\n---\n\n## 1. Core Loop Design\n\n### The 30-Second Test\n\n```\nEvery game needs a fun 30-second loop:\n1. ACTION → Player does something\n2. FEEDBACK → Game responds\n3. REWARD → Player feels good\n4. REPEAT\n```\n\n### Loop Examples\n\n| Genre | Core Loop |\n|-------|-----------|\n| Platformer | Run → Jump → Land → Collect |\n| Shooter | Aim → Shoot → Kill → Loot |\n| Puzzle | Observe → Think → Solve → Advance |\n| RPG | Explore → Fight → Level → Gear |\n\n---\n\n## 2. Game Design Document (GDD)\n\n### Essential Sections\n\n| Section | Content |\n|---------|---------|\n| **Pitch** | One-sentence description |\n| **Core Loop** | 30-second gameplay |\n| **Mechanics** | How systems work |\n| **Progression** | How player advances |\n| **Art Style** | Visual direction |\n| **Audio** | Sound direction |\n\n### Principles\n\n- Keep it living (update regularly)\n- Visuals help communicate\n- Less is more (start small)\n\n---\n\n## 3. Player Psychology\n\n### Motivation Types\n\n| Type | Driven By |\n|------|-----------|\n| **Achiever** | Goals, completion |\n| **Explorer** | Discovery, secrets |\n| **Socializer** | Interaction, community |\n| **Killer** | Competition, dominance |\n\n### Reward Schedules\n\n| Schedule | Effect | Use |\n|----------|--------|-----|\n| **Fixed** | Predictable | Milestone rewards |\n| **Variable** | Addictive | Loot drops |\n| **Ratio** | Effort-based | Grind games |\n\n---\n\n## 4. Difficulty Balancing\n\n### Flow State\n\n```\nToo Hard → Frustration → Quit\nToo Easy → Boredom → Quit\nJust Right → Flow → Engagement\n```\n\n### Balancing Strategies\n\n| Strategy | How |\n|----------|-----|\n| **Dynamic** | Adjust to player skill |\n| **Selection** | Let player choose |\n| **Accessibility** | Options for all |\n\n---\n\n## 5. Progression Design\n\n### Progression Types\n\n| Type | Example |\n|------|---------|\n| **Skill** | Player gets better |\n| **Power** | Character gets stronger |\n| **Content** | New areas unlock |\n| **Story** | Narrative advances |\n\n### Pacing Principles\n\n- Early wins (hook quickly)\n- Gradually increase challenge\n- Rest beats between intensity\n- Meaningful choices\n\n---\n\n## 6. Anti-Patterns\n\n| ❌ Don''t | ✅ Do |\n|----------|-------|\n| Design in isolation | Playtest constantly |\n| Polish before fun | Prototype first |\n| Force one way to play | Allow player expression |\n| Punish excessively | Reward progress |\n\n---\n\n> **Remember:** Fun is discovered through iteration, not designed on paper.\n"},"lastSynced":"2026-03-08T02:01:23.575Z","agentAnalysis":{"suitability":{"en":"Perfect for Creative Agents needing structured game development principles and core loop design capabilities.","zh":"非常适合需要结构化游戏开发原则和核心循环设计能力的创意代理","ja":"創造性エージェントが構造化されたゲーム開発の原則とコアループ設計能力を必要とする場合に最適","ko":"구조화된 게임 개발 원칙과 핵심 루프 디자인 능력이 필요한 창의적 에이전트에게 적합","es":"Perfecto para Agentes Creativos que necesitan principios de desarrollo de juegos estructurados y capacidades de diseño de bucle central.","fr":"Parfait pour les agents créatifs ayant besoin de principes de développement de jeux structurés et de capacités de conception de boucle centrale.","de":"Perfekt für kreative Agenten, die strukturierte Spielentwicklungsprinzipien und Kerndesignfähigkeiten benötigen.","pt":"Perfeito para Agentes Criativos que precisam de princípios de desenvolvimento de jogos estruturados e capacidades de design de loop central.","ru":"Идеально подходит для творческих агентов, которым необходимы структурированные принципы разработки игр и возможности проектирования основной игровой механики.","ar":"مثالي للوكلاء الإبداعيين الذين يحتاجون إلى مبادئ متطورة لتصميم ألعاب منظمة وقدرات تصميم حلقة لعب مركزية."},"recommendation":{"en":"Empowers agents to craft engaging games using design thinking, sequential thinking, and core loop design principles, incorporating feedback and reward mechanisms to create immersive player experiences.","zh":"赋予代理使用设计思维、顺序思维和核心循环设计原则来创建吸引人的游戏，融入反馈和奖励机制以创建沉浸式玩家体验","ja":"設計思考、順序思考、コアループ設計原則を使用して魅力的ゲームを作成し、フィードバックと報酬メカニズムを組み込んで没入感のあるプレイヤー体験を作成するエージェントをEmpowerする","ko":"디자인 사고, 순차적 사고, 핵심 루프 디자인 원리를 사용하여 매력적인 게임을 만들고, 피드백 및 보상 메커니즘을 통합하여 몰입감 있는 플레이어 경험을 만드는 에이전트를 강화합니다","es":"Habilita a los agentes a crear juegos atractivos utilizando diseño de pensamiento, pensamiento secuencial y principios de diseño de bucle central, incorporando mecanismos de retroalimentación y recompensa para crear experiencias de jugador inmersivas.","fr":"Permet aux agents de créer des jeux engageants en utilisant la conception de pensée, la pensée séquentielle et les principes de conception de boucle centrale, en intégrant des mécanismes de rétroaction et de récompense pour créer des expériences de joueur immersives.","de":"Ermöglicht es Agenten, ansprechende Spiele zu erstellen, indem sie Design-Denken, sequenzielles Denken und Kerndesign-Prinzipien verwenden und Feedback- und Belohnungsmechanismen einsetzen, um immersive Spielerfahrungen zu schaffen.","pt":"Habilita os agentes a criar jogos envolventes usando design thinking, pensamento sequencial e princípios de design de loop central, incorporando mecanismos de feedback e recompensa para criar experiências de jogador imersivas.","ru":"Наделяет агентов возможностью создавать увлекательные игры, используя принципы дизайна-мышления, последовательного мышления и проектирования основной игровой механики, включая механизмы обратной связи и наград для создания погружающих игровых опытов.","ar":"يمنح الوكلاء إمكانية إنشاء ألعاب متجاوبة باستخدام التفكير التصميمي والتفكير المتسلسل ومبادئ تصميم حلقة اللعب المركزية، ودمج آليات обратية وآلية المكافأة لإنشاء تجارب لاعبي غامرة."},"useCases":{"en":["Designing addictive core loops for mobile games","Developing engaging feedback and reward systems","Applying sequential thinking to debug game development processes"],"zh":["为移动游戏设计上瘾的核心循环","开发吸引人的反馈和奖励系统","将顺序思维应用于调试游戏开发流程"],"ja":["モバイルゲームのアドクティブなコアループを設計する","魅力的フィードバックと報酬システムを開発する","ゲーム開発プロセスのデバッグに順序思考を適用する"],"ko":["모바일 게임을 위한 중독성 있는 핵심 루프를 설계하는 것","매력적인 피드백 및 보상 시스템을 개발하는 것","게임 개발 프로세스의 디버깅에 순차적 사고를 적용하는 것"],"es":["Diseñar bucles centrales adictivos para juegos móviles","Desarrollar sistemas de retroalimentación y recompensa atractivos","Aplicar pensamiento secuencial para depurar procesos de desarrollo de juegos"],"fr":["Concevoir des boucles centrales addictives pour les jeux mobiles","Développer des systèmes de rétroaction et de récompense engageants","Appliquer la pensée séquentielle pour déboguer les processus de développement de jeux"],"de":["Entwerfen von süchtig machenden Kernschleifen für Mobile Games","Entwickeln von ansprechenden Feedback- und Belohnungssystemen","Anwenden von sequenziellen Denken, um Spielentwicklungsprozesse zu debuggen"],"pt":["Projeto de loops centrais viciantes para jogos móveis","Desenvolvimento de sistemas de feedback e recompensa envolventes","Aplicação de pensamento sequencial para depurar processos de desenvolvimento de jogos"],"ru":["Проектирование увлекательных основных игровых механик для мобильных игр","Разработка увлекательных систем обратной связи и наград","Применение последовательного мышления для отладки процессов разработки игр"],"ar":["تصميم حلقة لعب مركزية مخدرة لألعاب الجوال","تطوير أنظمة للتعليقات والمكافآت المثيرة","تطبيق التفكير المتسلسل لتصحيح أخطاء عمليات تطوير الألعاب"]},"limitations":{"en":["Requires understanding of game design principles","Limited to game development applications"],"zh":["需要了解游戏设计原则","仅限游戏开发应用"],"ja":["ゲーム設計の原則の理解が必要","ゲーム開発アプリケーションに限定"],"ko":["게임 디자인 원리의 이해가 필요","게임 개발 응용 프로그램에만 제한"],"es":["Requiere comprensión de los principios de diseño de juegos","Limitado a aplicaciones de desarrollo de juegos"],"fr":["Nécessite une compréhension des principes de conception de jeux","Limité aux applications de développement de jeux"],"de":["Benötigt Verständnis für Spielentwicklungsprinzipien","Begrenzt auf Spielentwicklungsanwendungen"],"pt":["Exige compreensão de princípios de design de jogos","Limitado a aplicações de desenvolvimento de jogos"],"ru":["Требует понимания принципов дизайна игр","Ограничен применением в разработке игр"],"ar":["يتطلب فهم مبادئ تصميم الألعاب","محدود بتطبيقات تطوير الألعاب"]},"version":4},"contentHash":"c8795c5a13b2e91a803d787c59f6bcb7c726c95094d0db54fb69ccc3f71bdc3b","qualityScore":36}');
