INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('darthlinuxer/Agentic-Skills/game-design', 'game-design', 'darthlinuxer', 'Agentic-Skills', 'community', 'game-design darthlinuxer Agentic-Skills community The game-design skill enables developers to create engaging games using core loop design principles. It benefits game developers and designers by providing a structured approach to game development. 游戏设计涉及创建吸引人的核心循环，包括30秒测试和设计思维 ゲームデザインでは、30秒ループテストとデザイン思考を使用してエンゲージメントの高いゲームを作成する 게임 디자인은 사용자 참여를 유도하는 핵심 루프 생성을 포함하며, 30초 테스트와 디자인 사고를 활용 Diseño de juegos con agentes de IA para crear experiencias de juego atractivas y divertidas Concevoir des jeux avec des outils d''IA pour offrir des expériences de jeu engageantes et amusantes Game-Design mit KI-Agenten für unterhaltsame und ansprechende Spielerlebnisse O design de jogo envolve a criação de um loop de jogo atraente, com ação, feedback e recompensa. Aprenda a aplicar o pensamento sequencial para resolver problemas complexos. Дизайн игр включает в себя создание увлекательного основного цикла, состоящего из действия, обратной связи и награды. Изучите, как применять последовательное мышление для решения сложных проблем. تصميم الألعاب يتضمن إنشاء حلقة لعبة جذابة، مع عمل، ملاحظات و مكافأة. تعلم كيفية تطبيق التفكير التسلسلي لحل المشكلات المعقدة. how to use game-design game-design principles core loop design examples game-design vs level design game-design setup guide what is game-design game-design install for AI Agents game-design alternative for developers 游戏设计 核心循环设计 30秒测试 设计思维 序列思考 游戏开发 AI游戏设计 游戏设计工具 游戏设计软件 Applies Sequential Thinking for complex problem-solving in game design Utilizes the 30-Second Test for evaluating core loop effectiveness Supports design thinking for creating engaging games Breaks down decisions and design processes into structured reasoning steps Enables creation of fun and rewarding core loops using ACTION, FEEDBACK, and REWARD sequences Game-design is a set of principles and practices used to create engaging and interactive games, focusing on core loop design and player experience.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('arbgjr/smart_alarm/reference-indexer', 'community', 'arbgjr', 'smart_alarm', 'arbgjr/smart_alarm', 'reference-indexer', 0, 0, 36, '2026-03-08T01:57:15.299Z', '2026-03-08T02:01:25.722Z', 'd4d5d7f829d7f6f8873f64aacbc96b74e6b0cb34b4eaafbb73d5ae23589886d4', '{"id":"arbgjr/smart_alarm/reference-indexer","name":"reference-indexer","description":{"en":"The reference-indexer skill manages external reference documents, indexing them for use in RAG. It benefits developers by automating tasks such as validation, text extraction, and summarization.","zh":"Reference Indexer Skill用于管理外部参考文档，支持/ref-add和/ref-search命令","ja":"Reference Indexer Skillは外部参考文書を管理するために使用され、/ref-addと/ref-searchコマンドをサポートします","ko":"Reference Indexer Skill은 외부 참조 문서를 관리하는 데 사용되며 /ref-add 및 /ref-search 명령을 지원합니다","es":"Reference Indexer es una habilidad que gestiona documentos de referencia externa, indexándolos para su uso en RAG. Permite validar archivos, extraer texto y crear resúmenes automáticos","fr":"Reference Indexer est une compétence qui gère des documents de référence externes, les indexant pour une utilisation dans RAG. Elle permet de valider les fichiers, d''extraire le texte et de créer des résumés automatiques","de":"Reference Indexer ist eine Fähigkeit, die externe Referenzdokumente verwaltet, indem sie diese für die Verwendung in RAG indexiert. Sie ermöglicht die Validierung von Dateien, das Extrahieren von Text und die Erstellung von automatischen Zusammenfassungen","pt":"O Reference Indexer é uma habilidade que gerencia documentos de referência externa, indexando-os para uso no RAG, permitindo busca e recuperação de informações de forma eficiente","ru":"Reference Indexer - это навык, который управляет внешними справочными документами, индексируя их для использования в RAG, что позволяет выполнять поиск и извлечение информации эффективно","ar":"Reference Indexer هو مهارة تدير المستندات المرجعية الخارجية، وتفهرسها للاستخدام في RAG، مما يسمح بالبحث واسترجاع المعلومات بفعالية"},"seo":{"title":{"en":"reference-indexer: Automated Reference Management for AI ...","zh":"Reference Indexer Skill Setup Guide - AI工具","ja":"Reference Indexer Skill セットアップガイド - AIエージェント","ko":"Reference Indexer Skill 설정 가이드 - AI 에이전트","es":"Guía de configuración de Reference Indexer para desarroll...","fr":"Guide d''installation de Reference Indexer pour les dévelo...","de":"Einrichtungsleitfaden für Reference Indexer für Entwickler","pt":"Guia de Configuração do Reference Indexer para Desenvolve...","ru":"Настройка Reference Indexer: Руководство для Разработчиков","ar":"دليل إعداد Reference Indexer لل مطورين"},"description":{"en":"Discover how reference-indexer streamlines reference management with commands like /ref-add and /ref-search. Learn how to optimize your AI agent''s workflow t...","zh":"了解Reference Indexer Skill的技术细节，包括/ref-add和/ref-search命令，用于管理外部参考文档","ja":"Reference Indexer Skillの技術的詳細を学び、/ref-addと/ref-searchコマンドを使用して外部参考文書を管理する","ko":"Reference Indexer Skill의 기술적 세부 사항을 알아보고 /ref-add 및 /ref-search 명령을 사용하여 외부 참조 문서를 관리합니다","es":"Aprende a configurar Reference Indexer para indexar documentos de referencia externa y mejorar la búsqueda en tu aplicación","fr":"Découvrez comment configurer Reference Indexer pour indexer des documents de référence externes et améliorer la recherche dans votre application","de":"Erfahren Sie, wie Sie Reference Indexer einrichten, um externe Referenzdokumente zu indexieren und die Suche in Ihrer Anwendung zu verbessern","pt":"Aprenda a configurar e utilizar o Reference Indexer para gerenciar documentos de referência externa e melhorar a eficiência do seu workflow de desenvolvimento","ru":"Узнайте, как настроить и использовать Reference Indexer для управления внешними справочными документами и повышения эффективности вашего рабочего процесса ра...","ar":"تعرف على كيفية إعداد واستخدام Reference Indexer لإدارة المستندات المرجعية الخارجية وتحسين كفاءة سير عمل تطويرك"},"definition":{"en":"reference-indexer is a skill that indexes and manages external reference documents for AI agents, enabling efficient search and retrieval of relevant information.","zh":"Reference Indexer Skill是一种AI工具，用于管理和索引外部参考文档","ja":"Reference Indexer Skillは、外部参考文書を管理および索引するためのAIエージェントです","ko":"Reference Indexer Skill은 외부 참조 문서를 관리하고 색인하는 AI 에이전트입니다","es":"Reference Indexer es una habilidad que indexa documentos de referencia externa para su uso en aplicaciones de búsqueda","fr":"Reference Indexer est une compétence qui indexe des documents de référence externes pour une utilisation dans les applications de recherche","de":"Reference Indexer ist eine Fähigkeit, die externe Referenzdokumente indexiert, um diese in Suchanwendungen zu verwenden","pt":"O Reference Indexer é uma ferramenta que indexa e gerencia documentos de referência externa para uso em aplicações de desenvolvimento","ru":"Reference Indexer - это инструмент, который индексирует и управляет внешними справочными документами для использования в приложениях разработки","ar":"Reference Indexer هو أداة تفهرس و تدير المستندات المرجعية الخارجية للاستخدام في تطبيقات التطوير"},"features":{"en":["Validates files using /ref-add command","Extracts text from PDF and Word documents","Generates automatic summaries for indexed documents","Updates the RAG corpus with new reference documents","Supports search functionality using /ref-search command"],"zh":["支持/ref-add命令添加文档到索引","支持/ref-search命令搜索文档","自动提取PDF和Word文档中的文本","创建文档摘要","更新RAG索引"],"ja":["/ref-addコマンドを使用して文書を索引に追加する","/ref-searchコマンドを使用して文書を検索する","PDFおよびWord文書から自動的にテキストを抽出する","文書の要約を作成する","RAG索引を更新する"],"ko":["/ref-add 명령을 사용하여 문서를 색인에 추가","/ref-search 명령을 사용하여 문서를 검색","PDF 및 Word 문서에서 자동으로 텍스트를 추출","문서 요약을 생성","RAG 색인을 업데이트합니다"],"es":["Indexación de documentos de referencia externa","Validación de archivos","Extracción de texto de archivos PDF y Word","Creación de resúmenes automáticos","Integración con RAG para mejorar la búsqueda"],"fr":["Indexation de documents de référence externes","Validation de fichiers","Extraction de texte de fichiers PDF et Word","Création de résumés automatiques","Intégration avec RAG pour améliorer la recherche"],"de":["Indexierung externer Referenzdokumente","Validierung von Dateien","Extraktion von Text aus PDF- und Word-Dateien","Erstellung von automatischen Zusammenfassungen","Integration mit RAG zur Verbesserung der Suche"],"pt":["Adiciona documentos ao índice de referências usando o comando /ref-add","Valida arquivos e extrai texto de documentos PDF e Word","Cria resumos automáticos para documentos adicionados","Atualiza o índice de referências após adicionar novos documentos","Permite busca nos documentos de referência usando o comando /ref-search"],"ru":["Добавляет документы в индекс справок с помощью команды /ref-add","Проверяет файлы и извлекает текст из документов PDF и Word","Создает автоматические резюме для добавленных документов","Обновляет индекс справок после добавления новых документов","Позволяет выполнять поиск в справочных документах с помощью команды /ref-search"],"ar":["يضيف المستندات إلى فهرس المراجع باستخدام الأمر /ref-add","يتحقق من الملفات وينقح النص من المستندات PDF و Word","ينشئ ملخصات آلية للمستندات المضافة","يعمل على تحديث فهرس المراجع بعد إضافة مستندات جديدة","يسمح بالبحث في المستندات المرجعية باستخدام الأمر /ref-search"]},"keywords":{"en":["how to use reference-indexer","reference-indexer setup guide","reference-indexer alternative","reference-indexer vs other AI skills","installing reference-indexer","reference-indexer for AI agents","automated reference management","RAG reference indexing","PDF and Word document indexing"],"zh":["Reference Indexer Skill","AI工具","外部参考文档","文档管理","索引","搜索","PDF","Word","RAG"],"ja":["Reference Indexer Skill","AIエージェント","外部参考文書","文書管理","索引","検索","PDF","Word","RAG"],"ko":["Reference Indexer Skill","AI 에이전트","외부 참조 문서","문서 관리","색인","검색","PDF","Word","RAG"],"es":["Reference Indexer","indexación de documentos","búsqueda en aplicaciones","RAG","validación de archivos","extracción de texto","resúmenes automáticos","desarrollo de aplicaciones","herramientas de búsqueda"],"fr":["Reference Indexer","indexation de documents","recherche dans les applications","RAG","validation de fichiers","extraction de texte","résumés automatiques","développement d''applications","outils de recherche"],"de":["Reference Indexer","Indexierung von Dokumenten","Suche in Anwendungen","RAG","Validierung von Dateien","Extraktion von Text","automatische Zusammenfassungen","Anwendungsentwicklung","Suchtools"],"pt":["Reference Indexer","gerenciamento de documentos","índice de referências","comando /ref-add","comando /ref-search","desenvolvimento de aplicações","ferramentas de desenvolvimento","índice de documentos","busca de documentos"],"ru":["Reference Indexer","управление документами","индекс справок","команда /ref-add","команда /ref-search","разработка приложений","инструменты разработки","индекс документов","поиск документов"],"ar":["Reference Indexer","إدارة المستندات","فهرس المراجع","الأمر /ref-add","الأمر /ref-search","تطوير التطبيقات","أدوات التطوير","فهرس المستندات","بحث المستندات"]}},"owner":"arbgjr","repo":"smart_alarm","repoPath":"arbgjr/smart_alarm","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.299Z","topics":[],"category":"community","skillMd":{"name":"reference-indexer","description":"|","bodyPreview":"# Reference Indexer Skill\n\n## Proposito\n\nEsta skill gerencia documentos de referencia externa, indexando-os para uso no RAG.\n\n## Comandos\n\n### /ref-add {path}\n\nAdiciona documento ao indice de referencias:\n\n```bash\n/ref-add .agentic_sdlc/references/legal/lei-13775-2018.pdf\n```\n\nAcoes:\n1. Valida o arquivo\n2. Extrai texto (se PDF/Word)\n3. Cria resumo automatico\n4. Adiciona ao corpus RAG\n5. Atualiza indice\n\n### /ref-search {query}\n\nBusca nos documentos de referencia:\n\n```bash\n/ref-search \"prazo de a","body":"# Reference Indexer Skill\n\n## Proposito\n\nEsta skill gerencia documentos de referencia externa, indexando-os para uso no RAG.\n\n## Comandos\n\n### /ref-add {path}\n\nAdiciona documento ao indice de referencias:\n\n```bash\n/ref-add .agentic_sdlc/references/legal/lei-13775-2018.pdf\n```\n\nAcoes:\n1. Valida o arquivo\n2. Extrai texto (se PDF/Word)\n3. Cria resumo automatico\n4. Adiciona ao corpus RAG\n5. Atualiza indice\n\n### /ref-search {query}\n\nBusca nos documentos de referencia:\n\n```bash\n/ref-search \"prazo de aceite duplicata\"\n```\n\nRetorna:\n- Documentos relevantes\n- Trechos com contexto\n- Score de relevancia\n\n### /ref-list\n\nLista todos os documentos indexados:\n\n```bash\n/ref-list\n```\n\nMostra:\n- Documentos por categoria\n- Status de indexacao\n- Data de adicao\n\n### /ref-remove {path}\n\nRemove documento do indice:\n\n```bash\n/ref-remove .agentic_sdlc/references/legal/documento-antigo.pdf\n```\n\n## Formatos Suportados\n\n| Formato | Extensao | Metodo de Extracao |\n|---------|----------|-------------------|\n| PDF | .pdf | pdftotext / PyPDF2 |\n| Word | .docx | python-docx |\n| Markdown | .md | Direto |\n| Texto | .txt | Direto |\n| HTML | .html | BeautifulSoup |\n\n## Estrutura de Referencias\n\n```\n.agentic_sdlc/references/\n├── legal/              # Leis, regulamentos, normas\n├── technical/          # RFCs, especificacoes tecnicas\n├── business/           # Regras de negocio, manuais\n├── internal/           # Documentos internos\n└── _index.yml          # Indice de documentos\n```\n\n## Indice de Documentos\n\nArquivo `_index.yml`:\n\n```yaml\nindex:\n  version: 1\n  updated_at: \"2026-01-12T...\"\n\ndocuments:\n  - id: \"ref-001\"\n    path: \"legal/lei-13775-2018.pdf\"\n    title: \"Lei 13.775/2018 - Duplicatas Eletrônicas\"\n    category: legal\n    added_at: \"2026-01-12T...\"\n    indexed: true\n    summary: \"Lei que regulamenta as duplicatas escriturais...\"\n    keywords:\n      - duplicata\n      - escritural\n      - eletronica\n    page_count: 5\n\n  - id: \"ref-002\"\n    path: \"technical/icp-brasil.pdf\"\n    title: \"Padrões ICP-Brasil\"\n    category: technical\n    added_at: \"2026-01-12T...\"\n    indexed: true\n```\n\n## Extracao de Texto\n\n### PDF\n\n```bash\n# Usando pdftotext (poppler-utils)\npdftotext -layout input.pdf output.txt\n\n# Usando Python\npython3 << ''EOF''\nimport PyPDF2\n\nwith open(''input.pdf'', ''rb'') as f:\n    reader = PyPDF2.PdfReader(f)\n    text = ''''\n    for page in reader.pages:\n        text += page.extract_text() + ''\\n''\n    print(text)\nEOF\n```\n\n### Word (docx)\n\n```python\nfrom docx import Document\n\ndoc = Document(''input.docx'')\ntext = ''\\n''.join([p.text for p in doc.paragraphs])\nprint(text)\n```\n\n## Integracao com RAG\n\nDocumentos indexados sao adicionados ao corpus RAG:\n\n```yaml\ncorpus_entry:\n  id: \"ref-001\"\n  source: \"references/legal/lei-13775-2018.pdf\"\n  type: \"reference\"\n  category: \"legal\"\n  content: \"{texto extraido}\"\n  embeddings: [...]  # Gerado pelo RAG\n  metadata:\n    title: \"Lei 13.775/2018\"\n    page: 1\n    section: \"Art. 1\"\n```\n\n## Workflow de Indexacao\n\n```yaml\nindexing_workflow:\n  1_validate:\n    - Verificar formato suportado\n    - Verificar tamanho (max 50MB)\n    - Verificar permissoes\n\n  2_extract:\n    - Extrair texto do documento\n    - Limpar formatacao\n    - Dividir em chunks\n\n  3_analyze:\n    - Gerar resumo automatico\n    - Extrair keywords\n    - Classificar categoria\n\n  4_index:\n    - Adicionar ao corpus RAG\n    - Gerar embeddings\n    - Atualizar indice\n\n  5_verify:\n    - Testar busca\n    - Verificar qualidade\n```\n\n## Configuracao\n\nNo `settings.json`:\n\n```json\n{\n  \"memory\": {\n    \"rag_corpus\": \".agentic_sdlc/corpus\",\n    \"max_document_size_mb\": 50,\n    \"chunk_size\": 1000,\n    \"chunk_overlap\": 200\n  }\n}\n```\n\n## Boas Praticas\n\n1. **Nomeie arquivos descritivamente**: `lei-13775-2018-duplicatas.pdf`\n2. **Organize por categoria**: legal, technical, business\n3. **Mantenha versoes**: Nao sobrescreva, versione\n4. **Documente a fonte**: Adicione de onde veio\n5. **Resuma docs longos**: Crie resumos para PDFs grandes\n\n## Troubleshooting\n\n### PDF nao extrai texto\n\nAlguns PDFs sao imagens escaneadas. Use OCR:\n\n```bash\nocrmypdf input.pdf output.pdf\npdftotext output.pdf -\n```\n\n### Documento muito grande\n\nDivida em partes menores ou aumente `max_document_size_mb`.\n\n### Encoding incorreto\n\nForce UTF-8 na extracao:\n\n```bash\npdftotext -enc UTF-8 input.pdf output.txt\n```\n"},"lastSynced":"2026-03-08T02:01:25.722Z","agentAnalysis":{"suitability":{"en":"Ideal for AI Agents like Cursor, Windsurf, and Claude Code requiring automated document management and analysis capabilities.","zh":"适合于像Cursor、Windsurf和Claude Code这样的AI代理，需要自动化文档管理和分析能力。","ja":"Cursor、Windsurf、Claude CodeなどのAIエージェントに適しています。自動化されたドキュメント管理および分析機能を必要とします。","ko":"Cursor, Windsurf 및 Claude Code와 같은 AI 에이전트에 적합합니다. 자동화된 문서 관리 및 분석 기능이 필요한 경우에 적합합니다.","es":"Ideal para agentes de IA como Cursor, Windsurf y Claude Code que requieren capacidades de gestión y análisis de documentos automatizados.","fr":"Idéal pour les agents IA comme Cursor, Windsurf et Claude Code nécessitant des capacités de gestion et d''analyse de documents automatisées.","de":"Ideal für KI-Agents wie Cursor, Windsurf und Claude Code, die eine automatisierte Dokumentenverwaltung und Analysefunktionen benötigen.","pt":"Ideal para agentes de IA como Cursor, Windsurf e Claude Code que exigem capacidades de gerenciamento e análise de documentos automatizados.","ru":"Идеально подходит для агентов ИИ, таких как Cursor, Windsurf и Claude Code, требующих автоматизированных возможностей управления и анализа документов.","ar":"مثالي للوكلاء الذكاء الاصطناعي مثل Cursor و Windsurf و Claude Code الذين يتطلبون قدرات إدارة وتحليل وثائق آلية."},"recommendation":{"en":"Empowers agents to efficiently manage external reference documents by validating files, extracting text from PDF and Word documents, generating automatic summaries, and updating the RAG corpus index, leveraging file formats like PDF and protocols for seamless integration.","zh":"赋予代理高效管理外部参考文档的能力，通过验证文件、从PDF和Word文档中提取文本、生成自动摘要，并更新RAG语料库索引，利用PDF等文件格式和协议实现无缝集成。","ja":"エージェントに外部リファレンスドキュメントを効率的に管理する能力を与えます。ファイルの検証、PDFおよびWordドキュメントからのテキスト抽出、自動サマリーの生成、RAGコーパスインデックスの更新を行い、PDFなどのファイル形式やプロトコルを利用してシームレスな統合を実現します。","ko":"외부 참조 문서를 효율적으로 관리할 수 있는 에이전트의 능력을賦与합니다. 파일을検証하고, PDF 및 Word 문서에서 텍스트를 추출하고, 자동 요약을 생성하며, RAG 코퍼스 인덱스를 업데이트하여 PDF 등의 파일 형식 및 프로토콜을 활용하여无缝な 통합을實現합니다.","es":"Habilita a los agentes a gestionar eficientemente los documentos de referencia externos validando archivos, extrayendo texto de documentos PDF y Word, generando resúmenes automáticos y actualizando el índice del corpus RAG, aprovechando formatos de archivo como PDF y protocolos para una integración sin problemas, utilizando React, Python, CLI, API y otros frameworks.","fr":"Permet aux agents de gérer efficacement les documents de référence externes en validant les fichiers, en extrayant le texte des documents PDF et Word, en générant des résumés automatiques et en mettant à jour l''index du corpus RAG, en exploitant des formats de fichiers comme PDF et des protocoles pour une intégration sans problèmes, en utilisant React, Python, CLI, API et d''autres frameworks.","de":"Ermöglicht es Agents, externe Referenzdokumente effizient zu verwalten, indem Dateien validiert, Text aus PDF- und Word-Dokumenten extrahiert, automatische Zusammenfassungen generiert und den RAG-Corpus-Index aktualisiert werden, wobei Dateiformate wie PDF und Protokolle für eine nahtlose Integration genutzt werden, unter Verwendung von React, Python, CLI, API und anderen Frameworks.","pt":"Habilita os agentes a gerenciar documentos de referência externos de forma eficiente, validando arquivos, extraíndo texto de documentos PDF e Word, gerando resumos automáticos e atualizando o índice do corpus RAG, aproveitando formatos de arquivo como PDF e protocolos para integração sem interrupções.","ru":"Позволяет агентам эффективно управлять внешними справочными документами, проверяя файлы, извлекая текст из документов PDF и Word, генерируя автоматические резюме и обновляя индекс корпуса RAG, используя форматы файлов, такие как PDF, и протоколы для бесперебойной интеграции.","ar":"تمكّن الوكلاء من إدارة المستندات المرجعية الخارجية بشكل فعال من خلال التحقق من الملفات و استخراج النص من مستندات PDF و Word و توليد ملخصات آلية و تحديث فهرس مجموعة RAG، مستفيدا من صيغ الملفات مثل PDF و البروتوكولات من أجل التكامل السلس."},"useCases":{"en":["Automating document validation and indexing","Generating summaries for large reference documents","Searching reference documents with specific queries"],"zh":["自動化文档验证和索引","为大型参考文档生成摘要","使用特定查询搜索参考文档"],"ja":["ドキュメントの検証とインデックス作成の自動化","大規模なリファレンスドキュメントのサマリー生成","特定のクエリを使用したリファレンスドキュメントの検索"],"ko":["문서의 검증 및 색인 생성 자동화","대규모 참조 문서의 요약 생성","특정 쿼리를 사용한 참조 문서 검색"],"es":["Automatizar la validación y indexación de documentos","Generar resúmenes para grandes documentos de referencia","Buscar documentos de referencia con consultas específicas"],"fr":["Automatiser la validation et l''indexation de documents","Générer des résumés pour les grands documents de référence","Rechercher des documents de référence avec des requêtes spécifiques"],"de":["Automatisieren der Dokumentenvalidierung und -indexierung","Generieren von Zusammenfassungen für große Referenzdokumente","Suchen von Referenzdokumenten mit spezifischen Abfragen"],"pt":["Automatizar a validação e indexação de documentos","Gerar resumos para documentos de referência grandes","Pesquisar documentos de referência com consultas específicas"],"ru":["Автоматизировать проверку и индексацию документов","Генерировать резюме для крупных справочных документов","Искать справочные документы с помощью конкретных запросов"],"ar":["تحسين آلي لتحقق من الصحة و الفهرسة للمستندات","توليد ملخصات للمستندات المرجعية الكبيرة","البحث في المستندات المرجعية باستخدام استفسارات محددة"]},"limitations":{"en":["Requires filesystem access to read and index documents","Limited to PDF and Word document formats for text extraction"],"zh":["需要文件系统访问权限来读取和索引文档","仅限PDF和Word文档格式的文本提取"],"ja":["ドキュメントを読み込んでインデックスを作成するためにファイルシステムへのアクセスが必要","テキスト抽出はPDFおよびWordドキュメント形式に限られる"],"ko":["문서를 읽고 색인화하기 위해 파일 시스템에 접근할 수 있는 권한이 필요함","텍스트 추출은 PDF 및 Word 문서 형식에만 제한됨"],"es":["Requiere acceso al sistema de archivos para leer e indexar documentos","Limitado a formatos de documentos PDF y Word para la extracción de texto"],"fr":["Nécessite un accès au système de fichiers pour lire et indexer des documents","Limité aux formats de documents PDF et Word pour l''extraction de texte"],"de":["Benötigt Dateisystemzugriff, um Dokumente zu lesen und zu indexieren","Begrenzt auf PDF- und Word-Dateiformate für die Textextraktion"],"pt":["Exige acesso ao sistema de arquivos para ler e indexar documentos","Limitado aos formatos de documentos PDF e Word para extração de texto"],"ru":["Требует доступа к файловой системе для чтения и индексации документов","Ограничен форматами документов PDF и Word для извлечения текста"],"ar":["يتطلب الوصول إلى نظام الملفات لقراءة و فهرسة المستندات","محدود بصيغ المستندات PDF و Word لاستخراج النص"]},"version":4},"contentHash":"d4d5d7f829d7f6f8873f64aacbc96b74e6b0cb34b4eaafbb73d5ae23589886d4","qualityScore":36}');
