INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('arbgjr/smart_alarm/reference-indexer', 'reference-indexer', 'arbgjr', 'smart_alarm', 'community', 'reference-indexer arbgjr smart_alarm community The reference-indexer skill manages external reference documents, indexing them for use in RAG. It benefits developers by automating tasks such as validation, text extraction, and summarization. Reference Indexer Skill用于管理外部参考文档，支持/ref-add和/ref-search命令 Reference Indexer Skillは外部参考文書を管理するために使用され、/ref-addと/ref-searchコマンドをサポートします Reference Indexer Skill은 외부 참조 문서를 관리하는 데 사용되며 /ref-add 및 /ref-search 명령을 지원합니다 Reference Indexer es una habilidad que gestiona documentos de referencia externa, indexándolos para su uso en RAG. Permite validar archivos, extraer texto y crear resúmenes automáticos Reference Indexer est une compétence qui gère des documents de référence externes, les indexant pour une utilisation dans RAG. Elle permet de valider les fichiers, d''extraire le texte et de créer des résumés automatiques Reference Indexer ist eine Fähigkeit, die externe Referenzdokumente verwaltet, indem sie diese für die Verwendung in RAG indexiert. Sie ermöglicht die Validierung von Dateien, das Extrahieren von Text und die Erstellung von automatischen Zusammenfassungen O Reference Indexer é uma habilidade que gerencia documentos de referência externa, indexando-os para uso no RAG, permitindo busca e recuperação de informações de forma eficiente Reference Indexer - это навык, который управляет внешними справочными документами, индексируя их для использования в RAG, что позволяет выполнять поиск и извлечение информации эффективно Reference Indexer هو مهارة تدير المستندات المرجعية الخارجية، وتفهرسها للاستخدام في RAG، مما يسمح بالبحث واسترجاع المعلومات بفعالية how to use reference-indexer reference-indexer setup guide reference-indexer alternative reference-indexer vs other AI skills installing reference-indexer reference-indexer for AI agents automated reference management RAG reference indexing PDF and Word document indexing Reference Indexer Skill AI工具 外部参考文档 文档管理 索引 搜索 PDF Word RAG Validates files using /ref-add command Extracts text from PDF and Word documents Generates automatic summaries for indexed documents Updates the RAG corpus with new reference documents Supports search functionality using /ref-search command reference-indexer is a skill that indexes and manages external reference documents for AI agents, enabling efficient search and retrieval of relevant information.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('grenos/gh-viewer/karpathy', 'community', 'grenos', 'gh-viewer', 'grenos/gh-viewer', 'karpathy', 0, 0, 36, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:27.740Z', '4057f78e8ff79ea20b72090f1719d5279b709cf17c9684cf8e1e8954552f6a9e', '{"id":"grenos/gh-viewer/karpathy","name":"karpathy","description":{"en":"The karpathy skill provides principles for writing clean, minimal, and purposeful code, benefiting AI agent developers. It emphasizes thinking before coding and simplicity first.","zh":"Karpathy 编码原则为开发者提供了写出干净、最小化和目的明确的代码的指导。通过遵循这套原则，开发者可以提高代码质量和可维护性","ja":"Karpathy コーディング原則は、クリーンでミニマルなコードを書くための指針を提供します。開発者はこの原則に従って、コードの品質とメンテナンス性を向上させることができます","ko":"Karpathy 코딩 원칙은 개발자들에게 깔끔하고 최소한의 코드를 작성하는 지침을 제공합니다. 이 원칙을 따르면 코드 품질과 유지보수성을 향상할 수 있습니다","es":"Karpathy es un conjunto de principios de codificación que promueven la escritura de código limpio, minimalista y con propósito. Aprende a aplicar estos principios en tu flujo de trabajo.","fr":"Karpathy est un ensemble de principes de codage qui favorisent l''écriture de code propre, minimaliste et à objectif clair. Apprenez à appliquer ces principes dans votre flux de travail.","de":"Karpathy ist eine Sammlung von Coding-Prinzipien, die das Schreiben von sauberen, minimalistischen und zweckorientierten Code fördern. Erfahren Sie, wie Sie diese Prinzipien in Ihrem Workflow anwenden können.","pt":"O Karpathy é um conjunto de princípios para escrever código limpo e minimalista, com foco em simplicidade e clareza.","ru":"Карпато - это набор принципов для написания чистого и минималистичного кода, с упором на простоту и ясность для ИИ Агентов.","ar":"كارباثي هو مجموعة من المبادئ لكتابة رمز نظيف ومتوافق، مع التركيز على البساطة والوضوح للأدوات الذكية."},"seo":{"title":{"en":"karpathy: Clean Code Principles for AI Agents | AI Agent ...","zh":"Karpathy 编码原则：代码简洁性和最小化指南","ja":"Karpathy コーディング原則: クリーンでミニマルなコードを書くためのガイド","ko":"Karpathy 코딩 원칙: 깔끔하고 최소한의 코드 작성 가이드","es":"Guía de implementación de Karpathy: Principios de codific...","fr":"Guide de démarrage Karpathy: Principes de codage propres ...","de":"Karpathy-Implementierungsleitfaden: Prinzipien für sauber...","pt":"Guia de Configuração do Karpathy: Princípios de Codificaç...","ru":"Настройка Карпатого: Лучшие Практики для Чистого Кодирова...","ar":"إعداد كارباثي: مبادئ الترميز النقي للأدوات الذكية"},"description":{"en":"Discover how karpathy coding principles can transform your AI agent development. Learn to write clean, minimal, and purposeful code with our expert guide.","zh":"了解 Karpathy 编码原则，实现代码简洁、最小化和目的明确。发现如何写出干净、高效的代码","ja":"Karpathy コーディング原則を学び、クリーンでミニマルなコードを書く方法を発見しましょう","ko":"Karpathy 코딩 원칙을 알아보고, 깔끔하고 최소한의 코드를 작성하는 방법을 발견하세요","es":"Aprende a aplicar los principios de codificación de Karpathy para escribir código limpio y eficiente. Descubre cómo pensar antes de codificar y priorizar la ...","fr":"Découvrez comment appliquer les principes de codage de Karpathy pour écrire du code propre et efficace. Apprenez à réfléchir avant de coder et à privilégier ...","de":"Erfahren Sie, wie Sie die Karpathy-Coding-Prinzipien anwenden, um sauberen und effizienten Code zu schreiben. Lernen Sie, bevor Sie codieren, nachzudenken un...","pt":"Aprenda a aplicar os princípios de codificação do Karpathy para escrever código limpo e minimalista, com dicas práticas para desenvolvedores.","ru":"Изучите принципы кодирования Карпатого для написания чистого и минималистичного кода, с практическими советами для разработчиков ИИ Агентов.","ar":"تعلم كيفية تطبيق مبادئ الترميز لكارباثي لكتابة رمز نظيف ومتوافق مع الأدوات الذكية."},"definition":{"en":"karpathy is a set of coding principles for writing clean, minimal, and purposeful code, focusing on clarity and simplicity in AI agent development.","zh":"Karpathy 编码原则是一套指导开发者写出干净、最小化和目的明确的代码的原则","ja":"Karpathy コーディング原則は、クリーンでミニマルなコードを書くための原則です","ko":"Karpathy 코딩 원칙은 깔끔하고 최소한의 코드를 작성하는 원칙입니다","es":"Karpathy es un conjunto de principios de codificación que promueven la simplicidad y la claridad en el código.","fr":"Karpathy est un ensemble de principes de codage qui favorisent la simplicité et la clarté dans le code.","de":"Karpathy ist eine Sammlung von Coding-Prinzipien, die Einfachheit und Klarheit im Code fördern.","pt":"Karpathy é um conjunto de princípios de codificação que visam escrever código limpo, minimalista e de propósito.","ru":"Карпато - это набор принципов кодирования, направленный на написание чистого, минималистичного и целенаправленного кода для ИИ Агентов.","ar":"كارباثي هو مجموعة من المبادئ لكتابة رمز نظيف ومتوافق وغرضي للأدوات الذكية."},"features":{"en":["Surfaces tradeoffs and assumptions explicitly","Presents multiple interpretations when possible","Prioritizes simpler approaches to coding","Encourages stopping and asking when faced with confusion","Promotes pushing back when warranted for code clarity"],"zh":["思考在编码前：明确假设和潜在的解释","简洁优先：追求最小化和目的明确的代码","明确表达：避免隐藏混淆和潜在的问题","代码可维护性：通过遵循原则提高代码质量"],"ja":["コーディング前に考える：仮定と潜在的な解釈を明確にする","シンプルさを優先する：最小限のコードと目的明確性を追求する","明確な表現：混乱や潜在的な問題を隠さない","コードのメンテナンス性：原則に従ってコードの品質を向上させる"],"ko":["코딩 전 생각하기：가정과 잠재적인 해석을 명확히 하기","단순성 우선：최소한의 코드와 목적 명확성을 추구하기","명확한 표현：혼란이나 잠재적인 문제를 숨기지 않기","코드 유지보수성：원칙을 따르면 코드 품질을 향상시킬 수 있습니다"],"es":["Principios de codificación minimalista","Priorización de la simplicidad en el código","Análisis de tradeoffs y suposiciones explícitas","Enfoque en la claridad y la legibilidad del código","Aplicación de principios de codificación para mejorar la eficiencia"],"fr":["Principes de codage minimalistes","Priorisation de la simplicité dans le code","Analyse des compromis et hypothèses explicites","Focalisation sur la clarté et la lisibilité du code","Application de principes de codage pour améliorer l''efficacité"],"de":["Prinzipien für minimalistischen Code","Priorisierung von Einfachheit im Code","Analyse von Tradeoffs und expliziten Annahmen","Fokus auf Klarheit und Lesbarkeit des Codes","Anwendung von Coding-Prinzipien zur Verbesserung der Effizienz"],"pt":["Princípios de codificação limpa e minimalista","Foco em simplicidade e clareza","Análise de tradeoffs e apresentação de interpretações múltiplas","Abordagem proativa para resolver confusões e incertezas","Implementação de soluções simples e eficazes"],"ru":["Принципы чистого и минималистичного кодирования","Фокус на простоте и ясности для ИИ Агентов","Анализ tradeoffs и представление множественных интерпретаций","Прямой подход к решению путаницы и неопределенностей","Реализация простых и эффективных решений"],"ar":["مبادئ الترميز النقي والمتوافق","التركيز على البساطة والوضوح للأدوات الذكية","تحليل التبادل ومعالجة التأويلات المتعددة","منهج مباشر لحل اللبس والغموض","تنفيذ حلول بسيطة وفعالة"]},"keywords":{"en":["how to use karpathy","karpathy coding principles","karpathy alternative","karpathy vs clean code","karpathy setup guide","what is karpathy","karpathy install","karpathy for AI agents"],"zh":["Karpathy 编码原则","代码简洁性","最小化代码","目的明确的代码","代码可维护性","开发者最佳实践","代码质量提高","编程指南"],"ja":["Karpathy コーディング原則","コードのシンプルさ","最小限のコード","目的明確なコード","コードのメンテナンス性","開発者のベストプラクティス","コードの品質向上","プログラミングガイド"],"ko":["Karpathy 코딩 원칙","코드 단순성","최소한의 코드","목적 명확한 코드","코드 유지보수성","개발자 최고의 실践","코드 품질 향상","프로그래밍 가이드"],"es":["principios de codificación","código limpio","código minimalista","simplicidad en el código","análisis de tradeoffs","suposiciones explícitas","claridad en el código","legibilidad del código","eficiencia en el código"],"fr":["principes de codage","code propre","code minimaliste","simplicité dans le code","analyse des compromis","hypothèses explicites","clarté dans le code","lisibilité du code","efficacité dans le code"],"de":["Coding-Prinzipien","sauberer Code","minimalistischer Code","Einfachheit im Code","Tradeoff-Analyse","explizite Annahmen","Klarheit im Code","Lesbarkeit des Codes","Effizienz im Code"],"pt":["Karpathy","princípios de codificação","código limpo","minimalista","simplicidade","clareza","desenvolvimento de software","ferramentas de desenvolvimento"],"ru":["Карпато","принципы кодирования","чистый код","минималистичный","простота","ясность","разработка программного обеспечения","ИИ Агенты","инструменты разработки"],"ar":["كارباثي","مبادئ الترميز","رمز نظيف","متوافق","بساطة","وضوح","تطوير البرمجيات","أدوات التطوير","أدوات ذكية"]}},"owner":"grenos","repo":"gh-viewer","repoPath":"grenos/gh-viewer","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"karpathy","description":"Coding principles for simplicity, clarity, and surgical precision. Use when you want Claude to think before coding, keep solutions minimal, make surgical changes, and define verifiable success criteria. Triggers on: karpathy mode, think before coding, simplicity first, surgical changes.","bodyPreview":"# Karpathy Coding Principles\n\nPrinciples for writing clean, minimal, and purposeful code.\n\n---\n\n## 1. Think Before Coding\n\n**Don''t assume. Don''t hide confusion. Surface tradeoffs.**\n\nBefore implementing:\n\n- State your assumptions explicitly. If uncertain, ask.\n- If multiple interpretations exist, present them - don''t pick silently.\n- If a simpler approach exists, say so. Push back when warranted.\n- If something is unclear, stop. Name what''s confusing. Ask.\n\n---\n\n## 2. Simplicity First\n\n**Minimum","body":"# Karpathy Coding Principles\n\nPrinciples for writing clean, minimal, and purposeful code.\n\n---\n\n## 1. Think Before Coding\n\n**Don''t assume. Don''t hide confusion. Surface tradeoffs.**\n\nBefore implementing:\n\n- State your assumptions explicitly. If uncertain, ask.\n- If multiple interpretations exist, present them - don''t pick silently.\n- If a simpler approach exists, say so. Push back when warranted.\n- If something is unclear, stop. Name what''s confusing. Ask.\n\n---\n\n## 2. Simplicity First\n\n**Minimum code that solves the problem. Nothing speculative.**\n\n- No features beyond what was asked.\n- No abstractions for single-use code.\n- No \"flexibility\" or \"configurability\" that wasn''t requested.\n- No error handling for impossible scenarios.\n- If you write 200 lines and it could be 50, rewrite it.\n\nAsk yourself: \"Would a senior engineer say this is overcomplicated?\" If yes, simplify.\n\n---\n\n## 3. Surgical Changes\n\n**Touch only what you must. Clean up only your own mess.**\n\nWhen editing existing code:\n\n- Don''t \"improve\" adjacent code, comments, or formatting.\n- Don''t refactor things that aren''t broken.\n- Match existing style, even if you''d do it differently.\n- If you notice unrelated dead code, mention it - don''t delete it.\n\nWhen your changes create orphans:\n\n- Remove imports/variables/functions that YOUR changes made unused.\n- Don''t remove pre-existing dead code unless asked.\n\nThe test: Every changed line should trace directly to the user''s request.\n\n---\n\n## 4. Goal-Driven Execution\n\n**Define success criteria. Loop until verified.**\n\nTransform tasks into verifiable goals:\n\n- \"Add validation\" -> \"Write tests for invalid inputs, then make them pass\"\n- \"Fix the bug\" -> \"Write a test that reproduces it, then make it pass\"\n- \"Refactor X\" -> \"Ensure tests pass before and after\"\n\nFor multi-step tasks, state a brief plan:\n\n```\n1. [Step] -> verify: [check]\n2. [Step] -> verify: [check]\n3. [Step] -> verify: [check]\n```\n\nStrong success criteria let you loop independently. Weak criteria (\"make it work\") require constant clarification.\n"},"lastSynced":"2026-03-08T02:01:27.740Z","agentAnalysis":{"suitability":{"en":"Perfect for Code-Generation Agents needing clean, minimal, and purposeful coding principles.","zh":"非常适合需要清晰、最小化和有目的的编码原则的代码生成代理。","ja":"クリーンでミニマルで目的のあるコーディングの原則を必要とするコード生成エージェントに最適です。","ko":"클린하고 최소화되고 목적이 있는 코딩 원칙이 필요한 코드 생성 에이전트에 적합합니다.","es":"Perfecto para agentes de generación de código que necesitan principios de codificación limpios, mínimos y con propósito.","fr":"Parfait pour les agents de génération de code nécessitant des principes de codage propres, minimaux et à but.","de":"Perfekt für Code-Generation-Agents, die saubere, minimale und zweckmäßige Codierungsprinzipien benötigen.","pt":"Perfeito para Agentes de Geração de Código que necessitam de princípios de codificação limpos, mínimos e propositais.","ru":"Идеально подходит для агентов генерации кода, требующих чистых, минимальных и целенаправленных принципов кодирования.","ar":"مثالي لوكلاء генера代码 الذين يحتاجون إلى مبادئ برمجة نظيفة وحد أدنى وغرضية."},"recommendation":{"en":"Empowers agents to write efficient code by thinking before coding, surfacing tradeoffs, and prioritizing simplicity first, utilizing principles like explicit assumption stating and tradeoff analysis.","zh":"通过思考然后编码、揭示权衡和优先考虑简单性等原则，赋予代理编写高效代码的能力，首先利用显式假设陈述和权衡分析等。","ja":"コーディングの前に考える、トレードオフを浮き彫りにする、シンプルさを優先するなど、明示的な仮定の記述やトレードオフ分析などの原則を利用して、エージェントに効率的なコードを書く力を与えます。","ko":"코딩하기 전에 생각하고, 트레이드오프를 표면화하고, 단순성을 우선시하는 등, 명시적인 가설 진술과 트레이드오프 분석 등의 원칙을 사용하여 에이전트가 효율적인 코드를 작성할 수 있는 능력을 부여합니다.","es":"Habilita a los agentes a escribir un código eficiente al pensar antes de codificar, exponer compensaciones y priorizar la simplicidad primero, utilizando principios como la declaración explícita de suposiciones y el análisis de compensaciones.","fr":"Permet aux agents d''écrire un code efficace en réfléchissant avant de coder, en mettant en évidence les compromis et en donnant la priorité à la simplicité d''abord, en utilisant des principes tels que l''énoncé explicite des hypothèses et l''analyse des compromis.","de":"Ermächtigt die Agents, effizienten Code zu schreiben, indem sie vor dem Codieren nachdenken, Kompromisse aufdecken und die Einfachheit zuerst priorisieren, indem sie Prinzipien wie die explizite Angabe von Annahmen und die Kompromissanalyse verwenden.","pt":"Habilita os agentes a escrever códigos eficientes, pensando antes de codificar, identificando compromissos e priorizando a simplicidade primeiro, utilizando princípios como declaração de suposição explícita e análise de compromissos.","ru":"Наделяет агентов возможностью писать эффективный код, думая перед кодированием, выявляя компромиссы и отдая приоритет простоте в первую очередь, используя принципы, такие как явное заявление предположений и анализ компромиссов.","ar":"يمنح الوكلاء khảية كتابة كود فعال، تفكير قبل البرمجة، وتصدر التضحيات وتقديم الأولوية للبساطة أولاً، باستخدام مبادئ مثل بيان افتراض صريح وتحليل التضحيات."},"useCases":{"en":["Implementing think-before-code protocols","Generating minimal and purposeful code snippets","Debugging complex codebases through simplicity-first approaches"],"zh":["实施思考然后编码的协议","生成最小化和有目的的代码片段","通过简单性优先的方法调试复杂的代码库"],"ja":["コードを書く前に考えるプロトコルを実装する","最小限で目的のあるコードスニペットを生成する","シンプルさを優先するアプローチで複雑なコードベースをデバッグする"],"ko":["코딩하기 전에 생각하는 프로토콜을 구현하는 것","최소화되고 목적이 있는 코드 스니펫을 생성하는 것","단순성을 우선하는 접근법으로 복잡한 코드베이스를 디버깅하는 것"],"es":["Implementar protocolos de pensar-antes-de-codificar","Generar fragmentos de código mínimos y con propósito","Depurar código complejo a través de enfoques de simplicidad-primero"],"fr":["Mettre en œuvre des protocoles de réflexion avant de coder","Générer des extraits de code minimaux et à but","Déboguer des bases de code complexes grâce à des approches de simplicité d''abord"],"de":["Implementierung von Denk-Bevor-Code-Protokollen","Generierung minimaler und zweckmäßiger Code-Snippets","Fehlerbehebung komplexer Codebasen durch Einfachheit-zuerst-Ansätze"],"pt":["Implementar protocolos de pensar-antes-de-codificar","Gerar trechos de código mínimos e propositais","Depurar bases de código complexas por meio de abordagens de simplicidade-primeiro"],"ru":["Реализовать протоколы думай-перед-кодированием","Генерировать минимальные и целенаправленные фрагменты кода","Отлаживать сложные базы кода посредством подходов простоты-сначала"],"ar":["تنفيذ بروتوكولات تفكير قبل البرمجة","生成 شذرات من الكود الأدنى والأمثل","تصحيح أخطاء في قواعد بيانات الكود المعقدة من خلال نهج البساطة أولاً"]},"limitations":{"en":["Requires developer buy-in for coding principles","May not be suitable for rapid prototyping or proof-of-concept projects"],"zh":["需要开发人员对编码原则的认同","可能不适合快速原型设计或概念验证项目"],"ja":["コーディングの原則に対する開発者の同意が必要","迅速なプロトタイピングや概念検証プロジェクトには適さない可能性がある"],"ko":["코딩 원칙에 대한 개발자의 동의가 필요함","신속한 프로토 타이핑이나 개념 검증 프로젝트에는 적합하지 않을 수 있음"],"es":["Requiere la adhesión del desarrollador a los principios de codificación","Puede no ser adecuado para proyectos de prototipado rápido o de prueba de concepto"],"fr":["Nécessite l''adhésion du développeur aux principes de codage","Peut ne pas être adapté aux projets de prototypage rapide ou de preuve de concept"],"de":["Benötigt die Zustimmung des Entwicklers zu den Codierungsprinzipien","Kann für Projekte mit schnellem Prototyping oder Proof-of-Concept nicht geeignet sein"],"pt":["Requer aceitação do desenvolvedor para os princípios de codificação","Pode não ser adequado para projetos de prototipagem rápida ou de conceito"],"ru":["Требует согласия разработчика с принципами кодирования","Может быть не подходит для быстрой прототипизации или проектов-демонстраторов"],"ar":["يتطلب موافقة المطور على مبادئ البرمجة","قد لا يكون مناسباً لمشاريع النمذجة السريعة أو البراهين القطعية"]},"version":4},"contentHash":"4057f78e8ff79ea20b72090f1719d5279b709cf17c9684cf8e1e8954552f6a9e","qualityScore":36}');
