INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ahtavarasmus/lightfriend-cloud/lightfriend-add-frontend-page', 'lightfriend-add-frontend-page', 'ahtavarasmus', 'lightfriend-cloud', 'community', 'lightfriend-add-frontend-page ahtavarasmus lightfriend-cloud community The lightfriend-add-frontend-page skill helps developers add new pages to the Lightfriend cloud version''s Yew WebAssembly frontend. It benefits developers working with Rust and WebAssembly. 本文指导您如何向 Lightfriend 云版本添加新前端页面，包括创建页面组件、路由枚举和路由处理器 このガイドでは、Lightfriend クラウドバージョンに新しいフロントエンドページを追加する方法を説明します。ページコンポーネント、ルート列挙、ルートハンドラーの作成が含まれます 이 가이드는 Lightfriend 클라우드 버전에 새 프론트엔드 페이지를 추가하는 방법을 설명합니다. 페이지 컴포�트, 라우트 열거 및 라우트 핸들러의 생성이 포함됩니다 Lightfriend es una versión en la nube que permite agregar páginas de frontend con Yew WebAssembly. Este skill te guía a través del proceso de creación de un componente de página y ruta Lightfriend est une version cloud qui permet d''ajouter des pages de frontend avec Yew WebAssembly. Ce skill vous guide à travers le processus de création d''un composant de page et d''une route Lightfriend ist eine Cloud-Version, die das Hinzufügen von Frontend-Seiten mit Yew WebAssembly ermöglicht. Dieses Skill führt Sie durch den Prozess der Erstellung eines Seitenkomponenten und einer Route O lightfriend-add-frontend-page é um guia para adicionar páginas ao frontend do Lightfriend Yew WebAssembly. Ele aborda a criação de componentes de página, enumerações de rota e tratamento de rotas. ИИ Агент lightfriend-add-frontend-page предназначен для добавления новых страниц в frontend Lightfriend Yew WebAssembly. Он охватывает создание компонентов страниц, перечисление маршрутов и обработку маршрутов. أداة الذكاء الاصطناعي lightfriend-add-frontend-page مصممة لإضافة صفحات جديدة إلى واجهة المستخدم الخلفية لبرنامج Lightfriend Yew WebAssembly. она تغطي إنشاء مكونات الصفحة وتركيبات المسار ومعالجة المسار how to use lightfriend-add-frontend-page lightfriend-add-frontend-page setup guide lightfriend-add-frontend-page alternative lightfriend-add-frontend-page vs other frontend frameworks adding new pages to Yew WebAssembly frontend lightfriend-add-frontend-page install lightfriend-add-frontend-page tutorial what is lightfriend-add-frontend-page lightfriend-add-frontend-page documentation Lightfriend 添加前端页面 AI 工具 前端开发 Yew WebAssembly Rust 语言 云版本 页面组件 路由枚举 路由处理器 Creates page components in frontend/src/pages/ Adds route enum variants in main.rs Implements route handlers in switch functions Supports navigation links for new pages Utilizes Yew and gloo_net::http::Request for frontend development Follows a step-by-step process for adding new pages lightfriend-add-frontend-page is a skill that guides developers through adding new pages to the Lightfriend Yew WebAssembly frontend, including page components, route enums, and navigation links.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('ConnerBabb/Instapermit/secure-pr', 'community', 'ConnerBabb', 'Instapermit', 'ConnerBabb/Instapermit', 'secure-pr', 0, 0, 36, '2026-03-08T01:57:15.300Z', '2026-03-08T02:01:28.525Z', 'a15a81ed53643a87372ebd675dd2cae661465c3ed35729ccba2eb0e13ebdf8f3', '{"id":"ConnerBabb/Instapermit/secure-pr","name":"secure-pr","description":{"en":"The secure-pr skill streamlines GitHub security for developers by automating pre-flight checks and security reviews. It benefits developers working with Python and GitHub repositories.","zh":"Secure PR 工作流程是一个确保代码安全和质量的重要步骤。通过预检、安全审查和自动化测试，开发人员可以确保代码的安全性和可靠性","ja":"Secure PR ワークフローは、コードのセキュリティと品質を確保するための重要なステップです。Pre-flight チェック、セキュリティレビュー、自動テストを通じて、開発者はコードのセキュリティと信頼性を確保できます","ko":"Secure PR 워크플로우는 코드의 보안과 품질을 확보하는 중요한 단계입니다. 사전검사, 보안검토, 자동화 테스트를 통해 개발자는 코드의 보안성과 신뢰성을 확보할 수 있습니다","es":"Secure-pr es una herramienta que ayuda a proteger tus flujos de trabajo mediante la revisión de seguridad y el análisis de código","fr":"Secure-pr est un outil qui aide à sécuriser vos workflows en effectuant une révision de sécurité et une analyse de code","de":"Secure-pr ist ein Tool, das dabei hilft, Ihre Workflows zu schützen, indem es Sicherheitsprüfungen und Code-Analysen durchführt","pt":"O Secure-PR é uma ferramenta de IA que ajuda a garantir a segurança das pull requests. Ele executa verificações de pré-voo e revisões de segurança.","ru":"Secure-PR - это инструмент ИИ, который помогает обеспечить безопасность пулл-реквестов. Он выполняет предварительные проверки и проверки безопасности.","ar":"Secure-PR هو أداة ذكاء اصطناعي تساعد على ضمان أمان طلبات السحب. وهو ي実ن فحوصات ما قبل الطيران ومراجعات الأمان."},"seo":{"title":{"en":"secure-pr: Secure Pull Request Setup Guide | AI Agent Skill","zh":"Secure PR 工作流程设置指南","ja":"Secure PR ワークフロー設定ガイド - AIエージェント","ko":"Secure PR 워크플로우 설정 가이드 - 인공지능 툴","es":"Guía de configuración de secure-pr para flujos de trabajo...","fr":"Guide de mise en place de secure-pr pour des workflows sé...","de":"Einrichtungsleitfaden für secure-pr zur Sicherung von Wor...","pt":"Guia de Configuração do Secure-PR: Melhores Práticas para...","ru":"Настройка Secure-PR: Руководство по Безопасности для ИИ А...","ar":"دليل إعداد Secure-PR: أفضل الممارسات لأدوات الذكاء الاصطناعي"},"description":{"en":"Boost your GitHub security with secure-pr! Learn how to perform pre-flight checks and security reviews with ruff and pytest. Get started now!","zh":"学习如何设置 Secure PR 工作流程，确保代码安全和质量。了解预检、安全审查和自动化测试的重要性","ja":"Secure PR ワークフローを設定し、コードのセキュリティと品質を確保する方法を学びます。Pre-flight チェック、セキュリティレビュー、自動テストの重要性について","ko":"Secure PR 워크플로우를 설정하고 코드의 보안과 품질을 확보하는 방법을 배우세요. 사전검사, 보안검토, 자동화 테스트의 중요성에 대해","es":"Aprende a proteger tus flujos de trabajo con secure-pr, una herramienta de revisión de seguridad y código","fr":"Découvrez comment sécuriser vos workflows avec secure-pr, un outil de révision de sécurité et de code","de":"Erfahren Sie, wie Sie Ihre Workflows mit secure-pr schützen, einem Tool für die Sicherheits- und Code-Überprüfung","pt":"Aprenda a configurar o Secure-PR para garantir a segurança das suas pull requests com ferramentas de IA. Siga os passos para uma revisão de segurança completa.","ru":"Узнайте, как настроить Secure-PR для обеспечения безопасности ваших пулл-реквестов с помощью ИИ Агентов. Следуйте шагам для полной проверки безопасности.","ar":"تعلم كيفية إعداد Secure-PR لضمان أمان طلبات السحب مع أدوات الذكاء الاصطناعي. اتبع الخطوات لمراجعة أمان شاملة."},"definition":{"en":"secure-pr is a GitHub security workflow that automates pre-flight checks and security reviews using ruff and pytest to identify vulnerabilities and secrets.","zh":"Secure PR 是一种确保代码安全和质量的工作流程，通过预检、安全审查和自动化测试来检测和修复代码中的安全漏洞","ja":"Secure PR は、コードのセキュリティと品質を確保するためのワークフローです。Pre-flight チェック、セキュリティレビュー、自動テストを通じて、コード内のセキュリティホールを検出して修復します","ko":"Secure PR은 코드의 보안과 품질을 확보하는 워크플로우로, 사전검사, 보안검토, 자동화 테스트를 통해 코드 내의 보안 취약점을検出하고 수정합니다","es":"Secure-pr es una herramienta de revisión de seguridad que analiza el código para detectar vulnerabilidades","fr":"Secure-pr est un outil de révision de sécurité qui analyse le code pour détecter les vulnérabilités","de":"Secure-pr ist ein Sicherheits-Überprüfungstool, das den Code analysiert, um Schwachstellen zu erkennen","pt":"O Secure-PR é uma ferramenta de IA que executa verificações de segurança em pull requests.","ru":"Secure-PR - это инструмент ИИ, который выполняет проверки безопасности в пулл-реквестах.","ar":"Secure-PR هو أداة ذكاء اصطناعي تقوم بتشغيل فحوصات أمان في طلبات السحب."},"features":{"en":["Runs pre-flight checks using ruff check and ruff format --check","Performs security reviews with /security-review slash command","Identifies hardcoded secrets and API keys","Detects injection vulnerabilities and unsafe data handling","Analyzes dependency issues with pytest"],"zh":["预检检查：运行 linter 和测试以确保代码质量","安全审查：运行 /security-review 命令以检测安全漏洞","自动化测试：使用 pytest 运行自动化测试以确保代码的可靠性","检测硬编码的秘密或 API 密钥","检测注入漏洞和不安全的数据处理","检测依赖问题"],"ja":["Pre-flight チェック：linter とテストを実行してコードの品質を確保します","セキュリティレビュー：/security-review コマンドを実行してセキュリティホールを検出します","自動テスト：pytest を使用して自動テストを実行してコードの信頼性を確保します","ハードコードされた秘密や API キーを検出します","インジェクション脆弱性と不安全なデータ処理を検出します","依存関係の問題を検出します"],"ko":["사전검사：linter 와 테스트를 실행하여 코드의 품질을 확보합니다","보안검토：/security-review 명령을 실행하여 보안 취약점을検出합니다","자동화 테스트：pytest 를 사용하여 자동화 테스트를 실행하여 코드의 신뢰성을 확보합니다","하드코딩된 비밀번호나 API 키를検出합니다","인젝션 취약점과 불안전한 데이터 처리를검출합니다","의존성 문제를검출합니다"],"es":["Revisión de seguridad con linter y pruebas locales","Análisis de código para detectar secretos codificados y claves de API","Detección de vulnerabilidades de inyección y manipulación de datos","Revisión de dependencias para asegurar la seguridad","Compatibilidad con comandos de seguridad como /security-review"],"fr":["Révision de sécurité avec linter et tests locaux","Analyse de code pour détecter les secrets codés et les clés d''API","Détection des vulnérabilités d''injection et de manipulation de données","Révision des dépendances pour assurer la sécurité","Compatibilité avec les commandes de sécurité comme /security-review"],"de":["Sicherheitsprüfung mit Linter und lokalen Tests","Code-Analyse zur Erkennung von hartcodierten Geheimnissen und API-Schlüsseln","Erkennung von Injections- und Datenmanipulationsschwachstellen","Überprüfung von Abhängigkeiten zur Gewährleistung der Sicherheit","Unterstützung von Sicherheitsbefehlen wie /security-review"],"pt":["Verificações de pré-voo com linting e testes","Revisão de segurança com comando de slash","Detecção de segredos hardcoded ou chaves de API","Prevenção de vulnerabilidades de injeção","Tratamento seguro de dados","Verificação de dependências"],"ru":["Предварительные проверки с линтингом и тестами","Проверка безопасности с помощью команды слэш","Обнаружение зашитых секретов или ключей API","Предотвращение уязвимостей инъекции","Безопасная обработка данных","Проверка зависимостей"],"ar":["فحوصات ما قبل الطيران مع لينтинج واختبارات","مراجعة أمان مع أمر شرطة","اكتشاف الأسرار المبرمجة أو مفاتيح API","منع ثغرات الحقن","معالجة بيانات آمنة","فحص الإعتماديات"]},"keywords":{"en":["how to use secure-pr","secure-pr setup guide","github security workflow","ruff and pytest integration","secure-pr vs github code review","secure-pr install","what is secure-pr","secure-pr alternative","secure-pr for python developers"],"zh":["Secure PR","代码安全","代码质量","预检检查","安全审查","自动化测试","依赖问题","AI 工具","代码审查"],"ja":["Secure PR","コードのセキュリティ","コードの品質","Pre-flight チェック","セキュリティレビュー","自動テスト","依存関係の問題","AI エージェント","コードレビュー"],"ko":["Secure PR","코드 보안","코드 품질","사전검사","보안검토","자동화 테스트","의존성 문제","인공지능 툴","코드 리뷰"],"es":["secure-pr","herramientas de seguridad","revisión de código","análisis de seguridad","protección de workflows","seguridad de desarrollo","desarrollo seguro","prácticas de seguridad"],"fr":["secure-pr","outils de sécurité","révision de code","analyse de sécurité","protection de workflows","sécurité de développement","développement sécurisé","pratiques de sécurité"],"de":["secure-pr","Sicherheitstools","Code-Überprüfung","Sicherheitsanalyse","Schutz von Workflows","Sicherheit im Entwicklungsprozess","sichere Entwicklung","Sicherheitspraktiken"],"pt":["Secure-PR","ferramentas de IA","segurança de pull requests","verificações de pré-voo","revisão de segurança","detecção de segredos","prevenção de vulnerabilidades","tratamento seguro de dados","verificação de dependências"],"ru":["Secure-PR","ИИ Агенты","безопасность пулл-реквестов","предварительные проверки","проверка безопасности","обнаружение зашитых секретов","предотвращение уязвимостей","безопасная обработка данных","проверка зависимостей"],"ar":["Secure-PR","أدوات الذكاء الاصطناعي","أمان طلبات السحب","فحوصات ما قبل الطيران","مراجعة أمان","اكتشاف الأسرار المبرمجة","منع ثغرات الحقن","معالجة بيانات آمنة","فحص الإعتماديات"]}},"owner":"ConnerBabb","repo":"Instapermit","repoPath":"ConnerBabb/Instapermit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.300Z","topics":[],"category":"community","skillMd":{"name":"secure-pr","description":"Run security review, then create a PR and watch CI checks","bodyPreview":"## Secure PR Workflow\n\nFollow these steps in order. Do not skip any step.\n\n### Step 1 — Pre-flight checks\n\nRun the linter and tests locally. If either fails, fix the issues before continuing.\n\n```\nruff check .\nruff format --check .\npytest\n```\n\n### Step 2 — Security review\n\nRun the `/security-review` slash command to perform a full security review of all pending changes. This reviews the diff for:\n- Hardcoded secrets or API keys\n- Injection vulnerabilities\n- Unsafe data handling\n- Dependency issu","body":"## Secure PR Workflow\n\nFollow these steps in order. Do not skip any step.\n\n### Step 1 — Pre-flight checks\n\nRun the linter and tests locally. If either fails, fix the issues before continuing.\n\n```\nruff check .\nruff format --check .\npytest\n```\n\n### Step 2 — Security review\n\nRun the `/security-review` slash command to perform a full security review of all pending changes. This reviews the diff for:\n- Hardcoded secrets or API keys\n- Injection vulnerabilities\n- Unsafe data handling\n- Dependency issues\n- Any other security concerns\n\n**Do not proceed to step 3 until the security review is complete and all findings are addressed.**\n\n### Step 3 — Create the PR\n\nCreate the pull request using the standard format:\n\n```\ngh pr create --title \"<short title>\" --body \"$(cat <<''EOF''\n## Summary\n<bullet points summarizing changes>\n\n## Security Review\n- [x] Security review completed via `/security-review`\n- [x] No hardcoded secrets or API keys\n- [x] No injection vulnerabilities found\n\n## Test plan\n<bulleted checklist of testing done>\n\n🤖 Generated with [Claude Code](https://claude.com/claude-code)\nEOF\n)\"\n```\n\n### Step 4 — Watch CI checks\n\nAfter the PR is created, wait for all CI checks (lint, test, CodeQL) to complete:\n\n```\ngh pr checks --watch\n```\n\nReport the final status of each check to the user. If any check fails, investigate the failure, fix it, push the fix, and re-watch.\n"},"lastSynced":"2026-03-08T02:01:28.525Z","agentAnalysis":{"suitability":{"en":"Ideal for GitHub-focused AI Agents, such as AutoGPT and LangChain, needing streamlined security reviews and pre-flight checks for Python repositories.","zh":"适用于专注于GitHub的AI代理，例如AutoGPT和LangChain，需要简化的安全审查和Python仓库的预飞检查。","ja":"GitHubに焦点を当てたAIエージェント、たとえばAutoGPTやLangChainなど、Pythonリポジトリのストリームライン化されたセキュリティレビューとプレフライトチェックが必要な場合に最適です。","ko":"GitHub에 중점을 둔 AI 에이전트(AutoGPT 및 LangChain 등)에서 Python 저장소에 대한 보안 검토 및 프레플ライト 검사를 간소화하는 데 적합합니다.","es":"Ideal para agentes de IA centrados en GitHub, como AutoGPT y LangChain, que necesitan revisiones de seguridad simplificadas y controles previos para repositorios de Python.","fr":"Idéal pour les agents d''IA axés sur GitHub, tels que AutoGPT et LangChain, nécessitant des examens de sécurité simplifiés et des vérifications préalables pour les référentiels Python.","de":"Ideal für auf GitHub fokussierte KI-Agents, wie AutoGPT und LangChain, die gestreamte Sicherheitsprüfungen und Vorkontrollen für Python-Repositorys benötigen.","pt":"Ideal para agentes de IA focados no GitHub, como AutoGPT e LangChain, que necessitam de revisões de segurança simplificadas e verificações pré-voo para repositórios Python.","ru":"Идеально подходит для агентов ИИ, ориентированных на GitHub, таких как AutoGPT и LangChain, которым требуются упрощенные проверки безопасности и предполетные проверки для репозиториев Python.","ar":"مثالي للوكلاء الذكية التي تركز على GitHub، مثل AutoGPT و LangChain، التي تحتاج إلى مراجعات أمنية مبسطة وتحقق قبل الطيران لمستودعات Python."},"recommendation":{"en":"Empowers agents to automate security reviews using the `/security-review` slash command, checking for hardcoded secrets, injection vulnerabilities, and unsafe data handling, while also integrating with tools like Ruff for linting and Pytest for testing.","zh":"赋予代理使用 `/security-review`斜线命令自动化安全审查，检查硬编码的秘密、注入漏洞和不安全的数据处理，同时还与Ruff等工具集成以进行linting，并使用Pytest进行测试。","ja":"エージェントに、ハードコードされたシークレット、インジェクションの脆弱性、および不安全なデータの処理をチェックしながら、 `/security-review` スラッシュコマンドを使用してセキュリティレビューを自動化する機能を与え、さらにRuffなどのツールと統合してlintingを行い、Pytestを使用してテストを行います。","ko":"에이전트가 `/security-review` 슬래시 명령을 사용하여 보안 검토를 자동화 할 수 있도록 하여 하드 코딩된 비밀, 주입 취약성 및 안전하지 않은 데이터 처리를 확인하며 Ruff와 같은 도구와 통합하여 린팅을 수행하고 Pytest를 사용하여 테스트를 수행합니다.","es":"Habilita a los agentes a automatizar las revisiones de seguridad utilizando el comando de barra `/security-review`, que busca secretos codificados, vulnerabilidades de inyección y manipulación de datos no segura, e integra herramientas como Ruff para la verificación y Pytest para las pruebas.","fr":"Permet aux agents d''automatiser les examens de sécurité en utilisant la commande de barre `/security-review`, qui vérifie les secrets codés, les vulnérabilités d''injection et la manipulation de données non sécurisée, et intègre des outils comme Ruff pour la mise en page et Pytest pour les tests.","de":"Ermöglicht es den Agents, Sicherheitsprüfungen zu automatisieren, indem sie den Befehl `/security-review` verwenden, der nach hartcodierten Geheimnissen, Injektionsanfälligkeiten und unsicherer Datenverwaltung sucht und Tools wie Ruff für die Überprüfung und Pytest für die Tests integriert.","pt":"Habilita os agentes a automatizar as revisões de segurança usando o comando de barra `/security-review`, verificando segredos codificados, vulnerabilidades de injeção e tratamento de dados não seguro, além de integrar com ferramentas como Ruff para linting e Pytest para teste.","ru":"Позволяет агентам автоматизировать проверки безопасности с помощью команды `/security-review`, проверяя закодированные секреты, уязвимости инъекции и небезопасное обработку данных, а также интегрирует с инструментами seperti Ruff для проверки кода и Pytest для тестирования.","ar":"تمكين الوكلاء من تutomation مراجعات الأمن باستخدام أمر `/security-review` ، والتحقق من الأسرار المبرمجة والثغرات الأمنية وتحميل البيانات غير الآمنة ، بالإضافة إلى التكامل مع أدوات مثل Ruff لتحليل الشفرة و Pytest للاختبار."},"useCases":{"en":["Automating pre-flight checks with Ruff and Pytest","Performing full security reviews of pending changes","Identifying hardcoded secrets and API keys in Python code"],"zh":["使用Ruff和Pytest自动执行预飞检查","对待处理的更改执行完整的安全审查","在Python代码中识别硬编码的秘密和API密钥"],"ja":["RuffとPytestを使用してプレフライトチェックを自動化する","保留中の変更の完全なセキュリティレビューを実行する","Pythonコード内のハードコードされたシークレットとAPIキーを識別する"],"ko":["Ruff 및 Pytest를 사용하여 프레플ライト 검사를 자동화하는 것","대기 중인 변경 사항에 대한 완벽한 보안 검토를 수행하는 것","Python 코드 내에서 하드 코딩된 비밀 및 API 키를 식별하는 것"],"es":["Automatizar controles previos con Ruff y Pytest","Realizar revisiones de seguridad completas de los cambios pendientes","Identificar secretos codificados y claves de API en el código de Python"],"fr":["Automatiser les vérifications préalables avec Ruff et Pytest","Effectuer des examens de sécurité complets des modifications en attente","Identifier les secrets codés et les clés d''API dans le code Python"],"de":["Vorkontrollen mit Ruff und Pytest automatisieren","Vollständige Sicherheitsprüfungen von ausstehenden Änderungen durchführen","Hartcodierte Geheimnisse und API-Schlüssel im Python-Code identifizieren"],"pt":["Automatizar verificações pré-voo com Ruff e Pytest","Realizar revisões de segurança completas de alterações pendentes","Identificar segredos codificados e chaves de API em código Python"],"ru":["Автоматизировать предполетные проверки с помощью Ruff и Pytest","Проводить полные проверки безопасности ожидаемых изменений","Определить закодированные секреты и ключи API в коде Python"],"ar":["توفير التحقق قبل الطيران مع Ruff و Pytest","إجراء مراجعات أمنية كاملة للتغييرات المعلقة","تحديد الأسرار المبرمجة ومفاتيح API في код Python"]},"limitations":{"en":["Requires GitHub repository access","Python and Ruff compatibility needed","Pytest testing framework required"],"zh":["需要GitHub仓库访问","需要Python和Ruff兼容性","需要Pytest测试框架"],"ja":["GitHubリポジトリへのアクセスが必要","PythonおよびRuffの互換性が必要","Pytestテストフレームワークが必要"],"ko":["GitHub 저장소 액세스가 필요합니다.","Python 및 Ruff 호환성이 필요합니다.","Pytest 테스트 프레임워크가 필요합니다."],"es":["Requiere acceso al repositorio de GitHub","Se necesita compatibilidad con Python y Ruff","Se requiere el marco de pruebas Pytest"],"fr":["Nécessite un accès au référentiel GitHub","Une compatibilité avec Python et Ruff est nécessaire","Le framework de test Pytest est requis"],"de":["Benötigt Zugriff auf das GitHub-Repository","Python- und Ruff-Kompatibilität erforderlich","Pytest-Testframework erforderlich"],"pt":["Requer acesso ao repositório GitHub","Compatibilidade com Python e Ruff necessária","Framework de teste Pytest necessário"],"ru":["Требуется доступ к репозиторию GitHub","Необходимо совместимость с Python и Ruff","Требуется тестовый фреймворк Pytest"],"ar":["يتطلب الوصول إلى مستودع GitHub","مطلوب توافق مع Python و Ruff","مطلوب إطار الاختبار Pytest"]},"version":4},"contentHash":"a15a81ed