INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('ConnerBabb/Instapermit/secure-pr', 'secure-pr', 'ConnerBabb', 'Instapermit', 'community', 'secure-pr ConnerBabb Instapermit community The secure-pr skill streamlines GitHub security for developers by automating pre-flight checks and security reviews. It benefits developers working with Python and GitHub repositories. Secure PR 工作流程是一个确保代码安全和质量的重要步骤。通过预检、安全审查和自动化测试，开发人员可以确保代码的安全性和可靠性 Secure PR ワークフローは、コードのセキュリティと品質を確保するための重要なステップです。Pre-flight チェック、セキュリティレビュー、自動テストを通じて、開発者はコードのセキュリティと信頼性を確保できます Secure PR 워크플로우는 코드의 보안과 품질을 확보하는 중요한 단계입니다. 사전검사, 보안검토, 자동화 테스트를 통해 개발자는 코드의 보안성과 신뢰성을 확보할 수 있습니다 Secure-pr es una herramienta que ayuda a proteger tus flujos de trabajo mediante la revisión de seguridad y el análisis de código Secure-pr est un outil qui aide à sécuriser vos workflows en effectuant une révision de sécurité et une analyse de code Secure-pr ist ein Tool, das dabei hilft, Ihre Workflows zu schützen, indem es Sicherheitsprüfungen und Code-Analysen durchführt O Secure-PR é uma ferramenta de IA que ajuda a garantir a segurança das pull requests. Ele executa verificações de pré-voo e revisões de segurança. Secure-PR - это инструмент ИИ, который помогает обеспечить безопасность пулл-реквестов. Он выполняет предварительные проверки и проверки безопасности. Secure-PR هو أداة ذكاء اصطناعي تساعد على ضمان أمان طلبات السحب. وهو ي実ن فحوصات ما قبل الطيران ومراجعات الأمان. how to use secure-pr secure-pr setup guide github security workflow ruff and pytest integration secure-pr vs github code review secure-pr install what is secure-pr secure-pr alternative secure-pr for python developers Secure PR 代码安全 代码质量 预检检查 安全审查 自动化测试 依赖问题 AI 工具 代码审查 Runs pre-flight checks using ruff check and ruff format --check Performs security reviews with /security-review slash command Identifies hardcoded secrets and API keys Detects injection vulnerabilities and unsafe data handling Analyzes dependency issues with pytest secure-pr is a GitHub security workflow that automates pre-flight checks and security reviews using ruff and pytest to identify vulnerabilities and secrets.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('kaxuna1/ecomsite/elasticsearch', 'community', 'kaxuna1', 'ecomsite', 'kaxuna1/ecomsite', 'elasticsearch', 0, 0, 36, '2026-03-08T01:57:15.301Z', '2026-03-08T02:01:35.463Z', 'a8d89f236331338f3e98997cc59e49a82d831a8284814cfd0e5c7969d30c83d0', '{"id":"kaxuna1/ecomsite/elasticsearch","name":"elasticsearch","description":{"en":"The Elasticsearch skill configures Elasticsearch for audit logging, full-text search, and analytics queries, benefiting developers and administrators. It uses the @elastic/elasticsearch client for setup and configuration.","zh":"Elasticsearch是一种强大的搜索和分析引擎，本项目使用Elasticsearch进行audit日志和全文搜索。了解如何配置Elasticsearch客户端和扩展TSVECTOR","ja":"Elasticsearchは強力な検索および分析エンジンです。このプロジェクトでは、Elasticsearchを使用して監査ログと全文検索を行います。Elasticsearchクライアントの設定方法とTSVECTORの拡張方法について学びます","ko":"Elasticsearch는 강력한 검색 및 분석 엔진입니다. 본 프로젝트에서는 Elasticsearch를 사용하여 감사 로깅 및 전체 텍스트 검색을 수행합니다. Elasticsearch 클라이언트 설정 및 TSVECTOR 확장 방법에 대해 배웁니다","es":"Configura Elasticsearch para registro de auditoría y búsqueda de texto completo con nuestro servicio de Elasticsearch. Aprende a utilizar el cliente de Elasticsearch para Node.js","fr":"Configurez Elasticsearch pour la journalisation d''audit et la recherche de texte complet avec notre service Elasticsearch. Découvrez comment utiliser le client Elasticsearch pour Node.js","de":"Konfigurieren Sie Elasticsearch für die Audit-Protokollierung und die Volltextsuche mit unserem Elasticsearch-Service. Erfahren Sie, wie Sie den Elasticsearch-Client für Node.js verwenden","pt":"O Elasticsearch é uma solução de busca e análise de dados que pode ser configurada para auditoria, busca de texto completo e consultas analíticas","ru":"Elasticsearch - это решение для поиска и анализа данных, которое можно настроить для аудита, полнотекстового поиска и аналитических запросов","ar":"Elasticsearch هو حل للبحث والتح