INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('kaxuna1/ecomsite/elasticsearch', 'elasticsearch', 'kaxuna1', 'ecomsite', 'community', 'elasticsearch kaxuna1 ecomsite community The Elasticsearch skill configures Elasticsearch for audit logging, full-text search, and analytics queries, benefiting developers and administrators. It uses the @elastic/elasticsearch client for setup and configuration. Elasticsearch是一种强大的搜索和分析引擎，本项目使用Elasticsearch进行audit日志和全文搜索。了解如何配置Elasticsearch客户端和扩展TSVECTOR Elasticsearchは強力な検索および分析エンジンです。このプロジェクトでは、Elasticsearchを使用して監査ログと全文検索を行います。Elasticsearchクライアントの設定方法とTSVECTORの拡張方法について学びます Elasticsearch는 강력한 검색 및 분석 엔진입니다. 본 프로젝트에서는 Elasticsearch를 사용하여 감사 로깅 및 전체 텍스트 검색을 수행합니다. Elasticsearch 클라이언트 설정 및 TSVECTOR 확장 방법에 대해 배웁니다 Configura Elasticsearch para registro de auditoría y búsqueda de texto completo con nuestro servicio de Elasticsearch. Aprende a utilizar el cliente de Elasticsearch para Node.js Configurez Elasticsearch pour la journalisation d''audit et la recherche de texte complet avec notre service Elasticsearch. Découvrez comment utiliser le client Elasticsearch pour Node.js Konfigurieren Sie Elasticsearch für die Audit-Protokollierung und die Volltextsuche mit unserem Elasticsearch-Service. Erfahren Sie, wie Sie den Elasticsearch-Client für Node.js verwenden O Elasticsearch é uma solução de busca e análise de dados que pode ser configurada para auditoria, busca de texto completo e consultas analíticas Elasticsearch - это решение для поиска и анализа данных, которое можно настроить для аудита, полнотекстового поиска и аналитических запросов Elasticsearch هو حل للبحث والتحليل البيانات يمكن تكوينه لمراقبة التدقيق والبحث النصي الكامل واستفسارات التحليلات how to use elasticsearch elasticsearch setup guide elasticsearch vs postgresql what is elasticsearch elasticsearch install elasticsearch alternative elasticsearch for ai agents elasticsearch full-text search elasticsearch analytics queries Elasticsearch设置 audit日志 全文搜索 分析查询 TSVECTOR Node.js客户端库 Elasticsearch客户端设置 搜索引擎优化 Configures Elasticsearch for audit logging and full-text search Uses the @elastic/elasticsearch Client for setup and configuration Supports analytics queries and product search beyond PostgreSQL''s TSVECTOR Enables audit trails for API key access and admin actions Extends to product search for enhanced data retrieval Elasticsearch is a search and analytics engine that enables efficient data retrieval and analysis, using technologies like the Elasticsearch Client and TSVECTOR.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('onepunch-tk/cc-test-notion-invoice-web/workflow-team', 'community', 'onepunch-tk', 'cc-test-notion-invoice-web', 'onepunch-tk/cc-test-notion-invoice-web', 'workflow-team', 0, 0, 36, '2026-03-08T01:57:15.301Z', '2026-03-08T02:01:37.539Z', 'f8077dd13af381253ecef26a90cde25ac3d0f420a6742e77d86e1d3aa7158237', '{"id":"onepunch-tk/cc-test-notion-invoice-web/workflow-team","name":"workflow-team","description":{"en":"The workflow-team skill enables autonomous parallel development workflows for Agent Teams, benefiting team leads and teammates. It automates tasks and dependencies analysis.","zh":"workflow-team是一种自主的并行开发工作流，通过/workflow-team lead和/workflow-team teammate命令来管理","ja":"workflow-teamは、自律的な並列開発ワークフローであり、/workflow-team leadおよび/workflow-team teammateコマンドで管理します","ko":"workflow-team은 자율적인 병렬 개발 워크플로우이며, /workflow-team lead와 /workflow-team teammate 명령어로 관리합니다","es":"El flujo de trabajo en equipo permite un desarrollo en paralelo autónomo. Se invoca con `/workflow-team lead` o `/workflow-team teammate`","fr":"Le flux de travail d''équipe permet un développement parallèle autonome. Il est invoqué avec `/workflow-team lead` ou `/workflow-team teammate`","de":"Der Team-Workflow ermöglicht eine autonome parallele Entwicklung. Er wird mit `/workflow-team lead` oder `/workflow-team teammate` aufgerufen","pt":"O skill workflow-team permite um fluxo de trabalho em equipe autônomo e paralelo para equipes de desenvolvimento. Invocar com /workflow-team lead ou /workflow-team teammate","ru":"Умение workflow-team позволяет реализовать автономный и параллельный рабочий процесс команды для команд разработчиков. Вызовите с помощью /workflow-team lead или /workflow-team teammate","ar":"المهارة workflow-team تمكن من تدفق عمل فريق tự động ومتوازي لفريق التطوير. استدع مع /workflow-team lead أو /workflow-team teammate"},"seo":{"title":{"en":"workflow-team: Autonomous Parallel Development Setup Guid...","zh":"workflow-team 工作流设置指南","ja":"AIエージェントのためのworkflow-team ワークフロー導入ガイド","ko":"workflow-team 작업 흐름 가이드","es":"Guía de Configuración de workflow-team para Desarrolladores","fr":"Guide de Mise en Route de workflow-team pour les Développ...","de":"Einrichtungsleitfaden für workflow-team-Entwickler","pt":"Guia de Configuração do Fluxo de Trabalho em Equipe para ...","ru":"Настройка Работы Команды в Системе ИИ Агентов","ar":"دليل إعداد تدفق العمل الفريق لآلات الإي الأجنت"},"description":{"en":"Discover how to invoke autonomous parallel development workflows with /workflow-team lead or /workflow-team teammate. Learn more and get started today!","zh":"了解workflow-team的工作流设置和最佳实践，提高团队开发效率","ja":"AIエージェントのためのworkflow-teamワークフロー設定とベストプラクティスを紹介","ko":"workflow-team 작업 흐름 설정과 개발 효율성 향상을 위한 가이드","es":"Aprende a configurar workflow-team para un desarrollo en paralelo autónomo. Invoca con `/workflow-team lead` o `/workflow-team teammate`","fr":"Découvrez comment configurer workflow-team pour un développement parallèle autonome. Invitez avec `/workflow-team lead` ou `/workflow-team teammate`","de":"Erfahren Sie, wie Sie workflow-team für eine autonome parallele Entwicklung konfigurieren. Rufen Sie mit `/workflow-team lead` oder `/workflow-team teammate`...","pt":"Aprenda a configurar o fluxo de trabalho em equipe para ferramentas de IA com o skill workflow-team. Melhore a colaboração e a produtividade da equipe","ru":"Узнайте, как настроить рабочий процесс команды в системе ИИ Агентов с помощью умения workflow-team. Улучшите сотрудничество и производительность команды","ar":"تعلم كيفية إعداد تدفق العمل الفريق لآلات الإي الأجنت مع مهارة workflow-team. تحسين التعاون والإنتاجية الفريق"},"definition":{"en":"workflow-team is an autonomous parallel development workflow for Agent Teams, facilitating task management and dependency analysis.","zh":"workflow-team是一种工作流管理工具，用于团队开发中的任务分配和依赖管理","ja":"workflow-teamは、AIエージェントのためのワークフロー管理ツールであり、チーム開発におけるタスク割り当てと依存関係管理に使用されます","ko":"workflow-team은 작업 흐름 관리 도구로서, 팀 개발에서 태스크 할당과 의존성 관리에 사용됩니다","es":"Un flujo de trabajo en equipo es un proceso de desarrollo en paralelo autónomo para equipos de agentes","fr":"Un flux de travail d''équipe est un processus de développement parallèle autonome pour les équipes d''agents","de":"Ein Team-Workflow ist ein Prozess der autonomen parallelen Entwicklung für Agenten-Teams","pt":"O que é workflow-team? É um skill que permite um fluxo de trabalho em equipe autônomo e paralelo para equipes de desenvolvimento","ru":"Что такое workflow-team? Это умение, которое позволяет реализовать автономный и параллельный рабочий процесс команды для команд разработчиков","ar":"ما هي مهارة workflow-team؟ هي مهارة تمكن من تدفق عمل فريق tự động ومتوازي لفريق التطوير"},"features":{"en":["Invokes workflow with /workflow-team lead or /workflow-team teammate commands","Enters PlanMode for task scope analysis and file dependency identification","Breaks work into tasks with clear file ownership using CLAUDE.md and PROJECT-STRUCTURE.md","Analyzes task scope and identifies required files and dependencies","Reads ROADMAP.md for project planning and management"],"zh":["自主的并行开发工作流","通过/workflow-team lead和/workflow-team teammate命令来管理","支持任务分配和依赖管理","清晰的文件所有权和依赖关系分析","支持多个开发阶段的管理"],"ja":["自律的な並列開発ワークフロー","/workflow-team leadおよび/workflow-team teammateコマンドによる管理","タスク割り当てと依存関係管理のサポート","明確なファイル所有権と依存関係分析","複数の開発段階の管理サポート"],"ko":["자율적인 병렬 개발 워크플로우","/workflow-team lead와 /workflow-team teammate 명령어로 관리","태스크 할당과 의존성 관리를 지원","명확한 파일 소유권과 의존성 분석","다중 개발 단계의 관리를 지원"],"es":["Desarrollo en paralelo autónomo con `/workflow-team lead`","Asignación de tareas con propiedad de archivos claros","Análisis de alcance de tareas y dependencias","Invocación con `/workflow-team teammate` para colaboración en equipo","Lectura de documentos como `CLAUDE.md` y `docs/PROJECT-STRUCTURE.md`"],"fr":["Développement parallèle autonome avec `/workflow-team lead`","Attribution de tâches avec propriété de fichiers clairs","Analyse de la portée des tâches et des dépendances","Invitation avec `/workflow-team teammate` pour la collaboration d''équipe","Lecture de documents tels que `CLAUDE.md` et `docs/PROJECT-STRUCTURE.md`"],"de":["Autonome parallele Entwicklung mit `/workflow-team lead`","Zuweisung von Aufgaben mit klaren Dateieigentümern","Analyse des Aufgabenumfangs und der Abhängigkeiten","Aufruf mit `/workflow-team teammate` für Teamzusammenarbeit","Lese von Dokumenten wie `CLAUDE.md` und `docs/PROJECT-STRUCTURE.md`"],"pt":["Fluxo de trabalho em equipe autônomo e paralelo","Invocação com /workflow-team lead ou /workflow-team teammate","Fase de planejamento com leitura de arquivos CLAUDE.md, docs/PROJECT-STRUCTURE.md e docs/ROADMAP.md","Análise de escopo de tarefa e identificação de arquivos e dependências necessários","Divisão de trabalho em tarefas com propriedade de arquivo clara"],"ru":["Автономный и параллельный рабочий процесс команды","Вызов с помощью /workflow-team lead или /workflow-team teammate","Фаза планирования с чтением файлов CLAUDE.md, docs/PROJECT-STRUCTURE.md и docs/ROADMAP.md","Анализ объема задачи и определение необходимых файлов и зависимостей","Разделение работы на задачи с четкой собственностью файлов"],"ar":["تدفق عمل فريق tự động ومتوازي","استدعاء مع /workflow-team lead أو /workflow-team teammate","مرحلة التخطيط مع قراءة ملفات CLAUDE.md, docs/PROJECT-STRUCTURE.md وdocs/ROADMAP.md","تحليل نطاق المهمة وتحديد الملفات والاعتماديات المطلوبة","تقسيم العمل إلى مهام مع ملكية ملف واضحة"]},"keywords":{"en":["how to use workflow-team","workflow-team setup guide","autonomous parallel development workflow","workflow-team alternative","workflow-team vs competing tools","workflow-team install","what is workflow-team","workflow-team lead command","workflow-team teammate command"],"zh":["workflow-team","工作流管理","团队开发","并行开发","任务分配","依赖管理","AI工具","开发效率"],"ja":["workflow-team","AIエージェント","ワークフロー管理","チーム開発","並列開発","タスク割り当て","依存関係管理","開発効率"],"ko":["workflow-team","작업 흐름 관리","팀 개발","병렬 개발","태스크 할당","의존성 관리","AI 도구","개발 효율성"],"es":["workflow-team","desarrollo en paralelo autónomo","agentes de AI","herramientas de desarrollo","configuración de workflow","colaboración en equipo","gestión de tareas","análisis de dependencias"],"fr":["workflow-team","développement parallèle autonome","agents d''AI","outils de développement","configuration de flux de travail","collaboration d''équipe","gestion de tâches","analyse de dépendances"],"de":["workflow-team","autonome parallele Entwicklung","AI-Agenten","Entwicklungstools","Workflow-Konfiguration","Teamzusammenarbeit","Aufgabenverwaltung","Abhängigkeitsanalyse"],"pt":["fluxo de trabalho em equipe","ferramentas de IA","desenvolvimento de equipes","colaboração em equipe","produtividade da equipe","workflow-team","skill de workflow","autonomia em equipe","paralelismo em equipe"],"ru":["рабочий процесс команды","ИИ Агенты","разработка команд","сотрудничество команды","производительность команды","workflow-team","умение workflow","автономность команды","параллелизм команды"],"ar":["تدفق عمل الفريق","آلات الإي الأجنت","فريق التطوير","التعاون الفريق","إنتاجية الفريق","workflow-team","مهارة تدفق العمل","الاستقلالية الفريق","التوازي الفريق"]}},"owner":"onepunch-tk","repo":"cc-test-notion-invoice-web","repoPath":"onepunch-tk/cc-test-notion-invoice-web","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.301Z","topics":[],"category":"community","skillMd":{"name":"workflow-team","description":"|","bodyPreview":"# Agent Teams Workflow\n\nAutonomous parallel development workflow for Agent Teams.\nInvoke with: `/workflow-team lead` or `/workflow-team teammate`\n\n---\n\n## For Team Lead (`/workflow-team lead`)\n\n### Phase 1: Plan\n\n| Step | Action |\n|------|--------|\n| 1 | Enter `PlanMode` |\n| 2 | Read `CLAUDE.md`, `docs/PROJECT-STRUCTURE.md`, `docs/ROADMAP.md` |\n| 3 | Analyze task scope, identify required files and dependencies |\n| 4 | Break work into tasks with **clear file ownership** (no overlapping files) |\n|","body":"# Agent Teams Workflow\n\nAutonomous parallel development workflow for Agent Teams.\nInvoke with: `/workflow-team lead` or `/workflow-team teammate`\n\n---\n\n## For Team Lead (`/workflow-team lead`)\n\n### Phase 1: Plan\n\n| Step | Action |\n|------|--------|\n| 1 | Enter `PlanMode` |\n| 2 | Read `CLAUDE.md`, `docs/PROJECT-STRUCTURE.md`, `docs/ROADMAP.md` |\n| 3 | Analyze task scope, identify required files and dependencies |\n| 4 | Break work into tasks with **clear file ownership** (no overlapping files) |\n| 5 | Create detailed step-by-step plan with task breakdown |\n| 6 | Exit `PlanMode` → wait for plan approval |\n\n> After plan approval, create tasks via `TaskCreate` and spawn teammates immediately. No separate confirmation needed.\n\n### Phase 2: Execute (after user approval)\n\n| Step | Action |\n|------|--------|\n| 1 | Switch to `development` branch, create a working branch for the team |\n| 2 | Spawn teammates with detailed prompts (see Spawn Example below) |\n| 3 | Use **Delegate Mode** (Shift+Tab) — do NOT implement yourself |\n| 4 | Monitor teammate progress, unblock as needed |\n\n> Enable **Plan Approval** for complex/risky tasks.\n> All teammates work on the **same feature branch** (file ownership prevents conflicts).\n\n#### Spawn Example\n\n```\nCreate an agent team with N teammates:\n1. \"{name}\" — Read {task-file-path}. Own files: {file-list}.\n2. \"{name}\" — Read {task-file-path}. Own files: {file-list}.\nUse Opus for all teammates. Require plan approval.\n```\n\n### Phase 3: Review & Merge (after all teammates complete)\n\n| Step | Action |\n|------|--------|\n| 1 | Run the project''s test command (see CLAUDE.md Commands) to verify integration |\n| 2 | Run `code-reviewer` sub-agent on all changed files |\n| 3 | Run `e2e-tester` sub-agent to validate user flows |\n| 4 | Read report in `/docs/reports/code-review/` → fix ALL issues where status ≠ \"complete\" |\n| 5 | Merge working branch → `development` |\n| 6 | Update `ROADMAP.md` and `PROJECT-STRUCTURE.md` |\n\n### Merge Strategy\n\n```\nmain\n └── development\n      └── {working-branch}  ← single branch, all teammates work here\n           ├── teammate-A commits (owns: file-list-A)\n           ├── teammate-B commits (owns: file-list-B)\n           └── teammate-C commits (owns: file-list-C)\n\nAfter all teammates done → Phase 3\n```\n\n### Git Conventions\n\nSee [workflow-commits.md](../git/references/workflow-commits.md)\n\n---\n\n## For Teammates (`/workflow-team teammate`)\n\n### Execution Steps\n\n| Step | Action |\n|------|--------|\n| 1 | Read `CLAUDE.md`, `docs/PROJECT-STRUCTURE.md`, assigned task file |\n| 2 | Run `unit-test-writer` sub-agent (Red Phase). **NEVER analyze patterns or write test code yourself — always delegate to the `unit-test-writer` subagent.** |\n| 3 | Implement code to pass tests (Green Phase) → run the project''s test command (see CLAUDE.md Commands) |\n| 4 | Run the project''s coverage command (see CLAUDE.md Commands) |\n| 5 | Commit per [workflow-commits.md](../git/references/workflow-commits.md) |\n| 6 | Message lead: files changed, test results, remaining issues |\n\n### Teammate Rules\n\n- **ONLY modify files** assigned to you\n- **NEVER touch** files owned by another teammate\n- **Shared files** (barrel `index.ts`, `routes.ts`): message lead before modifying\n- **New files**: create freely within your task scope\n- **Do NOT create branches** — work on the feature branch created by lead\n\n### Failure Recovery (Autonomous)\n\n```\nIF any step fails:\n  1. Log to docs/reports/failures/{teammate-name}-{timestamp}.md\n  2. Retry SAME approach (1 attempt)\n  3. Retry DIFFERENT approach (1 attempt)\n  4. After 3 failures:\n     → Message lead: \"Blocked on [issue]. Attempted [approaches].\"\n     → Pick up next available task\n     → DO NOT STOP\n```\n\n### Communication\n\n| Event | Action |\n|-------|--------|\n| Task complete | Message lead with summary |\n| Blocked by another task | Message lead, pick up next task |\n| Found issue in shared code | Message lead (don''t fix directly) |\n| Need design decision | Message lead with options + recommendation |\n\n---\n\n## Cost Notes\n\n- Use `opus` model for teammates\n- Teammates: **NO code-reviewer** — TDD cycle is the quality gate, lead handles all review in Phase 3\n- Lead runs `code-reviewer` + `e2e-tester` as the single review gate post-merge\n- Minimize sub-agent calls per teammate\n- Avoid broadcast messages — message lead directly\n"},"lastSynced":"2026-03-08T02:01:37.539Z","agentAnalysis":{"suitability":{"en":"Ideal for Team Lead Agents and teammates requiring autonomous parallel development workflows with automated task and dependency analysis.","zh":"适合团队领队代理和需要自主并行开发工作流的团队成员，具有自动任务和依赖分析功能。","ja":"チームリードエージェントと自動的な並行開発ワークフローが必要なチームメンバーに最適です。タスクと依存関係の分析が自動化されています。","ko":"팀 리드 에이전트와 자동화된 병렬 개발 워크플로가 필요한 팀 멤버에게 적합합니다. 작업 및 종속성 분석이 자동화되어 있습니다.","es":"Ideal para Agentes Líder de Equipo y compañeros de equipo que requieren flujos de trabajo de desarrollo paralelo autónomo con análisis de tareas y dependencias automatizado.","fr":"Idéal pour les agents chefs d''équipe et les membres de l''équipe nécessitant des flux de travail de développement parallèle autonome avec analyse de tâches et de dépendances automatisée.","de":"Ideal für Teamleitende Agenten und Teammitglieder, die autarke parallele Entwicklungsmethoden mit automatisierter Aufgaben- und Abhängigkeitsanalyse benötigen.","pt":"Ideal para Líderes de Equipe e colegas de equipe que exigem fluxos de trabalho de desenvolvimento paralelo autônomo com análise automática de tarefas e dependências.","ru":"Идеально подходит для руководителей команд и членов команд, требующих автономных параллельных рабочих процессов разработки с автоматическим анализом задач и зависимостей.","ar":"مثالية للضيوف وقادة الفريق والزملاء الذين يحتاجون إلى تدفقات عمل متوازية ذاتية مع تحليل مهام واعتماديات آلي."},"recommendation":{"en":"Empowers agents to invoke workflow-team lead or teammate modes, analyzing task scope, identifying required files and dependencies, and breaking work into tasks with clear file ownership using CLAUDE.md, PROJECT-STRUCTURE.md, and ROADMAP.md.","zh":"赋予代理人调用工作流-团队领队或团队成员模式的能力，分析任务范围，识别所需文件和依赖关系，并使用 CLAUDE.md、PROJECT-STRUCTURE.md 和 ROADMAP.md 将工作分解为具有明确文件所有权的任务。","ja":"エージェントにワークフロー-チームリードまたはチームメンバー モードを呼び出す機能を付与し、タスクの範囲を分析し、必要なファイルと依存関係を識別し、CLAUDE.md、PROJECT-STRUCTURE.md、ROADMAP.md を使用してファイル所有権が明確なタスクに作業を分解します。","ko":"에이전트에 워크플로-팀 리드 또는 팀 멤버 모드를 호출하는 기능을 부여하고, 작업 범위를 분석하고, 필요한 파일과 종속성을 식별하고, CLAUDE.md, PROJECT-STRUCTURE.md, ROADMAP.md를 사용하여 파일 소유권이 명확한 작업으로 분할합니다.","es":"Habilita a los agentes a invocar modos de flujo de trabajo de equipo líder o compañero de equipo, analizando el alcance de la tarea, identificando archivos y dependencias necesarios y dividiendo el trabajo en tareas con propiedad de archivo clara utilizando CLAUDE.md, PROJECT-STRUCTURE.md y ROADMAP.md.","fr":"Permet aux agents d''invoker des modes de flux de travail d''équipe chef ou membre d''équipe, analysant la portée de la tâche, identifiant les fichiers et les dépendances nécessaires et divisant le travail en tâches avec propriété de fichier claire en utilisant CLAUDE.md, PROJECT-STRUCTURE.md et ROADMAP.md.","de":"Ermächtigt Agenten, Workflow-Teamleiter- oder Teammitgliedmodi aufzurufen, analysiert den Aufgabenbereich, identifiziert erforderliche Dateien und Abhängigkeiten und unterteilt die Arbeit in Aufgaben mit klarer Dateieigentümerschaft unter Verwendung von CLAUDE.md, PROJECT-STRUCTURE.md und ROADMAP.md.","pt":"Habilita os agentes a invocar modos de fluxo de trabalho de liderança de equipe ou colega de equipe, analisando o escopo da tarefa, identificando arquivos e dependências necessários e dividindo o trabalho em tarefas com propriedade de arquivo clara usando CLAUDE.md, PROJECT-STRUCTURE.md e ROADMAP.md.","ru":"Наделяет агентов возможностью вызывать режимы рабочих процессов руководителя команды или члена команды, анализируя объем задачи, определяя необходимые файлы и зависимости, и разбивая работу на задачи с четкой собственностью файла с помощью CLAUDE.md, PROJECT-STRUCTURE.md и ROADMAP.md.","ar":"تمكّن الوكيل من استدعاء أوضاع سير عمل قائد فريق أو زميل، وتحليل نطاق المهمة، وتحديد الملفات والاعتماديات المطلوبة، وتقسيم العمل إلى مهام مع ملكية ملف واضحة باستخدام CLAUDE.md و PROJECT-STRUCTURE.md و ROADMAP.md."},"useCases":{"en":["Automating task assignments for team members","Analyzing dependencies between project files","Generating parallel development workflows for Agent Teams"],"zh":["自动为团队成员分配任务","分析项目文件之间的依赖关系","为代理团队生成并行开发工作流"],"ja":["チームメンバーにタスクを自動的に割り当てる","プロジェクト ファイル間の依存関係を分析する","エージェント チームの並行開発ワークフローを生成する"],"ko":["팀 멤버에게 작업을 자동으로 할당","프로젝트 파일 사이의 종속성을 분석","에이전트 팀을 위한 병렬 개발 워크플로우 생성"],"es":["Automatización de asignaciones de tareas para miembros del equipo","Análisis de dependencias entre archivos de proyecto","Generación de flujos de trabajo de desarrollo paralelo para Equipos de Agentes"],"fr":["Automatisation des affectations de tâches pour les membres de l''équipe","Analyse des dépendances entre les fichiers de projet","Génération de flux de travail de développement parallèle pour les équipes d''agents"],"de":["Automatisierung von Aufgabenzuweisungen für Teammitglieder","Analyse von Abhängigkeiten zwischen Projektdaten","Erzeugung von parallelen Entwicklungsmethoden für Agententeams"],"pt":["Automatizar atribuições de tarefas para membros da equipe","Analizar dependências entre arquivos de projeto","Gerar fluxos de trabalho de desenvolvimento paralelo para Equipes de Agentes"],"ru":["Автоматизировать назначение задач членам команды","Анализировать зависимости между файлами проекта","Генерировать параллельные рабочие процессы разработки для команд агентов"],"ar":["تحسين任务 التخصيص تلقائيًا للأعضاء الفريق","تحليل الاعتماديات بين ملفات المشروع","توليد سير عمل تطوير متوازي لفريق الوكيل"]},"limitations":{"en":["Requires access to CLAUDE.md, docs/PROJECT-STRUCTURE.md, and docs/ROADMAP.md files","Limited to Agent Teams workflow"],"zh":["需要访问 CLAUDE.md、docs/PROJECT-STRUCTURE.md 和 docs/ROADMAP.md 文件","仅限代理团队工作流"],"ja":["CLAUDE.md、docs/PROJECT-STRUCTURE.md、docs/ROADMAP.md ファイルへのアクセスが必要","エージェント チームのワークフローのみに限定"],"ko":["CLAUDE.md, docs/PROJECT-STRUCTURE.md, docs/ROADMAP.md 파일에 접근해야 함","에이전트 팀 워크플로우만 해당"],"es":["Requiere acceso a los archivos CLAUDE.md, docs/PROJECT-STRUCTURE.md y docs/ROADMAP.md","Limitado a flujos de trabajo de Equipos de Agentes"],"fr":["Nécessite l''accès aux fichiers CLAUDE.md, docs/PROJECT-STRUCTURE.md et docs/ROADMAP.md","Limité aux flux de travail d''équipes d''agents"],"de":["Erfordert Zugriff auf die Dateien CLAUDE.md, docs/PROJECT-STRUCTURE.md und docs/ROADMAP.md","Begrenzt auf Workflow von Agententeams"],"pt":["Exige acesso aos arquivos CLAUDE.md, docs/PROJECT-STRUCTURE.md e docs/ROADMAP.md","Limitado ao fluxo de trabalho de Equipes de Agentes"],"ru":["Требует доступа к файлам CLAUDE.md, docs/PROJECT-STRUCTURE.md и docs/ROADMAP.md","Ограничен рабочим процессом команд агентов"],"ar":["يتطلب الوصول إلى الملفات CLAUDE.md و docs/PROJECT-STRUCTURE.md و docs/ROADMAP.md","محدود بسير عمل فريق الوكيل"]},"version":4},"contentHash":"f8077dd13af381253ecef26a90cde25ac3d0f420a6742e77d86e1d3aa7158237","qualityScore":36}');
