INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('nayukata/notify-patch-notes/manage-client-state', 'manage-client-state', 'nayukata', 'notify-patch-notes', 'community', 'manage-client-state nayukata notify-patch-notes community The manage-client-state skill provides a full workflow for managing client-side state, benefiting developers who need to handle global UI states, URL states, and context providers. It''s ideal for use cases like sidebars, themes, and pagination. manage-client-state 技术提供了客户端状态管理的全工作流，包括 UI 状态和 URL 同步 クライアント状態管理スキルは、クライアントサイドの状態管理の全ワークフローを提供します 클라이언트 상태 관리 스킬은 클라이언트 내 상태 관리의 전체 워크플로우를 제공합니다 Manage-client-state es una habilidad para gestionar el estado de la interfaz de usuario en el lado cliente. Permite gestionar el estado global de la UI, la navegación y el almacenamiento en el navegador Manage-client-state est une compétence pour gérer l''état de l''interface utilisateur côté client. Elle permet de gérer l''état global de l''UI, la navigation et le stockage dans le navigateur Manage-client-state ist eine Fähigkeit zur Verwaltung des Clientzustands auf der Clientseite. Sie ermöglicht die Verwaltung des globalen UI-Zustands, der Navigation und des Browser-Speichers O manage-client-state é uma habilidade que fornece gerenciamento de estado do cliente para UI e URL. Manage-client-state — это навык, который предоставляет управление состоянием клиента для UI и URL. manage-client-state هو مهارة يقدم إدارة حالة العميل للواجهة والرابط how to use manage-client-state manage-client-state vs manage-swr-data manage-client-state setup guide client-side state management best practices manage-client-state alternative manage-client-state install manage-client-state tutorial what is manage-client-state manage-client-state documentation AIエージェント 客户端状态管理 UI 状态管理 URL 同步 浏览器存储 manage-client-state React JavaScript Manages global UI states, such as sidebars and themes Synchronizes URL states for pagination, filters, and search Avoids using context providers for simpler state management Persists state to URL for better user experience Utilizes browser storage, such as localStorage, for data persistence manage-client-state is a skill that manages client-side state, including global UI states, URL states, and context providers, to provide a seamless user experience.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('edumesones/azure--demo/architecture-designer', 'community', 'edumesones', 'azure--demo', 'edumesones/azure--demo', 'architecture-designer', 0, 0, 36, '2026-03-08T01:57:15.304Z', '2026-03-08T02:01:56.598Z', '461975634d21151de5d1cb71b3601686c32028d1f8494c6887f1e62159fba9ac', '{"id":"edumesones/azure--demo/architecture-designer","name":"architecture-designer","description":{"en":"The architecture-designer skill transforms project requirements into concrete architectural decisions with proper ADR documentation, benefiting developers and project managers. It creates an architecture overview in docs.","zh":"架构设计师是一种AI工具，帮助开发者创建技术架构，通过分析项目需求和生成ADR文档","ja":"アーキテクチャデザイナーは、開発者が技術アーキテクチャを設計するためのAIツールです。プロジェクト要件を分析し、ADR文書を生成します","ko":"아키텍처 디자이너는 개발자가 기술 아키텍처를 설계하는 데 도움을 주는 AI 도구입니다. 프로젝트 요구사항을 분석하고 ADR 문서를 생성합니다","es":"El Architecture Designer es un agente que transforma requisitos de proyecto en decisiones arquitectónicas concretas con documentación ADR adecuada. Permite la creación de una visión general de la arquitectura en formato ''do''","fr":"L''Architecture Designer est un agent qui transforme les exigences de projet en décisions architecturales concrètes avec une documentation ADR appropriée. Il permet la création d''une vue d''ensemble de l''architecture au format ''do''","de":"Der Architecture Designer ist ein Agent, der Projektanforderungen in konkrete Architekturentscheidungen mit passender ADR-Dokumentation umwandelt. Er ermöglicht die Erstellung einer Architekturübersicht im ''do''-Format","pt":"O Architecture Designer é uma ferramenta que ajuda a criar uma visão geral da arquitetura do projeto","ru":"ИИ Агент Architecture Designer помогает создать общий план архитектуры проекта","ar":"مصمم الهندسة المعمارية هو أداة تساعد في إنشاء نظرة عامة على هندسة المشروع"},"seo":{"title":{"en":"Architecture Designer: Transform Project Requirements int...","zh":"架构设计师 Setup Guide - 使用AI工具创建技术架构","ja":"アーキテクチャデザイナー ベストプラクティス - AIエージェントによる技術アーキテクチャの設計","ko":"아키텍처 디자이너 설정 가이드 - AI 도구를 사용한 기술 아키텍처 생성","es":"Guía de configuración de Architecture Designer para proye...","fr":"Guide de démarrage de l''Architecture Designer pour les pr...","de":"Einrichtungsleitfaden für Architecture Designer in Entwic...","pt":"Guia de Configuração do Architecture Designer","ru":"Настройка ИИ Агента Architecture Designer","ar":"دليل إعداد مصمم الهندسة المعمارية"},"description":{"en":"Get started with architecture-designer and learn how to define technical architecture with ADR documentation. Discover how to create an architecture overview...","zh":"了解架构设计师的功能和特点，使用AI工具创建技术架构，提高开发效率","ja":"アーキテクチャデザイナーの機能と特徴を紹介します。AIエージェントを使用して技術アーキテクチャを設計し、開発効率を向上させましょう","ko":"아키텍처 디자이너의 기능과 특징을 살펴보고 AI 도구를 사용하여 기술 아키텍처를 생성하여 개발 효율성을 높이세요","es":"Aprende a transformar requisitos de proyecto en decisiones arquitectónicas concretas con la documentación ADR adecuada utilizando el agente de inteligencia a...","fr":"Découvrez comment transformer les exigences de projet en décisions architecturales concrètes avec la documentation ADR appropriée en utilisant l''agent d''inte...","de":"Erfahren Sie, wie Sie Projektanforderungen in konkrete Architekturentscheidungen mit passender ADR-Dokumentation umwandeln, indem Sie den KI-Agenten ''KI-Tool...","pt":"Aprenda a transformar requisitos de projeto em decisões arquiteturais concretas com o Architecture Designer","ru":"Преобразуйте требования проекта в конкретные архитектурные решения с помощью ИИ Агента Architecture Designer","ar":"تعرف على كيفية تحويل متطلبات المشروع إلى قرارات هندسية ملموسة باستخدام مصمم الهندسة المعمارية"},"definition":{"en":"architecture-designer is a skill that helps define technical architecture by transforming project requirements into concrete decisions with ADR documentation","zh":"架构设计师是一种AI工具，用于创建技术架构和ADR文档","ja":"アーキテクチャデザイナーは、技術アーキテクチャとADR文書を設計するためのAIツールです","ko":"아키텍처 디자이너는 기술 아키텍처와 ADR 문서를 생성하는 AI 도구입니다","es":"El Architecture Designer es un agente de inteligencia artificial que ayuda a definir la arquitectura de un proyecto","fr":"L''Architecture Designer est un agent d''intelligence artificielle qui aide à définir l''architecture d''un projet","de":"Der Architecture Designer ist ein KI-Agent, der bei der Definition der Architektur eines Projekts hilft","pt":"O que é Architecture Designer? É uma ferramenta que transforma requisitos de projeto em decisões arquiteturais","ru":"Что такое ИИ Агент Architecture Designer? Это инструмент, который преобразует требования проекта в архитектурные решения","ar":"ما هو مصمم الهندسة المعمارية؟ هو أداة تحول متطلبات المشروع إلى قرارات هندسية"},"features":{"en":["Triggers architecture design with commands like ''Help me define the architecture'' or ''/architecture''","Requires ''docs/project.md'' to exist with project definition","Creates an architecture overview in ''docs''","Suggests project interview if ''docs/project.md'' does not exist","Supports ADR documentation for technical architecture decisions"],"zh":["创建架构概述","生成ADR文档","分析项目需求","支持/docs/project.md文件","触发器：Help me define the architecture"],"ja":["アーキテクチャ概要の作成","ADR文書の生成","プロジェクト要件の分析","docs/project.mdファイルのサポート","トリガー：Help me define the architecture"],"ko":["아키텍처 개요 생성","ADR 문서 생성","프로젝트 요구사항 분석","docs/project.md 파일 지원","트리거：Help me define the architecture"],"es":["Transformación de requisitos de proyecto en decisiones arquitectónicas concretas","Creación de documentación ADR adecuada","Generación de una visión general de la arquitectura en formato ''do''","Integración con proyectos definidos en ''docs/project.md''","Compatibilidad con comandos como ''/architecture''","Soporte para la creación de una visión general de la arquitectura"],"fr":["Transformation des exigences de projet en décisions architecturales concrètes","Création de documentation ADR appropriée","Génération d''une vue d''ensemble de l''architecture au format ''do''","Intégration avec des projets définis dans ''docs/project.md''","Compatibilité avec des commandes comme ''/architecture''","Prise en charge de la création d''une vue d''ensemble de l''architecture"],"de":["Umwandlung von Projektanforderungen in konkrete Architekturentscheidungen","Erstellung passender ADR-Dokumentation","Generierung einer Architekturübersicht im ''do''-Format","Integration mit in ''docs/project.md'' definierten Projekten","Kompatibilität mit Befehlen wie ''/architecture''","Unterstützung bei der Erstellung einer Architekturübersicht"],"pt":["Criação de visão geral da arquitetura","Documentação de ADR","Transformação de requisitos de projeto em decisões arquiteturais","Integração com docs/project.md","Gatilhos de comando como ''Help me define the architecture''"],"ru":["Создание общего плана архитектуры","Документация АDR","Преобразование требований проекта в архитектурные решения","Интеграция с docs/project.md","Триггеры команд как ''Help me define the architecture''"],"ar":["إنشاء نظرة عامة على هندسة المشروع","توثيق ADR","تحويل متطلبات المشروع إلى قرارات هندسية","التكامل مع docs/project.md","مفكاتل الأوامر مثل ''Help me define the architecture''"]},"keywords":{"en":["how to use architecture-designer","what is architecture-designer","architecture-designer alternative","architecture-designer setup guide","transform project requirements into architecture","ADR documentation best practices","technical architecture design with AI"],"zh":["AI工具","技术架构","ADR文档","项目需求分析","架构设计师","docs/project.md","Help me define the architecture"],"ja":["AIエージェント","技術アーキテクチャ","ADR文書","プロジェクト要件分析","アーキテクチャデザイナー","docs/project.md","Help me define the architecture"],"ko":["AI 도구","기술 아키텍처","ADR 문서","프로젝트 요구사항 분석","아키텍처 디자이너","docs/project.md","Help me define the architecture"],"es":["architecture designer","agente de inteligencia artificial","herramientas de ai","transformación de requisitos de proyecto","documentación adr","visión general de la arquitectura","proyectos de desarrollo","desarrollo de software","arquitectura de software"],"fr":["architecture designer","agent d''intelligence artificielle","outils d''ia","transformation des exigences de projet","documentation adr","vue d''ensemble de l''architecture","projets de développement","développement de logiciels","architecture de logiciels"],"de":["architecture designer","ki-agent","ki-tools","umwandlung von projektanforderungen","adr-dokumentation","architekturübersicht","entwicklungsprojekte","softwareentwicklung","softwarearchitektur"],"pt":["Architecture Designer","projeto de arquitetura","requisitos de projeto","decisões arquiteturais","ADR","docs/project.md","ferramentas de desenvolvimento","desenvolvimento de software"],"ru":["ИИ Агент Architecture Designer","проект архитектуры","требования проекта","архитектурные решения","ADR","docs/project.md","инструменты разработки","разработка программного обеспечения"],"ar":["مصمم الهندسة المعمارية","مشروع هندسة","متطلبات المشروع","قرارات هندسية","ADR","docs/project.md","أدوات التطوير","تطوير البرمجيات"]}},"owner":"edumesones","repo":"azure--demo","repoPath":"edumesones/azure--demo","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.304Z","topics":[],"category":"community","skillMd":{"name":"architecture-designer","description":"Define technical architecture and create ADRs. Triggers on Help me define the architecture, Define architecture, Lets design the architecture.","bodyPreview":"# Architecture Designer (Fase 0)\n\nTransform project requirements into concrete architectural decisions with proper ADR documentation.\n\n## Triggers\n\n- \"Help me define the architecture\"\n- \"Define architecture\"\n- \"Let''s design the architecture\"\n- \"Help me with technical architecture\"\n- `/architecture`\n\n## Prerequisites\n\n- `docs/project.md` should exist with project definition\n- If not exists, suggest: \"Let''s first interview about the project\"\n\n## Purpose\n\nCreate:\n1. **Architecture overview** in `do","body":"# Architecture Designer (Fase 0)\n\nTransform project requirements into concrete architectural decisions with proper ADR documentation.\n\n## Triggers\n\n- \"Help me define the architecture\"\n- \"Define architecture\"\n- \"Let''s design the architecture\"\n- \"Help me with technical architecture\"\n- `/architecture`\n\n## Prerequisites\n\n- `docs/project.md` should exist with project definition\n- If not exists, suggest: \"Let''s first interview about the project\"\n\n## Purpose\n\nCreate:\n1. **Architecture overview** in `docs/architecture/_index.md`\n2. **ADRs** (Architecture Decision Records) in `docs/decisions/`\n3. **Technical foundation** for feature development\n\n## Process\n\n### 1. Read Project Context\n\n```bash\n# Read project definition\ncat docs/project.md\n\n# Check existing architecture docs\nls -la docs/architecture/ 2>/dev/null\nls -la docs/decisions/ 2>/dev/null\n```\n\n### 2. Identify Key Decisions\n\nBased on project.md, identify decisions needed:\n\n| Category | Typical Decisions |\n|----------|-------------------|\n| **Language/Runtime** | Python, Node, Go, Rust |\n| **Framework** | FastAPI, Django, Express, Next.js |\n| **Database** | PostgreSQL, MongoDB, SQLite, Redis |\n| **Authentication** | JWT, OAuth, Session, API Keys |\n| **Hosting** | AWS, GCP, Azure, Vercel, Self-hosted |\n| **API Style** | REST, GraphQL, gRPC |\n| **Frontend** | React, Vue, Gradio, CLI |\n| **Caching** | Redis, Memcached, In-memory |\n| **Queue/Async** | Celery, RQ, SQS, None |\n| **Monitoring** | CloudWatch, Datadog, Prometheus |\n\n### 3. Interview for Each Decision\n\nFor each major decision, ask:\n\n```\n\"For [CATEGORY], I see a few options:\n\nA) [Option A] - [Pros: X, Y] [Cons: Z]\nB) [Option B] - [Pros: X, Y] [Cons: Z]\nC) [Option C] - [Pros: X, Y] [Cons: Z]\n\nBased on your project (MVP timeline, team size, scale needs),\nI''d recommend [X] because [reason].\n\nWhat''s your preference?\"\n```\n\n### 4. Create ADRs\n\nFor each decision, create `docs/decisions/ADR-NNN-title.md`\n\n### 5. Create Architecture Overview\n\nUpdate `docs/architecture/_index.md` with:\n- System diagram\n- Tech stack table linking to ADRs\n- Project structure\n- Key patterns\n\n### 6. Interview Rules\n\n```\nARCHITECTURE INTERVIEW RULES\n\n1. Always provide options with trade-offs\n   Never ask \"what database?\" - ask \"PostgreSQL or MongoDB? Here''s why...\"\n\n2. Make recommendations based on project context\n   \"Given your MVP timeline, I recommend X\"\n\n3. Create ADR immediately after each decision\n   Don''t wait until the end\n\n4. Challenge over-engineering\n   \"Do you really need Kubernetes for MVP? ECS is simpler.\"\n\n5. Document the WHY, not just the WHAT\n   Future you will thank present you\n```\n\n### 7. Completion Check\n\nBefore ending, verify:\n- [ ] All major categories have decisions\n- [ ] Each decision has an ADR\n- [ ] Architecture overview exists\n- [ ] Project structure is defined\n- [ ] No conflicting decisions\n\n### 8. Handoff\n\nWhen complete:\n\n```\nArchitecture defined. Created:\n- docs/architecture/_index.md (overview)\n- docs/decisions/ADR-001-*.md through ADR-00N-*.md\n\nNext step:\n\"Define MVP features\" -> Creates feature folders ready for implementation\n\nOr: \"Let''s start with the first feature\"\n```\n"},"lastSynced":"2026-03-08T02:01:56.598Z","agentAnalysis":{"suitability":{"en":"Ideal for Technical Agents needing to transform project requirements into concrete architectural decisions with ADR documentation.","zh":"适用于需要将项目需求转化为具体架构决策的技术代理，并使用ADR文档进行记录。","ja":"プロジェクトの要件を具体的なアーキテクチャの決定に変換する必要があるテクニカルエージェントに適しています。ADR文書化を使用しています。","ko":"프로젝트 요구 사항을 구체적인 아키텍처 결정으로 변환해야 하는 기술 에이전트에게 적합합니다. ADR 문서화 사용","es":"Ideal para Agentes Técnicos que necesitan transformar los requisitos del proyecto en decisiones arquitectónicas concretas con documentación de ADR.","fr":"Idéal pour les agents techniques ayant besoin de transformer les exigences de projet en décisions architecturales concrètes avec une documentation ADR.","de":"Ideal für technische Agenten, die Projektanforderungen in konkrete architektonische Entscheidungen mit ADR-Dokumentation umwandeln müssen.","pt":"Ideal para Agentes Técnicos que precisam transformar requisitos de projeto em decisões arquiteturais concretas com documentação ADR.","ru":"Идеально для технических агентов, которым необходимо преобразовывать требования проекта в конкретные архитектурные решения с помощью документации ADR.","ar":"مثالي لعميل تقني بحاجة إلى تحويل متطلبات المشروع إلى قرارات هندسية ملموسة مع توثيق ADR."},"recommendation":{"en":"Empowers agents to create architecture overviews in documentation files, utilizing ADR documentation and generating concrete architectural decisions from project requirements, leveraging triggers like ''Help me define the architecture'' and integrating with existing project definitions in ''docs/project.md'' files.","zh":"使代理能够在文档文件中创建架构概述，利用ADR文档，并从项目需求中生成具体的架构决策，利用诸如''帮助我定义架构''的触发器，并集成到现有的项目定义中，位于''docs/project.md''文件中。","ja":"エージェントがドキュメントファイル内でアーキテクチャの概要を作成できるようにし、ADR文書化を利用し、プロジェクトの要件から具体的なアーキテクチャの決定を生成し、''アーキテクチャを定義してください''などのトリガーを利用し、''docs/project.md''ファイル内の既存のプロジェクト定義と統合します。","ko":"에이전트가 문서 파일 내에서 아키텍처 개요를 생성할 수 있도록 하며 ADR 문서화를 활용하여 프로젝트 요구 사항에서 구체적인 아키텍처 결정을 생성하며 ''아키텍처를 정의해 주세요''와 같은 트리거를 활용하고 ''docs/project.md'' 파일 내의 기존 프로젝트 정의와 통합합니다.","es":"Permite a los agentes crear vistas generales de la arquitectura en archivos de documentación, utilizando la documentación de ADR y generando decisiones arquitectónicas concretas a partir de los requisitos del proyecto, aprovechando desencadenantes como ''Ayúdame a definir la arquitectura'' e integrándose con las definiciones de proyecto existentes en archivos ''docs/project.md''.","fr":"Permet aux agents de créer des vues d''ensemble de l''architecture dans des fichiers de documentation, en utilisant la documentation ADR et en générant des décisions architecturales concrètes à partir des exigences du projet, en exploitant des déclencheurs tels que ''Aidez-moi à définir l''architecture'' et en s''intégrant aux définitions de projet existantes dans les fichiers ''docs/project.md''.","de":"Ermächtigt Agenten, Architekturübersichten in Dokumentationsdateien zu erstellen, indem sie die ADR-Dokumentation nutzen und konkrete architektonische Entscheidungen aus Projektanforderungen generieren, Auslöser wie ''Helfen Sie mir, die Architektur zu definieren'' nutzend und sich in bestehende Projektdefinitionen in ''docs/project.md''-Dateien integrierend.","pt":"Habilita os agentes a criarem visões gerais de arquitetura em arquivos de documentação, utilizando a documentação ADR e gerando decisões arquiteturais concretas a partir dos requisitos do projeto, utilizando gatilhos como ''Ajude-me a definir a arquitetura'' e integrando com as definições de projeto existentes em arquivos ''docs/project.md''.","ru":"Наделяет агентов возможностью создавать обзоры архитектуры в файлах документации, используя документацию ADR и генерируя конкретные архитектурные решения из требований проекта, используя триггеры, такие как ''Помогите мне определить архитектуру'' и интегрируя с существующими определениями проекта в файлах ''docs/project.md''.","ar":"يمنح الوكيل القدرة على إنشاء نظرة عامة على الهندسة المعمارية في ملفات الوثائق، باستخدام توثيق ADR وتوليد قرارات هندسية ملموسة من متطلبات المشروع، باستخدام محفزات مثل ''ساعدني في تعريف الهندسة المعمارية'' والدمج مع تعريفات المشروع الحالية في ملفات ''docs/project.md''."},"useCases":{"en":["Defining technical architecture for new projects","Generating architecture overviews in documentation","Creating ADR documentation for project requirements"],"zh":["为新项目定义技术架构","在文档中生成架构概述","为项目需求创建ADR文档"],"ja":["新しいプロジェクトのテクニカルアーキテクチャを定義する","ドキュメント内でアーキテクチャの概要を生成する","プロジェクトの要件のためのADR文書化を作成する"],"ko":["새로운 프로젝트를 위한 기술 아키텍처 정의","문서 내에서 아키텍처 개요 생성","프로젝트 요구 사항에 대한 ADR 문서화 생성"],"es":["Definir la arquitectura técnica para nuevos proyectos","Generar vistas generales de la arquitectura en la documentación","Crear documentación de ADR para los requisitos del proyecto"],"fr":["Définir l''architecture technique pour les nouveaux projets","Générer des vues d''ensemble de l''architecture dans la documentation","Créer une documentation ADR pour les exigences du projet"],"de":["Technische Architektur für neue Projekte definieren","Architekturübersichten in der Dokumentation generieren","ADR-Dokumentation für Projektanforderungen erstellen"],"pt":["Definir arquitetura técnica para novos projetos","Gerar visões gerais de arquitetura em documentação","Criar documentação ADR para requisitos de projeto"],"ru":["Определение технической архитектуры для новых проектов","Генерация обзоров архитектуры в документации","Создание документации ADR для требований проекта"],"ar":["تحديد الهندسة المعمارية الفنية للمشاريع الجديدة","توليد نظرة عامة على الهندسة المعمارية في الوثائق","إنشاء توثيق ADR لمتطلبات المشروع"]},"limitations":{"en":["Requires existing project definition in ''docs/project.md''","Specific to project architecture design"],"zh":["需要现有的项目定义位于''docs/project.md''文件中","仅限于项目架构设计"],"ja":["''docs/project.md''ファイル内に既存のプロジェクト定義が必要","プロジェクトアーキテクチャ設計に限定"],"ko":["''docs/project.md'' 파일 내에 기존 프로젝트 정의가 필요","프로젝트 아키텍처 설계에限定"],"es":["Requiere una definición de proyecto existente en ''docs/project.md''","Específico para el diseño de la arquitectura del proyecto"],"fr":["Nécessite une définition de projet existante dans ''docs/project.md''","Spécifique à la conception de l''architecture du projet"],"de":["Erfordert eine bestehende Projektdefinition in ''docs/project.md''","Spezifisch für das Design der Projektarchitektur"],"pt":["Exige definição de projeto existente em ''docs/project.md''","Específico para design de arquitetura de projeto"],"ru":["Требует существующего определения проекта в ''docs/project.md''","Ограничен дизайном архитектуры проекта"],"ar":["يتطلب تعريف مشروع موجود في ''docs/project.md''","محدد لتصميم هندسة المشروع"]},"version":4},"contentHash":"461975634d21151de5d1cb71b3601686c32028d1f8494c6887f1e62159fba9ac","qualityScore":36}');
