INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('edumesones/azure--demo/architecture-designer', 'architecture-designer', 'edumesones', 'azure--demo', 'community', 'architecture-designer edumesones azure--demo community The architecture-designer skill transforms project requirements into concrete architectural decisions with proper ADR documentation, benefiting developers and project managers. It creates an architecture overview in docs. 架构设计师是一种AI工具，帮助开发者创建技术架构，通过分析项目需求和生成ADR文档 アーキテクチャデザイナーは、開発者が技術アーキテクチャを設計するためのAIツールです。プロジェクト要件を分析し、ADR文書を生成します 아키텍처 디자이너는 개발자가 기술 아키텍처를 설계하는 데 도움을 주는 AI 도구입니다. 프로젝트 요구사항을 분석하고 ADR 문서를 생성합니다 El Architecture Designer es un agente que transforma requisitos de proyecto en decisiones arquitectónicas concretas con documentación ADR adecuada. Permite la creación de una visión general de la arquitectura en formato ''do'' L''Architecture Designer est un agent qui transforme les exigences de projet en décisions architecturales concrètes avec une documentation ADR appropriée. Il permet la création d''une vue d''ensemble de l''architecture au format ''do'' Der Architecture Designer ist ein Agent, der Projektanforderungen in konkrete Architekturentscheidungen mit passender ADR-Dokumentation umwandelt. Er ermöglicht die Erstellung einer Architekturübersicht im ''do''-Format O Architecture Designer é uma ferramenta que ajuda a criar uma visão geral da arquitetura do projeto ИИ Агент Architecture Designer помогает создать общий план архитектуры проекта مصمم الهندسة المعمارية هو أداة تساعد في إنشاء نظرة عامة على هندسة المشروع how to use architecture-designer what is architecture-designer architecture-designer alternative architecture-designer setup guide transform project requirements into architecture ADR documentation best practices technical architecture design with AI AI工具 技术架构 ADR文档 项目需求分析 架构设计师 docs/project.md Help me define the architecture Triggers architecture design with commands like ''Help me define the architecture'' or ''/architecture'' Requires ''docs/project.md'' to exist with project definition Creates an architecture overview in ''docs'' Suggests project interview if ''docs/project.md'' does not exist Supports ADR documentation for technical architecture decisions architecture-designer is a skill that helps define technical architecture by transforming project requirements into concrete decisions with ADR documentation');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('Falkicon/Mechanic/s-research', 'community', 'Falkicon', 'Mechanic', 'Falkicon/Mechanic', 's-research', 0, 0, 36, '2026-03-08T01:57:15.310Z', '2026-03-08T02:02:30.431Z', 'e645d572ffe340be54b39e662ef712ea196bbd8fe8033a68e49a0a6f010932c9', '{"id":"Falkicon/Mechanic/s-research","name":"s-research","description":{"en":"s-research is an in-game development hub for World of Warcraft addon developers, centralizing debugging, testing, error capture, and performance monitoring. It provides expert guidance for discovering and understanding WoW APIs and patterns.","zh":"s-research是一个World of Warcraft插件开发的调试和性能监控工具，提供API研究、测试和错误捕获功能","ja":"s-researchはWorld of Warcraftプラグイン開発のデバッグとパフォーマンスモニタリングツールで、API研究、テスト、エラーキャプチャ機能を提供します","ko":"s-research는 월드 오브 워크래프트 플러그인 개발을 위한 디버깅 및 성능 모니터링 도구로, API 연구, 테스트 및 오류 캡처 기능을 제공합니다","es":"s-research es una herramienta de desarrollo de addons para World of Warcraft que centraliza depuración, pruebas y monitoreo de rendimiento. Ofrece soporte de copia universal y CLI para búsqueda de APIs y captura de errores","fr":"s-research est un outil de développement d''addons pour World of Warcraft qui centralise le débogage, les tests et la surveillance des performances. Il propose un support de copie universel et CLI pour la recherche d''API et la capture d''erreurs","de":"s-research ist ein Addon-Entwicklungstool für World of Warcraft, das Debugging, Tests und Leistungsüberwachung zentralisiert. Es bietet universellen Kopiersupport und CLI für API-Suche und Fehlerüberwachung","pt":"O s-research é um hub de desenvolvimento para addons de World of Warcraft, oferecendo depuração, teste e monitoramento de desempenho. Utilize comandos CLI para pesquisa de APIs e obtenha informações detalhadas","ru":"ИИ Агент s-research - это центр разработки аддонов для World of Warcraft, предоставляющий отладку, тестирование и мониторинг производительности. Используйте команды CLI для поиска API и получения详ной информации","ar":"س-research هو مركز تطوير الإضافات للعبة World of Warcraft، يوفر فحص الأخطاء واختبار الأداء. استخدم أوامر CLI للبحث عن واجهات برمجة التطبيقات والحصول على معلومات مفصلة"},"seo":{"title":{"en":"s-research: WoW Addon Development Hub | AI Agent Skill","zh":"s-researchSetup Guide: World of Warcraft API调试和性能监控","ja":"s-researchセットアップガイド: World of Warcraft APIデバッグとパフォーマンスモニタリング","ko":"s-research 설정 가이드: 월드 오브 워크래프트 API 디버깅 및 성능 모니터링","es":"Guía de configuración de s-research para desarrolladores ...","fr":"Guide de mise en route de s-research pour les développeur...","de":"Einrichtungsleitfaden für s-research für WoW-Entwickler","pt":"Guia de Configuração s-research: Desenvolvimento de Addon...","ru":"ИИ Агент s-research: Руководство по Настройке для Разрабо...","ar":"دليل إعداد س-research: تطوير الإضافات للعبة World of Warc..."},"description":{"en":"Unlock efficient WoW addon development with s-research. Discover how to centralize debugging, testing, and performance monitoring - get started now!","zh":"使用s-research进行World of Warcraft插件开发，实现API调试、测试、错误捕获和性能监控","ja":"s-researchを使用してWorld of Warcraftプラグイン開発を実施し、APIデバッグ、テスト、エラーキャプチャ、パフォーマンスモニタリングを行う","ko":"s-research를 사용하여 월드 오브 워크래프트 플러그인 개발을 수행하고 API 디버깅, 테스트, 오류 캡처 및 성능 모니터링을 구현합니다","es":"Descubre cómo centralizar depuración, pruebas y monitoreo de rendimiento con s-research, la herramienta de desarrollo de addons para World of Warcraft","fr":"Découvrez comment centraliser le débogage, les tests et la surveillance des performances avec s-research, l''outil de développement d''addons pour World of War...","de":"Erfahren Sie, wie Sie Debugging, Tests und Leistungsüberwachung mit s-research, dem Addon-Entwicklungstool für World of Warcraft, zentralisieren","pt":"Aprenda a utilizar o s-research, um hub de desenvolvimento para addons de World of Warcraft, com recursos de depuração, teste e monitoramento de desempenho","ru":"Изучите возможности ИИ Агента s-research, центра разработки аддонов для World of Warcraft, с функциями отладки, тестирования и мониторинга производительности","ar":"تعرف على س-research، مركز تطوير الإضافات للعبة World of Warcraft، مع ميزات فحص الأخطاء واختبار الأداء"},"definition":{"en":"s-research is an in-game development hub for World of Warcraft addon developers, offering centralized tools for debugging, testing, and performance monitoring.","zh":"s-research是一个用于World of Warcraft插件开发的AI工具，提供API调试和性能监控功能","ja":"s-researchはWorld of Warcraftプラグイン開発用のAIエージェントで、APIデバッグとパフォーマンスモニタリング機能を提供します","ko":"s-research는 월드 오브 워크래프트 플러그인 개발을 위한 AI 도구로, API 디버깅 및 성능 모니터링 기능을 제공합니다","es":"s-research es una herramienta de desarrollo de addons para World of Warcraft que proporciona una plataforma centralizada para depuración, pruebas y monitoreo de rendimiento","fr":"s-research est un outil de développement d''addons pour World of Warcraft qui propose une plateforme centralisée pour le débogage, les tests et la surveillance des performances","de":"s-research ist ein Addon-Entwicklungstool für World of Warcraft, das eine zentrale Plattform für Debugging, Tests und Leistungsüberwachung bietet","pt":"O s-research é um conjunto de ferramentas para desenvolvedores de addons de World of Warcraft, que centraliza depuração, teste e monitoramento de desempenho","ru":"ИИ Агент s-research - это набор инструментов для разработчиков аддонов World of Warcraft, который объединяет отладку, тестирование и мониторинг производительности","ar":"س-research هو مجموعة أدوات لمطوري الإضافات للعبة World of Warcraft، التي توفر فحص الأخطاء واختبار الأداء"},"features":{"en":["Search APIs offline using `mech call api.search` command","Retrieve API information with `mech call api.info` command","Supports universal copy for efficient workflow","Centralizes error capture and performance monitoring","Provides expert guidance for understanding WoW APIs and patterns","Integrates with CLI commands for streamlined development"],"zh":["API研究和发现","CLI命令支持","离线API搜索","API信息查询","错误捕获和性能监控"],"ja":["API研究と発見","CLIコマンドサポート","オフラインAPI検索","API情報の照会","エラーキャプチャとパフォーマンスモニタリング"],"ko":["API 연구 및 발견","CLI 명령어 지원","오프라인 API 검색","API 정보 조회","오류 캡처 및 성능 모니터링"],"es":["Búsqueda de APIs de WoW con soporte de copia universal","Depuración y pruebas centralizadas","Monitoreo de rendimiento y captura de errores","CLI para búsqueda de APIs y captura de errores","Soporte para desarrolladores de addons de WoW"],"fr":["Recherche d''API de WoW avec support de copie universel","Débogage et tests centralisés","Surveillance des performances et capture d''erreurs","CLI pour recherche d''API et capture d''erreurs","Support pour les développeurs d''addons de WoW"],"de":["WoW-API-Suche mit universellem Kopiersupport","Zentrales Debugging und Testing","Leistungsüberwachung und Fehlerüberwachung","CLI für API-Suche und Fehlerüberwachung","Unterstützung für WoW-Addon-Entwickler"],"pt":["Depuração e teste de addons de World of Warcraft","Monitoramento de desempenho com suporte a cópia universal","Pesquisa de APIs com comandos CLI","Obtenção de informações detalhadas sobre APIs","Suporte a comandos CLI para tarefas comuns","Integração com o workflow de pesquisa de APIs"],"ru":["Отладка и тестирование аддонов World of Warcraft","Мониторинг производительности с поддержкой универсальной копии","Поиск API с помощью команд CLI","Получение подробной информации об API","Поддержка команд CLI для常用 задач","Интеграция с рабочим процессом поиска API"],"ar":["فحص الأخطاء واختبار الإضافات للعبة World of Warcraft","مراقبة الأداء مع دعم نسخة عالمية","بحث واجهات برمجة التطبيقات باستخدام أوامر CLI","الحصول على معلومات مفصلة عن واجهات برمجة التطبيقات","دعم أوامر CLI للعمليات الشائعة","التكامل مع سير عمل البحث عن واجهات برمجة التطبيقات"]},"keywords":{"en":["how to use s-research","s-research setup guide","WoW addon development tools","s-research alternative","s-research vs other development hubs","what is s-research","s-research install","WoW API research workflow","s-research for AI agents","centralized debugging for WoW addons"],"zh":["World of Warcraft插件开发","API调试","性能监控","AI工具","CLI命令","API研究","错误捕获"],"ja":["World of Warcraftプラグイン開発","APIデバッグ","パフォーマンスモニタリング","AIエージェント","CLIコマンド","API研究","エラーキャプチャ"],"ko":["월드 오브 워크래프트 플러그인 개발","API 디버깅","성능 모니터링","AI 도구","CLI 명령어","API 연구","오류 캡처"],"es":["s-research","desarrollo de addons para WoW","herramientas de desarrollo de WoW","depuración de WoW","pruebas de WoW","monitoreo de rendimiento de WoW","búsqueda de APIs de WoW","CLI para WoW"],"fr":["s-research","développement d''addons pour WoW","outils de développement de WoW","débogage de WoW","tests de WoW","surveillance des performances de WoW","recherche d''API de WoW","CLI pour WoW"],"de":["s-research","Addon-Entwicklung für WoW","WoW-Entwicklungstools","WoW-Debugging","WoW-Testing","WoW-Leistungsüberwachung","WoW-API-Suche","CLI für WoW"],"pt":["s-research","desenvolvimento de addons","World of Warcraft","depuração","teste","monitoramento de desempenho","CLI","API","addons wow","desenvolvedores de addons"],"ru":["ИИ Агент s-research","разработка аддонов","World of Warcraft","отладка","тестирование","мониторинг производительности","CLI","API","аддоны wow","разработчики аддонов"],"ar":["س-research","تطوير الإضافات","لعبة World of Warcraft","فحص الأخطاء","اختبار","مراقبة الأداء","CLI","واجهات برمجة التطبيقات","إضافات wow","مطوري الإضافات"]}},"owner":"Falkicon","repo":"Mechanic","repoPath":"Falkicon/Mechanic","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.310Z","topics":[],"category":"community","skillMd":{"name":"s-research","description":">","bodyPreview":"# Researching WoW APIs\n\nExpert guidance for discovering and understanding World of Warcraft APIs and patterns.\n\n## Related Commands\n\n- [c-research](../../commands/c-research.md) - API research workflow\n\n## CLI Commands (Use These First)\n\n> **MANDATORY**: Always use CLI commands before manual exploration.\n\n| Task | Command |\n|------|---------|\n| Search APIs (Offline) | `mech call api.search -i ''{\"query\": \"*Spell*\"}''` |\n| API Info | `mech call api.info -i ''{\"api_name\": \"C_Spell.GetSpellInfo\"}''` |","body":"# Researching WoW APIs\n\nExpert guidance for discovering and understanding World of Warcraft APIs and patterns.\n\n## Related Commands\n\n- [c-research](../../commands/c-research.md) - API research workflow\n\n## CLI Commands (Use These First)\n\n> **MANDATORY**: Always use CLI commands before manual exploration.\n\n| Task | Command |\n|------|---------|\n| Search APIs (Offline) | `mech call api.search -i ''{\"query\": \"*Spell*\"}''` |\n| API Info | `mech call api.info -i ''{\"api_name\": \"C_Spell.GetSpellInfo\"}''` |\n| List by Namespace | `mech call api.list -i ''{\"namespace\": \"C_Spell\"}''` |\n| Search Icons | `mech call atlas.search -i ''{\"query\": \"sword\"}''` |\n| API Stats | `mech call api.stats` |\n\n## Capabilities\n\n1. **API Discovery** — Search 5000+ WoW APIs offline using static definitions\n2. **Blizzard UI Research** — Find patterns in Blizzard''s own Lua source code\n3. **Ace3 Patterns** — Guidance on using common addon libraries (AceDB, AceEvent, etc.)\n4. **Icon/Atlas Search** — Find UI assets and textures by name\n\n## Routing Logic\n\n| Request type | Load reference |\n|--------------|----------------|\n| Offline API lookup patterns | [references/api-research.md](references/api-research.md) |\n| Blizzard UI source patterns | [references/blizzard-ui.md](references/blizzard-ui.md) |\n| Ace3 library patterns | [references/ace3-patterns.md](references/ace3-patterns.md) |\n| CLI Reference | [../../docs/cli-reference.md](../../docs/cli-reference.md) |\n\n## Quick Reference\n\n### Search WoW APIs\n```bash\nmech call api.search -i ''{\"query\": \"GetItem*\", \"namespace\": \"C_Item\"}''\n```\n\n### Get Detailed API Info\n```bash\nmech call api.info -i ''{\"api_name\": \"C_Spell.GetSpellInfo\"}''\n```\n\n### Search Icons\n```bash\nmech call atlas.search -i ''{\"query\": \"sword\", \"limit\": 10}''\n```\n\n### Best Practices\n- **Search First**: Use `api.search` before guessing API names.\n- **Audit Blizzard**: Use ripgrep on local wow-ui-source to see how Blizzard uses an API.\n- **Namespace Awareness**: Most modern APIs are in `C_` namespaces (e.g., `C_Timer`, `C_Spell`).\n"},"lastSynced":"2026-03-08T02:02:30.431Z","agentAnalysis":{"suitability":{"en":"Perfect for WoW Addon Developer Agents needing expert guidance on WoW APIs and patterns.","zh":"非常适合需要有关魔兽世界API和模式专家指导的魔兽世界插件开发者代理","ja":"WoW APIやパターンに関する専門家のガイダンスを必要とするWoWアドオン開発者エージェントに最適","ko":"魔兽世界 API 및 패턴에 대한 전문가 지침이 필요한魔兽世界 애드온 개발자 에이전트에 적합","es":"Perfecto para Agentes de Desarrollo de Addons de WoW que necesitan orientación experta sobre WoW APIs y patrones.","fr":"Parfait pour les agents de développement d''addons WoW ayant besoin de conseils d''experts sur les API et les modèles de WoW.","de":"Perfekt für WoW-Addon-Entwicklungsagenten, die Expertenrat zu WoW-APIs und Mustern benötigen.","pt":"Perfeito para Agentes de Desenvolvedores de Addons do WoW que precisam de orientação especializada sobre APIs e padrões do WoW.","ru":"Идеально подходит для агентов разработчиков дополнений WoW, которым требуется экспертное руководство по API и шаблонам WoW.","ar":"مثالي لعميل وكلاء تطوير الإضافة الخاصة بـ WoW الذين يحتاجون إلى إرشادات خبيرة حول واجهات برمجة التطبيقات وأنماط WoW."},"recommendation":{"en":"Empowers agents to discover and understand World of Warcraft APIs using CLI commands like `mech call api.search` and `mech call api.info`, providing comprehensive content analysis for debugging, testing, and performance monitoring.","zh":"赋予代理发现和理解魔兽世界API的能力，使用CLI命令，如`mech call api.search`和`mech call api.info`，提供调试、测试和性能监控的全面内容分析","ja":"エージェントがWorld of Warcraft APIを発見し、理解できるようにし、`mech call api.search`や`mech call api.info`などのCLIコマンドを使用して、デバッグ、テスト、パフォーマンスモニタリングのための包括的なコンテンツ分析を提供する","ko":"에이전트가魔兽世界 API를 발견하고 이해할 수 있도록 해주는 것, `mech call api.search`와 `mech call api.info`와 같은 CLI 명령을 사용하여 디버깅, 테스트 및 성능 모니터링을 위한 포괄적인 내용 분석을 제공","es":"Habilita a los agentes a descubrir y comprender las API de World of Warcraft utilizando comandos de CLI como `mech call api.search` y `mech call api.info`, proporcionando un análisis de contenido integral para la depuración, las pruebas y el monitoreo del rendimiento.","fr":"Permet aux agents de découvrir et de comprendre les API de World of Warcraft en utilisant des commandes CLI comme `mech call api.search` et `mech call api.info`, fournissant une analyse de contenu complète pour le débogage, les tests et la surveillance des performances.","de":"Ermächtigt Agenten, World of Warcraft APIs mithilfe von CLI-Befehlen wie `mech call api.search` und `mech call api.info` zu entdecken und zu verstehen, und bietet eine umfassende Inhaltsanalyse für Debugging, Testing und Leistungsüberwachung.","pt":"Habilita os agentes a descobrirem e compreenderem as APIs do World of Warcraft usando comandos CLI como `mech call api.search` e `mech call api.info`, fornecendo análise de conteúdo abrangente para depuração, teste e monitoramento de desempenho.","ru":"Наделяет агентов возможностью обнаруживать и понимать API World of Warcraft с помощью команд CLI, таких как `mech call api.search` и `mech call api.info`, предоставляя полный анализ содержания для отладки, тестирования и мониторинга производительности.","ar":"يمنح الوكلاء القدرة على اكتشاف وفهم واجهات برمجة التطبيقات الخاصة بـ World of Warcraft باستخدام أوامر CLI مثل `mech call api.search` و `mech call api.info` ، مع تقديم تحليل محتوى شامل لتصحيح الأخطاء واختبار ومراقبة الأداء."},"useCases":{"en":["Debugging WoW addon issues using API research workflows","Testing WoW API calls with `mech call` commands","Analyzing performance metrics for WoW addon optimization"],"zh":["使用API研究工作流调试魔兽世界插件问题","使用`mech call`命令测试魔兽世界API调用","分析魔兽世界插件优化的性能指标"],"ja":["APIリサーチワークフローを使用してWoWアドオンの問題をデバッグする","`mech call`コマンドを使用してWoW API呼び出しをテストする","WoWアドオンの最適化のパフォーマンスメトリックを分析する"],"ko":["API 연구 워크플로를 사용하여魔兽世界 애드온 문제를 디버깅","`mech call` 명령을 사용하여魔兽世界 API 호출을 테스트","魔兽世界 애드온 최적화를 위한 성능 메트릭 분석"],"es":["Depuración de problemas de addon de WoW utilizando flujos de trabajo de investigación de API","Pruebas de llamadas de API de WoW con comandos `mech call`","Análisis de métricas de rendimiento para la optimización de addons de WoW"],"fr":["Débogage des problèmes d''addon WoW en utilisant des flux de travail de recherche d''API","Test des appels d''API WoW avec des commandes `mech call`","Analyse des métriques de performance pour l''optimisation des addons WoW"],"de":["Debugging von WoW-Addon-Problemen unter Verwendung von API-Recherchearbeitsabläufen","Testen von WoW-API-Aufrufen mit `mech call`-Befehlen","Analyse von Leistungsmetriken für die Optimierung von WoW-Addons"],"pt":["Depuração de problemas de addon do WoW usando fluxos de trabalho de pesquisa de API","Teste de chamadas de API do WoW com comandos `mech call`","Análise de métricas de desempenho para otimização de addon do WoW"],"ru":["Отладка проблем дополнения WoW с помощью рабочих процессов исследования API","Тестирование вызовов API WoW с помощью команд `mech call`","Анализ метрик производительности для оптимизации дополнения WoW"],"ar":["تصحيح أخطاء مشاكل الإضافة الخاصة بـ WoW باستخدام سير عمل بحث واجهة برمجة التطبيقات","اختبار 호출ات واجهة برمجة التطبيقات الخاصة بـ WoW باستخدام أوامر `mech call`","تحليل معايير الأداء لتحسين الإضافة الخاصة بـ WoW"]},"limitations":{"en":["Requires CLI access","World of Warcraft API knowledge required","Limited to WoW addon development context"],"zh":["需要CLI访问","需要魔兽世界API知识","仅限魔兽世界插件开发环境"],"ja":["CLIアクセスが必要","World of Warcraft APIの知識が必要","WoWアドオン開発のコンテキストに限定"],"ko":["CLI 액세스가 필요","魔兽世界 API 지식이 필요","魔兽世界 애드온 개발 환경에만限"],"es":["Requiere acceso a CLI","Conocimiento de la API de World of Warcraft es requerido","Limitado al contexto de desarrollo de addons de WoW"],"fr":["Nécessite un accès CLI","Connaissance de l''API de World of Warcraft requise","Limité au contexte de développement d''addons WoW"],"de":["Benötigt CLI-Zugriff","World of Warcraft API-Kenntnisse erforderlich","Begrenzt auf den Kontext der WoW-Addon-Entwicklung"],"pt":["Requer acesso CLI","Conhecimento da API do World of Warcraft é necessário","Limitado ao contexto de desenvolvimento de addon do WoW"],"ru":["Требует доступа CLI","Требуется знание API World of Warcraft","Ограничен контекстом разработки дополнения WoW"],"ar":["يتطلب الوصول إلى CLI","مطلوب معرفة واجهة برمجة التطبيقات الخاصة بـ World of Warcraft","محدود سياق تطوير الإضافة الخاصة بـ WoW"]},"version":4},"contentHash":"e645d572ffe340be54b39e662ef712ea196bbd8fe8033a68e49a0a6f010932c9","qualityScore":36}');
