INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('Falkicon/Mechanic/s-research', 's-research', 'Falkicon', 'Mechanic', 'community', 's-research Falkicon Mechanic community s-research is an in-game development hub for World of Warcraft addon developers, centralizing debugging, testing, error capture, and performance monitoring. It provides expert guidance for discovering and understanding WoW APIs and patterns. s-research是一个World of Warcraft插件开发的调试和性能监控工具，提供API研究、测试和错误捕获功能 s-researchはWorld of Warcraftプラグイン開発のデバッグとパフォーマンスモニタリングツールで、API研究、テスト、エラーキャプチャ機能を提供します s-research는 월드 오브 워크래프트 플러그인 개발을 위한 디버깅 및 성능 모니터링 도구로, API 연구, 테스트 및 오류 캡처 기능을 제공합니다 s-research es una herramienta de desarrollo de addons para World of Warcraft que centraliza depuración, pruebas y monitoreo de rendimiento. Ofrece soporte de copia universal y CLI para búsqueda de APIs y captura de errores s-research est un outil de développement d''addons pour World of Warcraft qui centralise le débogage, les tests et la surveillance des performances. Il propose un support de copie universel et CLI pour la recherche d''API et la capture d''erreurs s-research ist ein Addon-Entwicklungstool für World of Warcraft, das Debugging, Tests und Leistungsüberwachung zentralisiert. Es bietet universellen Kopiersupport und CLI für API-Suche und Fehlerüberwachung O s-research é um hub de desenvolvimento para addons de World of Warcraft, oferecendo depuração, teste e monitoramento de desempenho. Utilize comandos CLI para pesquisa de APIs e obtenha informações detalhadas ИИ Агент s-research - это центр разработки аддонов для World of Warcraft, предоставляющий отладку, тестирование и мониторинг производительности. Используйте команды CLI для поиска API и получения详ной информации س-research هو مركز تطوير الإضافات للعبة World of Warcraft، يوفر فحص الأخطاء واختبار الأداء. استخدم أوامر CLI للبحث عن واجهات برمجة التطبيقات والحصول على معلومات مفصلة how to use s-research s-research setup guide WoW addon development tools s-research alternative s-research vs other development hubs what is s-research s-research install WoW API research workflow s-research for AI agents centralized debugging for WoW addons World of Warcraft插件开发 API调试 性能监控 AI工具 CLI命令 API研究 错误捕获 Search APIs offline using `mech call api.search` command Retrieve API information with `mech call api.info` command Supports universal copy for efficient workflow Centralizes error capture and performance monitoring Provides expert guidance for understanding WoW APIs and patterns Integrates with CLI commands for streamlined development s-research is an in-game development hub for World of Warcraft addon developers, offering centralized tools for debugging, testing, and performance monitoring.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('alexanderop/workoutTracker/workout-domain', 'community', 'alexanderop', 'workoutTracker', 'alexanderop/workoutTracker', 'workout-domain', 0, 0, 36, '2026-03-08T01:57:15.311Z', '2026-03-08T02:02:31.421Z', '3839b43fac92f21b7dd0ff283e9cb169c440e9dbbdbc0daad20211ce927f4231', '{"id":"alexanderop/workoutTracker/workout-domain","name":"workout-domain","description":{"en":"The workout-domain skill enables developers to create structured workout sequences using discriminated unions via `kind`. It benefits fitness application developers and personal trainers.","zh":"Workout Domain提供块式训练模型，包括强度块、计时块和心血管块等，帮助开发者创建健身应用","ja":"ワークアウトドメインは，ブロックベースのワークアウトモデルを提供し，ストレングスブロック，タイムドブロック，カードブロックなどの機能を活用する","ko":"운동 도메인은 블록 기반의 운동 모델을 제공하며, 강도 블록, 타이머 블록, 심장 박동 수 블록 등의 기능을 포함하여 개발자들이 운동 애플리케이션을 구축할 수 있도록 합니다","es":"El dominio de entrenamiento permite crear rutinas de ejercicios personalizadas con bloques de fuerza y cardio. Utiliza discriminated unions para definir bloques de entrenamiento","fr":"Le domaine d''entraînement permet de créer des routines d''exercices personnalisées avec des blocs de force et de cardio. Il utilise des unions discriminées pour définir les blocs d''entraînement","de":"Die Workout-Domäne ermöglicht die Erstellung individueller Trainingspläne mit Kraft- und Cardio-Blöcken. Sie verwendet discriminated unions, um Trainingsblöcke zu definieren","pt":"O domínio de treinamento é uma sequência de blocos de exercícios que utilizam unions discriminadas via ''kind''","ru":"Домен тренировок представляет собой последовательность блоков упражнений, использующих дискриминированные объединения через ''kind''","ar":"نطاق التدريب هو تسلسل من كتل التمارين التي تستخدم اتحادات محددة عبر ''kind''"},"seo":{"title":{"en":"workout-domain: Block-Based Workout Model Setup Guide | A...","zh":"健身域设置指南 - Workout Domain","ja":"ワークアウトドメインのベストプラクティス - AIエージェント","ko":"운동 도메인 구축 가이드 - Workout Domain","es":"Guía de configuración de dominio de entrenamiento","fr":"Guide de configuration du domaine d''entraînement","de":"Einrichtungsleitfaden für Workout-Domäne","pt":"Guia de Configuração do Domínio de Treinamento","ru":"Настройка ИИ Агентов для Workout Domain","ar":"دليل إعداد نطاق التدريب"},"description":{"en":"Discover how to implement a block-based workout model with workout-domain. Learn to create sequences of strength, timed, and cardio blocks with ease. Get sta...","zh":"了解Workout Domain的技术细节，包括块式训练模型和强度块等功能，提升您的健身应用开发","ja":"ワークアウトドメインの技術的な詳細，例えばブロックベースのワークアウトモデルやストレングスブロックについて学び，AIエージェントを活用する","ko":"운동 도메인의 기술적인 세부 정보, 블록 기반 운동 모델 및 강도 블록 등을 포함하여 운동 애플리케이션 개발을 향상시키세요","es":"Aprende a configurar y utilizar el dominio de entrenamiento para crear rutinas de ejercicios personalizadas con bloques de fuerza y cardio","fr":"Découvrez comment configurer et utiliser le domaine d''entraînement pour créer des routines d''exercices personnalisées avec des blocs de force et de cardio","de":"Erfahren Sie, wie Sie die Workout-Domäne konfigurieren und verwenden, um individuelle Trainingspläne mit Kraft- und Cardio-Blöcken zu erstellen","pt":"Aprenda a configurar o domínio de treinamento com blocos de exercícios personalizados e unions discriminadas","ru":"Узнайте, как настроить домен тренировок с помощью блоков упражнений и дискриминированных объединений","ar":"تعرف على كيفية إعداد نطاق التدريب باستخدام كتل تمارين مخصصة وتحديد الاتحادات"},"definition":{"en":"workout-domain is a technical framework for creating block-based workout models, utilizing TypeScript and discriminated unions to define workout sequences.","zh":"Workout Domain是一种块式训练模型，用于创建健身应用","ja":"ワークアウトドメインは，ブロックベースのワークアウトモデルの一種で，AIエージェントを活用した健身アプリケーションの開発に利用される","ko":"운동 도메인은 블록 기반의 운동 모델의 한 종류로, 운동 애플리케이션 개발에 사용됩니다","es":"El dominio de entrenamiento es un modelo de entrenamiento basado en bloques que utiliza unions discriminadas para definir bloques de fuerza, cardio y temporizados","fr":"Le domaine d''entraînement est un modèle d''entraînement basé sur des blocs qui utilise des unions discriminées pour définir des blocs de force, de cardio et de temporisation","de":"Die Workout-Domäne ist ein blockbasiertes Trainingsmodell, das discriminated unions verwendet, um Kraft-, Cardio- und Zeitblöcke zu definieren","pt":"O que é domínio de treinamento? É um modelo de treinamento baseado em blocos que utiliza TypeScript","ru":"Что такое домен тренировок? Это блоковый модель тренировок, использующий TypeScript","ar":"ما هو نطاق التدريب؟ هو نموذج تدريب قائم على الكتل باستخدام TypeScript"},"features":{"en":["Supports strength blocks with traditional sets/reps exercises","Includes timed blocks such as AmrapBlock, EmomBlock, TabataBlock, and ForTimeBlock","Utilizes discriminated unions via `kind` for workout block definition","Enables creation of sequences of blocks for comprehensive workouts","Defines sets with user-inputted weight as a string","Allows for identification of blocks using a unique `id` number"],"zh":["块式训练模型","强度块（StrengthBlock）","计时块（TimedBlock）","心血管块（CardioBlock）","区分联合类型（discriminated unions）"],"ja":["ブロックベースのワークアウトモデル","ストレングスブロック（StrengthBlock）","タイムドブロック（TimedBlock）","カードブロック（CardioBlock）","区別付き_union（discriminated unions）"],"ko":["블록 기반의 운동 모델","강도 블록（StrengthBlock）","타이머 블록（TimedBlock）","심장 박동 수 블록（CardioBlock）","구분된 유니온（discriminated unions）"],"es":["Bloques de fuerza con series y repeticiones","Bloques de cardio con temporización","Uso de unions discriminadas para definir bloques de entrenamiento","Compatibilidad con TypeScript para definir tipos de bloques de entrenamiento","Soporte para bloques de entrenamiento personalizados","Integración con herramientas de entrenamiento para un seguimiento preciso"],"fr":["Blocs de force avec séries et répétitions","Blocs de cardio avec temporisation","Utilisation d''unions discriminées pour définir les blocs d''entraînement","Compatibilité avec TypeScript pour définir les types de blocs d''entraînement","Prise en charge de blocs d''entraînement personnalisés","Intégration avec des outils d''entraînement pour un suivi précis"],"de":["Kraftblöcke mit Serien und Wiederholungen","Cardio-Blöcke mit Zeitsteuerung","Verwendung von discriminated unions, um Trainingsblöcke zu definieren","Kompatibilität mit TypeScript für die Definition von Trainingsblocktypen","Unterstützung für benutzerdefinierte Trainingsblöcke","Integration mit Trainingswerkzeugen für eine genaue Verfolgung"],"pt":["Blocos de exercícios personalizados com unions discriminadas via ''kind''","Tipos de blocos: StrengthBlock, TimedBlock, CardioBlock","Suporte a exercícios de força com sets e reps","Utilização de TypeScript para definição de tipos","Interface de programação para criação de blocos de exercícios","Suporte a diferentes tipos de blocos de exercícios"],"ru":["Пользовательские блоки упражнений с дискриминированными объединениями через ''kind''","Типы блоков: StrengthBlock, TimedBlock, CardioBlock","Поддержка упражнений для силы с подходами и повторениями","Использование TypeScript для определения типов","Интерфейс программирования для создания блоков упражнений","Поддержка различных типов блоков упражнений"],"ar":["كتلات تمارين مخصصة باتحادات محددة عبر ''kind''","أنواع الكتل: StrengthBlock, TimedBlock, CardioBlock","دعم التمارين القائمة على القوة مع مجموعات وتكرارات","استخدام TypeScript لتعريف الأنواع","واجهة برمجة لإنشاء كتل التمارين","دعم أنواع مختلفة من كتل التمارين"]},"keywords":{"en":["how to use workout-domain","workout-domain alternative","workout-domain setup guide","what is workout-domain","workout-domain vs fitness apps","install workout-domain","block-based workout model","TypeScript workout domain","discriminated unions in workout-domain","workout-domain for personal trainers"],"zh":["Workout Domain","块式训练模型","健身应用开发","AI工具","区分联合类型","强度块","计时块","心血管块"],"ja":["ワークアウトドメイン","ブロックベースのワークアウトモデル","AIエージェント","健身アプリケーションの開発","区別付き_union","ストレングスブロック","タイムドブロック","カードブロック"],"ko":["운동 도메인","블록 기반의 운동 모델","AI工具","운동 애플리케이션 개발","구분된 유니온","강도 블록","타이머 블록","심장 박동 수 블록"],"es":["dominio de entrenamiento","bloques de fuerza","bloques de cardio","uniones discriminadas","TypeScript","entrenamiento personalizado","herramientas de entrenamiento","rutinas de ejercicios","plan de entrenamiento"],"fr":["domaine d''entraînement","blocs de force","blocs de cardio","unions discriminées","TypeScript","entraînement personnalisé","outils d''entraînement","routines d''exercices","plan d''entraînement"],"de":["Workout-Domäne","Kraftblöcke","Cardio-Blöcke","discriminated unions","TypeScript","individuelles Training","Trainingswerkzeuge","Trainingspläne","Übungsroutine"],"pt":["domínio de treinamento","blocos de exercícios","unions discriminadas","TypeScript","exercícios de força","sets e reps","treinamento personalizado","desenvolvimento de aplicativos de treinamento","tecnologias de treinamento"],"ru":["домен тренировок","блоки упражнений","дискриминированные объединения","TypeScript","упражнения для силы","подходы и повторения","персональный тренинг","разработка приложений для тренировок","технологии тренировок"],"ar":["نطاق التدريب","كتلات التمارين","اتحادات محددة","TypeScript","تمارين القوة","مجموعات وتكرارات","تدريب مخصص","تطوير تطبيقات التدريب","تقنيات التدريب"]}},"owner":"alexanderop","repo":"workoutTracker","repoPath":"alexanderop/workoutTracker","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.311Z","topics":[],"category":"community","skillMd":{"name":"workout-domain","description":"Workout block model, types, and operations. Use when building workouts, managing block kinds (strength/AMRAP/EMOM/Tabata/ForTime/cardio), handling sets/reps, or working with workout persistence and benchmarks. Triggers: workout, block, strength, cardio, AMRAP, EMOM, Tabata, ForTime, exercise, set, reps, weight, RIR, timed block, create workout, build workout, block kind, discriminated union, block result, round, interval, benchmark, template, persist workout, complete workout.","bodyPreview":"# Workout Domain\n\n## Block-Based Workout Model\n\nWorkouts are sequences of **blocks** using discriminated unions via `kind`:\n\n```ts\ntype WorkoutBlock = StrengthBlock | TimedBlock | CardioBlock\n\ntype TimedBlock = AmrapBlock | EmomBlock | TabataBlock | ForTimeBlock\n```\n\n### Strength Block\n\nTraditional sets/reps exercises:\n\n```ts\ntype StrengthBlock = {\n  kind: ''strength''\n  id: number\n  exerciseName: string\n  sets: Array<Set>\n}\n\ntype Set = {\n  id: number\n  weight?: string    // User input as string","body":"# Workout Domain\n\n## Block-Based Workout Model\n\nWorkouts are sequences of **blocks** using discriminated unions via `kind`:\n\n```ts\ntype WorkoutBlock = StrengthBlock | TimedBlock | CardioBlock\n\ntype TimedBlock = AmrapBlock | EmomBlock | TabataBlock | ForTimeBlock\n```\n\n### Strength Block\n\nTraditional sets/reps exercises:\n\n```ts\ntype StrengthBlock = {\n  kind: ''strength''\n  id: number\n  exerciseName: string\n  sets: Array<Set>\n}\n\ntype Set = {\n  id: number\n  weight?: string    // User input as string\n  reps?: string\n  rir?: string       // Reps in reserve\n  completed: boolean\n}\n```\n\n### Timed Blocks\n\nAMRAP, EMOM, Tabata, ForTime:\n\n```ts\ntype AmrapBlock = {\n  kind: ''amrap''\n  id: number\n  config: AmrapConfig\n  exercises: Array<BlockExercise>\n  result?: AmrapResult\n}\n\ntype EmomBlock = {\n  kind: ''emom''\n  id: number\n  config: EmomConfig\n  exercises: Array<BlockExercise>\n  result?: EmomResult\n}\n\ntype TabataBlock = {\n  kind: ''tabata''\n  id: number\n  config: TabataConfig\n  exercises: Array<BlockExercise>\n  result?: TabataResult\n}\n\ntype ForTimeBlock = {\n  kind: ''fortime''\n  id: number\n  config: ForTimeConfig\n  exercises: Array<BlockExercise>\n  result?: ForTimeResult\n}\n```\n\n### Cardio Block\n\n```ts\ntype CardioBlock = {\n  kind: ''cardio''\n  id: number\n  exerciseName: string\n  duration?: number\n  distance?: number\n  calories?: number\n}\n```\n\n## Type Files\n\n| File | Purpose |\n|------|---------|\n| `src/types/blocks.ts` | Runtime block types |\n| `src/db/schema.ts` | Persistence types with `Db` prefix |\n\n**Convention**: Database types use `Db` prefix (e.g., `DbStrengthBlock`) and `null` instead of `undefined`.\n\n## Key Composables\n\n### Workout Feature\n\n| Composable | Purpose |\n|------------|---------|\n| `useWorkout.ts` | Singleton state, block/set CRUD operations |\n| `useWorkoutPersistence.ts` | Auto-save, complete, discard active workout |\n| `useWorkoutExercise.ts` | Exercise selection within workout |\n| `useWorkoutBuilder.ts` | Build workout from scratch or template |\n\n### Benchmark Feature\n\n| Composable | Purpose |\n|------------|---------|\n| `useBenchmark.ts` | Core benchmark state and operations |\n| `useBenchmarkPersistence.ts` | Save benchmark attempts |\n| `useBenchmarkTimer.ts` | Timer for timed benchmarks |\n\n### Template Feature\n\n| Composable | Purpose |\n|------------|---------|\n| `useTemplateForm.ts` | Create/edit template form state |\n| `useTemplatePicker.ts` | Select template to start workout |\n\n## Working with Blocks\n\n### Adding a Block\n\n```ts\nimport { useWorkout } from ''@/features/workout/composables/useWorkout''\n\nconst { addBlock } = useWorkout()\n\n// Add strength block\naddBlock({\n  kind: ''strength'',\n  exerciseName: ''Squat'',\n  sets: []\n})\n\n// Add AMRAP block\naddBlock({\n  kind: ''amrap'',\n  config: { duration: 10 },\n  exercises: []\n})\n```\n\n### Type-Safe Block Handling\n\nUse exhaustive switch for block kinds:\n\n```ts\nfunction getBlockTitle(block: WorkoutBlock): string {\n  switch (block.kind) {\n    case ''strength'':\n      return block.exerciseName\n    case ''amrap'':\n      return `AMRAP ${block.config.duration}min`\n    case ''emom'':\n      return `EMOM ${block.config.rounds}x${block.config.interval}s`\n    case ''tabata'':\n      return ''Tabata''\n    case ''fortime'':\n      return ''For Time''\n    case ''cardio'':\n      return block.exerciseName\n    default:\n      // TypeScript exhaustiveness check\n      const _exhaustive: never = block\n      return _exhaustive\n  }\n}\n```\n\n## Quick Find\n\n```bash\nrg -n \"kind: ''(strength|amrap|emom|tabata|fortime|cardio)''\" src/  # Block usage\nrg -n \"type.*Block = \" src/types/blocks.ts                        # Block type definitions\nrg -n \"export function use\" src/features/workout/composables      # Workout composables\n```\n"},"lastSynced":"2026-03-08T02:02:31.421Z","agentAnalysis":{"suitability":{"en":"Ideal for Fitness and Health Agents requiring structured workout sequence generation using discriminated unions via ''kind''.","zh":"适合于需要使用区分联合通过''kind''生成结构化锻炼序列的健身和健康代理。","ja":"フィットネスおよびヘルスエージェントが、''kind''経由の判別共用体を使用して構造化されたワークアウトシーケンスを生成する必要がある場合に最適です。","ko":"구별된 공용체를 통해 ''kind''를 사용하여 구조화된 운동 시퀸스를 생성해야 하는 피트니스 및 건강 에이전트에 적합합니다.","es":"Ideal para agentes de Fitness y Salud que requieren la generación de secuencias de entrenamiento estructuradas utilizando uniones discriminadas a través de ''kind''.","fr":"Idéal pour les agents de Fitness et de Santé nécessitant la génération de séquences d''entraînement structurées en utilisant des unions discriminées via ''kind''.","de":"Ideal für Fitness- und Gesundheitsagenten, die die Erzeugung von strukturierten Trainingssequenzen unter Verwendung von diskriminierten Vereinigungen über ''kind'' erfordern.","pt":"Ideal para Agentes de Fitness e Saúde que necessitam de geração de sequências de treino estruturadas usando discriminated unions via ''kind''.","ru":"Идеально подходит для Фитнес и Здоровья Агентов, требующих генерации структурированных последовательностей тренировок с использованием discriminated unions через ''kind''.","ar":"مثالي لوكلاء اللياقة البدنية والصحة الذين يحتاجون إلى إنشاء تسلسلات تدريب منظمة باستخدام discriminated unions عبر ''kind''."},"recommendation":{"en":"Empowers agents to create comprehensive workout plans using block-based models, including Strength, Timed, and Cardio blocks, with specific exercise details such as sets, reps, and weight, utilizing TypeScript for type safety and flexibility.","zh":"赋予代理创建综合锻炼计划的能力，使用基于块的模型，包括力量、计时和心血管块，并使用TypeScript实现类型安全和灵活性，提供具体的锻炼细节，例如组数、重复次数和重量。","ja":"エージェントが、TypeScriptを使用して安全性と柔軟性を確保し、セット、リピート、重量などの具体的な運動詳細を含む、ブロックベースのモデル（ストレングス、タイム、カーディオブロックなど）を使用して包括的な運動プランを作成できるようにします。","ko":"에이전트가 bloque 기반 모델을 사용하여 포괄적인 운동 계획을 생성할 수 있게 해주며, 이는 강도, 시간, 심혈관 블록을 포함하며, TypeScript를 사용하여 타입 안전성과 유연성을 제공하고, 세트, 리피트, 무게 등의 구체적인 운동 세부 정보를 제공합니다.","es":"Habilita a los agentes a crear planes de entrenamiento integrales utilizando modelos basados en bloques, incluyendo bloques de Fuerza, Cronometrados y Cardio, con detalles de ejercicios específicos como series, repeticiones y peso, utilizando TypeScript para la seguridad y flexibilidad de tipos.","fr":"Permet aux agents de créer des plans d''entraînement complets en utilisant des modèles basés sur des blocs, notamment des blocs de Force, de Temps et de Cardio, avec des détails d''exercices spécifiques tels que des séries, des répétitions et des poids, en utilisant TypeScript pour la sécurité et la flexibilité des types.","de":"Ermächtigt die Agenten, umfassende Trainingspläne unter Verwendung von blockbasierten Modellen zu erstellen, einschließlich Kraft-, Zeit- und Cardio-Blöcken, mit spezifischen Übungsdetails wie Sätzen, Wiederholungen und Gewicht, unter Verwendung von TypeScript für Typsicherheit und -flexibilität.","pt":"Capacita os agentes a criar planos de treino abrangentes usando modelos baseados em blocos, incluindo blocos de Força, Cronometrado e Cardio, com detalhes específicos de exercícios como séries, repetições e peso, utilizando TypeScript para segurança de tipos e flexibilidade.","ru":"Позволяет агентам создавать комплексные планы тренировок, используя блочные модели, включая блоки Силы, Времени и Кардио, с конкретными деталями упражнений, такими как подходы, повторения и вес, используя TypeScript для типобезопасности и гибкости.","ar":"يمكن الوكلاء من إنشاء خطط تدريب شاملة باستخدام نماذج قائمة على الكتل، بما في ذلك كتل القوة والتمارين الموقوتة والكارديو، مع تفاصيل تمرين محددة مثل المجموعات والتكرارات والوزن، باستخدام TypeScript لسلامة الأنواع والمرونة."},"useCases":{"en":["Generating customized workout sequences for personal training clients","Creating structured fitness plans with traditional sets and reps exercises","Automating workout block generation using discriminated unions via ''kind''"],"zh":["为个人训练客户生成定制的锻炼序列","创建具有传统组和重复次数练习的结构化健身计划","使用区分联合通过''kind''自动化锻炼块生成"],"ja":["パーソナルトレーニングクライアントのためのカスタマイズされたワークアウトシーケンスの生成","伝統的なセットとリピートのエクササイズを含む構造化されたフィットネスプランの作成","区分された共用体を使用して''kind''経由で自動化されたワークアウトブロックの生成"],"ko":["개인 트레이닝 클라이언트를 위한 사용자 지정 운동 시퀸스 생성","전통적인 세트 및 리피트 운동을 포함한 구조화된 피트니스 계획 생성","구별된 공용체를 통해 ''kind''를 사용한 자동화된 운동 블록 생성"],"es":["Generación de secuencias de entrenamiento personalizadas para clientes de entrenamiento personal","Creación de planes de fitness estructurados con ejercicios tradicionales de series y repeticiones","Automatización de la generación de bloques de entrenamiento utilizando uniones discriminadas a través de ''kind''"],"fr":["Génération de séquences d''entraînement personnalisées pour les clients d''entraînement personnel","Création de plans de fitness structurés avec des exercices traditionnels de séries et de répétitions","Automatisation de la génération de blocs d''entraînement en utilisant des unions discriminées via ''kind''"],"de":["Erzeugung von maßgeschneiderten Trainingssequenzen für persönliche Trainingsklienten","Erstellung von strukturierten Fitnessplänen mit traditionellen Sätzen und Wiederholungen","Automatisierung der Erzeugung von Trainingsblöcken unter Verwendung von diskriminierten Vereinigungen über ''kind''"],"pt":["Geração de sequências de treino personalizadas para clientes de treino pessoal","Criação de planos de fitness estruturados com exercícios tradicionais de séries e repetições","Automação da geração de blocos de treino usando discriminated unions via ''kind''"],"ru":["Генерация индивидуальных последовательностей тренировок для клиентов персонального тренинга","Создание структурированных фитнес-планов с традиционными упражнениями на подходы и повторения","Автоматизация генерации блоков тренировок с использованием discriminated unions через ''kind''"],"ar":["إنشاء تسلسلات تدريب مخصصة لعملاء التدريب الشخصي","إنشاء خطط لياقة بدنية منظمة مع تمارين المجموعات والتكرارات التقليدية","أتمتة إنشاء كتل التدريب باستخدام discriminated unions عبر ''kind''"]},"limitations":{"en":["Requires knowledge of TypeScript and discriminated unions","Limited to workout domain and fitness applications","User input required for weight and other exercise details"],"zh":["需要TypeScript和区分联合的知识","仅限于运动领域和健身应用","需要用户输入重量和其他运动细节"],"ja":["TypeScriptと判別共用体の知識が必要","運動ドメインとフィットネスアプリケーションに限定される","重量やその他の運動詳細のユーザー入力が必要"],"ko":["TypeScript 및 구별된 공용체에 대한 지식이 필요합니다.","운동 도메인 및 피트니스 애플리케이션으로만 제한됩니다.","무게 및 기타 운동 세부 정보에 대한 사용자 입력이 필요합니다."],"es":["Requiere conocimiento de TypeScript y uniones discriminadas","Limitado al dominio de entrenamiento y aplicaciones de fitness","Se requiere la entrada del usuario para el peso y otros detalles del ejercicio"],"fr":["Nécessite des connaissances en TypeScript et en unions discriminées","Limité au domaine de l''entraînement et aux applications de fitness","L''entrée de l''utilisateur est requise pour le poids et d''autres détails d''exercice"],"de":["Benötigt Kenntnisse von TypeScript und diskriminierten Vereinigungen","Begrenzt auf das Trainingsdomäne und Fitnessanwendungen","Benutzereingabe erforderlich für das Gewicht und andere Übungsdetails"],"pt":["Requer conhecimento de TypeScript e discriminated unions","Limitado ao domínio de treino e aplicações de fitness","É necessária a introdução de dados pelo utilizador para o peso e outros detalhes do exercício"],"ru":["Требует знания TypeScript и discriminated unions","Ограничено областью тренировок и фитнес-приложениями","Требуется ввод пользователем данных о весе и других деталях упражнения"],"ar":["يتطلب معرفة بـ TypeScript و discriminated unions","مقتصر على مجال التدريب وتطبيقات اللياقة البدنية","مطلوب إدخال المستخدم للوزن وتفاصيل التمرين الأخرى"]},"version":4},"contentHash":"3839b43fac92f21b7dd0ff283e9cb169c440e9dbbdbc0daad20211ce927f4231","qualityScore":36}');
