INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('zeyxx/CYNIC/dogs', 'dogs', 'zeyxx', 'CYNIC', 'community', 'dogs zeyxx CYNIC community The Dogs skill provides a collective AI consciousness for Claude Code, displaying session activity, top dogs, and historical statistics for 11 Dogs. It benefits developers working with AI agents and collective intelligence. 集体AI犬技能提供节点脚本执行和集体犬活动分析功能，帮助开发者了解犬的行为和模式 AIエージェントの犬スキルは、Nodeスクリプトの実行と集体犬活動の分析機能を提供し、開発者が犬の行動とパターンを理解するのに役立ちます Collective AI 개 스킬은 노드 스크립트 실행과 집단 개 활동 분석 기능을 제공하여 개발자가 개의 행동과 패턴을 이해하는 데 도움이 됩니다 El skill de perros ofrece una actividad colectiva de Claude Code, mostrando la sesión de actividad de todos los 11 perros y su rôle en el Collectif. Le skill des chiens offre une activité collective de Claude Code, affichant la session d''activité de tous les 11 chiens et leur rôle dans le Collectif. Das Hunde-Skill bietet eine kollektive Aktivität von Claude Code, zeigt die Sitzungsaktivität aller 11 Hunde und ihre Rolle im Collectif. A habilidade de dogs fornece uma visão geral da atividade de sessão e estatísticas de todos os tempos para desenvolvedores Хабилити dogs предоставляет обзор активности сессии и статистики за все время для разработчиков توفير مهارة الكلب لمحة عامة عن نشاط الجلسة وإحصائيات كل الوقت للمطورين how to use dogs skill dogs alternative to individual AI agents dogs setup guide for developers what is κυνικός in AI dogs vs individual AI agents installing dogs skill for Claude Code 集体AI犬技能 节点脚本执行 集体犬活动分析 AI工具 Node.js 集体智能 犬行为分析 AI开发 Runs the dogs summary script using node scripts/lib/dogs-summary.cjs Displays session activity of all 11 Dogs Ranks top dogs by actions Visualizes the Sefirot Tree of the Collective Provides all-time stats and historical dog activity Dogs is a collective AI consciousness skill for Claude Code, utilizing κυνικός to observe and analyze dog activity');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('rebyteai-template/langchain-retrieval-agent/build-and-deploy', 'community', 'rebyteai-template', 'langchain-retrieval-agent', 'rebyteai-template/langchain-retrieval-agent', 'build-and-deploy', 0, 0, 36, '2026-03-08T01:57:15.313Z', '2026-03-08T02:02:40.878Z', 'f77c23abb3cccf1bc6c32fa29a55f073ced5fbb7a04284334219ac8f2cef9b1f', '{"id":"rebyteai-template/langchain-retrieval-agent/build-and-deploy","name":"build-and-deploy","description":{"en":"The build-and-deploy skill enables developers to deploy LangChain.js agents powered by LangGraph, Supabase vector store, and Vercel AI SDK. It simplifies the deployment process for AI agents.","zh":"LangChain.js 代理的构建和部署，利用 LangGraph、Supabase矢量存储和 Vercel AI SDK","ja":"LangChain.js エージェントの構築とデプロイ、LangGraph、Supabaseベクターストア、Vercel AI SDKを使用","ko":"LangChain.js 에이전트의 빌드 및 배포, LangGraph, Supabase 벡터 저장소 및 Vercel AI SDK 사용","es":"El skill build-and-deploy permite a los desarrolladores configurar y desplegar agentes de IA con LangChain.js y tecnologías como Supabase y Vercel AI SDK","fr":"Le skill build-and-deploy permet aux développeurs de configurer et de déployer des agents IA avec LangChain.js et des technologies telles que Supabase et Vercel AI SDK","de":"Der build-and-deploy-Skill ermöglicht es Entwicklern, KI-Agents mit LangChain.js und Technologien wie Supabase und Vercel AI SDK zu konfigurieren und bereitzustellen","pt":"O agente de build e deploy com LangChain.js é uma ferramenta poderosa que utiliza Supabase e Vercel AI SDK para melhorar a eficiência do seu workflow.","ru":"Агент сборки и развертывания с LangChain.js - это мощный инструмент, который использует Supabase и Vercel AI SDK для повышения эффективности вашего рабочего процесса.","ar":"وكيل البناء والنشر مع LangChain.js هو أداة قوية تستخدم Supabase و Vercel AI SDK لتحسين كفاءة سير عملك."},"seo":{"title":{"en":"build-and-deploy: Vercel AI SDK Setup Guide | AI Agent Skill","zh":"LangChain.js AIエージェント构建和部署 Setup Guide","ja":"LangChain.js AIエージェントのビルドとデプロイ Best Practices","ko":"LangChain.js AI 에이전트 빌드 및 배포 가이드","es":"Guía de configuración de build-and-deploy para Agentes de IA","fr":"Guide de configuration de build-and-deploy pour les Agent...","de":"Einrichtungsleitfaden für build-and-deploy von KI-Agents","pt":"Guia de Configuração do Agente de Build e Deploy com Lang...","ru":"ИИ Агенты: Руководство по Настройке Build и Deploy с Lang...","ar":"دليل إعداد وكيل البناء والنشر مع LangChain.js"},"description":{"en":"Deploy LangChain.js agents with ease using build-and-deploy. Learn how to setup environment variables and use Vercel AI SDK for seamless deployment","zh":"使用 LangGraph、Supabase矢量存储和 Vercel AI SDK 构建和部署 LangChain.js AI 代理","ja":"LangGraph、Supabaseベクターストア、Vercel AI SDKを使用したLangChain.js AIエージェントの構築とデプロイ","ko":"LangGraph, Supabase 벡터 저장소 및 Vercel AI SDK를 사용하여 LangChain.js AI 에이전트 빌드 및 배포","es":"Aprende a configurar y desplegar agentes de IA con LangChain.js, Supabase y Vercel AI SDK para mejorar tus flujos de trabajo","fr":"Découvrez comment configurer et déployer des agents IA avec LangChain.js, Supabase et Vercel AI SDK pour améliorer vos flux de travail","de":"Erfahren Sie, wie Sie KI-Agents mit LangChain.js, Supabase und Vercel AI SDK konfigurieren und bereitstellen, um Ihre Arbeitsabläufe zu verbessern","pt":"Aprenda a configurar o agente de build e deploy com LangChain.js, Supabase e Vercel AI SDK para melhorar a eficiência do seu workflow","ru":"Узнайте, как настроить агент сборки и развертывания с LangChain.js, Supabase и Vercel AI SDK для повышения эффективности вашего рабочего процесса","ar":"تعرف على كيفية إعداد وكيل البناء والنشر مع LangChain.js و Supabase و Vercel AI SDK لتحسين كفاءة سير عملك"},"definition":{"en":"build-and-deploy is a LangChain.js agent skill that utilizes LangGraph, Supabase vector store, and Vercel AI SDK for efficient deployment","zh":"LangChain.js AI 代理的构建和部署是一种使用 LangGraph、Supabase矢量存储和 Vercel AI SDK 的技术","ja":"LangChain.js AIエージェントの構築とデプロイとは、LangGraph、Supabaseベクターストア、Vercel AI SDKを使用する技術です","ko":"LangChain.js AI 에이전트의 빌드 및 배포는 LangGraph, Supabase 벡터 저장소 및 Vercel AI SDK를 사용하는 기술입니다","es":"El build-and-deploy es un skill que permite la configuración y despliegue de agentes de IA con tecnologías como LangChain.js y Supabase","fr":"Le build-and-deploy est un skill qui permet la configuration et le déploiement d''agents IA avec des technologies telles que LangChain.js et Supabase","de":"Der build-and-deploy-Skill ist ein Skill, der die Konfiguration und Bereitstellung von KI-Agents mit Technologien wie LangChain.js und Supabase ermöglicht","pt":"O que é um agente de build e deploy? É uma ferramenta que automatiza o processo de build e deploy de aplicações.","ru":"Что такое агент сборки и развертывания? Это инструмент, который автоматизирует процесс сборки и развертывания приложений.","ar":"ما هو وكيل البناء والنشر? هو أداة ت自动 عملية بناء ونشر التطبيقات."},"features":{"en":["Utilizes Vercel AI SDK for seamless deployment","Employs LangGraph for retrieval tool functionality","Integrates with Supabase vector store for data management","Requires `vercel build --prod` and `vercel deploy --prebuilt --prod` for deployment","Supports environment variable setup via `.env` files","Follows critical rules for Git author permission issues in VM environments"],"zh":["使用 LangGraph 进行检索","集成了 Supabase 矢量存储","支持 Vercel AI SDK","环境变量设置","使用 `vercel build --prod` 和 `vercel deploy --prebuilt --prod` 进行部署"],"ja":["LangGraphを使用した検索","Supabaseベクターストアの統合","Vercel AI SDKのサポート","環境変数の設定","`vercel build --prod` と `vercel deploy --prebuilt --prod` を使用したデプロイ"],"ko":["LangGraph를 사용한 검색","Supabase 벡터 저장소 통합","Vercel AI SDK 지원","환경 변수 설정","`vercel build --prod` 및 `vercel deploy --prebuilt --prod`를 사용한 배포"],"es":["Soporte para LangChain.js","Integración con Supabase vector store","Uso de Vercel AI SDK","Configuración de variables de entorno","Despliegue en producción con Vercel"],"fr":["Prise en charge de LangChain.js","Intégration avec Supabase vector store","Utilisation de Vercel AI SDK","Configuration des variables d''environnement","Déploiement en production avec Vercel"],"de":["Unterstützung für LangChain.js","Integration mit Supabase-Vektor-Speicher","Verwendung von Vercel AI SDK","Konfiguration von Umgebungsvariablen","Bereitstellung in der Produktion mit Vercel"],"pt":["Utiliza LangChain.js para automatizar o processo de build","Integração com Supabase para armazenamento de dados","Utiliza Vercel AI SDK para deploy de aplicações","Suporte a variáveis de ambiente para personalização","Comando `vercel build --prod` para build de produção","Comando `vercel deploy --prebuilt --prod` para deploy de produção"],"ru":["Использует LangChain.js для автоматизации процесса сборки","Интеграция с Supabase для хранения данных","Использует Vercel AI SDK для развертывания приложений","Поддержка переменных окружения для настройки","Команда `vercel build --prod` для сборки производства","Команда `vercel deploy --prebuilt --prod` для развертывания производства"],"ar":["يستخدم LangChain.js لآتمتة عملية البناء","التكامل مع Supabase لتخزين البيانات","يستخدم Vercel AI SDK لنشر التطبيقات","دعم متغيرات البيئة للتعديل","الأمر `vercel build --prod` لبناء الإنتاج","الأمر `vercel deploy --prebuilt --prod` لنشر الإنتاج"]},"keywords":{"en":["how to use build-and-deploy","build-and-deploy setup guide","LangChain.js agent deployment","Vercel AI SDK installation","build-and-deploy vs LangChain","Supabase vector store integration","build-and-deploy environment variables","LangGraph retrieval tool","Vercel AI SDK tutorial"],"zh":["LangChain.js AI 代理","LangGraph","Supabase 矢量存储","Vercel AI SDK","AI 代理构建","AI 代理部署","LangChain.js 构建和部署"],"ja":["LangChain.js AIエージェント","LangGraph","Supabaseベクターストア","Vercel AI SDK","AIエージェントの構築","AIエージェントのデプロイ","LangChain.jsの構築とデプロイ"],"ko":["LangChain.js AI 에이전트","LangGraph","Supabase 벡터 저장소","Vercel AI SDK","AI 에이전트 빌드","AI 에이전트 배포","LangChain.js 빌드 및 배포"],"es":["agentes de IA","build-and-deploy","LangChain.js","Supabase","Vercel AI SDK","despliegue de agentes de IA","configuración de variables de entorno","desarrollo de agentes de IA"],"fr":["agents IA","build-and-deploy","LangChain.js","Supabase","Vercel AI SDK","déploiement d''agents IA","configuration des variables d''environnement","développement d''agents IA"],"de":["KI-Agents","build-and-deploy","LangChain.js","Supabase","Vercel AI SDK","Bereitstellung von KI-Agents","Konfiguration von Umgebungsvariablen","Entwicklung von KI-Agents"],"pt":["agente de build e deploy","LangChain.js","Supabase","Vercel AI SDK","automatização de build","deploy de aplicações","variáveis de ambiente","comando vercel build","comando vercel deploy"],"ru":["ИИ Агенты","агент сборки и развертывания","LangChain.js","Supabase","Vercel AI SDK","автоматизация сборки","развертывание приложений","переменные окружения","команда vercel build","команда vercel deploy"],"ar":["وكيل البناء والنشر","LangChain.js","Supabase","Vercel AI SDK","آتمتة البناء","نشر التطبيقات","متغيرات البيئة","أمر vercel build","أمر vercel deploy"]}},"owner":"rebyteai-template","repo":"langchain-retrieval-agent","repoPath":"rebyteai-template/langchain-retrieval-agent","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.313Z","topics":[],"category":"community","skillMd":{"name":"build-and-deploy","description":"Build and deploy this Next.js LangChain retrieval agent application with Supabase vector store. Use when building, deploying, setting up vector store, or preparing the project for production.","bodyPreview":"# Build and Deploy LangChain Retrieval Agent\n\n> **CRITICAL: For Vercel, you MUST use `vercel build --prod` then `vercel deploy --prebuilt --prod`.**\n> Do NOT use `vercel --prod` or `vercel deploy --prod` directly - these will fail due to Git author permission issues in VM environments.\n\n## Workflow\n\n### 1. Setup Environment Variables\n\n**Read `.env.example` to see all required variables:**\n\n```bash\ncat .env.example\n```\n\n**Create `.env` by reading values from current environment:**\n\nFor each varia","body":"# Build and Deploy LangChain Retrieval Agent\n\n> **CRITICAL: For Vercel, you MUST use `vercel build --prod` then `vercel deploy --prebuilt --prod`.**\n> Do NOT use `vercel --prod` or `vercel deploy --prod` directly - these will fail due to Git author permission issues in VM environments.\n\n## Workflow\n\n### 1. Setup Environment Variables\n\n**Read `.env.example` to see all required variables:**\n\n```bash\ncat .env.example\n```\n\n**Create `.env` by reading values from current environment:**\n\nFor each variable in `.env.example`, read the value from the current environment and write to `.env`. Example approach:\n\n```bash\n# Read .env.example and create .env with values from current environment\nwhile IFS= read -r line || [[ -n \"$line\" ]]; do\n  # Skip comments and empty lines\n  [[ \"$line\" =~ ^#.*$ || -z \"$line\" ]] && continue\n  # Extract variable name (before = sign)\n  var_name=$(echo \"$line\" | cut -d''='' -f1)\n  # Get value from environment\n  var_value=\"${!var_name}\"\n  # Write to .env\n  echo \"${var_name}=${var_value}\" >> .env\ndone < .env.example\n```\n\nOr manually inspect `.env.example` and create `.env` with the required values from environment variables.\n\n### 2. Install Dependencies\n\n```bash\nyarn install\n```\n\n### 3. Setup Supabase Vector Store\n\nGet the database connection URL from Supabase Dashboard:\n- Go to Settings → Database → Connection string → URI\n- Copy the URI and add it to `.env` as `SUPABASE_DB_URL`\n\n```bash\nyarn setup-db\n```\n\nThis creates the pgvector extension, documents table, and match_documents function in your Supabase project.\n\n### 4. Build\n\n```bash\nyarn build\n```\n\n### 5. Deploy\n\n**Vercel:**\n\nAll vercel CLI commands require `-t <token>` or `--token <token>` for authentication.\n\n```bash\n# Pull project settings (also links project, creates .vercel/project.json)\nvercel pull --yes -t $VERCEL_TOKEN\n\n# Push env vars to Vercel (first time only)\n# Must add to each environment separately\nwhile IFS=''='' read -r key value; do\n  [[ \"$key\" =~ ^#.*$ || -z \"$key\" || -z \"$value\" ]] && continue\n  for env in production preview development; do\n    printf ''%s'' \"$value\" | vercel env add \"$key\" $env -t $VERCEL_TOKEN\n  done\ndone < .env\n\n# Build locally for production\nvercel build --prod -t $VERCEL_TOKEN\n\n# Deploy prebuilt\nvercel deploy --prebuilt --prod --yes -t $VERCEL_TOKEN\n```\n\n**Netlify:**\n```bash\n# Import all env vars from .env (first time only)\nnetlify env:import .env\n\n# Deploy\nnetlify deploy --prod\n```\n\n## Critical Notes\n\n- **VERCEL PREBUILT MODE IS MANDATORY:** Always use `vercel build --prod` followed by `vercel deploy --prebuilt --prod`. Never use `vercel --prod` or `vercel deploy --prod` without `--prebuilt` flag.\n- **Supabase Required:** Need a Supabase project (free tier works)\n- **Vector Store Setup:** Run `yarn setup-db` to create tables automatically\n- **Environment Variables:** All values come from current environment - inspect `.env.example` for required variables\n- **OpenAI for Embeddings:** OPENAI_API_KEY is always required for vector embeddings\n- **No Dev Server:** Never run `yarn dev` in VM environment\n"},"lastSynced":"2026-03-08T02:02:40.878Z","agentAnalysis":{"suitability":{"en":"Perfect for LangChain.js Agents needing streamlined deployment to Vercel with Supabase vector store integration.","zh":"非常适合需要将LangChain.js Agent简化部署到Vercel并集成Supabase向量存储的场景。","ja":"Supabaseベクターストア統合によりVercelへの効率的なデプロイを必要とするLangChain.jsエージェントに最適です。","ko":"Supabase 벡터 스토어 통합과 함께 Vercel로의 간소화된 배포가 필요한 LangChain.js 에이전트에 완벽합니다.","es":"Ideal para agentes de LangChain.js que necesitan una implementación simplificada en Vercel con integración de almacén vectorial de Supabase.","fr":"Parfait pour les agents LangChain.js nécessitant un déploiement rationalisé vers Vercel avec intégration du magasin vectoriel Supabase.","de":"Perfekt für LangChain.js-Agents, die eine optimierte Bereitstellung auf Vercel mit Supabase-Vector-Store-Integration benötigen.","pt":"Perfeito para Agents LangChain.js que necessitam de uma implantação simplificada para a Vercel com integração de armazenamento vetorial Supabase.","ru":"Идеально подходит для агентов LangChain.js, которым требуется упрощённое развёртывание на Vercel с интеграцией векторного хранилища Supabase.","ar":"مثالي لوكلاء LangChain.js الذين يحتاجون إلى نشر مبسط إلى Vercel مع تكامل مخزن المتجهات Supabase."},"recommendation":{"en":"Empowers agents to deploy LangChain.js applications using LangGraph and Vercel AI SDK, simplifying the deployment process with `vercel build --prod` and `vercel deploy --prebuilt --prod` commands, while leveraging environment variables from `.env` files.","zh":"支持Agent使用LangGraph和Vercel AI SDK部署LangChain.js应用程序，通过`vercel build --prod`和`vercel deploy --prebuilt --prod`命令简化部署流程，同时利用`.env`文件中的环境变量。","ja":"LangGraphとVercel AI SDKを使用してLangChain.jsアプリケーションをデプロイする機能を提供し、`vercel build --prod`および`vercel deploy --prebuilt --prod`コマンドによるデプロイプロセスを簡素化し、`.env`ファイルからの環境変数を活用します。","ko":"LangGraph 및 Vercel AI SDK를 사용하여 LangChain.js 애플리케이션을 배포할 수 있도록 지원하며, `vercel build --prod` 및 `vercel deploy --prebuilt --prod` 명령어로 배포 프로세스를 간소화하고 `.env` 파일의 환경 변수를 활용합니다.","es":"Permite a los agentes implementar aplicaciones LangChain.js utilizando LangGraph y Vercel AI SDK, simplificando el proceso de implementación con los comandos `vercel build --prod` y `vercel deploy --prebuilt --prod`, mientras aprovecha las variables de entorno de los archivos `.env`.","fr":"Permet aux agents de déployer des applications LangChain.js en utilisant LangGraph et Vercel AI SDK, simplifiant le processus de déploiement avec les commandes `vercel build --prod` et `vercel deploy --prebuilt --prod`, tout en exploitant les variables d''environnement des fichiers `.env`.","de":"Ermöglicht Agents die Bereitstellung von LangChain.js-Anwendungen mit LangGraph und Vercel AI SDK, vereinfacht den Bereitstellungsprozess mit den Befehlen `vercel build --prod` und `vercel deploy --prebuilt --prod` und nutzt Umgebungsvariablen aus `.env`-Dateien.","pt":"Capacita os agents a implantar aplicações LangChain.js usando LangGraph e Vercel AI SDK, simplificando o processo de implantação com os comandos `vercel build --prod` e `vercel deploy --prebuilt --prod`, enquanto aproveita as variáveis de ambiente dos arquivos `.env`.","ru":"Позволяет агентам развёртывать приложения LangChain.js с использованием LangGraph и Vercel AI SDK, упрощая процесс развёртывания с помощью команд `vercel build --prod` и `vercel deploy --prebuilt --prod`, одновременно используя переменные среды из файлов `.env`.","ar":"يمكّن الوكلاء من نشر تطبيقات LangChain.js باستخدام LangGraph وVercel AI SDK، مما يبسط عملية النشر باستخدام أوامر `vercel build --prod` و`vercel deploy --prebuilt --prod`، مع الاستفادة من متغيرات البيئة من ملفات `.env`."},"useCases":{"en":["Deploying LangChain Retrieval Agents to Vercel","Configuring Supabase vector stores for AI models","Streamlining LangChain.js application deployment with automated build and deploy scripts"],"zh":["将LangChain检索型Agent部署到Vercel","为AI模型配置Supabase向量存储","通过自动化构建和部署脚本简化LangChain.js应用程序部署"],"ja":["LangChain検索エージェントのVercelへのデプロイ","AIモデル向けSupabaseベクターストアの設定","自動化されたビルドおよびデプロイスクリプトによるLangChain.jsアプリケーションのデプロイ効率化"],"ko":["LangChain 검색 에이전트를 Vercel에 배포","AI 모델을 위한 Supabase 벡터 스토어 구성","자동화된 빌드 및 배포 스크립트로 LangChain.js 애플리케이션 배포 간소화"],"es":["Implementar agentes de recuperación de LangChain en Vercel","Configurar almacenes vectoriales de Supabase para modelos de IA","Optimizar la implementación de aplicaciones LangChain.js con scripts de compilación e implementación automatizados"],"fr":["Déployer des agents de récupération LangChain sur Vercel","Configurer des magasins vectoriels Supabase pour les modèles d''IA","Rationaliser le déploiement d''applications LangChain.js avec des scripts de build et de déploiement automatisés"],"de":["Bereitstellung von LangChain Retrieval Agents auf Vercel","Konfiguration von Supabase-Vector-Stores für KI-Modelle","Optimierung der Bereitstellung von LangChain.js-Anwendungen mit automatisierten Build- und Deploy-Skripten"],"pt":["Implantação de LangChain Retrieval Agents na Vercel","Configuração de armazenamentos vetoriais Supabase para modelos de IA","Simplificação da implantação de aplicações LangChain.js com scripts automatizados de build e deploy"],"ru":["Развёртывание агентов извлечения LangChain на Vercel","Настройка векторных хранилищ Supabase для моделей ИИ","Упрощение развёртывания приложений LangChain.js с помощью автоматизированных скриптов сборки и развёртывания"],"ar":["نشر وكلاء الاسترجاع LangChain إلى Vercel","تهيئة مخازن متجهات Supabase لنماذج الذكاء الاصطناعي","تبسيط نشر تطبيقات LangChain.js باستخدام نصوص البناء والنشر الآلية"]},"limitations":{"en":["Requires Vercel account and Git author permissions","Must use `vercel build --prod` and `vercel deploy --prebuilt --prod` for successful deployment","Dependent on LangGraph and Vercel AI SDK compatibility"],"zh":["需要Vercel账户和Git作者权限","必须使用`vercel build --prod`和`vercel deploy --prebuilt --prod`命令以确保部署成功","依赖LangGraph和Vercel AI SDK的兼容性"],"ja":["VercelアカウントとGit作者権限が必要","成功裏のデプロイには`vercel build --prod`および`vercel deploy --prebuilt --prod`の使用が必須","LangGraphおよびVercel AI SDKの互換性に依存"],"ko":["Vercel 계정 및 Git 작성자 권한 필요","성공적인 배포를 위해 `vercel build --prod` 및 `vercel deploy --prebuilt --prod` 사용 필수","LangGraph 및 Vercel AI SDK 호환성에 종속"],"es":["Requiere cuenta de Vercel y permisos de autor de Git","Debe usar `vercel build --prod` y `vercel deploy --prebuilt --prod` para una implementación exitosa","Depende de la compatibilidad de LangGraph y Vercel AI SDK"],"fr":["Nécessite un compte Vercel et des autorisations d''auteur Git","Doit utiliser `vercel build --prod` et `vercel deploy --prebuilt --prod` pour un déploiement réussi","Dépend de la compatibilité de LangGraph et Vercel AI SDK"],"de":["Erfordert ein Vercel-Konto und Git-Autor-Berechtigungen","Muss `vercel build --prod` und `vercel deploy --prebuilt --prod` für eine erfolgreiche Bereitstellung verwenden","Abhängig von der Kompatibilität von LangGraph und Vercel AI SDK"],"pt":["Requer uma conta na Vercel e permissões de autor Git","Deve usar `vercel build --prod` e `vercel deploy --prebuilt --prod` para uma implantação bem-sucedida","Dependente da compatibilidade do LangGraph e do Vercel AI SDK"],"ru":["Требует учётной записи Vercel и прав автора Git","Для успешного развёртывания необходимо использовать `vercel build --prod` и `vercel deploy --prebuilt --prod`","Зависит от совместимости LangGraph и Vercel AI SDK"],"ar":["يتطلب حساب Vercel وأذونات مؤلف Git","يجب استخدام `vercel build --prod` و`vercel deploy --prebuilt --prod` للنشر الناجح","يعتمد على توافق LangGraph وVercel AI SDK"]},"version":4},"contentHash":"f77c23abb3cccf1bc6c32fa29a55f073ced5fbb7a04284334219ac8f2cef9b1f","qualityScore":36}');
