INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('copyleftdev/blsmesh/lamport-distributed-systems', 'lamport-distributed-systems', 'copyleftdev', 'blsmesh', 'community', 'lamport-distributed-systems copyleftdev blsmesh community The lamport-distributed-systems skill provides a distributed adversarial behavioral security evaluation framework for LLMs, leveraging Leslie Lamport''s work on logical clocks, consensus, and formal specification. This skill benefits developers and researchers working with distributed systems and ... Lamport分布系统是一个提供Swarm并行探测和加密共识的分布式系统安全评估框架 Lamport分散システムは、Swarmベースの並列プロービングと暗号化コンセンサスを提供する分散システムのセキュリティ評価フレームワークです Lamport 분산 시스템은 Swarm 기반 병렬 프로빙 및 암호화 합의를 제공하는 분산 시스템 보안 평가 프레임워크입니다 El framework de evaluación de seguridad de comportamiento adverso distribuido de Lamport utiliza relojes lógicos y consenso criptográfico para garantizar la seguridad de los LLM Le cadre d''évaluation de sécurité de comportement adversaire distribué de Lamport utilise des horloges logiques et un consensus cryptographique pour assurer la sécurité des LLM Das Framework für die Bewertung von verteilter adversarialer Sicherheit von Lamport verwendet logische Uhren und kryptographischen Konsens, um die Sicherheit von LLM zu gewährleisten O framework de avaliação de segurança comportamental adversarial distribuído para LLMs utiliza uma abordagem de probe parallelo com consenso criptográfico Фреймворк распределенной оценки безопасности поведения для LLMs использует параллельный зондирование с криптографическим консенсусом إطار التقييم الأمني السلوكي الموزع لل llm يستخدم نهج استكشاف موازية مع إجماع معماة how to use lamport-distributed-systems what is lamport-distributed-systems lamport-distributed-systems alternative lamport-distributed-systems vs paxos lamport-distributed-systems install lamport-distributed-systems setup guide distributed adversarial security evaluation leslie lamport distributed systems llm security evaluation framework Lamport分布系统 Swarm并行探测 加密共识 分布式系统安全 AIエージェント 分布式系统开发 Implements swarm-based parallel probing for efficient security evaluation Utilizes cryptographic consensus protocols for secure distributed decision-making Leverages Leslie Lamport''s work on logical clocks for synchronized distributed systems Employs formal specification (TLA+) for rigorous system design and verification Supports distributed system development with Paxos consensus algorithm Enables reliable distributed system engineering with Turing Award-winning principles lamport-distributed-systems is a distributed adversarial behavioral security evaluation framework for Large Language Models (LLMs), based on Leslie Lamport''s theoretical foundations for reliable distributed systems');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('WalkerHi11/mediabuy-plugins/campaign-structure', 'community', 'WalkerHi11', 'mediabuy-plugins', 'WalkerHi11/mediabuy-plugins', 'campaign-structure', 0, 0, 36, '2026-03-08T01:57:15.314Z', '2026-03-08T02:02:41.677Z', '84b19708afaee08b8f818efd0fcfe4cf225a8613e5a37e965d9dd557d5d0c5a5', '{"id":"WalkerHi11/mediabuy-plugins/campaign-structure","name":"campaign-structure","description":{"en":"The campaign-structure skill helps developers create optimal campaign architecture for testing and scaling media buying operations. It assists in assessing offers and allocating budgets.","zh":"创建最佳营销活动结构，包括Offer Type Assessment和Budget Allocation，以实现测试和扩展的最佳效果","ja":"キャンペーン構造を設計して、テストとスケーリングの最適なアーキテクチャを実現します","ko":"캠페인 구조를 설계하여 테스트와 확장의 최적의 아키텍처를 구축하세요","es":"La estructura de campaña es crucial para el éxito de las operaciones de compra de medios. Nuestro plugin de Claude Code ofrece 16 plugins profesionales configurados para ayudar a los desarrolladores a crear campañas óptimas.","fr":"La structure de campagne est essentielle pour le succès des opérations d''achat de médias. Notre plugin Claude Code propose 16 plugins professionnels configurés pour aider les développeurs à créer des campagnes optimales.","de":"Die Kampagnenstruktur ist entscheidend für den Erfolg von Medienkaufoperationen. Unser Claude-Code-Plugin bietet 16 professionell konfigurierte Plugins, um Entwicklern bei der Erstellung optimaler Kampagnen zu helfen.","pt":"O plugin de estrutura de campanha permite criar uma arquitetura de campanha otimizada para testes e escalabilidade. Ele oferece 16 plugins profissionalmente configurados para operações de compra de mídia.","ru":"Плагин структуры кампании позволяет создать оптимальную структуру кампании для тестирования и масштабирования. Он предлагает 16 профессионально настроенных плагинов для операций по покупке медиа.","ar":"مكون الإضافي للهيكل الحملي يسمح بإنشاء هيكل حملة محسّن للاختبار والتوسع. وهو يقدم 16 مكونًا إضافيًا معدًا بشكل احترافي لعمليات شراء الوسائط."},"seo":{"title":{"en":"Campaign-Structure: Setup Guide for AI Agents | AI Agent ...","zh":"AIエージェント营销活动结构设置指南","ja":"AIエージェントによるキャンペーン構造設計ベストプラクティス","ko":"AI 에이전트 캠페인 구조 최적화 가이드","es":"Guía de Configuración de Estructura de Campaña con AI Agent","fr":"Guide de Configuration de Structure de Campagne avec Outi...","de":"Konfigurationsleitfaden für Kampagnenstruktur mit KI-Tool","pt":"Guia de Configuração de Estrutura de Campanha para Ferram...","ru":"Настройка Структуры Кампании для ИИ Агентов","ar":"دليل ضبط بنية الحملة لأدوات الذكاء الاصطناعي"},"description":{"en":"Discover how to optimize campaign architecture with the campaign-structure skill. Learn how to assess offers, allocate budgets, and scale your media buying o...","zh":"了解如何使用AIエージェント创建最佳营销活动结构，包括Offer Type Assessment和Budget Allocation","ja":"AIエージェントを使用してキャンペーン構造を設計する方法を学び、Offer Type AssessmentとBudget Allocationを最適化する","ko":"AI 에이전트를 사용하여 캠페인 구조를 최적화하는 방법을 배우고, Offer Type Assessment와 Budget Allocation을 개선하세요","es":"Aprende a diseñar la arquitectura óptima de campaña para pruebas y escalado con nuestra guía de estructura de campaña","fr":"Découvrez comment créer une architecture de campagne optimale pour les tests et la mise à l''échelle avec notre guide de structure de campagne","de":"Erfahren Sie, wie Sie die optimale Kampagnenarchitektur für Tests und Skalierung mit unserem Kampagnenstruktur-Leitfaden erstellen","pt":"Aprenda a criar uma arquitetura de campanha otimizada para testes e escalabilidade com o plugin de estrutura de campanha","ru":"Узнайте, как создать оптимальную структуру кампании для тестирования и масштабирования с помощью плагина структуры кампании для ИИ Агентов","ar":"تعرف على كيفية إنشاء هيكل حملة محسّن للاختبار والتوسع باستخدام مكون إضافي للهيكل الحملي لأدوات الذكاء الاصطناعي"},"definition":{"en":"Campaign-structure is a plugin marketplace for media buying operations that provides 16 professionally configured plugins to create optimal campaign architecture.","zh":"营销活动结构是指使用AIエージェント创建和管理营销活动的框架","ja":"キャンペーン構造とは、AIエージェントを使用してキャンペーンを作成および管理するためのフレームワークです","ko":"캠페인 구조는 AI 에이전트를 사용하여 캠페인을 생성하고 관리하는 프레임워크입니다","es":"La estructura de campaña es el diseño y la configuración de la arquitectura de una campaña publicitaria para pruebas y escalado","fr":"La structure de campagne est la conception et la configuration de l''architecture d''une campagne publicitaire pour les tests et la mise à l''échelle","de":"Die Kampagnenstruktur ist die Gestaltung und Konfiguration der Architektur einer Werbekampagne für Tests und Skalierung","pt":"Estrutura de campanha é um conceito que se refere à organização e planejamento de uma campanha publicitária para atingir objetivos específicos","ru":"Структура кампании - это концепция, которая относится к организации и планированию рекламной кампании для достижения конкретных целей","ar":"هيكل الحملة هو مفهوم يرتبط بتنظيم وتخطيط حملة إعلانية لتحقيق أهداف محددة"},"features":{"en":["Assesses offer types, including VSL/long-form funnel and lead gen/simple funnel","Allocates daily testing budgets and sets target CPA/CPL","Determines acceptable loss thresholds and timelines to profitability","Supports testing and scaling of media buying operations","Provides 16 professionally configured plugins for campaign structure design","Enables choice of optimal campaign architecture for specific offers and budgets"],"zh":["Offer Type Assessment：VSL/长形式漏斗和Lead Gen/简单漏斗","Budget Allocation：每日测试预算、目标CPA/CPL和可接受的损失阈值","Timeline to Profitability：实现盈利的时间线","16个专业配置的插件"],"ja":["Offer Type Assessment：VSL/ロングフォームファネルとリードジェン/シンプルファネル","Budget Allocation：毎日のテスト予算、ターゲットCPA/CPLと許容損失閾値","Timeline to Profitability：利益を実現するためのタイムライン","16個のプロフェッショナルに構成されたプラグイン"],"ko":["Offer Type Assessment：VSL/긴 형식漏斗와 리드젠/단순漏斗","Budget Allocation：일일 테스트 예산, 목표 CPA/CPL 및 허용 가능한 손실 임계값","Timeline to Profitability：이익을 실현하는 데 걸리는 시간","16개의 전문적으로 구성된 플러그인"],"es":["Diseño de arquitectura de campaña óptima","Configuración de plugins profesionales para operaciones de compra de medios","Asignación de presupuesto y establecimiento de umbrales de pérdida","Análisis de tipo de oferta y asignación de presupuesto","Creación de un plan de escalado para campañas exitosas"],"fr":["Conception d''une architecture de campagne optimale","Configuration de plugins professionnels pour les opérations d''achat de médias","Allocation de budget et fixation de seuils de perte","Analyse du type d''offre et allocation de budget","Création d''un plan de mise à l''échelle pour les campagnes réussies"],"de":["Gestaltung einer optimalen Kampagnenarchitektur","Konfiguration von professionellen Plugins für Medienkaufoperationen","Budgetzuweisung und Festlegung von Verlustschwellen","Analyse des AngebotsTyps und Budgetzuweisung","Erstellung eines Skalierungsplans für erfolgreiche Kampagnen"],"pt":["Avaliação do tipo de oferta para determinar a abordagem de teste","Alocação de orçamento para testes diários e definição de metas de CPA/CPL","Definição de limiar de perda aceitável e cronograma para rentabilidade","Escolha da estrutura de campanha com base na oferta e orçamento","Otimização da arquitetura de campanha para testes e escalabilidade","Integração com 16 plugins profissionalmente configurados para operações de compra de mídia"],"ru":["Оценка типа предложения для определения подхода к тестированию","Распределение бюджета для ежедневных тестов и определение целевых показателей CPA/CPL","Определение приемлемого порога потерь и графика для прибыльности","Выбор структуры кампании на основе предложения и бюджета","Оптимизация структуры кампании для тестирования и масштабирования","Интеграция с 16 профессионально настроенными плагинами для операций по покупке медиа"],"ar":["تقييم نوع العرض لتحديد مدى الاختبار","تخصيص الميزانية للاختبارات اليومية وتحديد أهداف CPA/CPL","تحديد عتبة الخسارة المقبولة وجدول زمني للربحية","اختيار هيكل الحملة بناءً على العرض والميزانية","تحسين هيكل الحملة للاختبار والتوسع","التكامل مع 16 مكونًا إضافيًا معدًا بشكل احترافي لعمليات شراء الوسائط"]},"keywords":{"en":["how to use campaign-structure","what is campaign-structure","campaign-structure alternative","campaign-structure vs competitor","campaign-structure install","campaign-structure setup guide","media buying operations optimization","campaign architecture design","offer type assessment","budget allocation strategies"],"zh":["AIエージェント营销","营销活动结构","Offer Type Assessment","Budget Allocation","Timeline to Profitability","营销活动设计","AI营销工具"],"ja":["AIエージェントによるマーケティング","キャンペーン構造","オファータイプアセスメント","バジェットアロケーション","タイムライントゥプロフィタビリティ","キャンペーン設計","AIマーケティングツール"],"ko":["AI 에이전트 마케팅","캠페인 구조","오퍼 타입 평가","예산 할당","수익성 타임라인","캠페인 설계","AI 마케팅 도구"],"es":["estructura de campaña","diseño de campaña","operaciones de compra de medios","plugins de Claude Code","asignación de presupuesto","análisis de tipo de oferta","escalado de campañas","AI Agent para marketing"],"fr":["structure de campagne","conception de campagne","opérations d''achat de médias","plugins Claude Code","allocation de budget","analyse du type d''offre","mise à l''échelle de campagnes","Outil IA pour marketing"],"de":["Kampagnenstruktur","Kampagnengestaltung","Medienkaufoperationen","Claude-Code-Plugins","Budgetzuweisung","AngebotsTyp-Analyse","Skalierung von Kampagnen","KI-Tool für Marketing"],"pt":["estrutura de campanha","plugin de estrutura de campanha","testes de campanha","escalabilidade de campanha","compra de mídia","orçamento de campanha","CPA/CPL","rentabilidade de campanha","ferramentas de IA para marketing"],"ru":["структура кампании","плагин структуры кампании","тестирование кампании","масштабирование кампании","покупка медиа","бюджет кампании","CPA/CPL","прибыльность кампании","инструменты ИИ для маркетинга"],"ar":["هيكل الحملة","مكون إضافي للهيكل الحملي","اختبارات الحملة","توسع الحملة","شراء الوسائط","ميزانية الحملة","CPA/CPL","ربحية الحملة","أدوات الذكاء الاصطناعي للتسويق"]}},"owner":"WalkerHi11","repo":"mediabuy-plugins","repoPath":"WalkerHi11/mediabuy-plugins","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.314Z","topics":[],"category":"community","skillMd":{"name":"campaign-structure","description":"Design optimal Facebook/Meta campaign structure for testing including ABO vs CBO, ad set organization, targeting, and budget allocation. Use when setting up new campaigns, planning test structure, or optimizing account architecture.","bodyPreview":"# Campaign Structure Designer\r\n\r\nCreate optimal campaign architecture for testing and scaling.\r\n\r\n## Process\r\n\r\n### Step 1: Assess Offer and Budget\r\n\r\n**Offer Type Assessment**\r\n- VSL/long-form funnel → More controlled testing\r\n- Lead gen/simple funnel → Can be more aggressive\r\n- New offer → Need more testing budget\r\n- Proven offer → Can scale faster\r\n\r\n**Budget Allocation**\r\n- Daily testing budget\r\n- Target CPA/CPL\r\n- Acceptable loss threshold\r\n- Timeline to profitability\r\n\r\n### Step 2: Choose","body":"# Campaign Structure Designer\r\n\r\nCreate optimal campaign architecture for testing and scaling.\r\n\r\n## Process\r\n\r\n### Step 1: Assess Offer and Budget\r\n\r\n**Offer Type Assessment**\r\n- VSL/long-form funnel → More controlled testing\r\n- Lead gen/simple funnel → Can be more aggressive\r\n- New offer → Need more testing budget\r\n- Proven offer → Can scale faster\r\n\r\n**Budget Allocation**\r\n- Daily testing budget\r\n- Target CPA/CPL\r\n- Acceptable loss threshold\r\n- Timeline to profitability\r\n\r\n### Step 2: Choose Structure Type\r\n\r\n**ABO Testing Structure (Recommended for Testing)**\r\nUse when: Finding initial winners, testing new angles\r\n\r\n```\r\nCampaign: [Offer] Testing\r\n├── Ad Set 1: [Concept A] - $X/day\r\n│   ├── Ad 1: Hook variation 1\r\n│   ├── Ad 2: Hook variation 2\r\n│   └── Ad 3: Hook variation 3\r\n├── Ad Set 2: [Concept B] - $X/day\r\n│   ├── Ad 1...\r\n...\r\n```\r\n\r\n**CBO Scaling Structure**\r\nUse when: Scaling proven winners\r\n\r\n```\r\nCampaign: [Offer] Scale - $X/day CBO\r\n├── Ad Set 1: Winners Only\r\n│   ├── Winner Ad 1\r\n│   ├── Winner Ad 2\r\n│   └── Winner Ad 3\r\n```\r\n\r\n**2x2x3 Testing Method (Jason K)**\r\n- 2 Headlines\r\n- 2 Ad texts\r\n- 3 Images/faces\r\n= 12 ad variations testing copy combinations\r\n\r\n**Double Six Shooter (Jason K)**\r\n- 10-12 ad sets (different avatars)\r\n- Same 10-12 images per ad set\r\n- Large CBO with minimum spend per ad set\r\n- Let Facebook find winning avatar + image combos\r\n\r\n### Step 3: Set Targeting Parameters\r\n\r\n**Testing Phase**\r\n- 2% Lookalike audiences (Jason K recommends)\r\n- Mobile newsfeed only\r\n- WiFi only (for VSL)\r\n\r\n**Scaling Phase**\r\n- 10% Lookalike (Jason K)\r\n- All placements\r\n- Broader audiences\r\n\r\n**Audience Sources**\r\n- Purchase lookalikes\r\n- Add to cart lookalikes\r\n- Email list lookalikes\r\n- Page engagers (for exclusions)\r\n\r\n### Step 4: Define Budget Rules\r\n\r\n**Testing Budget**\r\n- Spend 1.5-2x target CPL before calling winner (Casto)\r\n- Use initiate checkout as leading indicator (3x purchase data)\r\n- Kill at threshold, don''t hold hoping\r\n\r\n**Winner Criteria (Jason K)**\r\n- Doesn''t lose more than once in 3 days\r\n- Doesn''t lose more than twice in 7 days\r\n- Consistent performance, not just spikes\r\n\r\n**Scaling Budget**\r\n- 20% increases (safe)\r\n- Can jump when hot, but risk breaking\r\n- Spread across multiple ad accounts\r\n\r\n### Step 5: Output Campaign Blueprint\r\n\r\n```\r\n## CAMPAIGN STRUCTURE: [Offer Name]\r\n\r\n### PHASE 1: INITIAL TESTING\r\n\r\n**Campaign: [Offer] - ABO Test**\r\n- Objective: Conversions\r\n- Budget: $[X]/day per ad set\r\n- Duration: [X] days minimum\r\n\r\n**Ad Set Structure:**\r\n| Ad Set | Concept | Targeting | Budget |\r\n|--------|---------|-----------|--------|\r\n| 1 | [Concept A] | 2% LAL | $X |\r\n| 2 | [Concept B] | 2% LAL | $X |\r\n| 3 | [Concept C] | 2% LAL | $X |\r\n\r\n**Per Ad Set:**\r\n- 5-10 ads per concept\r\n- Mix of hooks/variations\r\n- Mobile newsfeed only\r\n\r\n**Kill Criteria:**\r\n- CPL > [X] after $[spend]\r\n- CPA > [X] after [conversions]\r\n\r\n**Winner Criteria:**\r\n- CPL < [target]\r\n- Consistent 3+ days\r\n- Scalable volume\r\n\r\n---\r\n\r\n### PHASE 2: WINNER VALIDATION\r\n\r\n**Campaign: [Offer] - CBO Scale**\r\n- Budget: $[X]/day CBO\r\n- Winners only (3-5 ads)\r\n- Scale in place initially\r\n\r\n**Expansion:**\r\n- Replicate to Ad Account 2\r\n- Replicate to Ad Account 3\r\n- De-risk across accounts\r\n\r\n---\r\n\r\n### PHASE 3: FULL SCALE\r\n\r\n**Structure:**\r\n- Multiple CBOs across accounts\r\n- $10K max per CBO (avoid instability)\r\n- Weekend campaigns (separate)\r\n- Day-parting: 4AM-1PM Eastern (VSL)\r\n\r\n**Targeting Expansion:**\r\n- Move to 10% LAL\r\n- Test broad\r\n- All placements\r\n\r\n---\r\n\r\n### CREATIVE TESTING CADENCE\r\n\r\n**Weekly:**\r\n- 50-100 new creative variations\r\n- New hooks on proven angles\r\n- New angles on proven offers\r\n\r\n**Monthly:**\r\n- New concept batches\r\n- Founder content refresh\r\n- Seasonal angles\r\n\r\n### TRACKING SETUP\r\n- UTM structure: [Define]\r\n- Conversion events: [List]\r\n- Attribution window: [Setting]\r\n```\r\n\r\n## Key Principles\r\n\r\n**From Casto:**\r\n- Broad targeting, let creative do targeting\r\n- Use bid caps/cost caps when margins thin\r\n- Spread across multiple ad accounts\r\n- Build internal tools for launch automation\r\n\r\n**From Jason K:**\r\n- 2% LAL for testing, 10% for scaling\r\n- Watch initiate checkouts (3x data)\r\n- Day-part for VSL (turn off afternoon)\r\n- Weekend campaigns with higher budgets\r\n- Large CBO of winners is end goal\r\n\r\nSource: Jason K, Casto (Meta-CastovsJasonK)\r\n"},"lastSynced":"2026-03-08T02:02:41.677Z","agentAnalysis":{"suitability":{"en":"Essential for Media Buying Automation Agents that optimize digital advertising campaign architecture and budget allocation.","zh":"适用于自动化媒体购买代理，优化数字广告活动架构和预算分配。","ja":"メディア買入の自動化エージェントに不可欠で、デジタル広告キャンペーンのアーキテクチャと予算割り当てを最適化します。","ko":"미디어 구매 자동화 에이전트에 필수적이며 디지털 광고 캠페인 아키텍처 및 예산 할당을 최적화합니다.","es":"Esencial para los agentes de automatización de compras de medios que optimizan la arquitectura de las campañas publicitarias digitales y la asignación de presupuesto.","fr":"Essentiel pour les agents d''automatisation des achats de médias qui optimisent l''architecture des campagnes publicitaires numériques et l''allocation de budget.","de":"Wesentlich für Media Buying Automation Agents, die die Architektur von digitalen Werbekampagnen und die Budgetzuweisung optimieren.","pt":"Essencial para Agentes de Automação de Compras de Mídia que otimizam a arquitetura de campanhas publicitárias digitais e alocação de orçamento.","ru":"Необходимо для агентов автоматизации медиа-покупок, которые оптимизируют архитектуру цифровых рекламных кампаний и распределение бюджета.","ar":"ضروري لعمليات تنفيذ تلقائي لشراء الإعلام التي تحسن هيكل حملة الإعلان الرقمي وتخصيص الميزانية."},"recommendation":{"en":"Enables automated assessment of VSL/long-form vs lead gen funnels for optimal testing strategies. Provides budget allocation frameworks based on daily testing budgets, target CPA/CPL metrics, and acceptable loss thresholds for scaling operations.","zh":"实现自动评估VSL/长篇与潜在客户生成漏斗的最佳测试策略。提供基于每日测试预算、目标CPA/CPL指标和可接受的损失阈值的预算分配框架，以实现规模化运营。","ja":"VSL/ロングフォームとリードジェネレーション漏斗の最適なテスト戦略の自動評価を可能にします。毎日のテスト予算、目標CPA/CPLメトリクス、スケーリング操作の可容許損失閾値に基づく予算割り当てフレームワークを提供します。","ko":"VSL/장형 및 리드 생성漏斗의 최적 테스트 전략에 대한 자동 평가를 가능하게 합니다. 일일 테스트 예산, 목표 CPA/CPL 메트릭 및 확장 운영을 위한 허용 가능한 손실 임계값에 기반한 예산 할당 프레임워크를 제공합니다.","es":"Permite la evaluación automatizada de VSL/larga forma frente a embudos de generación de leads para estrategias de prueba óptimas. Proporciona marcos de asignación de presupuesto basados en presupuestos de prueba diarios, métricas de CPA/CPL de destino y umbrales de pérdida aceptables para operaciones de escalado.","fr":"Permet l''évaluation automatique de VSL/longue forme par rapport aux embouts de génération de leads pour des stratégies de test optimales. Fournit des cadres d''allocation de budget basés sur les budgets de test quotidiens, les métriques cible CPA/CPL et les seuils de perte acceptables pour les opérations d''extension.","de":"Ermöglicht die automatisierte Bewertung von VSL/langer Form im Vergleich zu Lead-Generierungs-Tunnels für optimale Teststrategien. Bietet Budgetzuweisungsframeworks auf der Grundlage von täglichen Testbudgets, Ziel-CPA/CPL-Metriken und akzeptablen Verlustschwellen für die Skalierung von Betrieben.","pt":"Permite avaliação automatizada de VSL/formulário longo versus funis de geração de leads para estratégias de teste ótimas. Fornece estruturas de alocação de orçamento com base em orçamentos de teste diários, métricas de CPA/CPL de destino e limites de perda aceitáveis para operações de escalonamento.","ru":"Позволяет автоматизировать оценку VSL/длинной формы против воронок генерации лидов для оптимальных стратегий тестирования. Предоставляет структуры распределения бюджета на основе ежедневных бюджетов тестирования, целевых метрик CPA/CPL и приемлемых порогов потерь для масштабирования операций.","ar":"تمكن التقييم التلقائي لـ VSL/النموذج الطويل مقابل قناة توليد الرسائل لاستراتيجيات الاختبار المثلى. توفر إطارات تخصيص الميزانية dựa على ميزانيات الاختبار اليومية، معايير CPA/CPL المستهدفة، وأحكام الفاقد المقبولة لعمليات التوسع."},"useCases":{"en":["Automating campaign architecture design for new offer testing","Optimizing budget allocation based on proven offer performance","Calculating acceptable loss thresholds for scaling timelines","Assessing funnel types for controlled vs aggressive testing approaches"],"zh":["自动化新的优惠测试活动架构设计","根据已验证的优惠性能优化预算分配","计算扩展时间表的可接受损失阈值","评估漏斗类型以进行受控与激进的测试方法"],"ja":["新しいオファーのテスト活動アーキテクチャ設計の自動化","検証されたオファーのパフォーマンスに基づく予算割り当ての最適化","拡張タイムラインの可容許損失閾値の計算","コントロールされたテストアプローチと積極的なテストアプローチのためのファネルタイプの評価"],"ko":["新的 제안 테스트 활동 아키텍처 디자인 자동화","검증된 제안 성능에 기반한 예산 할당 최적화","확장 시간표의 허용 가능한 손실 임계값 계산","제어된 테스트 접근 방식 및 공격적인 테스트 접근 방식에 대한漏斗 유형 평가"],"es":["Automatización del diseño de la arquitectura de la campaña para pruebas de nuevas ofertas","Optimización de la asignación de presupuesto en función del rendimiento de las ofertas probadas","Cálculo de los umbrales de pérdida aceptables para los plazos de escalado","Evaluación de los tipos de embudos para enfoques de prueba controlados frente a agresivos"],"fr":["Automatisation de la conception de l''architecture de la campagne pour les tests de nouvelles offres","Optimisation de l''allocation de budget en fonction des performances des offres éprouvées","Calcul des seuils de perte acceptables pour les délais d''extension","Évaluation des types d''embouts pour les approches de test contrôlées par rapport aux approches agressives"],"de":["Automatisierung des Designs der Kampagnenarchitektur für die Erprobung neuer Angebote","Optimierung der Budgetzuweisung basierend auf den Leistungen der getesteten Angebote","Berechnung der akzeptablen Verlustschwellen für die Skalierungszeiträume","Bewertung der Tunneltypen für kontrollierte versus aggressive Testansätze"],"pt":["Automatizar projeto de arquitetura de campanha para novos testes de ofertas","Otimizar alocação de orçamento com base no desempenho comprovado da oferta","Calcular limites de perda aceitáveis para cronogramas de escalonamento","Avaliar tipos de funis para abordagens de teste controlado versus agressivo"],"ru":["Автоматизировать проектирование архитектуры кампании для новых тестирований предложений","Оптимизировать распределение бюджета на основе проверенной производительности предложения","Рассчитывать приемлемые пороги потерь для графиков масштабирования","Оценивать типы воронок для контролируемых против агрессивных подходов к тестированию"],"ar":["توفير تصميم هيكل الحملة التلقائي لاختبار العروض الجديدة","تحسين تخصيص الميزانية بناءً على أداء العرض المثبت","حساب أحكام الفاقد المقبولة لمخططات التوسع","تقييم أنواع القنوات لمناهج اختبار مراقبة مقابل 접근ات عدوانية"]},"limitations":{"en":["Requires predefined budget and CPA/CPL parameters","Limited to digital media buying campaign structures","Needs offer type classification input for optimal performance"],"zh":["需要预定义的预算和CPA/CPL参数","仅限于数字媒体购买活动结构","需要优惠类型分类输入以实现最佳性能"],"ja":["予め定義された予算とCPA/CPLパラメータが必要","デジタルメディア買入キャンペーン構造に限定","最適なパフォーマンスを実現するためにオファーの種類分類入力が必要"],"ko":["사전에 정의된 예산 및 CPA/CPL 매개 변수가 필요","디지털 미디어 구매 캠페인 구조에만 제한","최적의 성능을 달성하기 위해 제안 유형 분류 입력이 필요"],"es":["Requiere parámetros de presupuesto y CPA/CPL predefinidos","Limitado a estructuras de campañas de compras de medios digitales","Necesita la clasificación de tipo de oferta como entrada para un rendimiento óptimo"],"fr":["Nécessite des paramètres de budget et de CPA/CPL prédéfinis","Limité aux structures de campagnes d''achats de médias numériques","Nécessite la classification du type d''offre comme entrée pour une performance optimale"],"de":["Benötigt vordefinierte Budget- und CPA/CPL-Parameter","Begrenzt auf digitale Medienkaufkampagnenstrukturen","Benötigt die Eingabe der Angebotsklassifizierung für eine optimale Leistung"],"pt":["Exige parâmetros de orçamento e CPA/CPL predefinidos","Limitado a estruturas de campanha de compra de mídia digital","Necessita de entrada de classificação de tipo de oferta para desempenho ótimo"],"ru":["Требует предварительно определенных параметров бюджета и CPA/CPL","Ограничен структурами цифровых медиа-покупок","Требует ввода классификации типа предложения для оптимальной производительности"],"ar":["يتطلب معايير ميزانية و CPA/CPL معينة مسبقًا","محدود بهياكل حملة شراء الإعلام الرقمي","يحتاج إلى إدخال تصنيف نوع العرض لأداء مثالي"]},"version":4},"contentHash":"84b19708afaee08b8f818efd0fcfe4cf225a8613e5a37e965d9dd557d5d0c5a5","qualityScore":36}');
