INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('WalkerHi11/mediabuy-plugins/campaign-structure', 'campaign-structure', 'WalkerHi11', 'mediabuy-plugins', 'community', 'campaign-structure WalkerHi11 mediabuy-plugins community The campaign-structure skill helps developers create optimal campaign architecture for testing and scaling media buying operations. It assists in assessing offers and allocating budgets. 创建最佳营销活动结构，包括Offer Type Assessment和Budget Allocation，以实现测试和扩展的最佳效果 キャンペーン構造を設計して、テストとスケーリングの最適なアーキテクチャを実現します 캠페인 구조를 설계하여 테스트와 확장의 최적의 아키텍처를 구축하세요 La estructura de campaña es crucial para el éxito de las operaciones de compra de medios. Nuestro plugin de Claude Code ofrece 16 plugins profesionales configurados para ayudar a los desarrolladores a crear campañas óptimas. La structure de campagne est essentielle pour le succès des opérations d''achat de médias. Notre plugin Claude Code propose 16 plugins professionnels configurés pour aider les développeurs à créer des campagnes optimales. Die Kampagnenstruktur ist entscheidend für den Erfolg von Medienkaufoperationen. Unser Claude-Code-Plugin bietet 16 professionell konfigurierte Plugins, um Entwicklern bei der Erstellung optimaler Kampagnen zu helfen. O plugin de estrutura de campanha permite criar uma arquitetura de campanha otimizada para testes e escalabilidade. Ele oferece 16 plugins profissionalmente configurados para operações de compra de mídia. Плагин структуры кампании позволяет создать оптимальную структуру кампании для тестирования и масштабирования. Он предлагает 16 профессионально настроенных плагинов для операций по покупке медиа. مكون الإضافي للهيكل الحملي يسمح بإنشاء هيكل حملة محسّن للاختبار والتوسع. وهو يقدم 16 مكونًا إضافيًا معدًا بشكل احترافي لعمليات شراء الوسائط. how to use campaign-structure what is campaign-structure campaign-structure alternative campaign-structure vs competitor campaign-structure install campaign-structure setup guide media buying operations optimization campaign architecture design offer type assessment budget allocation strategies AIエージェント营销 营销活动结构 Offer Type Assessment Budget Allocation Timeline to Profitability 营销活动设计 AI营销工具 Assesses offer types, including VSL/long-form funnel and lead gen/simple funnel Allocates daily testing budgets and sets target CPA/CPL Determines acceptable loss thresholds and timelines to profitability Supports testing and scaling of media buying operations Provides 16 professionally configured plugins for campaign structure design Enables choice of optimal campaign architecture for specific offers and budgets Campaign-structure is a plugin marketplace for media buying operations that provides 16 professionally configured plugins to create optimal campaign architecture.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('dudusoar/VRP-Toolkit/manage-skills', 'community', 'dudusoar', 'VRP-Toolkit', 'dudusoar/VRP-Toolkit', 'manage-skills', 0, 0, 36, '2026-03-08T01:57:15.315Z', '2026-03-08T02:02:46.185Z', 'c10213b298f7e99f4b53c994a87d6a03113ed1d5cb9757e540ed6257ca9d4068', '{"id":"dudusoar/VRP-Toolkit/manage-skills","name":"manage-skills","description":{"en":"The manage-skills AI agent skill is designed for managing, auditing, and maintaining all VRP Toolkit skills, benefiting developers and users alike. It provides core functions for skill directory comparison and compliance validation.","zh":"Manage Skills是用于管理和维护VRP Toolkit技能的元技能，提供审计和合规检查功能","ja":"Manage SkillsはVRP Toolkitのスキルを管理およびメンテナンスするメタスキルです","ko":"Manage Skills는 VRP Toolkit 스킬을 관리 및 유지보수하는 메타 스킬입니다","es":"manage-skills es una habilidad para auditar y mantener habilidades en tu toolkit de realidad virtual con Python y CLI.","fr":"manage-skills est une compétence pour auditer et maintenir des compétences dans votre toolkit de réalité virtuelle avec Python et CLI.","de":"manage-skills ist eine Fähigkeit, um Fähigkeiten in Ihrem VR-Toolkit mit Python und CLI zu überprüfen und zu warten.","pt":"O manage-skills é uma habilidade de meta que gerencia e audita habilidades de IA. Ele compara habilidades reais com documentação e valida contra padrões do VRP Toolkit.","ru":"Manage-skills - это meta-навык для управления и аудита ИИ Агентов. Он сравнивает фактические habilidades с документацией и проверяет против стандартов VRP Toolkit.","ar":"manage-skills هي مهارة ميتا لإدارة المهارات للأدوات الذكية. تقارن المهارات الفعلية بالوثائق ووتحقق ضد معايير VRP Toolkit."},"seo":{"title":{"en":"Manage-Skills: Meta-Skill Management Setup Guide | AI Age...","zh":"AIエージェント管理技能设置指南","ja":"AIエージェントのスキル管理ベストプラクティス","ko":"AI 에이전트 스킬 관리 설정 가이드","es":"Guía de Configuración de manage-skills para Agents de IA","fr":"Guide d''Installation de manage-skills pour les Outils d''IA","de":"Einrichtungsleitfaden für manage-skills in KI-Tools","pt":"Guia de Configuração do Gerenciamento de Habilidades de IA","ru":"Настройка ИИ Агентов с помощью manage-skills","ar":"دليل إعداد إدارة المهارات للأدوات الذكية"},"description":{"en":"Discover how to efficiently manage VRP Toolkit skills with the manage-skills AI agent skill. Learn to audit, validate, and maintain skills with ease. Get sta...","zh":"管理和维护VRP Toolkit技能的元技能，包括审计和合规检查","ja":"VRP Toolkitのスキルを管理およびメンテナンスするメタスキル","ko":"VRP Toolkit 스킬을 관리 및 유지보수하는 메타 스킬","es":"Aprende a configurar manage-skills para auditar y mantener habilidades en tu toolkit de realidad virtual con Python y CLI","fr":"Découvrez comment installer manage-skills pour auditer et maintenir des compétences dans votre toolkit de réalité virtuelle avec Python et CLI","de":"Erfahren Sie, wie Sie manage-skills einrichten, um Fähigkeiten in Ihrem VR-Toolkit mit Python und CLI zu überprüfen und zu warten","pt":"Aprenda a gerenciar e auditar habilidades de IA com o manage-skills. Descubra como validar habilidades contra padrões do VRP Toolkit.","ru":"Узнайте, как управлять и аудировать ИИ Агенты с помощью manage-skills. Проверьте habilidades против стандартов VRP Toolkit.","ar":"تعلم إدارة المهارات للأدوات الذكية مع manage-skills. اكتشف كيفية التحقق من المهارات ضد معايير VRP Toolkit."},"definition":{"en":"manage-skills is a meta-skill for managing and auditing VRP Toolkit skills, ensuring directory comparison and compliance validation.","zh":"Manage Skills是用于管理和维护VRP Toolkit技能的元技能","ja":"Manage SkillsはVRP Toolkitのスキルを管理するメタスキル","ko":"Manage Skills는 VRP Toolkit 스킬을 관리하는 메타 스킬","es":"manage-skills es una meta-habilidad para gestionar y auditar habilidades en un toolkit de realidad virtual","fr":"manage-skills est une méta-compétence pour gérer et auditer des compétences dans un toolkit de réalité virtuelle","de":"manage-skills ist eine Meta-Fähigkeit, um Fähigkeiten in einem VR-Toolkit zu verwalten und zu überprüfen","pt":"O que é manage-skills? É uma habilidade de meta para gerenciar e auditar habilidades de IA no VRP Toolkit.","ru":"Что такое manage-skills? Это meta-навык для управления и аудита ИИ Агентов в VRP Toolkit.","ar":"ما هي manage-skills؟ هي مهارة ميتا لإدارة المهارات للأدوات الذكية في VRP Toolkit."},"features":{"en":["Audits skills directory using `.claude/skills/` and SKILLS.md documentation","Validates skills against VRP Toolkit standards","Generates reports on skills in directory vs SKILLS.md","Identifies missing skills from documentation and directory","Executes sync status checks using `audit_skills.py` script"],"zh":["审计技能目录","检查技能合规性","使用Python脚本进行审计","生成技能报告","支持VRP Toolkit标准"],"ja":["スキルディレクトリの監査","スキルコンプライアンスの確認","Pythonスクリプトを使用した監査","スキルレポートの生成","VRP Toolkit標準のサポート"],"ko":["스킬 디렉토리 감사","스킬 컴플라이언스 확인","Python 스크립트를 사용한 감사","스킬 보고서 생성","VRP Toolkit 표준 지원"],"es":["Auditoría de habilidades con Python","Comparación de habilidades en el directorio y la documentación","Validación de habilidades contra estándares de toolkit de realidad virtual","Informes de habilidades faltantes y estado de sincronización","Uso de CLI para ejecutar scripts de auditoría"],"fr":["Audit de compétences avec Python","Comparaison de compétences dans le répertoire et la documentation","Validation de compétences contre les normes de toolkit de réalité virtuelle","Rapports de compétences manquantes et état de synchronisation","Utilisation de CLI pour exécuter des scripts d''audit"],"de":["Überprüfung von Fähigkeiten mit Python","Vergleich von Fähigkeiten im Verzeichnis und der Dokumentation","Validierung von Fähigkeiten gegen Standards von VR-Toolkits","Berichte über fehlende Fähigkeiten und Synchronisierungsstatus","Verwendung von CLI zur Ausführung von Audit-Skripten"],"pt":["Comparação de habilidades reais com documentação","Validação de habilidades contra padrões do VRP Toolkit","Relatórios de habilidades faltantes ou desatualizadas","Uso de scripts Python para auditoria","Integração com o diretório de habilidades do VRP Toolkit"],"ru":["Сравнение фактических habilidades с документацией","Проверка habilidades против стандартов VRP Toolkit","Отчеты о habilidades отсутствующих или устаревших","Использование скриптов Python для аудита","Интеграция с директорием habilidades VRP Toolkit"],"ar":["مقارنة المهارات الفعلية بالوثائق","التحقق من المهارات ضد معايير VRP Toolkit","تقارير المهارات الناقصة أو المتأخرة","استخدام البرامج النصية Python للتحقق","التكامل مع دليل المهارات من VRP Toolkit"]},"keywords":{"en":["how to use manage-skills","manage-skills alternative","manage-skills setup guide","what is manage-skills","manage-skills vs VRP Toolkit","manage-skills install","VRP Toolkit skill management","audit skills directory","skill compliance validation"],"zh":["AIエージェント","技能管理","VRP Toolkit","Python脚本","审计技能","合规检查","技能报告","元技能"],"ja":["AIエージェント","スキル管理","VRP Toolkit","Pythonスクリプト","スキル監査","コンプライアンス確認","スキルレポート","メタスキル"],"ko":["AI 에이전트","스킬 관리","VRP Toolkit","Python 스크립트","스킬 감사","컴플라이언스 확인","스킬 보고서","메타 스킬"],"es":["manage-skills","Agents de IA","Herramientas de IA","Toolkit de realidad virtual","Auditoría de habilidades","Python","CLI","Desarrollo de realidad virtual"],"fr":["manage-skills","Outils d''IA","Agents d''IA","Toolkit de réalité virtuelle","Audit de compétences","Python","CLI","Développement de réalité virtuelle"],"de":["manage-skills","KI-Tools","KI-Agents","VR-Toolkit","Überprüfung von Fähigkeiten","Python","CLI","Entwicklung von VR-Anwendungen"],"pt":["gerenciamento de habilidades de IA","auditória de habilidades","validação de habilidades","VRP Toolkit","Python","scripts de auditoria","diretório de habilidades","documentação de habilidades"],"ru":["управление ИИ Агентами","аудит ИИ Агентов","проверка ИИ Агентов","VRP Toolkit","Python","скрипты аудита","директория ИИ Агентов","документация ИИ Агентов"],"ar":["إدارة المهارات للأدوات الذكية","التحقق من المهارات","التحقق من المهارات","VRP Toolkit","Python","برامج التحقق","دليل المهارات","وثائق المهارات"]}},"owner":"dudusoar","repo":"VRP-Toolkit","repoPath":"dudusoar/VRP-Toolkit","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.315Z","topics":[],"category":"community","skillMd":{"name":"manage-skills","description":"Manage and maintain VRP Toolkit skills through compliance checking, audit tracking, and documentation synchronization. Use when (1) adding or modifying skills, (2) checking skill compliance with project standards, (3) auditing SKILLS.md vs skills directory consistency, (4) recording skill changes to SKILLS_LOG.md, or (5) performing periodic skill health checks. Ensures skills stay independent, under 500 lines, properly structured, and well-documented.","bodyPreview":"# Manage Skills\n\nMeta-skill for managing, auditing, and maintaining all VRP Toolkit skills.\n\n## Core Functions\n\n### 1. Audit Skills Directory\nCompare actual skills in `.claude/skills/` with SKILLS.md documentation.\n\n**Usage:**\n```bash\npython .claude/skills/manage-skills/scripts/audit_skills.py\n```\n\n**Reports:**\n- Skills in directory vs SKILLS.md\n- Missing from documentation\n- Missing from directory\n- Sync status\n\n### 2. Check Skill Compliance\nValidate skills against VRP Toolkit standards.\n\n**Usa","body":"# Manage Skills\n\nMeta-skill for managing, auditing, and maintaining all VRP Toolkit skills.\n\n## Core Functions\n\n### 1. Audit Skills Directory\nCompare actual skills in `.claude/skills/` with SKILLS.md documentation.\n\n**Usage:**\n```bash\npython .claude/skills/manage-skills/scripts/audit_skills.py\n```\n\n**Reports:**\n- Skills in directory vs SKILLS.md\n- Missing from documentation\n- Missing from directory\n- Sync status\n\n### 2. Check Skill Compliance\nValidate skills against VRP Toolkit standards.\n\n**Usage:**\n```bash\n# Check specific skill\npython .claude/skills/manage-skills/scripts/check_compliance.py skill-name\n\n# Check all skills\npython .claude/skills/manage-skills/scripts/check_compliance.py --all\n```\n\n**Checks:**\n- **Independence**: Skill doesn''t embed other skills'' content\n- **Size**: SKILL.md ≤ 500 lines (body, excluding frontmatter)\n- **Structure**: Required files present, no prohibited files\n- **Frontmatter**: Valid YAML with name and description\n- **References**: All reference files mentioned in SKILL.md\n\nSee [compliance_checklist.md](references/compliance_checklist.md) for detailed standards.\n\n### 3. Update SKILLS.md Index\nSync skills documentation in SKILLS.md with actual skills.\n\n**When:**\n- After adding new skill\n- After removing skill\n- After significantly modifying skill description\n\n**See:** [update_procedures.md](references/update_procedures.md) → Section 1\n\n### 4. Record Changes in SKILLS_LOG.md\nLog all skill modifications for tracking and history.\n\n**When:**\n- After any skill change (add/update/remove/rename/split/merge)\n\n**Template:**\n```markdown\n## YYYY-MM-DD - [Action]: [skill-name]\n**Action:** [Added/Updated/Removed/Renamed/Split/Merged]\n**Reason:** [Why this change was made]\n**Changes:**\n- [Specific change 1]\n- [Specific change 2]\n**Compliance Notes:** [Any compliance issues addressed]\n**Impact:** [How this affects other skills or workflows]\n```\n\n**See:** [update_procedures.md](references/update_procedures.md) → Section 2\n\n## Workflow Patterns\n\n### Pattern A: Add New Skill\n```\n1. Create skill using skill-creator\n2. Run: audit_skills.py\n   → Check if new skill appears in directory\n3. Update SKILLS.md skills index (Section 1)\n4. Record in SKILLS_LOG.md\n5. Run: check_compliance.py skill-name\n   → Verify new skill is compliant\n```\n\n### Pattern B: Modify Existing Skill\n```\n1. Make changes to skill\n2. Run: check_compliance.py skill-name\n   → Check for violations (size, independence, etc.)\n3. If issues found, fix them\n4. Update SKILLS.md description if needed\n5. Record changes in SKILLS_LOG.md\n```\n\n### Pattern C: Periodic Audit\n```\n1. Run: audit_skills.py\n   → Check directory vs SKILLS.md sync\n2. Run: check_compliance.py --all\n   → Check all skills for compliance\n3. Review warnings and errors\n4. Plan fixes or improvements\n5. Update SKILLS_LOG.md with findings\n```\n\n### Pattern D: Fix Compliance Issues\n\n**Size Violation (>500 lines):**\n```\n1. Identify extractable sections\n2. Move to references/ or create new skill\n3. Update SKILL.md references\n4. Re-run check_compliance.py\n5. Record in SKILLS_LOG.md\n```\n\n**Independence Violation:**\n```\n1. Find embedded content from other skills\n2. Replace with reference: \"See [skill-name] for...\"\n3. Re-run check_compliance.py\n4. Record in SKILLS_LOG.md\n```\n\nSee [update_procedures.md](references/update_procedures.md) for detailed procedures on:\n- Renaming skills\n- Splitting large skills\n- Merging similar skills\n- Archiving deprecated skills\n\n## Integration with Other Skills\n\n**Works with:**\n- **skill-creator** - Use to create new skills before managing them\n- **update-migration-log** - Similar logging pattern for migrations\n- **update-task-board** - Similar documentation sync pattern\n\n**DO NOT embed workflows from these skills** - Reference them instead.\n\n## Compliance Standards Quick Reference\n\n```yaml\nIndependence:\n  ✓ Can reference other skills: \"See [skill-name] for...\"\n  ✗ Cannot embed workflows from other skills\n\nSize:\n  ✓ SKILL.md ≤ 500 lines (excluding frontmatter)\n  ⚠ Warning at 400 lines\n  ✗ Error at 500 lines\n\nStructure:\n  ✓ Required: SKILL.md with valid frontmatter\n  ✓ Optional: scripts/, references/, assets/\n  ✗ Prohibited: README.md, CHANGELOG.md, etc.\n\nFrontmatter:\n  ✓ Required fields: name, description\n  ✓ Description: 50-200 words with use cases\n  ✗ Extra fields discouraged\n\nReferences:\n  ✓ All refs linked from SKILL.md\n  ✓ Max 1 level deep (no nested dirs)\n  ⚠ Warning if ref >500 lines\n```\n\nFull details: [compliance_checklist.md](references/compliance_checklist.md)\n\n## Files in This Skill\n\n```\nmanage-skills/\n├── SKILL.md                          # This file\n├── scripts/\n│   ├── audit_skills.py              # Directory vs CLAUDE.md audit\n│   └── check_compliance.py          # Compliance validation\n├── references/\n│   ├── compliance_checklist.md      # Detailed compliance standards\n│   └── update_procedures.md         # Step-by-step update procedures\n└── assets/\n    └── SKILLS_LOG_template.md       # Template for SKILLS_LOG.md\n```\n\n## Tips\n\n1. **Run audit after adding skills** - Catches missing documentation immediately\n2. **Check compliance before packaging** - Prevents distribution of non-compliant skills\n3. **Keep SKILLS_LOG.md updated** - Provides history for troubleshooting\n4. **Review warnings seriously** - They often indicate real issues\n5. **Split before 500 lines** - Easier to split at 400 than fix at 600\n\n## Limitations\n\n- Does not automatically fix compliance issues (manual fixes required)\n- Cannot detect semantic overlap between skills (manual review needed)\n- Windows encoding issues with emoji in scripts (uses ASCII fallback)\n"},"lastSynced":"2026-03-08T02:02:46.185Z","agentAnalysis":{"suitability":{"en":"Perfect for AI Agents needing advanced skill management and auditing capabilities, particularly those utilizing VRP Toolkit skills.","zh":"适合需要高级技能管理和审计能力的AI代理，特别是那些使用VRP Toolkit技能的代理。","ja":"高度なスキル管理および監査機能を必要とするAIエージェントに適しています。特に、VRP Toolkitスキルを使用するエージェントに適しています。","ko":"고급 스킬 관리 및 감사 기능이 필요한 AI 에이전트에게 적합합니다. 특히 VRP Toolkit 스킬을 사용하는 에이전트에게 적합합니다.","es":"Perfecto para agentes de IA que necesitan capacidades de administración y auditoría de habilidades avanzadas, particularmente aquellos que utilizan habilidades de VRP Toolkit.","fr":"Parfait pour les agents IA ayant besoin de capacités de gestion et d''audit de compétences avancées, en particulier ceux qui utilisent des compétences de VRP Toolkit.","de":"Perfekt für KI-Agents, die erweiterte Fähigkeitsmanagement- und Auditfunktionen benötigen, insbesondere solche, die VRP Toolkit-Fähigkeiten nutzen.","pt":"Perfeito para Agentes de IA que necessitam de gerenciamento avançado de habilidades e capacidades de auditoria, particularmente aqueles que utilizam habilidades do VRP Toolkit.","ru":"Идеально для ИИ-агентов, которым требуются продвинутые возможности управления навыками и аудита, особенно тех, кто использует навыки VRP Toolkit.","ar":"مثالي للوكلاء الذكاء الاصطناعي الذين يحتاجون إلى إدارة متقدمة لقدراتهم وتحليلها، ولا سيما أولئك الذين يستخدمون مهارات أدوات VRP."},"recommendation":{"en":"Empowers agents to efficiently manage and audit skills by comparing actual skills in `.claude/skills/` with SKILLS.md documentation, and validating skills against VRP Toolkit standards using Python scripts like `audit_skills.py`.","zh":"通过比较`.claude/skills/`中的实际技能与SKILLS.md文档，并使用Python脚本（如`audit_skills.py`）验证技能以满足VRP Toolkit标准，能够高效地管理和审计技能。","ja":"`.claude/skills/`内の実際のスキルとSKILLS.mdドキュメントを比較し、Pythonスクリプト（例：`audit_skills.py`）を使用してVRP Toolkit標準に従ってスキルを検証することで、スキルを効率的に管理および監査できます。","ko":"`audit_skills.py`와 같은 Python 스크립트를 사용하여 실제 스킬을 `.claude/skills/`와 비교하고 SKILLS.md 문서와의 일치 및 VRP Toolkit 표준에 대한 스킬 검증을 통해 스킬을 효율적으로 관리하고 감사할 수 있습니다.","es":"Habilita a los agentes a administrar y auditar habilidades de manera eficiente comparando las habilidades reales en `.claude/skills/` con la documentación de SKILLS.md y validando habilidades contra los estándares de VRP Toolkit utilizando scripts de Python como `audit_skills.py`.","fr":"Permet aux agents de gérer et d''auditer les compétences de manière efficace en comparant les compétences réelles dans `.claude/skills/` avec la documentation de SKILLS.md et en validant les compétences contre les normes de VRP Toolkit en utilisant des scripts Python tels que `audit_skills.py`.","de":"Ermöglicht es den Agents, Fähigkeiten effizient zu verwalten und zu auditen, indem sie die tatsächlichen Fähigkeiten in `.claude/skills/` mit der SKILLS.md-Dokumentation vergleichen und Fähigkeiten gegen die VRP Toolkit-Standards mit Python-Skripten wie `audit_skills.py` validieren.","pt":"Habilita os agentes a gerenciar e auditar habilidades de forma eficiente, comparando habilidades reais em `.claude/skills/` com a documentação SKILLS.md e validando habilidades contra os padrões do VRP Toolkit usando scripts Python como `audit_skills.py`.","ru":"Наделяет агентов возможностью эффективно управлять и аудировать навыки, сравнивая фактические навыки в `.claude/skills/` с документацией SKILLS.md и проверяя навыки на соответствие стандартам VRP Toolkit с помощью скриптов Python, таких как `audit_skills.py`.","ar":"يمنح الوكلاء القدرة على إدارة وتحليل القدرات بفعالية من خلال مقارنة المهارات الفعلية في `.claude/skills/` بالتوثيق SKILLS.md والتحقق من المهارات مقابل معايير أدوات VRP باستخدام نصوص Python مثل `audit_skills.py`."},"useCases":{"en":["Auditing skills directories for compliance","Validating skill compliance against VRP Toolkit standards","Comparing actual skills with documented skills in SKILLS.md"],"zh":["审计技能目录以确保遵守规定","验证技能是否符合VRP Toolkit标准","比较实际技能与SKILLS.md文档中记录的技能"],"ja":["スキルディレクトリを監査してコンプライアンスを確保する","スキルがVRP Toolkit標準に準拠していることを検証する","実際のスキルとSKILLS.mdドキュメントに記載されたスキルを比較する"],"ko":["감사 규정 준수 위해 스킬 디렉토리 감사","VRP Toolkit 표준에 대한 스킬 검증","실제 스킬과 SKILLS.md 문서에 기록된 스킬 비교"],"es":["Auditoría de directorios de habilidades para cumplimiento","Validación del cumplimiento de habilidades contra los estándares de VRP Toolkit","Comparación de habilidades reales con habilidades documentadas en SKILLS.md"],"fr":["Audit des répertoires de compétences pour la conformité","Validation de la conformité des compétences aux normes de VRP Toolkit","Comparaison des compétences réelles avec les compétences documentées dans SKILLS.md"],"de":["Auditing von Fähigkeitsverzeichnissen für Konformität","Validierung der Fähigkeitskonformität gegen die VRP Toolkit-Standards","Vergleich der tatsächlichen Fähigkeiten mit den in SKILLS.md dokumentierten Fähigkeiten"],"pt":["Auditoria de diretórios de habilidades para conformidade","Validação da conformidade de habilidades contra os padrões do VRP Toolkit","Comparação de habilidades reais com habilidades documentadas em SKILLS.md"],"ru":["Аудит директорий навыков для соответствия","Проверка соответствия навыков стандартам VRP Toolkit","Сравнение фактических навыков с задокументированными навыками в SKILLS.md"],"ar":["مراجعة دلائل المهارات للامتثال","التحقق من امتثال المهارات لمعايير أدوات VRP","مقارنة المهارات الفعلية بالمهارات المثبتة في SKILLS.md"]},"limitations":{"en":["Requires access to `.claude/skills/` directory","SKILLS.md documentation must be up-to-date","Python environment required for script execution"],"zh":["需要访问`.claude/skills/`目录","SKILLS.md文档必须是最新的","需要Python环境来执行脚本"],"ja":["`.claude/skills/`ディレクトリへのアクセスが必要","SKILLS.mdドキュメントは最新である必要があります","スクリプトの実行にはPython環境が必要"],"ko":["`.claude/skills/` 디렉토리에 대한 액세스가 필요합니다.","SKILLS.md 문서는 최신 상태여야 합니다.","스크립트 실행을 위해 Python 환경이 필요합니다."],"es":["Requiere acceso al directorio `.claude/skills/`","La documentación de SKILLS.md debe estar actualizada","Entorno de Python requerido para la ejecución de scripts"],"fr":["Nécessite l''accès au répertoire `.claude/skills/`","La documentation de SKILLS.md doit être à jour","Environnement Python requis pour l''exécution des scripts"],"de":["Erfordert Zugriff auf das Verzeichnis `.claude/skills/`","Die SKILLS.md-Dokumentation muss aktuell sein","Python-Umgebung erforderlich für die Skriptausführung"],"pt":["Requer acesso ao diretório `.claude/skills/`","A documentação SKILLS.md deve estar atualizada","Ambiente Python necessário para execução de scripts"],"ru":["Требуется доступ к директории `.claude/skills/`","Документация SKILLS.md должна быть актуальной","Необходимо окружение Python для выполнения скриптов"],"ar":["يتطلب الوصول إلى الدليل `.claude/skills/`","يجب أن تكون وثائق SKILLS.md محدثة","يتطلب بيئة Python لتشغيل البرامج النصية"]},"version":4},"contentHash":"c10213b298f7e99f4b53c994a87d6a03113ed1d5cb9757e540ed6257ca9d4068","qualityScore":36}');
