INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('dudusoar/VRP-Toolkit/manage-skills', 'manage-skills', 'dudusoar', 'VRP-Toolkit', 'community', 'manage-skills dudusoar VRP-Toolkit community The manage-skills AI agent skill is designed for managing, auditing, and maintaining all VRP Toolkit skills, benefiting developers and users alike. It provides core functions for skill directory comparison and compliance validation. Manage Skills是用于管理和维护VRP Toolkit技能的元技能，提供审计和合规检查功能 Manage SkillsはVRP Toolkitのスキルを管理およびメンテナンスするメタスキルです Manage Skills는 VRP Toolkit 스킬을 관리 및 유지보수하는 메타 스킬입니다 manage-skills es una habilidad para auditar y mantener habilidades en tu toolkit de realidad virtual con Python y CLI. manage-skills est une compétence pour auditer et maintenir des compétences dans votre toolkit de réalité virtuelle avec Python et CLI. manage-skills ist eine Fähigkeit, um Fähigkeiten in Ihrem VR-Toolkit mit Python und CLI zu überprüfen und zu warten. O manage-skills é uma habilidade de meta que gerencia e audita habilidades de IA. Ele compara habilidades reais com documentação e valida contra padrões do VRP Toolkit. Manage-skills - это meta-навык для управления и аудита ИИ Агентов. Он сравнивает фактические habilidades с документацией и проверяет против стандартов VRP Toolkit. manage-skills هي مهارة ميتا لإدارة المهارات للأدوات الذكية. تقارن المهارات الفعلية بالوثائق ووتحقق ضد معايير VRP Toolkit. how to use manage-skills manage-skills alternative manage-skills setup guide what is manage-skills manage-skills vs VRP Toolkit manage-skills install VRP Toolkit skill management audit skills directory skill compliance validation AIエージェント 技能管理 VRP Toolkit Python脚本 审计技能 合规检查 技能报告 元技能 Audits skills directory using `.claude/skills/` and SKILLS.md documentation Validates skills against VRP Toolkit standards Generates reports on skills in directory vs SKILLS.md Identifies missing skills from documentation and directory Executes sync status checks using `audit_skills.py` script manage-skills is a meta-skill for managing and auditing VRP Toolkit skills, ensuring directory comparison and compliance validation.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('spencerbeggs/claude-design-coordinator/rspress-frontmatter', 'community', 'spencerbeggs', 'claude-design-coordinator', 'spencerbeggs/claude-design-coordinator', 'rspress-frontmatter', 0, 0, 36, '2026-03-08T01:57:15.316Z', '2026-03-08T02:02:51.180Z', 'eeec9f3dde04fc1dd25b3d75d6e6499a3c0c48f8582bbbc1edb0113058883c25', '{"id":"spencerbeggs/claude-design-coordinator/rspress-frontmatter","name":"rspress-frontmatter","description":{"en":"rspress-frontmatter allows developers to configure YAML frontmatter in RSPress markdown/mdx files, controlling page metadata, layout, and special page types. This skill benefits developers working with RSPress.","zh":"RSPress Frontmatter 是一种用于配置 YAML 前置元数据的方法，用于控制 RSPress Markdown/MDX 文件的页面元数据、布局和特殊页面类型","ja":"RSPress Frontmatter は、RSPress Markdown/MDX ファイルのページメタデータ、レイアウト、特殊ページタイプを制御するための YAML フロントマター設定方法です","ko":"RSPress Frontmatter는 RSPress Markdown/MDX 파일의 페이지 메타데이터, 레이아웃, 특수 페이지 유형을 제어하기 위한 YAML 프론트매터 설정 방법입니다","es":"rspress-frontmatter permite configurar metadatos de página y diseño en RSPress. Aprende a utilizar sus características.","fr":"rspress-frontmatter permet de configurer les métadonnées de page et la mise en page dans RSPress. Découvrez ses fonctionnalités.","de":"rspress-frontmatter ermöglicht die Konfiguration von Seitmetadaten und Layout in RSPress. Erfahren Sie mehr über seine Funktionen.","pt":"O RSPress Frontmatter é uma ferramenta para configurar YAML frontmatter em arquivos markdown/mdx, controlando metadados de página e layout","ru":"RSPress Frontmatter - это инструмент для настройки YAML frontmatter в файлах markdown/mdx, контролирующий метаданные страницы и макет","ar":"RSPress Frontmatter هو أداة لإعداد YAML frontmatter في ملفات markdown/mdx ، للتحكم في بيانات الصفحة وتصميمها"},"seo":{"title":{"en":"rspress-frontmatter: YAML Frontmatter Configuration Setup...","zh":"RSPress Frontmatter 配置指南 - YAML 前置元数据控制","ja":"RSPress Frontmatter の設定方法 - YAML フロントマターによるページメタデータ制御","ko":"RSPress Frontmatter 설정 가이드 - YAML 프론트매터를 통한 페이지 메타데이터 제어","es":"Guía de configuración de rspress-frontmatter para metadat...","fr":"Configurer les métadonnées de page avec rspress-frontmatter","de":"Einrichten von rspress-frontmatter für Seitmetadaten","pt":"Guia de Configuração RSPress Frontmatter para Desenvolved...","ru":"Настройка RSPress Frontmatter: ИИ Агенты для Разработчиков","ar":"دليل إعداد RSPress Frontmatter للاستفادة القصوى من آداة ا..."},"description":{"en":"Discover how to control page metadata, layout, and special page types with rspress-frontmatter. Learn to configure YAML frontmatter in RSPress markdown/mdx f...","zh":"了解 RSPress Frontmatter 的配置方法，控制页面元数据、布局和特殊页面类型，优化您的 Markdown/MDX 文件","ja":"RSPress Frontmatter の設定方法について学び、ページメタデータ、レイアウト、特殊ページタイプを制御し、Markdown/MDX ファイルを最適化する","ko":"RSPress Frontmatter 설정 방법을 알아보고 페이지 메타데이터, 레이아웃, 특수 페이지 유형을 제어하여 Markdown/MDX 파일을 최적화하세요","es":"Aprende a configurar YAML frontmatter en RSPress para controlar metadatos de página, diseño y tipos de página especiales","fr":"Découvrez comment configurer les métadonnées de page avec rspress-frontmatter pour contrôler les métadonnées, la mise en page et les types de page spéciaux","de":"Erfahren Sie, wie Sie YAML-Frontmatter in RSPress konfigurieren, um Seitmetadaten, Layout und spezielle Seitentypen zu steuern","pt":"Aprenda a configurar o RSPress Frontmatter para controlar metadados de página, layout e tipos de página especiais em markdown/mdx","ru":"Узнайте, как настроить RSPress Frontmatter для управления метаданными страницы, макетом и специальными типами страниц в markdown/mdx","ar":"تعلم كيفية إعداد RSPress Frontmatter للتحكم في метادات الصفحة وتصميمها وأنواع الصفحات الخاصة في markdown/mdx"},"definition":{"en":"rspress-frontmatter is a configuration skill for controlling YAML frontmatter in RSPress markdown/mdx files to manage page metadata and layout.","zh":"RSPress Frontmatter 是一种 YAML 前置元数据配置方法","ja":"RSPress Frontmatter は YAML フロントマター設定方法の一種です","ko":"RSPress Frontmatter는 YAML 프론트매터 설정 방법 중的一种입니다","es":"rspress-frontmatter es una configuración de YAML frontmatter para controlar metadatos de página y diseño en RSPress","fr":"rspress-frontmatter est une configuration de frontmatter YAML pour contrôler les métadonnées de page et la mise en page dans RSPress","de":"rspress-frontmatter ist eine YAML-Frontmatter-Konfiguration zur Steuerung von Seitmetadaten und Layout in RSPress","pt":"RSPress Frontmatter é uma ferramenta de configuração para YAML frontmatter em markdown/mdx","ru":"RSPress Frontmatter - это инструмент для настройки YAML frontmatter в markdown/mdx","ar":"RSPress Frontmatter هو أداة لإعداد YAML frontmatter في markdown/mdx"},"features":{"en":["Configures YAML frontmatter in RSPress markdown/mdx files","Supports core metadata fields like title, description, and titleSuffix","Enables page layout control using specific fields","Overrides H1 heading with custom page title","Generates SEO meta tags using page description"],"zh":["支持设置页面标题（title）","支持设置页面描述（description）","支持设置页面标题后缀（titleSuffix）","支持控制页面布局","支持特殊页面类型的配置","基于 YAML 的前置元数据配置"],"ja":["ページタイトル（title）を設定する機能","ページ説明（description）を設定する機能","ページタイトルサフィックス（titleSuffix）を設定する機能","ページレイアウトを制御する機能","特殊ページタイプを設定する機能","YAML ベースのフロントマター設定"],"ko":["페이지 제목 설정 기능","페이지 설명 설정 기능","페이지 제목 후綴 설정 기능","페이지 레이아웃 제어 기능","특수 페이지 유형 설정 기능","YAML 기반 프론트매터 설정"],"es":["Configuración de metadatos de página con YAML frontmatter","Control de diseño de página con campos de metadatos personalizados","Compatibilidad con campos de metadatos como título, descripción y título suffix","Soporte para tipos de página especiales","Integración con RSPress markdown/mdx"],"fr":["Configuration des métadonnées de page avec frontmatter YAML","Contrôle de la mise en page de la page avec des champs de métadonnées personnalisés","Compatibilité avec des champs de métadonnées tels que titre, description et titre suffixe","Prise en charge de types de page spéciaux","Intégration avec RSPress markdown/mdx"],"de":["Konfiguration von Seitmetadaten mit YAML-Frontmatter","Steuerung des Layouts mit benutzerdefinierten Metadatenfeldern","Unterstützung für Metadatenfelder wie Titel, Beschreibung und Titelsuffix","Unterstützung für spezielle Seitentypen","Integration mit RSPress markdown/mdx"],"pt":["Controle de metadados de página via YAML frontmatter","Configuração de layout de página","Suporte a tipos de página especiais","Definição de título e descrição de página","Adição de sufixo personalizado ao título da página"],"ru":["Контроль метаданных страницы через YAML frontmatter","Настройка макета страницы","Поддержка специальных типов страниц","Определение заголовка и описания страницы","Добавление пользовательского суффикса к заголовку страницы"],"ar":["التحكم في بيانات الصفحة عبر YAML frontmatter","إعداد تصميم الصفحة","دعم لأنواع الصفحات الخاصة","تحديد عنوان ووصف الصفحة","إضافة بادئة مخصصة إلى عنوان الصفحة"]},"keywords":{"en":["how to use rspress-frontmatter","rspress-frontmatter setup guide","what is rspress-frontmatter","rspress-frontmatter alternative","rspress-frontmatter vs markdown","rspress-frontmatter install","configuring yaml frontmatter","rspress markdown configuration","controlling page metadata"],"zh":["RSPress Frontmatter","YAML 前置元数据","页面元数据配置","Markdown/MDX 文件优化","AIエージェント","前端开发","页面布局控制","特殊页面类型配置"],"ja":["RSPress Frontmatter","YAML フロントマター","ページメタデータ設定","Markdown/MDX ファイル最適化","AIエージェント","フロントエンド開発","ページレイアウト制御","特殊ページタイプ設定"],"ko":["RSPress Frontmatter","YAML 프론트매터","페이지 메타데이터 설정","Markdown/MDX 파일 최적화","AI 에이전트","프론트엔드 개발","페이지 레이아웃 제어","특수 페이지 유형 설정"],"es":["rspress-frontmatter","configuración de metadatos de página","YAML frontmatter","RSPress","markdown","mdx","metadatos de página","diseño de página","tipos de página especiales"],"fr":["rspress-frontmatter","configuration des métadonnées de page","frontmatter YAML","RSPress","markdown","mdx","métadonnées de page","mise en page","types de page spéciaux"],"de":["rspress-frontmatter","Konfiguration von Seitmetadaten","YAML-Frontmatter","RSPress","markdown","mdx","Seitmetadaten","Layout","spezielle Seitentypen"],"pt":["RSPress Frontmatter","configuração YAML frontmatter","metadados de página","layout de página","tipos de página especiais","desenvolvimento web","ferramentas de desenvolvimento"],"ru":["RSPress Frontmatter","настройка YAML frontmatter","метаданные страницы","макет страницы","специальные типы страниц","веб-разработка","инструменты разработки","ИИ Агенты"],"ar":["RSPress Frontmatter","إعداد YAML frontmatter","بيانات الصفحة","تصميم الصفحة","أنواع الصفحات الخاصة","تطوير الويب","أدوات التطوير","آداة الـ AI"]}},"owner":"spencerbeggs","repo":"claude-design-coordinator","repoPath":"spencerbeggs/claude-design-coordinator","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.316Z","topics":[],"category":"community","skillMd":{"name":"rspress-frontmatter","description":"Configure RSPress frontmatter for documentation pages. Use when setting up page metadata, controlling layout options, or configuring home page hero/features sections.","bodyPreview":"# RSPress Frontmatter Configuration\n\nConfigure YAML frontmatter in RSPress markdown/mdx files to control page\nmetadata, layout, and special page types.\n\n## Core Metadata Fields\n\n| Field | Type | Description |\n| ----- | ---- | ----------- |\n| `title` | string | Page title (overrides H1 heading) |\n| `description` | string | Page description for SEO meta tags |\n| `titleSuffix` | string | Custom suffix for page title |\n\n## Page Layout Control\n\n| Field | Type | Description |\n| --------- | ------- | -","body":"# RSPress Frontmatter Configuration\n\nConfigure YAML frontmatter in RSPress markdown/mdx files to control page\nmetadata, layout, and special page types.\n\n## Core Metadata Fields\n\n| Field | Type | Description |\n| ----- | ---- | ----------- |\n| `title` | string | Page title (overrides H1 heading) |\n| `description` | string | Page description for SEO meta tags |\n| `titleSuffix` | string | Custom suffix for page title |\n\n## Page Layout Control\n\n| Field | Type | Description |\n| --------- | ------- | ----------- |\n| `pageType` | string | Page type: `doc`, `home`, `blank`, `custom` |\n| `sidebar` | boolean | Show/hide sidebar (default: true) |\n| `outline` | boolean | Show/hide table of contents outline (default: true) |\n| `footer` | boolean | Show/hide footer (default: true) |\n| `navbar` | boolean | Show/hide navigation bar (default: true) |\n\n## Overview Page Configuration\n\nConfigure automatic overview pages that list child pages:\n\n```yaml\n---\npageType: overview\noverview: true\noverviewHeaders:\n  - 2\n  - 3\n---\n```\n\n## Home Page Configuration\n\nConfigure hero sections and feature cards:\n\n```yaml\n---\npageType: home\nhero:\n  name: Project Name\n  text: Tagline text\n  tagline: Subtitle description\n  actions:\n    - text: Get Started\n      link: /guide/getting-started\n      theme: brand\n    - text: View on GitHub\n      link: https://github.com/user/repo\n      theme: alt\nfeatures:\n  - title: Feature One\n    details: Description of first feature\n    icon: 🚀\n  - title: Feature Two\n    details: Description of second feature\n    icon: ⚡\n---\n```\n\n## Common Examples\n\n**Standard documentation page:**\n\n```yaml\n---\ntitle: Getting Started\ndescription: Learn how to install and configure the project\nsidebar: true\noutline: true\n---\n```\n\n**Home page:**\n\n```yaml\n---\npageType: home\ntitle: Welcome\nnavbar: true\nsidebar: false\nhero:\n  name: My Project\n  text: Build amazing things\n  tagline: Fast, flexible, and powerful\n---\n```\n\n**API reference page:**\n\n```yaml\n---\ntitle: API Reference\ndescription: Complete API documentation\noutline: true\npageType: doc\n---\n```\n\n**Blank page (custom layout):**\n\n```yaml\n---\npageType: blank\nnavbar: false\nsidebar: false\nfooter: false\n---\n```\n\n**Overview page:**\n\n```yaml\n---\ntitle: Guides\npageType: overview\noverview: true\n---\n```\n\n## Notes\n\n* Frontmatter must be at the very top of the file\n* All frontmatter blocks must use triple-dash (`---`) delimiters\n* Use YAML syntax for all field values\n* Boolean values should be lowercase: `true`, `false`\n* The `title` field overrides the first H1 heading in the document\n"},"lastSynced":"2026-03-08T02:02:51.180Z","agentAnalysis":{"suitability":{"en":"Ideal for Markdown Agents requiring precise control over RSPress page metadata and layout configuration.","zh":"适用于需要对 RSPress 页面元数据和布局配置进行精确控制的 Markdown Agents。","ja":"RSPress ページのメタデータとレイアウト構成を正確に制御する必要がある Markdown エージェントに適しています。","ko":"RSPress 페이지의 메타데이터와 레이아웃 구성에 대한 정확한 제어가 필요한 Markdown 에이전트에 적합합니다.","es":"Ideal para agentes de Markdown que requieren un control preciso sobre los metadatos de la página RSPress y la configuración del diseño.","fr":"Idéal pour les agents Markdown nécessitant un contrôle précis sur les métadonnées de page RSPress et la configuration de mise en page.","de":"Ideal für Markdown-Agents, die eine präzise Kontrolle über die RSPress-Seitenmetadaten und die Layoutkonfiguration benötigen.","pt":"Ideal para Agentes Markdown que exigem controle preciso sobre metadados de página e configuração de layout do RSPress.","ru":"Идеально для агентов Markdown, требующих точного контроля над метаданными страниц и настройкой макета RSPress.","ar":"مثالي للموكلين Markdown الذين يتطلبون التحكم الدقيق في بيانات التعريف الصفحة وتكوين تخطيط RSPress."},"recommendation":{"en":"Empowers agents to configure YAML frontmatter in RSPress markdown/mdx files, controlling page metadata, layout, and special page types using fields like title, description, and titleSuffix, thereby enhancing SEO meta tags and page customization.","zh":"赋予代理配置 RSPress 中的 YAML 前置内容，控制页面元数据、布局和特殊页面类型，使用诸如标题、描述和标题后缀等字段，从而增强 SEO 元标签和页面自定义。","ja":"RSPress の YAML フロントマターをエージェントが設定できるようにし、タイトル、説明、タイトルサフィックスなどのフィールドを使用して、ページのメタデータ、レイアウト、および特殊なページタイプを制御し、SEO メタタグとページのカスタマイズを強化します。","ko":"에이전트가 RSPress의 YAML 전면 매터를 구성할 수 있도록 하여 제목, 설명, 제목 접미사 등의 필드를 사용하여 페이지 메타데이터, 레이아웃 및 특수 페이지 유형을 제어하여 SEO 메타 태그 및 페이지 사용자 정의를 강화합니다.","es":"Permite a los agentes configurar el frontmatter YAML en archivos markdown/mdx de RSPress, controlando los metadatos de la página, el diseño y los tipos de página especiales mediante campos como título, descripción y títuloSuffix, lo que mejora las etiquetas meta de SEO y la personalización de la página.","fr":"Permet aux agents de configurer le frontmatter YAML dans les fichiers markdown/mdx de RSPress, en contrôlant les métadonnées de page, la mise en page et les types de page spéciaux à l''aide de champs tels que titre, description et titleSuffix, améliorant ainsi les balises meta de SEO et la personnalisation de la page.","de":"Ermächtigt Agents, das YAML-Frontmatter in RSPress-Markdown/MDX-Dateien zu konfigurieren, wodurch die Kontrolle über die Seitenmetadaten, die Layoutkonfiguration und spezielle Seitentypen mithilfe von Feldern wie Titel, Beschreibung und titleSuffix ermöglicht wird, was die SEO-Meta-Tags und die Seitennindividualisierung verbessert.","pt":"Habilita os agentes a configurarem o frontmatter YAML em arquivos markdown/mdx do RSPress, controlando metadados de página, layout e tipos de página especiais usando campos como título, descrição e titleSuffix, melhorando assim as tags de metadados SEO e personalização de página.","ru":"Наделяет агентов возможностью настраивать YAML-заголовок в файлах markdown/mdx RSPress, контролируя метаданные страницы, макет и специальные типы страниц, используя поля, такие как заголовок, описание и titleSuffix, тем самым улучшая теги метаданных SEO и настройку страницы.","ar":"يمنح الوكلاء إمكانية تكوين YAML frontmatter في ملفات markdown/mdx من RSPress، مما يتيح لهم التحكم في بيانات التعريف الصفحة والتخطيط وأنواع الصفحات الخاصة باستخدام حقول مثل العنوان والوصف واللاحقة العنوان، مما يعزز بذلك علامات متاداة SEO وتخصيص الصفحة."},"useCases":{"en":["Configuring page metadata for improved SEO","Customizing page layouts using YAML frontmatter","Creating special page types with tailored metadata"],"zh":["配置页面元数据以提高 SEO","使用 YAML 前置内容自定义页面布局","使用定制的元数据创建特殊页面类型"],"ja":["SEO を改善するためのページメタデータの設定","YAML フロントマターを使用したページレイアウトのカスタマイズ","カスタマイズされたメタデータを使用した特殊なページタイプの作成"],"ko":["SEO 향상을 위한 페이지 메타데이터 구성","YAML 전면 매터를 사용한 페이지 레이아웃 사용자 정의","사용자 정의 메타데이터를 사용한 특수 페이지 유형 생성"],"es":["Configuración de metadatos de página para una mejor optimización para motores de búsqueda","Personalización de diseños de página utilizando frontmatter YAML","Creación de tipos de página especiales con metadatos personalizados"],"fr":["Configuration des métadonnées de page pour une meilleure optimisation pour les moteurs de recherche","Personnalisation de la mise en page de page à l''aide de frontmatter YAML","Création de types de page spéciaux avec des métadonnées personnalisées"],"de":["Konfiguration von Seitenmetadaten für eine bessere Suchmaschinenoptimierung","Anpassung von Seitendesigns unter Verwendung von YAML-Frontmatter","Erstellung von speziellen Seitentypen mit angepassten Metadaten"],"pt":["Configurando metadados de página para melhorar o SEO","Personalizando layouts de página usando frontmatter YAML","Criando tipos de página especiais com metadados personalizados"],"ru":["Настройка метаданных страницы для улучшения SEO","Настройка макета страницы с помощью YAML-заголовка","Создание специальных типов страниц с настроенными метаданными"],"ar":["تكوين بيانات التعريف الصفحة لتحسين متاداة SEO","تخصيص تخطيط الصفحة باستخدام YAML frontmatter","إنشاء أنواع صفحات خاصة مع بيانات تعريف مخصصة"]},"limitations":{"en":["Requires RSPress environment","Limited to markdown/mdx file formats","Dependent on YAML frontmatter configuration"],"zh":["需要 RSPress 环境","仅限 markdown/mdx 文件格式","依赖于 YAML 前置内容配置"],"ja":["RSPress 環境が必要","markdown/mdx ファイル形式のみ","YAML フロントマター設定に依存"],"ko":["RSPress 환경이 필요","markdown/mdx 파일 형식만","YAML 전면 매터 구성에 의존"],"es":["Requiere entorno RSPress","Limitado a formatos de archivo markdown/mdx","Dependiente de la configuración de frontmatter YAML"],"fr":["Nécessite un environnement RSPress","Limité aux formats de fichiers markdown/mdx","Dépendant de la configuration de frontmatter YAML"],"de":["Benötigt RSPress-Umgebung","Begrenzt auf Markdown/MDX-Dateiformate","Abhängig von der YAML-Frontmatter-Konfiguration"],"pt":["Exige ambiente RSPress","Limitado a formatos de arquivo markdown/mdx","Dependente da configuração do frontmatter YAML"],"ru":["Требует среды RSPress","Ограничен форматами файлов markdown/mdx","Зависит от настройки YAML-заголовка"],"ar":["يتطلب بيئة RSPress","محدود بالتنسيقات ملفات markdown/mdx","يعتمد على تكوين YAML frontmatter"]},"version":4},"contentHash":"eeec9f3dde04fc1dd25b3d75d6e6499a3c0c48f8582bbbc1edb0113058883c25","qualityScore":36}');
