INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('spencerbeggs/claude-design-coordinator/rspress-frontmatter', 'rspress-frontmatter', 'spencerbeggs', 'claude-design-coordinator', 'community', 'rspress-frontmatter spencerbeggs claude-design-coordinator community rspress-frontmatter allows developers to configure YAML frontmatter in RSPress markdown/mdx files, controlling page metadata, layout, and special page types. This skill benefits developers working with RSPress. RSPress Frontmatter 是一种用于配置 YAML 前置元数据的方法，用于控制 RSPress Markdown/MDX 文件的页面元数据、布局和特殊页面类型 RSPress Frontmatter は、RSPress Markdown/MDX ファイルのページメタデータ、レイアウト、特殊ページタイプを制御するための YAML フロントマター設定方法です RSPress Frontmatter는 RSPress Markdown/MDX 파일의 페이지 메타데이터, 레이아웃, 특수 페이지 유형을 제어하기 위한 YAML 프론트매터 설정 방법입니다 rspress-frontmatter permite configurar metadatos de página y diseño en RSPress. Aprende a utilizar sus características. rspress-frontmatter permet de configurer les métadonnées de page et la mise en page dans RSPress. Découvrez ses fonctionnalités. rspress-frontmatter ermöglicht die Konfiguration von Seitmetadaten und Layout in RSPress. Erfahren Sie mehr über seine Funktionen. O RSPress Frontmatter é uma ferramenta para configurar YAML frontmatter em arquivos markdown/mdx, controlando metadados de página e layout RSPress Frontmatter - это инструмент для настройки YAML frontmatter в файлах markdown/mdx, контролирующий метаданные страницы и макет RSPress Frontmatter هو أداة لإعداد YAML frontmatter في ملفات markdown/mdx ، للتحكم في بيانات الصفحة وتصميمها how to use rspress-frontmatter rspress-frontmatter setup guide what is rspress-frontmatter rspress-frontmatter alternative rspress-frontmatter vs markdown rspress-frontmatter install configuring yaml frontmatter rspress markdown configuration controlling page metadata RSPress Frontmatter YAML 前置元数据 页面元数据配置 Markdown/MDX 文件优化 AIエージェント 前端开发 页面布局控制 特殊页面类型配置 Configures YAML frontmatter in RSPress markdown/mdx files Supports core metadata fields like title, description, and titleSuffix Enables page layout control using specific fields Overrides H1 heading with custom page title Generates SEO meta tags using page description rspress-frontmatter is a configuration skill for controlling YAML frontmatter in RSPress markdown/mdx files to manage page metadata and layout.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('slavochek2/claritypledge/awesome:web-artifacts-builder', 'community', 'slavochek2', 'claritypledge', 'slavochek2/claritypledge', 'awesome:web-artifacts-builder', 0, 0, 36, '2026-03-08T01:57:15.317Z', '2026-03-08T02:02:52.841Z', '7d71c93950d642b05df7389b000b458bdc43306f7d3127f4868d83fcbfcafee5', '{"id":"slavochek2/claritypledge/awesome:web-artifacts-builder","name":"awesome:web-artifacts-builder","description":{"en":"The awesome:web-artifacts-builder skill helps developers create frontend artifacts using React 18, TypeScript, and Vite. It provides a step-by-step process to initialize, develop, and bundle artifacts.","zh":"awesome:web-artifacts-builder 是一个用于构建前端 AI 工具的技能，支持 React 18、TypeScript、Vite 和 Tailwind CSS","ja":"awesome:web-artifacts-builder は、フロントエンド AI エージェントを構築するためのスキルです。React 18、TypeScript、Vite、Tailwind CSS をサポートしています","ko":"awesome:web-artifacts-builder는 프론트엔드 AI 도구를 구축하기 위한 스킬입니다. React 18, TypeScript, Vite 및 Tailwind CSS를 지원합니다","es":"El awesome:web-artifacts-builder es una herramienta para crear artefactos web con React 18, TypeScript y Vite. Sigue los pasos para inicializar, desarrollar y empaquetar tus artefactos","fr":"L''awesome:web-artifacts-builder est un outil pour créer des artefacts web avec React 18, TypeScript et Vite. Suivez les étapes pour initialiser, développer et empaqueter vos artefacts","de":"Der awesome:web-artifacts-builder ist ein Tool, um Web-Artefakte mit React 18, TypeScript und Vite zu erstellen. Befolgen Sie die Schritte, um Ihre Artefakte zu initialisieren, zu entwickeln und zu bündeln","pt":"O awesome:web-artifacts-builder é uma ferramenta para criar artefatos web personalizados, utilizando tecnologias como React 18 e TypeScript.","ru":"ИИ Агент awesome:web-artifacts-builder - это инструмент для создания индивидуальных веб-артефактов, использующий технологии sepert