INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('slavochek2/claritypledge/awesome:web-artifacts-builder', 'awesome:web-artifacts-builder', 'slavochek2', 'claritypledge', 'community', 'awesome:web-artifacts-builder slavochek2 claritypledge community The awesome:web-artifacts-builder skill helps developers create frontend artifacts using React 18, TypeScript, and Vite. It provides a step-by-step process to initialize, develop, and bundle artifacts. awesome:web-artifacts-builder 是一个用于构建前端 AI 工具的技能，支持 React 18、TypeScript、Vite 和 Tailwind CSS awesome:web-artifacts-builder は、フロントエンド AI エージェントを構築するためのスキルです。React 18、TypeScript、Vite、Tailwind CSS をサポートしています awesome:web-artifacts-builder는 프론트엔드 AI 도구를 구축하기 위한 스킬입니다. React 18, TypeScript, Vite 및 Tailwind CSS를 지원합니다 El awesome:web-artifacts-builder es una herramienta para crear artefactos web con React 18, TypeScript y Vite. Sigue los pasos para inicializar, desarrollar y empaquetar tus artefactos L''awesome:web-artifacts-builder est un outil pour créer des artefacts web avec React 18, TypeScript et Vite. Suivez les étapes pour initialiser, développer et empaqueter vos artefacts Der awesome:web-artifacts-builder ist ein Tool, um Web-Artefakte mit React 18, TypeScript und Vite zu erstellen. Befolgen Sie die Schritte, um Ihre Artefakte zu initialisieren, zu entwickeln und zu bündeln O awesome:web-artifacts-builder é uma ferramenta para criar artefatos web personalizados, utilizando tecnologias como React 18 e TypeScript. ИИ Агент awesome:web-artifacts-builder - это инструмент для создания индивидуальных веб-артефактов, использующий технологии seperti React 18 и TypeScript. awesome:web-artifacts-builder هو أداة لإنشاء نماذج ويب مخصصة، باستخدام تقنيات مثل React 18 و TypeScript. how to use awesome:web-artifacts-builder awesome:web-artifacts-builder setup guide awesome:web-artifacts-builder vs other frontend builders what is awesome:web-artifacts-builder awesome:web-artifacts-builder install building web artifacts with React and TypeScript awesome:web-artifacts-builder 前端 AI 工具 React 18 TypeScript Vite Tailwind CSS shadcn/ui AI 工具构建 前端开发 Initializes frontend repo using scripts/init-artifact.sh Supports development with React 18 and TypeScript Bundles code into a single HTML file using scripts/bundle-artifact.sh and Parcel Utilizes Tailwind CSS for styling and shadcn/ui for UI components Allows for optional testing of the artifact awesome:web-artifacts-builder is a skill that enables developers to build and deploy web artifacts using a stack of React, TypeScript, Vite, Parcel, and Tailwind CSS.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('chengyihua/nanobot-ts/baoyu-post-to-x', 'community', 'chengyihua', 'nanobot-ts', 'chengyihua/nanobot-ts', 'baoyu-post-to-x', 0, 0, 36, '2026-03-08T01:57:15.320Z', '2026-03-08T02:02:57.551Z', '4522ae2cfa2a7c79dfdce9f84be9f6541cdc36f5e234daff762f756faf614ebb', '{"id":"chengyihua/nanobot-ts/baoyu-post-to-x","name":"baoyu-post-to-x","description":{"en":"baoyu-post-to-x is a TypeScript-based framework that enables developers to post text, images, videos, and long-form articles to Twitter using a robust agent loop and memory system. It benefits developers seeking a lightweight and extensible personal AI assistant.","zh":"baoyu-post-to-x 是一个 TypeScript 构建的超轻量级 AI 个人助手框架，使用 Chrome 浏览器发布帖子","ja":"baoyu-post-to-x は、Chrome ブラウザを使用して投稿を実行するための超軽量の TypeScript AI エージェント フレームワークです","ko":"baoyu-post-to-x는 Chrome 브라우저를 사용하여 게시물 게시를 위한超軽量의 TypeScript AI 에이전트 프레임워크입니다","es":"baoyu-post-to-x es un framework de asistente personal de IA que permite publicar texto, imágenes, videos y artículos largos en X mediante un navegador Chrome real","fr":"baoyu-post-to-x est un framework d''agent personnel IA qui permet de publier du texte, des images, des vidéos et des articles longs sur X via un navigateur Chrome réel","de":"baoyu-post-to-x ist ein Framework für persönliche KI-Assistenten, das das Veröffentlichen von Text, Bildern, Videos und langen Artikeln auf X über einen echten Chrome-Browser ermöglicht","pt":"O baoyu-post-to-x é uma ferramenta de postagem automática para X, construída com TypeScript, que permite a publicação de textos, imagens, vídeos e artigos longos","ru":"ИИ Агент baoyu-post-to-x - это инструмент для автоматической публикации в X, построенный на TypeScript, который позволяет публиковать тексты, изображения, видео и длинные статьи","ar":"أداة النشر الآلي baoyu-post-to-x هي أداة للنشر التلقائي في X، مبنية على Type