INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('chengyihua/nanobot-ts/baoyu-post-to-x', 'baoyu-post-to-x', 'chengyihua', 'nanobot-ts', 'community', 'baoyu-post-to-x chengyihua nanobot-ts community baoyu-post-to-x is a TypeScript-based framework that enables developers to post text, images, videos, and long-form articles to Twitter using a robust agent loop and memory system. It benefits developers seeking a lightweight and extensible personal AI assistant. baoyu-post-to-x 是一个 TypeScript 构建的超轻量级 AI 个人助手框架，使用 Chrome 浏览器发布帖子 baoyu-post-to-x は、Chrome ブラウザを使用して投稿を実行するための超軽量の TypeScript AI エージェント フレームワークです baoyu-post-to-x는 Chrome 브라우저를 사용하여 게시물 게시를 위한超軽量의 TypeScript AI 에이전트 프레임워크입니다 baoyu-post-to-x es un framework de asistente personal de IA que permite publicar texto, imágenes, videos y artículos largos en X mediante un navegador Chrome real baoyu-post-to-x est un framework d''agent personnel IA qui permet de publier du texte, des images, des vidéos et des articles longs sur X via un navigateur Chrome réel baoyu-post-to-x ist ein Framework für persönliche KI-Assistenten, das das Veröffentlichen von Text, Bildern, Videos und langen Artikeln auf X über einen echten Chrome-Browser ermöglicht O baoyu-post-to-x é uma ferramenta de postagem automática para X, construída com TypeScript, que permite a publicação de textos, imagens, vídeos e artigos longos ИИ Агент baoyu-post-to-x - это инструмент для автоматической публикации в X, построенный на TypeScript, который позволяет публиковать тексты, изображения, видео и длинные статьи أداة النشر الآلي baoyu-post-to-x هي أداة للنشر التلقائي في X، مبنية على TypeScript، وتسمح بنشر النصوص والصور والفيديوهات والمقالات الطويلة how to use baoyu-post-to-x baoyu-post-to-x alternative baoyu-post-to-x setup guide what is baoyu-post-to-x baoyu-post-to-x vs other AI assistants baoyu-post-to-x install for developers baoyu-post-to-x Twitter integration TypeScript AI assistant framework ultra-lightweight AI assistant baoyu-post-to-x TypeScript AI 个人助手 超轻量级 AI 框架 Chrome 浏览器发布帖子 AI 代理循环 AI 内存系统 Posts text, images, videos, and long-form articles to Twitter via a real Chrome browser Bypasses anti-bot detection using a robust agent loop and memory system Utilizes a TypeScript-based framework for extensibility and customization Executes scripts located in the `scripts/` subdirectory for flexible automation Supports agent execution instructions for seamless integration baoyu-post-to-x is an ultra-lightweight, extensible personal AI assistant framework built with TypeScript, designed for handling complex tasks through a robust agent loop, memory system, and tool integration.');
INSERT OR REPLACE INTO skills (id, category, owner, repo, repo_path, name, stars, forks, quality_score, updated_at, last_synced, content_hash, data_json) VALUES ('wevm/wagmi/wagmi-development', 'community', 'wevm', 'wagmi', 'wevm/wagmi', 'wagmi-development', 0, 0, 36, '2026-03-08T01:57:15.323Z', '2026-03-08T02:02:58.005Z', '8b7190836badca89cbf5c0714ccc3c71c9813869dd2c2af50e75d961c58ded51', '{"id":"wevm/wagmi/wagmi-development","name":"wagmi-development","description":{"en":"wagmi-development provides reactive primitives for Ethereum apps, covering core actions and query options. It benefits developers building full-stack Ethereum applications.","zh":"Wagmi开发提供了一组反应式原语，用于构建Ethereum应用。它包括核心行动、查询选项和框架绑定","ja":"Wagmi開発は、Ethereumアプリを構築するための反応性プリミティブを提供します。コアアクション、クエリーオプション、フレームワークバインディングを含みます","ko":"Wagmi 개발은 Ethereum 애플리케이션을 구축하기 위한 리액티브 프imitives를 제공합니다. 핵심 액션, 쿼리 옵션, 프레임워크 바인딩을 포함","es":"Wagmi Development proporciona primitivas reactivas para aplicaciones de Ethereum, con funcionalidades como Core Action y Query Options","fr":"Wagmi Development fournit des primitives réactives pour les applications Ethereum, avec des fonctionnalités telles que Core Action et Query Options","de":"Wagmi Development bietet reaktive Primitive für Ethereum-Anwendungen, mit Funktionen wie Core Action und Query Options","pt":"Wagmi-Development fornece primitivos reativos para aplicativos Ethereum, incluindo ações baseadas em Viem e integração com TanStack Query","ru":"Wagmi-Development предоставляет реактивные примитивы для приложений Ethereum, включая действия на основе Viem и интеграцию с TanStack Query","ar":"Wagmi-Development يوفر بدائيات تفاعلية لتطبيقات Ethereum، بما في ذلك الإجراءات القائمة على Viem ودمج TanStack Query"},"seo":{"title":{"en":"wagmi-development: Reactive Ethereum App Setup Guide | AI...","zh":"Wagmi 开发设置指南 - Reactive primitives for Ethereum 应用","ja":"Wagmi 開発ベストプラクティス - AIエージェントによるEthereum アプリ","ko":"Wagmi 개발 가이드 - 리액티브 프imitives for Ethereum 애플리케이션","es":"Guía de configuración de Wagmi Development para aplicacio...","fr":"Guide de mise en place de Wagmi Development pour les appl...","de":"Wagmi Development-Setup-Anleitung für Ethereum-Anwendungen","pt":"Guia de Configuração Wagmi-Development: Primitivos Reativ...","ru":"Руководство по настройке Wagmi-Development: Реактивные пр...","ar":"دليل إعداد Wagmi-Development: البدائيات التفاعلية لتطبيقا..."},"description":{"en":"Unlock full-stack Ethereum app development with wagmi-development. Learn how to integrate TanStack Query and React hooks for seamless app building. Get start...","zh":"了解Wagmi开发的核心行动、查询选项和框架绑定。使用Wagmi构建强大的Ethereum应用","ja":"Wagmi開発のコアアクション、クエリーオプション、フレームワークバインディングを学ぶ。AIエージェントを使用して強力なEthereumアプリを構築","ko":"Wagmi 개발의 핵심 액션, 쿼리 옵션, 프레임워크 바인딩을 학습하세요. Wagmi를 사용하여 강력한 Ethereum 애플리케이션을 구축","es":"Aprende a utilizar Wagmi Development con patrones de full-stack para agregar funcionalidades a tus aplicaciones de Ethereum","fr":"Découvrez comment utiliser Wagmi Development avec des modèles de full-stack pour ajouter des fonctionnalités à vos applications Ethereum","de":"Erfahren Sie, wie Sie Wagmi Development mit Full-Stack-Mustern verwenden, um Funktionen zu Ihren Ethereum-Anwendungen hinzuzufügen","pt":"Aprenda a desenvolver aplicativos Ethereum com Wagmi-Development, incluindo ações baseadas em Viem e integração com TanStack Query","ru":"Узнайте, как разработать приложения Ethereum с помощью Wagmi-Development, включая действия на основе Viem и интеграцию с TanStack Query","ar":"تعلم تطوير تطبيقات Ethereum باستخدام Wagmi-Development، بما في ذلك الإجراءات القائمة على Viem ودمج TanStack Query"},"definition":{"en":"wagmi-development is a set of reactive primitives for building Ethereum apps, focusing on Viem-based actions and TanStack Query integration.","zh":"Wagmi开发是一种用于构建Ethereum应用的反应式原语集","ja":"Wagmi開発は、Ethereumアプリを構築するための反応性プリミティブの集合です","ko":"Wagmi 개발은 Ethereum 애플리케이션을 구축하기 위한 리액티브 프imitives의 집합","es":"Wagmi Development es un conjunto de patrones de full-stack para agregar funcionalidades a aplicaciones de Ethereum","fr":"Wagmi Development est un ensemble de modèles de full-stack pour ajouter des fonctionnalités aux applications Ethereum","de":"Wagmi Development ist ein Satz von Full-Stack-Mustern, um Funktionen zu Ethereum-Anwendungen hinzuzufügen","pt":"Wagmi-Development é um conjunto de primitivos reativos para desenvolver aplicativos Ethereum com ações baseadas em Viem","ru":"Wagmi-Development - это набор реактивных примитивов для разработки приложений Ethereum с действиями на основе Viem","ar":"Wagmi-Development هو مجموعة من البدائيات التفاعلية لتطوير تطبيقات Ethereum مع إجراءات قائمة على Viem"},"features":{"en":["Core Action functionality wrapping Viem","TanStack Query integration for query options","React hooks for framework bindings","Vue composables for framework bindings","Support for Viem-based actions","Layered architecture for modular development"],"zh":["核心行动（Core Action）","查询选项（Query Options）","React框架绑定","Vue框架绑定","TanStack Query集成"],"ja":["コアアクション（Core Action）","クエリーオプション（Query Options）","Reactフレームワークバインディング","Vueフレームワークバインディング","TanStack Query統合"],"ko":["핵심 액션（Core Action）","쿼리 옵션（Query Options）","React 프레임워크 바인딩","Vue 프레임워크 바인딩","TanStack Query 통합"],"es":["Core Action con funcionalidades básicas","Query Options con integración de TanStack Query","Enlaces de framework para React y Vue","Patrones de full-stack para aplicaciones de Ethereum","Soporte para acciones basadas en Viem"],"fr":["Core Action avec des fonctionnalités de base","Query Options avec intégration de TanStack Query","Liens de framework pour React et Vue","Modèles de full-stack pour les applications Ethereum","Prise en charge des actions basées sur Viem"],"de":["Core Action mit grundlegenden Funktionen","Query Options mit TanStack Query-Integration","Framework-Verknüpfungen für React und Vue","Full-Stack-Muster für Ethereum-Anwendungen","Unterstützung für Viem-basierte Aktionen"],"pt":["Ações baseadas em Viem","Integração com TanStack Query","Binders para React e Vue","Primitivos reativos para aplicativos Ethereum","Desenvolvimento full-stack com Wagmi-Development","Suporte a múltiplas frameworks"],"ru":["Действия на основе Viem","Интеграция с TanStack Query","Биндеры для React и Vue","Реактивные примитивы для приложений Ethereum","Разработка полноценных стеков с Wagmi-Development","Поддержка нескольких фреймворков"],"ar":["الإجراءات القائمة على Viem","دمج TanStack Query","رابطات ل React و Vue","البدائيات التفاعلية لتطبيقات Ethereum","تطوير التطبيقات الكاملة مع Wagmi-Development","دعم الإطارات المتعددة"]},"keywords":{"en":["how to use wagmi-development","wagmi-development setup guide","wagmi-development vs ethers.js","wagmi-development install","react hooks for ethereum","tanstack query integration","viem-based actions","ethereum app development","full-stack ethereum development"],"zh":["Wagmi开发","Ethereum应用","反应式原语","核心行动","查询选项","React","Vue","TanStack Query"],"ja":["Wagmi開発","Ethereumアプリ","反応性プリミティブ","コアアクション","クエリーオプション","React","Vue","TanStack Query","AIエージェント"],"ko":["Wagmi 개발","Ethereum 애플리케이션","리액티브 프imitives","핵심 액션","쿼리 옵션","React","Vue","TanStack Query"],"es":["Wagmi Development","aplicaciones de Ethereum","patrones de full-stack","Core Action","Query Options","React","Vue","TanStack Query","Viem","desarrollo de aplicaciones de Ethereum"],"fr":["Wagmi Development","applications Ethereum","modèles de full-stack","Core Action","Query Options","React","Vue","TanStack Query","Viem","développement d''applications Ethereum"],"de":["Wagmi Development","Ethereum-Anwendungen","Full-Stack-Muster","Core Action","Query Options","React","Vue","TanStack Query","Viem","Ethereum-Anwendungs-Entwicklung"],"pt":["Wagmi-Development","aplicativos Ethereum","primitivos reativos","ações baseadas em Viem","TanStack Query","React","Vue","desenvolvimento full-stack","binders para React e Vue"],"ru":["Wagmi-Development","приложения Ethereum","реактивные примитивы","действия на основе Viem","TanStack Query","React","Vue","разработка полноценных стеков","биндеры для React и Vue"],"ar":["Wagmi-Development","تطبيقات Ethereum","البدائيات التفاعلية","الإجراءات القائمة على Viem","TanStack Query","React","Vue","تطوير التطبيقات الكاملة","رابطات ل React و Vue"]}},"owner":"wevm","repo":"wagmi","repoPath":"wevm/wagmi","stars":0,"forks":0,"updatedAt":"2026-03-08T01:57:15.323Z","topics":[],"category":"community","skillMd":{"name":"wagmi-development","description":"Creates Wagmi features across all layers - core actions, query options, framework bindings. Use when adding new actions, hooks, or working across packages/core, packages/react, packages/vue.","bodyPreview":"# Wagmi Development\n\nFull-stack patterns for adding Wagmi features. This skill covers Viem-based actions only (not Wagmi config actions).\n\n## Layer Overview\n\n1. **Core Action** (`packages/core/src/actions/`) - Base functionality wrapping Viem\n2. **Query Options** (`packages/core/src/query/`) - TanStack Query integration\n3. **Framework Bindings** - React (`packages/react/src/hooks/`), Vue (`packages/vue/src/composables/`)\n\n---\n\n## 1. Core Action\n\n### Structure\n\n```ts\nimport {\n  type MyActionError","body":"# Wagmi Development\n\nFull-stack patterns for adding Wagmi features. This skill covers Viem-based actions only (not Wagmi config actions).\n\n## Layer Overview\n\n1. **Core Action** (`packages/core/src/actions/`) - Base functionality wrapping Viem\n2. **Query Options** (`packages/core/src/query/`) - TanStack Query integration\n3. **Framework Bindings** - React (`packages/react/src/hooks/`), Vue (`packages/vue/src/composables/`)\n\n---\n\n## 1. Core Action\n\n### Structure\n\n```ts\nimport {\n  type MyActionErrorType as viem_MyActionErrorType,\n  type MyActionParameters as viem_MyActionParameters,\n  type MyActionReturnType as viem_MyActionReturnType,\n  myAction as viem_myAction,\n} from ''viem/actions''\n\nimport type { Config } from ''../createConfig.js''\nimport type { ChainIdParameter, ConnectorParameter } from ''../types/properties.js''\nimport type { Compute } from ''../types/utils.js''\nimport { getAction } from ''../utils/getAction.js''\n\nexport type MyActionParameters<config extends Config = Config> = Compute<\n  ChainIdParameter<config> & viem_MyActionParameters\n>\n\nexport type MyActionReturnType = viem_MyActionReturnType\n\nexport type MyActionErrorType = viem_MyActionErrorType\n\n/** https://wagmi.sh/core/api/actions/myAction */\nexport async function myAction<config extends Config>(\n  config: config,\n  parameters: MyActionParameters<config>,\n): Promise<MyActionReturnType> {\n  const { chainId, ...rest } = parameters\n  const client = config.getClient({ chainId })\n  const action = getAction(client, viem_myAction, ''myAction'')\n  return action(rest)\n}\n```\n\n### Key Rules\n\n- **Viem imports**: Prefix with `viem_` (e.g., `viem_getBalance`)\n- **Client access**: \n  - Read-only: `config.getClient({ chainId })`\n  - Wallet: `await getConnectorClient(config, { chainId, connector, account })`\n  - Mixed: Use `getConnectorClient` for account, `getClient` for action (see `estimateGas.ts`)\n- **Parameters**: Add `ChainIdParameter<config>` always. Add `ConnectorParameter` for wallet actions.\n- **Type params**: Mirror Viem''s type params for inference. Use `const` modifier for literal inference (abi, args).\n- **Spread**: Omit wagmi-specific props (`chainId`, `connector`) when calling Viem action.\n\n### Testing\n\n**Runtime tests** (`action.test.ts`):\n```ts\nimport { abi, address, config } from ''@wagmi/test''\nimport { expect, test } from ''vitest''\nimport { myAction } from ''./myAction.js''\n\ntest(''default'', async () => {\n  await expect(myAction(config, { /* required params */ })).resolves.toMatchInlineSnapshot(`...`)\n})\n\ntest(''parameters: chainId'', async () => { /* test chainId param */ })\n\ntest(''behavior: error case'', async () => { /* test error handling */ })\n```\n\n**Type tests** (`action.test-d.ts`) - only if action has type inference:\n```ts\nimport { config } from ''@wagmi/test''\nimport { expectTypeOf, test } from ''vitest''\nimport { myAction } from ''./myAction.js''\n\ntest(''default'', async () => {\n  const result = await myAction(config, { /* params */ })\n  expectTypeOf(result).toEqualTypeOf<ExpectedType>()\n})\n```\n\n**Type benchmarks** (`action.bench-d.ts`) - only if action has type inference:\n```ts\nimport { attest } from ''@ark/attest''\nimport { test } from ''vitest''\nimport type { MyActionParameters } from ''./myAction.js''\n\ntest(''default'', () => {\n  type Result = MyActionParameters<typeof abi.erc20, ''balanceOf''>\n  const res = {} as Result\n  attest.instantiations([12345, ''instantiations''])\n  attest(res.args).type.toString.snap(`readonly [account: \\`0x\\${string}\\`]`)\n})\n```\n\n**Wallet action tests**: Connect before, disconnect after:\n```ts\ntest(''default'', async () => {\n  await connect(config, { connector })\n  await expect(myAction(config, { /* params */ })).resolves.toMatchInlineSnapshot(`...`)\n  await disconnect(config, { connector })\n})\n```\n\n---\n\n## 2. Query Options\n\nQuery (read-only) or Mutation (wallet) options for TanStack Query.\n\n### Query Structure\n\n```ts\nimport {\n  type MyActionErrorType,\n  type MyActionParameters,\n  type MyActionReturnType,\n  myAction,\n} from ''../actions/myAction.js''\nimport type { Config } from ''../createConfig.js''\nimport type { ScopeKeyParameter } from ''../types/properties.js''\nimport type { QueryOptions, QueryParameter } from ''../types/query.js''\nimport type { Compute, ExactPartial } from ''../types/utils.js''\nimport { filterQueryOptions, structuralSharing } from ''./utils.js''\n\nexport type MyActionOptions<\n  config extends Config,\n  selectData = MyActionData,\n> = Compute<ExactPartial<MyActionParameters<config>> & ScopeKeyParameter> &\n  QueryParameter<MyActionQueryFnData, MyActionErrorType, selectData, MyActionQueryKey<config>>\n\nexport function myActionQueryOptions<\n  config extends Config,\n  selectData = MyActionData,\n>(\n  config: config,\n  options: MyActionOptions<config, selectData> = {},\n): MyActionQueryOptions<config, selectData> {\n  return {\n    ...options.query,\n    enabled: Boolean(options.requiredParam && (options.query?.enabled ?? true)),\n    queryFn: async (context) => {\n      const [, { scopeKey: _, ...parameters }] = context.queryKey\n      if (!parameters.requiredParam) throw new Error(''requiredParam is required'')\n      const result = await myAction(config, {\n        ...(parameters as MyActionParameters),\n        requiredParam: parameters.requiredParam,\n      })\n      return result ?? null\n    },\n    queryKey: myActionQueryKey(options),\n    structuralSharing, // include when returning complex objects/arrays\n  }\n}\n\nexport type MyActionQueryFnData = Compute<MyActionReturnType>\nexport type MyActionData = MyActionQueryFnData\n\nexport function myActionQueryKey<config extends Config>(\n  options: Compute<ExactPartial<MyActionParameters<config>> & ScopeKeyParameter> = {},\n) {\n  return [''myAction'', filterQueryOptions(options)] as const\n}\n\nexport type MyActionQueryKey<config extends Config> = ReturnType<typeof myActionQueryKey<config>>\n\nexport type MyActionQueryOptions<\n  config extends Config,\n  selectData = MyActionData,\n> = QueryOptions<MyActionQueryFnData, MyActionErrorType, selectData, MyActionQueryKey<config>>\n```\n\n### Mutation Structure\n\n```ts\nimport type { MutationOptions, MutationParameter } from ''../types/query.js''\n\nexport type MyActionOptions<config extends Config, context = unknown> = MutationParameter<\n  MyActionData,\n  MyActionErrorType,\n  MyActionVariables<config>,\n  context\n>\n\nexport function myActionMutationOptions<config extends Config, context>(\n  config: config,\n  options: MyActionOptions<config, context> = {},\n): MyActionMutationOptions<config> {\n  return {\n    ...options.mutation,\n    mutationFn: async (variables) => {\n      return myAction(config, variables)\n    },\n    mutationKey: [''myAction''],\n  }\n}\n\nexport type MyActionMutationOptions<config extends Config> = MutationOptions<\n  MyActionData,\n  MyActionErrorType,\n  MyActionVariables<config>\n>\n```\n\n### Key Rules\n\n- **ExactPartial vs UnionExactPartial**: Use `ExactPartial` for simple types, `UnionExactPartial` for complex unions (contract actions)\n- **enabled**: Based on required params being truthy\n- **structuralSharing**: Include when action returns objects/arrays\n- **filterQueryOptions**: Filters common non-serializable props. Skip props like `onReplaced` manually in query key.\n- **Query key**: Always `[''actionName'', filterQueryOptions(options)]`\n\n### Testing\n\n```ts\nimport { config } from ''@wagmi/test''\nimport { expect, test } from ''vitest''\nimport { myActionQueryOptions } from ''./myAction.js''\n\ntest(''default'', () => {\n  expect(myActionQueryOptions(config, {})).toMatchInlineSnapshot(`\n    {\n      \"enabled\": false,\n      \"queryFn\": [Function],\n      \"queryKey\": [\"myAction\", {}],\n    }\n  `)\n})\n\ntest(''enabled'', () => {\n  expect(myActionQueryOptions(config, { requiredParam: ''value'' }).enabled).toBe(true)\n})\n\ntest(''queryFn: calls query fn'', async () => {\n  const options = myActionQueryOptions(config, { requiredParam: ''value'' })\n  const result = await options.queryFn({ queryKey: options.queryKey } as any)\n  expect(result).toMatchInlineSnapshot(`...`)\n})\n```\n\n---\n\n## 3. Framework Bindings\n\n### React Query Hook\n\n```ts\n''use client''\nimport type { Config, MyActionErrorType, ResolvedRegister } from ''@wagmi/core''\nimport type { Compute } from ''@wagmi/core/internal''\nimport {\n  type MyActionData,\n  type MyActionOptions,\n  myActionQueryOptions,\n} from ''@wagmi/core/query''\nimport type { ConfigParameter } from ''../types/properties.js''\nimport { type UseQueryReturnType, useQuery } from ''../utils/query.js''\nimport { useChainId } from ''./useChainId.js''\nimport { useConfig } from ''./useConfig.js''\n\nexport type UseMyActionParameters<\n  config extends Config = Config,\n  selectData = MyActionData,\n> = Compute<MyActionOptions<config, selectData> & ConfigParameter<config>>\n\nexport type UseMyActionReturnType<selectData = MyActionData> =\n  UseQueryReturnType<selectData, MyActionErrorType>\n\n/** https://wagmi.sh/react/api/hooks/useMyAction */\nexport function useMyAction<\n  config extends Config = ResolvedRegister[''config''],\n  selectData = MyActionData,\n>(\n  parameters: UseMyActionParameters<config, selectData> = {},\n): UseMyActionReturnType<selectData> {\n  const config = useConfig(parameters)\n  const chainId = useChainId({ config })\n  const options = myActionQueryOptions(config, {\n    ...parameters,\n    chainId: parameters.chainId ?? chainId,\n    query: parameters.query,\n  })\n  return useQuery(options)\n}\n```\n\n### React Mutation Hook\n\n```ts\n''use client''\nimport { useMutation } from ''@tanstack/react-query''\nimport type { Config, ResolvedRegister, MyActionErrorType } from ''@wagmi/core''\nimport {\n  type MyActionData,\n  type MyActionMutate,\n  type MyActionMutateAsync,\n  type MyActionOptions,\n  type MyActionVariables,\n  myActionMutationOptions,\n} from ''@wagmi/core/query''\nimport type { ConfigParameter } from ''../types/properties.js''\nimport type { UseMutationReturnType } from ''../utils/query.js''\nimport { useConfig } from ''./useConfig.js''\n\nexport type UseMyActionParameters<config extends Config = Config, context = unknown> =\n  MyActionOptions<config, context> & ConfigParameter<config>\n\nexport type UseMyActionReturnType<config extends Config = Config, context = unknown> =\n  UseMutationReturnType<\n    MyActionData,\n    MyActionErrorType,\n    MyActionVariables<config>,\n    context,\n    MyActionMutate<config, context>,\n    MyActionMutateAsync<config, context>\n  >\n\n/** https://wagmi.sh/react/api/hooks/useMyAction */\nexport function useMyAction<\n  config extends Config = ResolvedRegister[''config''],\n  context = unknown,\n>(\n  parameters: UseMyActionParameters<config, context> = {},\n): UseMyActionReturnType<config, context> {\n  const config = useConfig(parameters)\n  const options = myActionMutationOptions(config, parameters)\n  const mutation = useMutation(options)\n  type Return = UseMyActionReturnType<config, context>\n  return {\n    ...mutation,\n    mutate: mutation.mutate as Return[''mutate''],\n    mutateAsync: mutation.mutateAsync as Return[''mutateAsync''],\n  }\n}\n```\n\n### Vue Composable (Query)\n\n```ts\nimport type { Config, MyActionErrorType, ResolvedRegister } from ''@wagmi/core''\nimport type { Compute } from ''@wagmi/core/internal''\nimport {\n  type MyActionData,\n  type MyActionOptions,\n  myActionQueryOptions,\n} from ''@wagmi/core/query''\nimport { computed } from ''vue''\nimport type { ConfigParameter } from ''../types/properties.js''\nimport type { DeepMaybeRef } from ''../types/ref.js''\nimport { deepUnref } from ''../utils/cloneDeep.js''\nimport { type UseQueryReturnType, useQuery } from ''../utils/query.js''\nimport { useChainId } from ''./useChainId.js''\nimport { useConfig } from ''./useConfig.js''\n\nexport type UseMyActionParameters<\n  config extends Config = Config,\n  selectData = MyActionData,\n> = Compute<DeepMaybeRef<MyActionOptions<config, selectData> & ConfigParameter<config>>>\n\nexport type UseMyActionReturnType<selectData = MyActionData> =\n  UseQueryReturnType<selectData, MyActionErrorType>\n\n/** https://wagmi.sh/vue/api/composables/useMyAction */\nexport function useMyAction<\n  config extends Config = ResolvedRegister[''config''],\n  selectData = MyActionData,\n>(\n  parameters: UseMyActionParameters<config, selectData> = {},\n): UseMyActionReturnType<selectData> {\n  const params = computed(() => deepUnref(parameters))\n  const config = useConfig(params)\n  const chainId = useChainId({ config })\n  const options = computed(() =>\n    myActionQueryOptions(config as any, {\n      ...params.value,\n      chainId: params.value.chainId ?? chainId.value,\n      query: params.value.query,\n    }),\n  )\n  return useQuery(options as any) as any\n}\n```\n\n### Framework Rules\n\n| Rule | React | Vue |\n|------|-------|-----|\n| Top directive | `''use client''` | None |\n| Parameters wrapper | `Compute<...>` | `Compute<DeepMaybeRef<...>>` |\n| Reactivity | Direct | `computed()` + `deepUnref()` |\n| Doc URL | `wagmi.sh/react/api/hooks/` | `wagmi.sh/vue/api/composables/` |\n\n**Shared rules:**\n- `ResolvedRegister[''config'']`: Use in function signature only, not type defs\n- No `enabled`/`structuralSharing` in hooks: Handled by queryOptions\n\n### Testing\n\n**Query hook test-d.ts**:\n```ts\nimport { abi } from ''@wagmi/test''\nimport { expectTypeOf, test } from ''vitest''\nimport { useMyAction } from ''./useMyAction.js''\n\ntest(''select data'', () => {\n  const result = useMyAction({\n    /* params */\n    query: {\n      select(data) {\n        expectTypeOf(data).toEqualTypeOf<ExpectedDataType>()\n        return data\n      },\n    },\n  })\n  expectTypeOf(result.data).toEqualTypeOf<ExpectedDataType>()\n})\n```\n\n**Mutation hook test-d.ts**:\n```ts\nimport { expectTypeOf, test } from ''vitest''\nimport { useMyAction } from ''./useMyAction.js''\n\ntest(''context'', () => {\n  const { mutate } = useMyAction({\n    mutation: {\n      onMutate(variables) {\n        expectTypeOf(variables).toMatchTypeOf<{ /* expected shape */ }>()\n        return { foo: ''bar'' }\n      },\n      onError(error, variables, context) { /* test types */ },\n      onSuccess(data, variables, context) { /* test types */ },\n      onSettled(data, error, variables, context) { /* test types */ },\n    },\n  })\n\n  mutate({ /* params */ }, {\n    onSuccess(data, variables, context) { /* test inference */ },\n  })\n})\n```\n\n---\n\n## Exports\n\nAdd to `exports/index.ts` in respective package:\n\n```ts\n// packages/core/src/exports/index.ts\nexport {\n  type MyActionParameters,\n  type MyActionReturnType,\n  type MyActionErrorType,\n  myAction,\n} from ''../actions/myAction.js''\n\n// packages/core/src/exports/query.ts\nexport {\n  type MyActionData,\n  type MyActionOptions,\n  type MyActionQueryFnData,\n  type MyActionQueryKey,\n  type MyActionQueryOptions,\n  myActionQueryKey,\n  myActionQueryOptions,\n} from ''../query/myAction.js''\n\n// packages/react/src/exports/index.ts\nexport {\n  type UseMyActionParameters,\n  type UseMyActionReturnType,\n  useMyAction,\n} from ''../hooks/useMyAction.js''\n```\n\n---\n\n## Verification\n\n```bash\n# Format\npnpm format\n\n# Type check (all or filtered)\npnpm check:types\npnpm --filter @wagmi/core check:types\npnpm --filter wagmi check:types\n\n# Test (all or filtered)\npnpm test\npnpm test --project core\npnpm test --project react\n\n# Update test snapshots\npnpm vitest -u\n\n# Type benchmarks\npnpm bench:types\n\n# Viem version mismatch in test snapshots\npnpm version:update:viem\n\n# Build (all or filtered)\npnpm run clean && pnpm build\npnpm --filter @wagmi/core build\n```\n"},"lastSynced":"2026-03-08T02:02:58.005Z","agentAnalysis":{"suitability":{"en":"Perfect for Ethereum-focused AI Agents needing reactive primitives for building full-stack Ethereum applications.","zh":"非常适合需要为构建全栈以太坊应用而使用反应式原语的以太坊专注的AI代理。","ja":"Ethereumに焦点を当てたAIエージェントが、フルスタックEthereumアプリケーションを構築するために反応性プリミティブを必要とする場合に最適です。","ko":"이더리움에 중점을 둔 AI 에이전트가 완전한 이더리움 애플리케이션을 구축하기 위해 반응형 원시 값을 필요로 할 때 적합합니다.","es":"Perfecto para agentes de inteligencia artificial enfocados en Ethereum que necesitan primitivas reactivas para construir aplicaciones Ethereum de pilas completas.","fr":"Parfait pour les agents d''intelligence artificielle axés sur Ethereum ayant besoin de primitives réactives pour construire des applications Ethereum full-stack.","de":"Perfekt für Ethereum-fokussierte KI-Agents, die reaktive Primitives für den Bau von Full-Stack-Ethereum-Anwendungen benötigen.","pt":"Perfeito para Agentes de IA focados em Ethereum que precisam de primitivos reativos para construir aplicações Ethereum de pilha completa.","ru":"Идеально подходит для агентов ИИ, ориентированных на Ethereum, которым необходимы реактивные примитивы для создания полнофункциональных приложений Ethereum.","ar":"مثالي للوكلاء الذكية التي تركز على Ethereum التي تحتاج إلى بدائيات تفاعلية لإنشاء تطبيقات Ethereum كاملة الطبقة."},"recommendation":{"en":"Empowers agents to leverage Viem-based actions and TanStack Query integration for seamless Ethereum app development, covering core actions and query options with support for React and Vue framework bindings.","zh":"赋予代理使用基于Viem的操作和TanStack Query集成，实现无缝的以太坊应用开发，涵盖核心操作和查询选项，并支持React和Vue框架绑定。","ja":"ViemベースのアクションとTanStack Queryの統合を使用して、シームレスなEthereumアプリケーションの開発を可能にし、ReactとVueフレームワークバインディングをサポートするコアアクションとクエリオプションをカバーします。","ko":"에이전트가 Viem 기반의 동작 및 TanStack Query 통합을 사용하여 이더리움 애플리케이션 개발을 원활하게 수행할 수 있도록 하며, React 및 Vue 프레임워크 바인딩을 지원하는 핵심 동작 및 쿼리 옵션을 다룹니다.","es":"Habilita a los agentes a aprovechar acciones basadas en Viem y la integración de TanStack Query para un desarrollo de aplicaciones de Ethereum sin problemas, cubriendo acciones y opciones de consulta básicas con soporte para enlaces de marco de React y Vue.","fr":"Permet aux agents d''exploiter les actions basées sur Viem et l''intégration de TanStack Query pour un développement d''applications Ethereum sans accroc, couvrant les actions et les options de requête de base avec un support pour les liaisons de framework React et Vue.","de":"Ermöglicht es Agents, Viem-basierte Aktionen und TanStack Query-Integration zu nutzen, um eine nahtlose Ethereum-App-Entwicklung zu ermöglichen, die Kernaktionen und Abfrageoptionen mit Unterstützung für React- und Vue-Framework-Bindings abdeckt.","pt":"Permite que os agentes usem ações baseadas em Viem e integração do TanStack Query para um desenvolvimento de aplicativos Ethereum sem problemas, cobrindo ações e opções de consulta principais com suporte a ligações de estrutura React e Vue.","ru":"Позволяет агентам использовать действия на 