INSERT INTO skills_fts (id, name, owner, repo, category, search_text) VALUES ('wevm/wagmi/wagmi-development', 'wagmi-development', 'wevm', 'wagmi', 'community', 'wagmi-development wevm wagmi community wagmi-development provides reactive primitives for Ethereum apps, covering core actions and query options. It benefits developers building full-stack Ethereum applications. Wagmi开发提供了一组反应式原语，用于构建Ethereum应用。它包括核心行动、查询选项和框架绑定 Wagmi開発は、Ethereumアプリを構築するための反応性プリミティブを提供します。コアアクション、クエリーオプション、フレームワークバインディングを含みます Wagmi 개발은 Ethereum 애플리케이션을 구축하기 위한 리액티브 프imitives를 제공합니다. 핵심 액션, 쿼리 옵션, 프레임워크 바인딩을 포함 Wagmi Development proporciona primitivas reactivas para aplicaciones de Ethereum, con funcionalidades como Core Action y Query Options Wagmi Development fournit des primitives réactives pour les applications Ethereum, avec des fonctionnalités telles que Core Action et Query Options Wagmi Development bietet reaktive Primitive für Ethereum-Anwendungen, mit Funktionen wie Core Action und Query Options Wagmi-Development fornece primitivos reativos para aplicativos Ethereum, incluindo ações baseadas em Viem e integração com TanStack Query Wagmi-Development предоставляет реактивные примитивы для приложений Ethereum, включая действия на основе Viem и интеграцию с TanStack Query Wagmi-Development يوفر بدائيات تفاعلية لتطبيقات Ethereum، بما في ذلك الإجراءات القائمة على Viem ودمج TanStack Query how to use wagmi-development wagmi-development setup guide wagmi-development vs ethers.js wagmi-development install react hooks for ethereum tanstack query integration viem-based actions ethereum app development full-stack ethereum development Wagmi开发 Ethereum应用 反应式原语 核心行动 查询选项 React Vue TanStack Query Core Action functionality wrapping Viem TanStack Query integration for query options React hooks for framework bindings Vue composables for framework bindings Support for Viem-based actions Layered architecture for modular development wagmi-development is a set of reactive primitives for building Ethereum apps, focusing on Viem-based actions and TanStack Query integration.');
